window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch09"]={"id":"ch09","title":"第五章 细胞周期","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"周期时相 · 调控 · 检查点 · 减数分裂","modules":[{"i":0,"name":"绪论 · 概览","slides":[{"i":0,"sec":"","title":"第五章     细胞周期及调控","notes":"调控机制\n1 正调控：CDKs/cyclins\n2 负调控：检验点checkpoint\n\n【读图讲解】\n本页是「细胞周期及调控」的章首页，由两幅显微照片和下方调控要点组成。左图为非洲血百合细胞的普通光镜照片，紫色为核内染色体，胞质中红色细丝为细胞骨架，细胞正为分裂做准备，标尺20 μm；右图为荧光照片，蓝色为染色体，红色为纺锤体纤维。下方文字点出两大调控机制：正调控由CDKs/cyclins推动，负调控由检验点(checkpoint)把关。要点：细胞周期由正、负两套机制协同控制，CDK-cyclin是核心引擎。","page":1,"level":"掌握","img":"assets/img/ch09/p001.jpg","anim":null,"fig":null,"points":["细胞周期调控分正调控与负调控","正调控：周期蛋白依赖性激酶(CDKs)/周期蛋白(cyclins)","负调控：检验点(checkpoint)"],"check":{"q":"细胞周期调控的正调控与负调控机制分别是？","o":["A. 正调控为检验点，负调控为CDKs/cyclins","B. 正调控为CDKs/cyclins，负调控为检验点","C. 正、负调控均由检验点完成","D. 正、负调控均由CDKs/cyclins完成"],"a":"B","e":"细胞周期由正、负两套机制协同控制：正调控为CDKs/cyclins推动，负调控为检验点（checkpoint）把关。","oe":["A. 错误，两者颠倒，CDK-cyclin属于正调控。","B. 正确，CDK-cyclin正调控，检验点负调控。","C. 错误，检验点属负调控，正调控由CDK-cyclin执行。","D. 错误，CDK-cyclin为正调控，负调控是检验点。"]},"cards":null,"mem":"周期调控：正=CDK/cyclin，负=检验点","big":"assets/img/ch09/big/p001.jpg","terms":[{"t":"CDK","en":"cyclin-dependent kinase","d":"周期蛋白依赖性激酶，以cyclin为调节亚基、驱动细胞周期各时相的蛋白激酶。"}],"summary":"本页是「细胞周期及调控」的章首页，由两幅显微照片和下方调控要点组成","goal":"学完应能掌握并运用「第五章     细胞周期及调控」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞周期像“细胞的排班表”：什么时候复制 DNA、什么时候分裂都按周期进行，由 CDK/cyclin 和检验点管理。"}],"mcq":[{"id":"ch09_mcq_8","mod":"绪论 · 概览","modI":0,"q":"细胞周期中不经历解聚和重建的是（                 ）。","o":["A．收缩环","B．纺锤体","C．核纤层","D．中心体"],"a":"D","e":"A 项，胞质分裂开始时，大量的肌动蛋白和肌球蛋白在中间体处组装成微丝，并相 互组成微丝束，环绕细胞，称为收缩环。B 项，当细胞从间期进入有丝分裂期，间期细胞微 管网络解聚为游离的α∕β-微管蛋白二聚体，再重组成纺锤体，介导染色体的运动；分裂末期 纺锤体微管解聚，又重组形成细胞质微管网络。C 项，当细胞进行有丝分裂时，核纤层蛋白 被磷酸化，引起核纤层的可逆解聚。D 项，中心体在细胞周期过程中也要进行复制，并经历 一系列的发育过程，称为中心体周期。包括：G1 期末到 S 期复制；晚 G2 期到 M 期，子中 心粒长大并逐渐分离；有丝分裂前期分离成为一个生长辐射状微管的核心。","kp":"ch09_s0_0","oe":["胞质分裂时肌动蛋白与肌球蛋白组装成收缩环，经历重建。","间期微管解聚，M期重组成纺锤体，经历解聚与重建。","核纤层蛋白磷酸化引起核纤层可逆解聚，经历重建。","正确。中心体只进行复制与发育，不发生解聚和重建。"]},{"id":"ch09_mcq_11","mod":"绪论 · 概览","modI":0,"q":"染色体出现成倍状态发生于细胞周期中的（                ）","o":["A．G2 期和早 M 期","B．G1 期和 S 期","C．晚 M 期和 Gl 期","D．G0 期和 G1 期"],"a":"A","e":"S 期开始 DNA 的复制，同时染色体也在这个阶段完成复制。而 G2 与早 M 期是紧 接在 S 期之后的两个时期，其染色体同样保持成倍状态。","kp":"ch09_s0_0","oe":["正确。S期完成复制后，G2期与早M期染色体保持成倍状态。","G1期DNA未复制，S期正在复制，染色体不成倍。","晚M期细胞分裂后染色体减半，G1期未复制，不成倍。","G0期和G1期DNA均未复制，染色体不成倍。"]}],"judge":[{"id":"ch09_judge_4","modI":0,"q":"极微管头对头连接，因此从一个纺锤极到另一个纺锤极是连续存在的。（                     ）","a":"错","e":"极微管末端相互重叠并通过将微管之间跨接起来的蛋白质而相互连接。","kp":"ch09_s0_0","oe":["若判对则误认为极微管连续贯穿两极，实则两端重叠并借蛋白相连。","极微管并非连续，而是在赤道区末端重叠，通过交联蛋白相互连接。"]},{"id":"ch09_judge_9","modI":0,"q":"微管在着丝粒处成核然后连接至动粒。（            ）","a":"错","e":"微管在中心体处成核组装，然后连接到动粒。","kp":"ch09_s0_0","oe":["误认为微管由着丝粒成核再连动粒，混淆了成核部位与连接部位。","微管实际在中心体处成核组装，随后其正端连接到动粒上。"]},{"id":"ch09_judge_11","modI":0,"q":"一般细胞周期中，细胞经历生长和分裂两个过程，但有些细胞基本上只经历 DNA 复制 （S 相）和分裂（M 相），而无生长现象，例如干细胞。（           ）","a":"错","e":"干细胞具有完整的细胞周期。","kp":"ch09_s0_0","oe":["误以为干细胞只有DNA复制与分裂而无生长，故判对。","干细胞具有完整细胞周期，G1、S、G2、M齐全，同样经历生长过程。"]}],"fill":[{"id":"ch09_fill_12","modI":0,"q":"细线期的主要特征有：______、______、______。","a":"染色质凝集成单条细线；细线与核膜相连；染色质线上有染色粒","kp":"ch09_s0_0","oe":["细线期染色体呈细线状凝集，尚未配对。","细线期染色体通过端粒与核膜相连，起固定作用。","细线上可见染色粒，呈串珠状结构。"]},{"id":"ch09_fill_25","modI":0,"q":"根据是否增殖可将细胞划分为：______、________、和_______。","a":"G0 期细胞；周期中细胞；终末分化细胞","kp":"ch09_s0_0","oe":["暂时脱离细胞周期、停止分裂，受刺激可重返周期的细胞","持续进行分裂增殖，不断循环于G1-S-G2-M各时相的细胞","已丧失分裂能力、高度分化而不再增殖的细胞"]}],"short":[{"id":"ch09_short_3","modI":0,"q":"比较自然同步化、人工选择同步化、密度梯度离心法。","a":"（1）自然同步化，如有一种黏菌的变形体 plasmodia，某些受精卵早期卵裂。条件依赖 性突变株在细胞周期同步化中的应用：将与细胞周期调控有关的条件依赖性突变株转移到限 定条件下培养，所有细胞便被同步化在细胞周期中某一特定时期。 （2）人工选择同步化，如有丝分裂选择法，可用于单层贴壁生长细胞。优点是细胞未经任 何药物处理，细胞同步化效率高。缺点是分离的细胞数量少。 （3）密度梯度离心法，根据不同时期的细胞在体积和重量上存在差别进行分离。优点是方 法简单省时，效率高，成本低。缺点是对大多数种类的细胞并不适用。","kp":"ch09_s0_0"}],"calc":[{"id":"ch09_calc_4","modI":0,"q":"试述 UPPS。","a":"UPPS 即泛素蛋白酶水解系统，是一种依赖能量（ATP）的蛋白质降解系统，在这个系 统中，起介导蛋白质水解的是泛素，它是一个由 76 个氨基酸组成的高度保守的蛋白，其中 E1（泛素激活酶）、E2（泛素结合酶）和 E3（泛素蛋白连接酶）三种酶起重要的催化作用， 具体过程是： （1）泛素与泛素激活酶 E1 结合，形成 E1-泛素复合体。 （2）E1-泛素复合体将泛素转移给另一泛素结合酶 E2。 （3）在泛素蛋白连接酶 E3 的催化下，泛素与靶蛋白连接，并形成一条多聚泛素链。 （4）泛素化的靶蛋白转运到蛋白酶体，从而被降解。 这种泛素调节的蛋白质降锯过程在生物体中的作用非常重要。比如，与细胞周期相关的许多 蛋白质就是利用这个途径降解，使得蛋白质的浓度周期性的变化，保证在正确的时间和空间 上执行功能，使得细胞周期正常的运转。以色列科学家阿龙·切哈诺沃、阿夫拉姆·赫什科和 美国科学家欧文·罗斯三位科学家正是因为发现了泛素调节的蛋白质降解而获得 2004 年诺 贝尔奖。","kp":"ch09_s0_0"},{"id":"ch09_calc_7","modI":0,"q":"什么是细胞周期？细胞周期各时相的主要变化是什么？","a":"（1）细胞周期 细胞周期是指细胞从一次有丝分裂结束到下一次有丝分裂完成所经历的一个有序过程。它包 括细胞生长、DNA 复制和细胞分裂，最终将细胞遗传物质和其他内含物分配给两个子代细 胞等阶段。 （2）细胞周期各时相及其主要变化 细胞周期可划分为 G1、S、G2 和 M 四个时相，其主要变化如下： ①G1 期：G1 期细胞的物质代谢活跃，进行 RNA 和蛋白质的合成，细胞体积增大，dNTP 积 累，为细胞进入 S 期做准备。在 G1 晚期有检验点，可检验前次有丝分裂是否完成、外界环 境条件（如营养条件等）是否合适、细胞是否充分长大、DNA 是否有损伤等。多数细胞的 细胞周期时间长短主要由 G1 期决定。 ②S 期：主要进行 DNA 复制，常染色质与异染色质的复制不同步进行，DNA 量加倍。 ③G2 期：合成大量的蛋白质，但此期合成的蛋白质与前两期的不同，主要为细胞进入 M 期 做好充分准备。 ④M 期：核膜破裂，核仁消失，染色质聚集形成染色体，子染色体移向两极，在两极形成 子核，胞质分裂，形成两个子细胞。","kp":"ch09_s0_0"},{"id":"ch09_calc_9","modI":0,"q":"细胞周期同步化有哪些方法？比较其优缺点。","a":"细胞周期同步化是指在自然或者实验条件下，使一个细胞群体中所有细胞都处于细胞周 期的同一时相的过程。 （1）细胞周期同步化的方法 ①天然同步化 黏菌变形体进行多次核分裂后，再进行同步细胞分裂；大多数无脊椎动物和个别脊椎动物的 早期胚胎细胞，可同步化卵裂形成同步化细胞群体等，这种自然界存在的细胞周期同步化过 程，称为天然同步化。 ②人工同步化 a．人工选择同步化 人工选择同步化是指人为地将处于周期不同时相的细胞分离开来，从而获得不同时相的细胞 群体。在体外进行细胞培养时，处于 M 期的细胞体积较大，会变成球形，附着力减弱，经 振荡后可从培养液中收集。 b．人工诱导同步化 第一，DNA 合成阻断法：采用低毒或无毒的 DNA 合成抑制剂特异地抑制 DNA 合成，而不 影响处于其他时相的细胞进行细胞周期运转，经过两次 DNA 合成抑制剂处理，细胞最终抑 制在 G1／S 期交界处狭窄的时间区段，抑制剂去除后，细胞即可以进行同步细胞周期运转。 常用的 DNA 合成抑制剂有 TdR、羟基脲（HU）。 第二，分裂中期阻断法：某些药物可以抑制微管聚合，因而能有效地抑制细胞纺锤体的形成， 将细胞阻断在细胞分裂中期。常用药物有秋水仙素、秋水酰胺和诺考达唑。 （2）天然同步化与人工同步化的优、缺点 ①天然同步化 优点：不受人为条件的干扰，因而有可能在接近自然的条件下进行观察。 缺点：天然同步化的细胞群体受到诸多条件的限制，对结果有很大的影响。一般难以获得大 量的同步化细胞，难以满足实验的需要。 ②人工选择同步化 优点：细胞未经任何药物处理和伤害，能够真实反映细胞周期状况，且细胞同步化效率高。 缺点：分离的细胞数量少，需要多次收集方可得到较多的细胞，成本远大于其他方法。 ③人工诱导同步化 优点：在较短时间内可以获得较多的同步化细胞，并且比较节省时间和成本。 缺点：化学药物可能影响细胞的正常生理，从而影响细胞周期的状况。如果药物浓度过高， 一些细胞将不能回到细胞周期中，甚至死亡。","kp":"ch09_s0_0"}],"term":[{"id":"ch09_term_17","modI":0,"term":"静止期细胞（quiescent cell）。","def":"由于 R 点（又称 checkpoint）作用，周期中细胞暂时脱离细胞周期不进行增殖（大多处 于 G1 期），但给予适当刺激后可重新进入细胞周期进行细胞分裂，这些细胞称为静止期细 胞，或 G0 期细胞。","kps":"","kp":"ch09_s0_0"}]},{"i":1,"name":"一 细胞周期的概念","slides":[{"i":1,"sec":"","title":"一 细胞周期的概念","notes":"结束的过程称为细胞周期(cell cycle)。\n\n【读图讲解】\n本页讲解「细胞周期的概念」。文字给出定义：细胞从一次分裂结束到下一次分裂形成子细胞的过程称细胞周期；标准周期分G1、S、G2、M期，又可归为物质积累期(间期)和细胞分裂期(M期)。下方箭头图展示有丝分裂各期：前期(Prophase)纺锤体极出现、中期(Metaphase)姐妹染色单体排列、后期(Anaphase)分离、末期与胞质分裂，并对应到下部环形周期图的M、G1、S、G2。右侧饼图强调间期占时更长。要点：牢记各期顺序与间期、分裂期的划分。","page":2,"level":"掌握","img":"assets/img/ch09/p002.jpg","anim":null,"fig":null,"points":["细胞分裂产生新细胞生长开始到下一次细胞分裂形成子细胞","标准细胞周期分为G1, S, G2和M期","又可分为：物质积累期(间期或静止期)和细胞分裂期(M期)."],"check":{"q":"细胞周期是指？","o":["A. 从一次分裂结束到下一次分裂形成子细胞的过程","B. 仅指有丝分裂期这一时段","C. 从S期开始到M期结束的过程","D. 从G1期到S期的过程"],"a":"A","e":"细胞从一次分裂结束到下一次分裂形成子细胞的过程称细胞周期，包括G1、S、G2、M期，可归为间期与分裂期(M期)。","oe":["正确，这是细胞周期的标准定义。","错误，细胞周期还包括间期G1、S、G2期。","错误，起点是上次分裂结束，而非S期。","错误，该过程未包含G2与M期。"]},"cards":null,"mem":"周期=一次分裂结束到下次，分G1/S/G2/M","big":"assets/img/ch09/big/p002.jpg","summary":"结束的过程称为细胞周期(cell cycle)","goal":"学完应能掌握并运用「一 细胞周期的概念」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞周期指一次分裂结束到下一次分裂结束的全过程，包括间期（G1/S/G2）和分裂期(M)。"},{"i":2,"sec":"","title":"动物细胞和植物","notes":"细胞的胞质分裂\n\n【读图讲解】\n本页对比动物细胞与植物细胞的胞质分裂。上半部为洋葱根尖细胞有丝分裂光镜图，标注细胞核、核仁、染色体凝集、染色体及细胞板。下半部(a)动物细胞扫描电镜图及模式图：赤道处收缩形成卵裂沟，由微丝构成的收缩环缢缩，最终分成两个子细胞；(b)植物细胞透射电镜图及模式图：囊泡在赤道面聚集形成细胞板，进而发育为新细胞壁。要点：动物靠收缩环缢裂，植物靠细胞板扩展成新壁。","page":3,"level":"掌握","img":"assets/img/ch09/p003.jpg","anim":null,"fig":null,"points":["动物细胞胞质分裂在赤道处由微丝收缩环缢缩形成卵裂沟，最终分成两个子细胞","植物细胞由囊泡在赤道面聚集形成细胞板，进而发育为新细胞壁"],"check":{"q":"动物细胞与植物细胞胞质分裂方式的区别是？","o":["A. 动物靠细胞板，植物靠收缩环","B. 二者均靠收缩环缢裂","C. 二者均靠细胞板形成新壁","D. 动物靠收缩环缢裂，植物靠细胞板扩展成新壁"],"a":"D","e":"动物细胞胞质分裂在赤道处由微丝收缩环缢缩形成卵裂沟；植物细胞则由囊泡在赤道面聚集形成细胞板，进而发育为新细胞壁。","oe":["A. 错误，二者颠倒，动物靠收缩环，植物靠细胞板。","B. 错误，植物细胞靠细胞板而非收缩环缢裂。","C. 错误，动物细胞靠收缩环缢裂，不形成细胞板。","D. 正确，动物收缩环缢裂，植物细胞板成新壁。"]},"cards":null,"mem":"动物收缩环缢裂，植物细胞板成新壁","big":"assets/img/ch09/big/p003.jpg","summary":"本页对比动物细胞与植物细胞的胞质分裂","goal":"学完应能掌握并运用「动物细胞和植物」的核心内容，能解释其机制、比较相关概念。","intuition":"动物胞质分裂像“勒紧收口袋”（收缩环），植物像“中间砌墙”（细胞板）。"},{"i":3,"sec":"","title":"细胞周期的长短","notes":"➢ 同种细胞周期长短相似或相同;不同种类细胞周期长短差别很\n大。\n➢ S+G2+M 的时间变化较小，尤其M期更恒定(约0.5小时)；细胞\n周期时间长短差别在G1期.\n➢ 部分细胞的细胞周期没有G1、G2期，如早期胚胎细胞。","page":4,"level":"掌握","img":"assets/img/ch09/p004.jpg","anim":null,"fig":null,"points":["同种细胞周期长短相似或相同，不同种类差别很大","S+G2+M时间变化较小，M期更恒定(约0.5小时)，周期长短差别在G1期","部分细胞没有G1、G2期，如早期胚胎细胞"],"check":{"q":"关于细胞周期长短的叙述，正确的是？","o":["A. 周期长短差异主要在G1期，M期较恒定","B. 周期长短差异主要在M期，G1期恒定","C. 所有细胞的周期均含G1、G2期","D. 同种细胞的周期长短差别很大"],"a":"A","e":"同种细胞周期长短相似，不同种类差别大；S+G2+M时间变化小、M期最恒定，周期长短差别主要在G1期，早期胚胎细胞可无G1、G2期。","oe":["A. 正确，差异主要在G1期，M期约0.5小时恒定。","B. 错误，差异在G1期、M期恒定，此项恰好颠倒。","C. 错误，早期胚胎细胞可没有G1、G2期。","D. 错误，同种细胞的周期长短相似或相同。"]},"cards":null,"mem":"周期长短差在G1，M期约0.5h恒定","big":"assets/img/ch09/big/p004.jpg","summary":"➢ 同种细胞周期长短相似或相同;不同种类细胞周期长短差别很","goal":"学完应能掌握并运用「细胞周期的长短」的核心内容，能解释其机制、比较相关概念。","intuition":"周期长短差别主要在 G1 期；S+G2+M 相对固定，M 期最短（约 0.5h）。","derive":"【群体倍增时间】N = N₀·2^(t/Td)。\n取对数：Td = t·ln2 / ln(N/N₀)。\n例：t=24 h 时细胞数由 1×10⁵ 增至 4×10⁵，则 Td = 24×0.693/ln4 ≈ 12 h。"},{"i":4,"sec":"","title":"细胞周期的时相划分","notes":"细胞周期(cell cycle)指细胞从一次分裂结束到下一次分裂结束的全过程。①间期(interphase)为细胞分裂前的物质准备与积累阶段，包括G1期、S期(DNA synthesis)、G2期(S之后、有丝分裂之前的第二个时间间隔期)；②分裂期(M期，mitosis)是细胞增殖的实施过程，包括前期(prophase)、中期(metaphase)、后期(anaphase)、末期(telophase)，含核分裂与胞质分裂(cytokinesis)。此外还有特殊的有性生殖细胞分裂——减数分裂。细胞周期长短的差别主要在G1期。","page":5,"level":"掌握","img":"assets/img/ch09/p005.jpg","anim":"cell_cycle_wheel","fig":null,"points":["减数分裂:特殊的有"],"check":{"q":"关于细胞周期各时相的叙述，正确的是？","o":["A. S期主要合成ATP和RNA","B. 细胞周期长短的差别主要在G1期","C. G2期是DNA合成期","D. M期只进行核分裂，不含胞质分裂"],"a":"B","e":"细胞周期长短差别主要在G1期；间期分G1、S(DNA合成)、G2，M期包括前期、中期、后期、末期，含核分裂与胞质分裂。","oe":["错误，大量合成ATP和RNA的是G2期。","正确，周期长短差异主要取决于G1期。","错误，DNA合成在S期，G2在S期之后。","错误，M期包括核分裂与胞质分裂。"]},"cards":null,"mem":"G1物质准备，S复制DNA，G2备M，M分裂","big":"assets/img/ch09/big/p005.jpg","summary":"细胞周期(cell cycle)指细胞从一次分裂结束到下一次分裂结束的全过程","goal":"学完应能掌握并运用「细胞周期的时相划分」的核心内容，能解释其机制、比较相关概念。","intuition":"周期分四相：G1（准备）、S（复制 DNA）、G2（备分裂）、M（分裂），M 内又分前中后末。","derive":"【脉冲标记法测时相时长】用 ³H-TdR 脉冲标记 S 期细胞，追踪“标记有丝分裂细胞百分率(PLM)”曲线：① 从标记到首次出现标记分裂象的时间≈G2+½M；② PLM≈Ts/Tc（Td）可估 S 期占比；③ 平台期对应 Ts。据此求出 Ts 与总周期 Tc，再推出 G1、G2、M 的时长。"},{"i":5,"sec":"","title":"G1(Gap1) ：合成细胞生长所需的蛋白质、糖类和脂质等;","notes":"S(DNA synthesis): DNA合成期, 新的组蛋白也在这个时期合成; 真核新合成\n的DNA立即与组蛋白结合组成核小体串珠结构。\nG2(Gap2)：大量合成ATP、RNA、蛋白质等，为进入M期作好准备;\nM(mitosis): 有丝分裂期，核分裂+胞质分裂，形成2个子细胞。\n【结合课本/笔记】·与DNA合成启动相关，开始合成细胞生长所需要的多种蛋白质、RNA、碳水化合物、脂等，同时染色质去凝集。","page":6,"level":"掌握","img":"assets/img/ch09/p006.jpg","anim":null,"fig":null,"points":["染色体凝聚，两个姐妹染色单体均等的分配到2个子细胞中。"],"check":{"q":"关于细胞周期各时相的物质合成，下列叙述正确的是？","o":["A. 组蛋白在G2期合成","B. G1期完成全部DNA复制","C. M期大量合成ATP为S期作准备","D. S期合成DNA，新的组蛋白也在此期合成"],"a":"D","e":"S期为DNA合成期，新的组蛋白也在S期合成，新合成的DNA立即与组蛋白结合形成核小体串珠结构。","oe":["组蛋白与DNA同在S期合成，不是G2期。","DNA复制在S期完成，不在G1期。","大量合成ATP、RNA、蛋白质为进入M期作准备的是G2期。","S期合成DNA和组蛋白，叙述正确。"],"basis":"S(DNA synthesis): DNA合成期, 新的组蛋白也在这个时期合成"},"cards":null,"mem":"G1备物质，S复DNA组蛋白，G2备M，M分裂","big":"assets/img/ch09/big/p006.jpg","summary":"S(DNA synthesis): DNA合成期, 新的组蛋白也在这个时期合成; 真核新合成","goal":"学完应能掌握并运用「G1(Gap1) ：合成细胞生长所需的蛋白质、糖类和脂质等;」的核心内容，能解释其机制、比较相关概念。","intuition":"G1 像“开工前的备料”：合成生长所需蛋白与 RNA，为 DNA 复制做准备；G1 长短决定整个周期长短。"},{"i":6,"sec":"","title":"SMC蛋白复合体：有丝分裂前期染色体凝缩","notes":"有丝分裂前期，间期细长，弥漫样分布的染色质经过进一\n步螺旋化、折叠和包装等过程，逐渐变粗变短，形成光镜下可\n辨的早期染色体结构。\n已复制的两个姐妹染色单体间彼此黏着和凝缩是有丝\n分裂和减数分裂期间基因组准确分离的先决条件。\n这一过程是依赖不同的\nSMC (structural maintenance of chromosome) 蛋白复合物。\n真核细胞中包括两类蛋白复合物：\n➢ 黏连蛋白cohesin和凝缩蛋白condensin\n➢ 其核心组分均为具有ATPase活性的Smc家族成员。\n➢ 从细菌到高等生物，进化上高度保守，在染色体高级结构组\n织、包装和配对等方面具关键作用。","page":7,"level":"掌握","img":"assets/img/ch09/p007.jpg","anim":"cohesin_condensin","fig":null,"points":["有丝分裂前期染色质经螺旋化、折叠包装，变粗变短形成染色体","姐妹染色单体间彼此黏着和凝缩是基因组准确分离的先决条件","过程依赖SMC(染色体结构维持)蛋白复合物：cohesin(黏连蛋白)与condensin(凝缩蛋白)，核心组分均具ATPase活性"],"check":{"q":"有丝分裂前期染色体凝集及姐妹染色单体黏着主要依赖？","o":["A. 微管与驱动蛋白","B. SMC蛋白复合物中的凝缩蛋白和黏连蛋白","C. 肌动蛋白与肌球蛋白","D. 核纤层蛋白"],"a":"B","e":"染色体凝缩与姐妹染色单体黏着依赖SMC蛋白复合物，包括凝缩蛋白（condensin）和黏连蛋白（cohesin），其核心组分具ATPase活性且高度保守。","oe":["A. 错误，微管形成纺锤体，不负责染色单体黏着。","B. 正确，condensin和cohesin介导凝缩与黏着。","C. 错误，肌动蛋白-肌球蛋白参与胞质分裂，非凝集。","D. 错误，核纤层蛋白构成核纤层，不介导黏连。"]},"cards":null,"mem":"SMC复合体=cohesin+condensin促凝缩","big":"assets/img/ch09/big/p007.jpg","terms":[{"t":"黏连蛋白","en":"cohesin","d":"环形蛋白复合体，把姐妹染色单体黏连在一起，直至分裂后期。"},{"t":"凝缩蛋白","en":"condensin","d":"使染色体在分裂期高度凝缩的蛋白复合体。"},{"t":"SMC","en":"structural maintenance of chromosome","d":"上述复合体的核心ATPase亚基家族，进化上高度保守。"}],"summary":"有丝分裂前期，间期细长，弥漫样分布的染色质经过进一","goal":"学完应能掌握并运用「SMC蛋白复合体：有丝分裂前期染色体凝缩」的核心内容，能解释其机制、比较相关概念。","intuition":"SMC 复合体像“卷线器”：cohesin 像夹子把姐妹染色单体夹在一起，condensin 把染色体卷紧缩短，二者核心都是 SMC 家族 ATP 酶。"},{"i":7,"sec":"","title":"有丝分裂前期两个主要事件：●染色体凝缩 ●纺锤体的装配","notes":"已复制的染色体的两个姐妹染色单体间彼此黏连(cohesin)和染\n色体自身的凝缩(condensin)是有丝分裂和减数分裂遗传物质准\n确分离的先决条件。=cohesin/condensin\n促进染色体凝缩。\nATP-\nbinding                         凝缩蛋白condensin\n黏连蛋白cohensin\ncassette\n【中文讲解·对照课本/考点】\n考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页讲解】\n本页讲有丝分裂前期的两个主要事件：染色体凝缩与纺锤体装配，核心是黏连蛋白（cohesin）与凝缩蛋白（condensin）。已复制染色体中，姐妹染色单体间的彼此黏连依赖cohesin，它以分子间交联方式把两条染色单体持在一起；condensin则利用水解ATP的能量介导染色体DNA的分子内交联，促进染色体凝缩。二者是保证有丝分裂和减数分裂中遗传物质准确分离的先决条件。考点联系翟中和《细胞生物学》第十三章细胞周期与细胞分裂，需掌握cohesin与condensin的功能区别。","page":8,"level":"掌握","img":"assets/img/ch09/p008.jpg","anim":"mitosis_prophase","fig":null,"points":["Cohesin holds sister chromatids together.(分子间交联)","Condensin 利用水解ATP的能量介导染色体DNA分子内交联，"],"check":{"q":"有关黏连蛋白(cohesin)和凝缩蛋白(condensin)的叙述，正确的是？","o":["A. cohesin介导染色单体间黏连，condensin介导分子内交联","B. 两者功能相同，均维持姐妹染色单体黏连","C. condensin不需要ATP即可使染色体凝缩","D. cohesin水解ATP促进染色体凝缩"],"a":"A","e":"已复制染色体中姐妹染色单体的黏连依赖cohesin(分子间交联)，condensin利用ATP水解介导DNA分子内交联促进凝缩，二者是遗传物质准确分离的先决条件。","oe":["正确，cohesin分子间交联，condensin分子内交联。","错误，condensin主要促进染色体凝缩。","错误，condensin利用水解ATP介导交联。","错误，水解ATP促进凝缩的是condensin。"]},"cards":null,"mem":"前期=染色体凝缩+纺锤体装配，SMC介导","big":"assets/img/ch09/big/p008.jpg","summary":"已复制的染色体的两个姐妹染色单体间彼此黏连(cohesin)和染","goal":"学完应能掌握并运用「有丝分裂前期两个主要事件：●染色体凝缩 ●纺锤体的装配」的核心内容，能解释其机制、比较相关概念。","intuition":"有丝分裂前期两件大事：染色体凝缩（cohesin/condensin）和纺锤体装配。"},{"i":8,"sec":"","title":"Smc家族: condesins（凝缩蛋白） and cohesins(黏连蛋白)","notes":"两者的核心组分均为\n具有ATPase活性的\nSmc家族成员，从细\n菌到高等生物进化上\ncohesin→定位于姐妹染色单体            高度保守。\n体之间，ATP条件下使姐妹染色\n单体粘着为一个统一整体，直至               在有丝分裂前期，染\n分裂后期。\n色体高级结构组织、\n包装配对等方面有关\n键作用。\ncondensin →位于单个染色体上，\n在ATP和TOP II酶共同作用下，\n卷曲DNA形成超螺旋结构，帮助\ncondensin               染色体自身结构凝缩(分子内)","page":9,"level":"掌握","img":"assets/img/ch09/p009.jpg","anim":null,"fig":null,"points":["Smc家族从细菌到高等生物进化上高度保守，核心组分具ATPase活性","cohesin定位于姐妹染色单体之间，ATP条件下使姐妹染色单体粘着为统一整体，直至分裂后期","condensin位于单个染色体上，在ATP和拓扑异构酶II作用下卷曲DNA形成超螺旋"],"check":{"q":"关于凝缩蛋白(condensin)与黏连蛋白(cohesin)，下列叙述正确的是？","o":["A. 两者的作用均不需要ATP水解供能","B. 两者的核心组分均为具ATPase活性的Smc家族成员","C. 两者均定位于姐妹染色单体之间介导黏连","D. 两者均位于单条染色体上促进分子内凝缩"],"a":"B","e":"condensin与cohesin的核心组分都是具ATPase活性的Smc家族成员，进化高度保守；cohesin黏连姐妹染色单体，condensin促进染色体自身凝缩。","oe":["错误，二者发挥功能均需ATP水解提供能量。","正确，二者核心组分均为具ATPase活性的Smc家族成员。","错误，只有cohesin定位于姐妹染色单体之间介导黏连。","错误，只有condensin位于单条染色体上促凝缩。"]},"cards":null,"mem":"cohesin粘单体，condensin凝缩染色体","big":"assets/img/ch09/big/p009.jpg","summary":"两者的核心组分均为","goal":"学完应能掌握并运用「Smc家族: condesins（凝缩蛋白） and cohesins(黏连蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"SMC 家族像“染色体的整理员”：cohesin 夹住姐妹染色单体，condensin 把染色体卷紧，都靠 ATP。"},{"i":9,"sec":"","title":"凝缩蛋白condensin","notes":"黏连蛋白\ncohesin\n黏连蛋白\ncohesin\n【中文讲解·对照课本/考点】\n考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 纺锤体（mitotic spindle）：有丝分裂前期，中心粒分别移向细胞两级，微管加速聚合，形成纺锤形结构，称为纺锤体。\n• 染色体（chromosome）：当细胞进入有丝分裂时，伸展、弥散的丝状染色质高度折叠、盘曲而凝缩成条状或棒状的特殊形态，称为染色体。\n\n【本页讲解】\n本页以示意图标注凝缩蛋白（condensin）与黏连蛋白（cohesin），是对染色体凝缩与姐妹染色单体黏连机制的图解巩固。cohesin负责将姐妹染色单体沿纵轴黏连在一起，保证分离前成对存在；condensin则通过压缩DNA促进染色质高度折叠盘曲，使染色体在有丝分裂期凝缩成棒状。二者协同是有丝分裂与减数分裂中遗传物质准确分离的结构基础。考点联系翟中和《细胞生物学》第十三章细胞周期与细胞分裂，可结合纺锤体与染色体的概念一并记忆。","page":10,"level":"掌握","img":"assets/img/ch09/p010.jpg","anim":null,"fig":null,"points":["有丝分裂中凝缩蛋白(condensin)与黏连蛋白(cohesin)各自发挥作用"],"check":{"q":"cohesin与condensin协同保障遗传物质准确分离，关于二者功能下列正确的是？","o":["A. cohesin位于单条染色体内部介导分子内凝缩","B. condensin使姐妹染色单体黏连，cohesin压缩DNA","C. cohesin使姐妹染色单体沿纵轴黏连，condensin压缩DNA促凝缩","D. 两者均在分裂后期才开始发挥作用"],"a":"C","e":"cohesin将姐妹染色单体沿纵轴黏连，保证分离前成对存在；condensin通过压缩DNA促进染色质高度折叠盘曲，使染色体凝缩成棒状。","oe":["错误，介导分子内凝缩的是condensin而非cohesin。","错误，使姐妹染色单体黏连的是cohesin而非condensin。","正确，cohesin负责黏连，condensin负责压缩DNA凝缩。","错误，二者在分裂前期即参与染色体凝缩与黏连。"]},"cards":null,"mem":"凝缩蛋白condensin，黏连蛋白cohesin","big":"assets/img/ch09/big/p010.jpg","summary":"考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「凝缩蛋白condensin」的核心内容，能解释其机制、比较相关概念。","intuition":"凝缩蛋白像“把毛线缠成团”：把细长的染色质卷紧、缩成光镜下可见的染色体。"},{"i":10,"sec":"","title":"Different cell cycle length","notes":"The greatest variation occurs in the duration of G1\nThe shortest eukaryotic division cycles of all are the early\nembryonic cell cycles, no G1 and G2\n【中文讲解·对照课本/考点】\n考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题为“细胞周期长度的差异”（different cell cycle length）。原文指出：细胞周期各时相中变化最大的是G1期（G1 phase），即G1期长短决定周期总时长。最短的真核分裂周期是早期胚胎细胞周期（early embryonic cell cycles），它们缺少G1期和G2期，只有S期与M期交替，因此细胞只分裂不生长。联系翟中和《细胞生物学》第十三章：不同细胞周期长短的差异主要源于G1期，早期卵裂属特殊细胞周期。","page":11,"level":"掌握","img":"assets/img/ch09/p011.jpg","anim":null,"fig":null,"points":["细胞周期时间变化最大的是G1期","最短的真核细胞分裂周期是早期胚胎细胞周期，没有G1和G2期"],"check":{"q":"关于真核细胞周期长短的差异，下列叙述正确的是？","o":["A. 各时相中变化最大的是S期，其长短决定周期总时长","B. 早期胚胎细胞周期缺少G1期和S期，只进行M期","C. 早期胚胎细胞周期具有完整的G1期和G2期","D. 各时相中变化最大的是G1期，其长短决定周期总时长"],"a":"D","e":"细胞周期各时相中变化最大的是G1期，G1长短决定周期总时长；早期胚胎细胞周期缺少G1和G2，只有S期与M期交替，故细胞只分裂不生长。","oe":["错误，变化最大的是G1期而不是S期。","错误，早期胚胎周期缺少的是G1和G2而非S期。","错误，早期胚胎细胞周期缺少G1期和G2期。","正确，各时相中G1期变化最大并决定周期总时长。"]},"cards":null,"mem":"周期变异最大在G1，早期胚胎无G1/G2","big":"assets/img/ch09/big/p011.jpg","summary":"考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「Different cell cycle length」的核心内容，能解释其机制、比较相关概念。","intuition":"不同细胞周期长短不同：变化最大在 G1；早期胚胎细胞甚至没有 G1、G2。"},{"i":11,"sec":"","title":"特殊的细胞周期","notes":"During early embryonic cell cycles, the egg\ncytoplasm is rapidly divided into smaller cells.\nThe cells do not grow during these cycles, which\nlack G1 and G2.\n【中文讲解·对照课本/考点】\n考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期◆概念：细胞从一次有丝分裂结束到下一次有丝分完成所经历的一个有序过程。其间细胞遗传物质和其他内含物分配给子细胞。◆细胞周期时相组成\n\n【本页英文讲解】\n本页主题是“特殊的细胞周期——非洲爪蟾的早期卵裂”。原文说明：早期胚胎细胞周期（early embryonic cell cycles）中，卵细胞质（egg cytoplasm）被迅速分割成许多更小的细胞；这些周期中细胞并不生长，且缺少G1期和G2期，仅有DNA复制（S期）与分裂（M期）交替，故分裂速度极快。这是典型的特殊细胞周期，考查早期卵裂周期缺乏G1、G2这一特点。","page":12,"level":"掌握","img":"assets/img/ch09/p012.jpg","anim":null,"fig":null,"points":["●非洲爪蟾的早期卵裂"],"check":{"q":"非洲爪蟾早期卵裂细胞周期的特点是？","o":["A. 缺少S期和M期","B. 缺少G1和G2期，仅S期与M期交替","C. 与普通体细胞周期完全相同","D. 细胞明显生长增大后才进行分裂"],"a":"B","e":"早期胚胎细胞周期中卵细胞质被迅速分割成更小的细胞，细胞不生长，且缺少G1期和G2期，仅S期与M期交替，故分裂速度极快。","oe":["错误，早期卵裂仍有S期和M期交替。","正确，早期卵裂周期缺乏G1、G2期。","错误，其缺少G1、G2，与体细胞不同。","错误，这些周期中细胞并不生长。"]},"cards":null,"mem":"爪蟾早期卵裂：只有S/M，无G1、G2","big":"assets/img/ch09/big/p012.jpg","summary":"考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「特殊的细胞周期」的核心内容，能解释其机制、比较相关概念。","intuition":"特殊周期像“压缩版”：早期胚胎细胞周期极短、省掉 G1/G2，只为快速分裂。"},{"i":12,"sec":"","title":"特殊的细胞周期","notes":"酵母细胞的周期包括G1期、S期、G2期和M期四个时相，持续时间较短，约90 min。酵母细胞分裂属于封闭式分裂：核膜不解聚，纺锤体位于核内。","page":13,"level":"掌握","img":"assets/img/ch09/p013.jpg","anim":null,"fig":null,"points":["●酵母","包括G1 期、 S 期、","酵母细胞周期持续","细胞分裂过程属于"],"check":{"q":"酵母细胞周期的特点之一是？","o":["A. 核膜裂解，属于开放式分裂","B. 细胞周期中完全没有S期","C. 核膜不解聚，纺锤体位于核内(封闭式分裂)","D. 周期持续数天，分裂十分缓慢"],"a":"C","e":"酵母细胞周期包括G1、S、G2、M期，持续时间约90min；其分裂为封闭式，核膜不解聚，纺锤体位于核内。","oe":["错误，酵母核膜不解聚，为封闭式分裂。","错误，酵母周期含G1、S、G2、M期。","正确，酵母属封闭式分裂，纺锤体在核内。","错误，酵母周期较短，约90min。"]},"cards":null,"mem":"酵母周期约90min，封闭式分裂核膜不破","big":"assets/img/ch09/big/p013.jpg","summary":"酵母细胞的周期包括G1期、S期、G2期和M期四个时相，持续时间较短，约90 min","goal":"学完应能掌握并运用「特殊的细胞周期」的核心内容，能解释其机制、比较相关概念。","intuition":"酵母周期约 90min，属封闭式分裂：核膜不解体，纺锤体在核内。"},{"i":13,"sec":"","title":"细胞社会成员的类型","notes":"根据细胞的分裂情况分为：\n细胞周期持续运转。如造血干细胞(产生红细胞、白细胞)、\n肠干细胞、上皮基底层细胞、植物根茎尖细胞等。\n期, 但在一定因素诱导下可重新进行细胞分裂。肝细胞、\nB淋巴细胞(与抗原相互作用而诱导)、结缔组织中的成纤维细胞\n(伤口愈合时大量产生)。\n生不再分裂直到死亡的细胞。 如红细胞/白细胞、肌细胞、\n神经细胞(北大书丁明孝等主编5th，327页第二段开头第一句)等。\n神经干细胞？(成年哺乳动物脑中特定区域存在？北大书5th，317页)","page":14,"level":"掌握","img":"assets/img/ch09/p014.jpg","anim":null,"fig":null,"points":["周期性细胞(cycling cell)：连续分裂, 不断产生新细胞，","G0期细胞/休眠细胞(quiescent cell)：暂时离开细胞周","终末分化细胞：机体内分化程度很高, 一旦生成则终"],"check":{"q":"关于不同类型细胞的说法，正确的是？","o":["A. 神经细胞能持续分裂产生新细胞","B. 红细胞属于周期性细胞，不断分裂","C. G0期细胞永远失去分裂能力","D. 肝细胞、成纤维细胞属G0期细胞，可被诱导重新分裂"],"a":"D","e":"周期性细胞持续分裂(造血干细胞等)；G0期细胞暂时离开周期、可在诱导下重新分裂(肝细胞、B淋巴细胞、成纤维细胞)；终末分化细胞不再分裂(红细胞、肌细胞、神经细胞)。","oe":["错误，神经细胞属终末分化细胞，不再分裂。","错误，红细胞属终末分化细胞，不再分裂。","错误，G0期细胞在诱导下可重新进入周期。","正确，肝细胞与成纤维细胞为G0期休眠细胞。"]},"cards":null,"mem":"三类：周期性、休眠G0、终末分化","big":"assets/img/ch09/big/p014.jpg","terms":[{"t":"周期性细胞","en":"cycling cell","d":"持续进行分裂的细胞。"},{"t":"休眠细胞","en":"quiescent cell","d":"暂不分裂、受刺激后可再进入周期的细胞（如肝细胞）。"},{"t":"终末分化细胞","en":"terminally differentiated cell","d":"高度分化、不再分裂的细胞。"}],"summary":"根据细胞的分裂情况分为：","goal":"学完应能掌握并运用「细胞社会成员的类型」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞分三种“上班状态”：周期性细胞（一直分裂）、休眠细胞（暂停可再启）、终末分化细胞（不再分裂）。"},{"i":14,"sec":"","title":"周期性细胞：上皮基底层细胞","notes":"Cell replacement occurs in the epidermis\n皮肤中，表皮的外层不断剥落被下面新的细胞层\n代替，the epidermis turns over every two weeks.\n【中文讲解·对照课本/考点】\n考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期◆概念：细胞从一次有丝分裂结束到下一次有丝分完成所经历的一个有序过程。其间细胞遗传物质和其他内含物分配给子细胞。◆细胞周期时相组成\n\n【本页英文讲解】\n本页主题是“周期性细胞（cycling cells）：上皮基底层细胞”。原文指出，皮肤表皮（epidermis）中发生细胞替换（cell replacement）：最外层不断剥落，由下方新的细胞层补充，表皮约每两周（every two weeks）更新一次（the epidermis turns over every two weeks）。基底层细胞属于持续分裂的周期性细胞，是组织更新的来源，对应教材中周期性细胞与终末分化细胞的分类。","page":15,"level":"掌握","img":"assets/img/ch09/p015.jpg","anim":null,"fig":null,"points":["皮肤表皮外层不断剥落，由下面新的细胞层代替","表皮约每两周(the epidermis turns over every two weeks)更新一次"],"check":{"q":"关于皮肤表皮的细胞更新，下列叙述正确的是？","o":["A. 表皮最外层不断剥落，由基底层细胞增殖补充，约每两周更新一次","B. 表皮细胞形成后即不再分裂，不发生细胞替换","C. 表皮更新周期很短，约为24小时即完全更新","D. 基底层细胞属终末分化细胞，已丧失分裂能力"],"a":"A","e":"皮肤表皮最外层不断剥落，由下方基底层细胞增殖补充，表皮约每两周更新一次；基底层细胞属持续分裂的周期性细胞。","oe":["正确，表皮由基底层细胞补充，约每两周更新一次。","错误，表皮存在持续的细胞替换并不断更新。","错误，表皮约每两周更新一次而非24小时。","错误，基底层细胞是能持续分裂的周期性细胞。"]},"cards":null,"mem":"周期性细胞如上皮基底层，表皮两周更新","big":"assets/img/ch09/big/p015.jpg","summary":"皮肤中，表皮的外层不断剥落被下面新的细胞层","goal":"学完应能掌握并运用「周期性细胞：上皮基底层细胞」的核心内容，能解释其机制、比较相关概念。","intuition":"上皮基底层细胞像“不断补员的岗位”：持续分裂补充脱落的表皮，约两周换一批。"},{"i":15,"sec":"","title":"哺乳动物小肠上皮细胞的更新","notes":"哺乳动物小肠上皮细胞更新和干细胞增殖补充：上皮细胞从底部隐窝处不断分裂的干细胞产生，沿着上皮层向上移动，到达小肠微绒毛顶部后死亡、脱落入肠腔。人体内完成一次更新约需3–6天。","page":16,"level":"掌握","img":"assets/img/ch09/p016.jpg","anim":null,"fig":null,"points":["小肠上皮细胞由底部隐窝处不断分裂的干细胞产生","细胞沿上皮层向上移动，到达微绒毛顶部后死亡脱落入肠腔","人体内约需3–6天"],"check":{"q":"哺乳动物小肠上皮细胞更新的来源是？","o":["A. 肠腔中脱落的成熟上皮细胞","B. 微绒毛顶部的终末分化细胞","C. 底部隐窝处不断分裂的干细胞","D. 随血液迁移而来的淋巴细胞"],"a":"C","e":"小肠上皮细胞由底部隐窝处不断分裂的干细胞产生，沿上皮层向上移动，到达微绒毛顶部后死亡脱落入肠腔，人体内约需3-6天完成更新。","oe":["错误，脱落入肠腔的是衰老死亡的上皮细胞。","错误，顶部终末分化细胞已不能增殖补充。","正确，底部隐窝的干细胞分裂产生新的上皮细胞。","错误，淋巴细胞并非小肠上皮更新的来源。"]},"cards":null,"mem":"小肠上皮：隐窝干细胞上移，3-6天脱落","big":"assets/img/ch09/big/p016.jpg","summary":"哺乳动物小肠上皮细胞更新和干细胞增殖补充：上皮细胞从底部隐窝处不断分裂的干细胞产生，沿着上皮层向上移动，到达小肠微绒毛顶部后死亡、脱落入肠腔","goal":"学完应能掌握并运用「哺乳动物小肠上皮细胞的更新」的核心内容，能解释其机制、比较相关概念。","intuition":"小肠上皮像“传送带换人”：隐窝干细胞不断产生新细胞，上移 3–6 天后脱落。"},{"i":16,"sec":"","title":"造血干细胞的分化（血细胞谱系）","notes":"血细胞苏木精染色显示，造血干细胞可分化为多种血细胞：中性粒细胞、嗜酸性粒细胞、嗜碱性粒细胞、巨噬细胞、血小板、巨核细胞、破骨细胞、淋巴细胞等。这些细胞均属血细胞谱系，由造血干细胞分化产生。","page":17,"level":"掌握","img":"assets/img/ch09/p017.jpg","anim":null,"fig":null,"points":["造血干细胞可分化为多种血细胞","包括中性/嗜酸/嗜碱性粒细胞、巨噬细胞、血小板、巨核细胞、破骨细胞等"],"check":{"q":"下列哪组细胞均可由造血干细胞分化而来？","o":["A. 神经元、心肌细胞、肝细胞","B. 中性粒细胞、巨噬细胞、血小板","C. 表皮细胞、成纤维细胞、软骨细胞","D. 骨骼肌细胞、脂肪细胞、胰岛B细胞"],"a":"B","e":"中性粒细胞、巨噬细胞、血小板以及破骨细胞、巨核细胞等均属血细胞谱系，由造血干细胞分化产生。","oe":["错误，神经元、心肌、肝细胞并非造血干细胞来源。","正确，中性粒细胞、巨噬细胞、血小板均源自造血干细胞。","错误，表皮、成纤维、软骨细胞不属血细胞谱系。","错误，骨骼肌、脂肪、胰岛B细胞非造血起源。"]},"cards":null,"mem":"造血干细胞分化出各类血细胞与巨核/血小板","big":"assets/img/ch09/big/p017.jpg","summary":"血细胞苏木精染色显示，造血干细胞可分化为多种血细胞：中性粒细胞、嗜酸性粒细胞、嗜碱性粒细胞、巨噬细胞、血小板、巨核细胞、破骨细胞、淋巴细胞等","goal":"学完应能掌握并运用「造血干细胞的分化（血细胞谱系）」的核心内容，能解释其机制、比较相关概念。","intuition":"造血干细胞像“血细胞的祖师爷”：可分化出各种血细胞。"},{"i":17,"sec":"","title":"B细胞受抗原刺激开始细胞分裂","notes":"产生大量抗体。-休眠细胞\n肝脏再生\n\n【读图讲解】\n本页说明休止细胞受刺激后可重返分裂，以B细胞和肝再生为例。左侧主题为B细胞受抗原刺激开始细胞分裂并产生大量抗体：静息B细胞表面带有能识别特定抗原的膜结合抗体，不同B细胞携带不同抗体；当抗原与其表面抗体结合，该B细胞被刺激而增殖，并分泌大量相同的可溶性抗体。右侧为肝脏再生：切除三分之二肝脏后，剩余细胞增殖，肝组织逐渐再生恢复。要点：休止细胞在一定条件下可重新进入细胞周期。","page":18,"level":"掌握","img":"assets/img/ch09/p018.jpg","anim":null,"fig":null,"points":["B细胞受抗原刺激开始细胞分裂，产生大量抗体","休眠细胞(如肝细胞)受刺激可再生，如肝脏再生"],"check":{"q":"关于休止细胞重返细胞周期，下列叙述正确的是？","o":["A. 切除大部分肝脏后剩余肝细胞不能再增殖","B. 休止细胞一旦进入G0便永久失去分裂能力","C. 静息B细胞受抗原刺激后停止分裂只合成抗体","D. 静息B细胞受抗原刺激后可增殖并分泌大量抗体"],"a":"D","e":"静息B细胞表面膜抗体结合抗原后被刺激增殖，并分泌大量相同抗体；肝脏再生实验也说明休止细胞在一定条件下可重返细胞周期。","oe":["错误，肝切除后剩余细胞可增殖使肝组织再生。","错误，休止细胞受刺激后可重新进入细胞周期。","错误，受抗原刺激的B细胞会增殖而非停止分裂。","正确，静息B细胞受刺激后可增殖并分泌大量抗体。"]},"cards":null,"mem":"B细胞遇抗原产抗体，肝再生=休眠细胞复苏","big":"assets/img/ch09/big/p018.jpg","summary":"本页说明休止细胞受刺激后可重返分裂，以B细胞和肝再生为例","goal":"学完应能掌握并运用「B细胞受抗原刺激开始细胞分裂」的核心内容，能解释其机制、比较相关概念。","intuition":"B 细胞像“按需扩军的部队”：受抗原刺激才大量分裂、产生抗体。"},{"i":18,"sec":"","title":"细胞周期控制系统对周期主要过程的触发","notes":"major processes of the cell cycle\n1) The cell cycle control system is based on cyclically actived\nprotein kinases---cyclin-dependent kinases (Cdks).\nEngine molecules for cell cycle\n2) The control system can arrest the cell cycle at specific\ncheckpoints.\nThe Brake\n【中文讲解·对照课本/考点】\n考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题为“细胞周期控制系统触发细胞周期的主要事件”。原文提出两点：①细胞周期控制系统基于周期性激活的蛋白激酶（cyclin-dependent kinases，Cdks，周期蛋白依赖性激酶），被喻为细胞周期的“引擎”（engine molecules）；②控制系统可在特定检验点（checkpoints）阻滞细胞周期，相当于“刹车”（brake）。这是理解周期调控引擎与刹车两大核心的引言。","page":19,"level":"掌握","img":"assets/img/ch09/p019.jpg","anim":null,"fig":null,"points":["细胞周期控制系统基于周期性激活的蛋白激酶——周期蛋白依赖性激酶(Cdks)，是细胞周期的引擎分子","控制系统可在特定检验点阻滞细胞周期"],"check":{"q":"细胞周期控制系统被喻为周期的“引擎”和“刹车”，分别指？","o":["A. 周期性激活的CDK与检验点阻滞","B. 检验点阻滞与周期性激活的CDK","C. 周期蛋白与蛋白酶体","D. 纺锤体与着丝粒"],"a":"A","e":"周期蛋白依赖性激酶(Cdks)周期性激活驱动周期运行，被称为引擎；控制系统可在特定检验点阻滞周期，相当于刹车。","oe":["正确，引擎指CDK，刹车指检验点阻滞。","错误，引擎与刹车的对应关系被颠倒。","错误，周期蛋白是CDK调节亚基，蛋白酶体非刹车。","错误，纺锤体与着丝粒不构成引擎与刹车。"]},"cards":null,"mem":"周期控制核心=周期性激活的CDK激酶","big":"assets/img/ch09/big/p019.jpg","summary":"考点：一 细胞周期的概念 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「细胞周期控制系统对周期主要过程的触发」的核心内容，能解释其机制、比较相关概念。","intuition":"周期控制系统像“总控室”：以 CDK 为核心，按序触发复制、分裂等大事件。"}],"mcq":[{"id":"ch09_mcq_7","mod":"一 细胞周期的概念","modI":1,"q":"在减数分裂 S 期 DNA 并不完全复制，大约还有（             ）DNA 是在偶线期合成的。","o":["A．100%","B．50%","C．10%","D．0.3%"],"a":"D","e":"偶线期发生的重要事件：（1）同源染色体配对；（2）合成在 S 期未合成的约 0.3% 的 DNA（偶线期 DNA）。","kp":"ch09_s1_4","oe":["若全部未复制则与事实不符，偶线期仅合成极少量DNA。","数值明显过大，S期已复制绝大部分DNA。","数值偏大，偶线期合成的DNA仅占约0.3%。","正确。偶线期合成S期未合成的约0.3%DNA，即偶线期DNA。"]}],"judge":[{"id":"ch09_judge_1","modI":1,"q":"细胞分裂时内质网要经历解体与重建的过程。（           ）","a":"对","e":"","kp":"ch09_s1_17","oe":["有丝分裂时内质网解体、分散，分裂后重新聚合重建，表述正确。","若判错，则忽视内质网在分裂期解体、分裂后重建的事实。"]},{"id":"ch09_judge_2","modI":1,"q":"早期胚胎细胞细胞周期短，随着卵裂球数量增加，其总体积也随着增加。（                      ）","a":"错","e":"卵细胞在成熟过程中已积累了大量的物质基础，基本满足早期胚胎发育的物质需要， 子细胞在 G1、G2 期并不生长，越分裂体积越小，但总体积并不增加。","kp":"ch09_s1_3","oe":["若判对则忽略卵裂期子细胞不生长，分裂后体积减小，总体积不增。","早期卵裂球只分裂不生长，子细胞越小，胚胎总体积并不增加。"]},{"id":"ch09_judge_3","modI":1,"q":"正常细胞在有丝分裂中期时，每条染色体的动粒均已分别结合来自纺锤体两极的微管。 （     ）","a":"对","e":"","kp":"ch09_s1_7","oe":["中期每条染色体的两个动粒分别连接来自两极的动粒微管。","若判错，则中期染色体确已实现双极动粒微管连接，否定无据。"]},{"id":"ch09_judge_6","modI":1,"q":"G0 细胞是永远失去了分裂能力的细胞。（      ）","a":"错","e":"G0 细胞是暂时处于休眠状态的细胞，在受到适当的刺激后会回重返细胞周期进行 分裂繁殖。","kp":"ch09_s1_12","oe":["认为G0期细胞已永久脱离细胞周期，不再具有分裂能力。","G0只是暂时休眠，受适当刺激后可重返周期、恢复分裂繁殖。"]},{"id":"ch09_judge_12","modI":1,"q":"在细胞周期中，如果纺锤体装配不正常，则被阻止于 G2 期。（           ）","a":"错","e":"纺锤体组装检验点存在于细胞分裂中期，监控纺锤体微管与染色单体动粒的连接、 染色体在赤道面的队列和向纺锤体两极的分离等。上述事件未正确完成前，该检验点阻止细 胞从分裂中期进入后期。","kp":"ch09_s1_12","oe":["误认为纺锤体装配检验点位于G2期，故判对。","纺锤体组装检验点位于分裂中期，异常时阻止细胞由中期进入后期。"]},{"id":"ch09_judge_13","modI":1,"q":"体细胞只能进行有丝分裂，生殖细胞只能进行减数分裂。（              ）","a":"错","e":"生殖细胞还可进行有丝分裂。","kp":"ch09_s1_4","oe":["误以为生殖细胞只进行减数分裂，故判对。","生殖细胞（如精原、卵原细胞）也能进行有丝分裂增殖，并非只能减数分裂。"]},{"id":"ch09_judge_15","modI":1,"q":"不同生物及同一生物的不同细胞的细胞周期时间是不同的，其中 G1 期持续时间的差异最 大。（      ）","a":"对","e":"细胞周期时间长短主要差别在 G1 期，而 S、G2、M 总时间是相对恒定的。","kp":"ch09_s1_3","oe":["周期长短差异主要在G1期，S、G2、M总时间相对恒定。","误以为各期时长可变性相同，其实G1期持续时间的差异最大。"]},{"id":"ch09_judge_16","modI":1,"q":"所渭 Hayflick 界限是指细胞分化的极限。（      ）","a":"错","e":"Hayflick 界限是指细胞分裂次数的极限。","kp":"ch09_s1_17","oe":["误以为Hayflick界限指细胞分化的极限，故判对。","Hayflick界限指正常细胞体外分裂次数的极限，与分化程度无关。"]}],"fill":[{"id":"ch09_fill_2","modI":1,"q":"根据增殖状况，可将细胞分类三类，分别为______、______、______。","a":"周期中细胞；静止期细胞（G0 细胞）；终末分化细胞","kp":"ch09_s1_17","oe":["持续分裂的细胞，不断循环于细胞周期。","暂时退出周期进入G0期，受刺激可重返分裂。","高度分化失去分裂能力，不再进入细胞周期。"]},{"id":"ch09_fill_3","modI":1,"q":"和动物细胞的细胞周期相比较，植物细胞的细胞周期两个突出特点是______和______。","a":"不含中心体；以中间板形式进行胞质分裂","kp":"ch09_s1_2","oe":["植物细胞无中心体，纺锤体由无中心体机制形成。","靠细胞板扩展形成新壁来完成胞质分裂。"]},{"id":"ch09_fill_4","modI":1,"q":"中心体在______期末开始复制。到达______期，细胞已经含有一对中心体，但两者不分 开。到达______期，一对中心体开始分离，移向两极。","a":"G1 期；S 期；G2 期","kp":"ch09_s1_4","oe":["中心体在G1期开始复制，为S期提供拷贝基础。","到达S期细胞已含一对中心体，但两者不分开。","到达G2期一对中心体开始分离，并移向两极。"]},{"id":"ch09_fill_8","modI":1,"q":"原核生物的细胞周期分为：______、______、______。","a":"启动期；DNA 合成期；细胞分裂期","kp":"ch09_s1_1","oe":["细胞生长并启动复制，为DNA合成做准备。","进行DNA复制，使遗传物质加倍。","完成分裂，将DNA均等分配给子细胞。"]},{"id":"ch09_fill_9","modI":1,"q":"细胞分裂的方式有：______、______、______。","a":"无丝分裂；有丝分裂；减数分裂","kp":"ch09_s1_17","oe":["核直接缢裂，无纺锤体和染色体变化，如蛙红细胞。","体细胞分裂方式，染色体均等分配，维持数目恒定。","生殖细胞分裂方式，染色体减半，形成配子。"]},{"id":"ch09_fill_13","modI":1,"q":"细菌的细胞周期最短的时间为______min，最长可达______min，这与环境有关。","a":"20；100","kp":"ch09_s1_12","oe":["细菌周期最短约20分钟，如快速生长的大肠杆菌。","最长可达100分钟，取决于营养等环境条件。"]},{"id":"ch09_fill_14","modI":1,"q":"细胞周期中各个时期的长短各有不同，但一般说来，______期长，______期短。","a":"S；M","kp":"ch09_s1_3","oe":["S期即DNA合成期，时间较长，以完成DNA复制。","M期即分裂期，时间较短，相对快速完成。"]},{"id":"ch09_fill_16","modI":1,"q":"常用的细胞同步化方法有______和______等。","a":"选择同步化；诱导同步化","kp":"ch09_s1_12","oe":["利用细胞物理性质差异，分离出同一时相的细胞。","用药物或营养抑制使细胞积累于某时相而同步。"]},{"id":"ch09_fill_17","modI":1,"q":"减数分裂过程中变化最为复杂的时相为______。","a":"减数分裂Ⅰ的前期","kp":"ch09_s1_12","oe":["减数分裂Ⅰ前期经历细线、偶线、粗线、双线、终变期，变化最复杂。"]},{"id":"ch09_fill_19","modI":1,"q":"各种细胞的细胞周期时间（Tc）长短不一，有的细胞只有数十分钟，如______细胞，有 的可长达数月之久，如______细胞和______细胞。","a":"胚胎；休眠；卵母","kp":"ch09_s1_3","oe":["胚胎细胞周期很短，仅数十分钟，分裂迅速。","休眠细胞可长期停留，细胞周期长达数月之久。","卵母细胞停留于减数分裂，周期可长达数月。"]},{"id":"ch09_fill_27","modI":1,"q":"G1 期细胞同 S 期细胞融合，则 S 期细胞__________，G1 期细胞_________。G2 期细胞同 S 期细胞融合，则 S 期细胞__________，G2 期细胞_________。G1、S 和 G2 期细胞分别同 M 期细胞融合，则 Gl、S 及 G2 细胞均产生________。","a":"染色体凝聚；发生染色体复制；DNA 复制加快；保持不变；染色体超前凝聚","kp":"ch09_s1_4","oe":["S期细胞受G1期细胞影响，染色质发生凝聚","G1期细胞被S期细胞诱导，提前启动DNA复制","S期细胞受G2期细胞作用，DNA复制速度加快","G2期细胞已完成DNA复制，故保持不变","M期成熟促进因子使G1、S、G2染色质均超前凝聚"]}],"short":[{"id":"ch09_short_1","modI":1,"q":"细胞增殖有何意义？","a":"细胞增殖的意义是： （1）细胞增殖是细胞生命活动的重要特征之一，是生物繁育的基础。 （2）单细胞生物细胞增殖导致生物个体数量的增加。 （3）多细胞生物由一个单细胞（受精卵）分裂发育而来，细胞增殖是多细胞生物繁殖的基 础。 （4）成体生物仍然需要细胞增殖，主要取代衰老死亡的细胞，维持个体细胞数量的相对平 衡和机体的正常功能。 （5）创伤愈合、组织再生、病理组织修复等，都要依赖细胞增殖。","kp":"ch09_s1_4"},{"id":"ch09_short_4","modI":1,"q":"植物细胞的细胞周期有何特点？","a":"（1）植物细胞的细胞周期与动物细胞的标准细胞周期非常相似，含有 G1 期、S 期、C2 期和 M 期四个时期；（2）植物细胞不含中心体，但在细胞分裂时可以正常组装纺锤体；（3） 植物细胞以形成中板的形式进行胞质分裂。","kp":"ch09_s1_2"},{"id":"ch09_short_7","modI":1,"q":"下面的叙述有错误吗？请指出并解释。“生殖细胞和体细胞 DNA 的稳定对于一种物种的 生存都是至关重要的。”","a":"这种说法是正确的。如果体细胞中的 DNA 不够稳定（即如果积累突变过程过快）则导 致个体死亡（如死于肿瘤），因为这些突变常发生在生物繁殖之前，因此导致该物种的灭绝。 如果生殖细胞中的 DNA 不够稳定，就会积累许多突变并传递给后代，所以该物种将难以维 持下去。","kp":"ch09_s1_2"},{"id":"ch09_short_8","modI":1,"q":"细胞内的突变使编码参与 DNA 复制的蛋白质的基因失活。在没有这种蛋白质的情况下， 细胞内的 DNA 复制仍然尽可能地进行。如果下列蛋白质消失，将会产生什么样的 DNA 产 物？ （1）DNA 聚合酶； （2）DNA 连接酶； （3）DNA 聚合酶的滑动夹钳； （4）清除 RNA 引物的切除酶； （5）DNA 解旋酶: （6）引物酶。","a":"（1）无 DNA 聚合酶，复制根本不可能进行，RNA 引物将在复制起始位点积累。 （2）DNA 连接酶负责连接后随链上合成的 DNA 片段。没有连接酶，则新复制的 DNA 链 将保持片段状态，但核苷酸不会丢失。 （3）无滑动夹钳，DNA 聚合酶常会脱离 DNA 模板，虽然原则上能够再结合上来并继续反 应，但不断地脱离与再结合将会耗费很多时间，从而大大降低 DNA 复制的速度。 （4）没有 RNA 切除酶，则 RNA 片段将保持与新复制的 DNA 片段共价连接。由于连接酶 不能将 DNA 连接于 RNA,连接反应不能进行。因此，后随链将由 RNA 和 DNA 片段两者组 成。 （5）没有 DNA 解旋酶，则 DNA 聚合酶将不会前进，因为它不能分开其前方模板 DNA 双 链，不合成或极少合成新的 DNA （6）无引物酶，则 RNA 引物在前导链或后随链上均不能合成。DNA 复制不能起始","kp":"ch09_s1_5"},{"id":"ch09_short_9","modI":1,"q":"在减数分裂Ⅰ中，姐妹染色单体为什么必须保持配对？","a":"减数分裂开始于 DNA 的复制，产生一个含有各条染色体 4 个拷贝的四倍体细胞，在随 后的两次减数分裂中这 4 个拷贝必须被均等分配至 4 个单倍体细胞。姐妹染色单体保持配对， 这样： （1）第一次减数分裂产生的细胞接受完整的两套染色体。 （2）在第二次减数分裂中染色体将会再次均等分配。如果姐妹染色单体不保持配对，在第 二次分裂中将不可能鉴别哪些染色单体应被组合在一起，因而很难保证每一染色单体的一个 拷贝被精确分配到每一个子细胞中。因而在第一次减数分裂中保持姐妹染色单体配对是一种 简易的方法，用于始终监视哪些染色单体应被分配在一起","kp":"ch09_s1_7"},{"id":"ch09_short_10","modI":1,"q":"比较有丝分裂与减数分裂的异同。","a":"见表 13-1。 表 13-1 有丝分裂与减数分裂的比较 有丝分裂           减数分裂 确保遗传的稳定性和生 体细胞以此方式进行分化与增 物变异，主要是生殖细胞 殖，维持机体发育和细胞更新 的分裂方式 DNA 复制一次，细胞分 DNA 复制一次，细胞分裂一次 裂两次 S 期时间相对较长       S 期时间相对较短 一个细胞产生四个子细 一个细胞产生两个子细胞 胞 常发生染色体的交叉互 不发生染色体互换 换，产生变异分裂时间 分裂时间短，1～2 小时 长，24 小时至几年","kp":"ch09_s1_4"},{"id":"ch09_short_11","modI":1,"q":"简述用放射性同位素 3H-TdR（氚胸腺嘧啶）标记法来测定细胞周期长短的原理。假如一 种体外培养的非同步生长细胞，它的细胞周期 G1 期是 6 小时，S 期是 6 小时，G2 期是 5 小 时，M 期是 1 小时，如果用 3H-TdR 标记细胞 15 分钟后，立即洗去 3H-TdR，然后放置在新 鲜培养基中继续培养。请问： （1）用 3H-TdR 标记 15 分钟后，这时被标记的细胞占细胞总数的百分比是多少？ （2）用 3H-TdR 标记 15 分钟后，洗净后放置在新鲜培养基中培养 18 小时，这时被标记的 M 期细胞又占多少比例？","a":"用 3H-TdR 标记法测定细胞周期长短的原理：用放射性同位素 3H-TdR（氚胸腺嘧啶） 标记细胞，3H-TdR（氚胸腺嘧啶）在 DNA 复制过程中被整合入新合成的 DNA 从而对细胞 做上标记。短暂标记后将细胞转移到新鲜普通培养基中培养，每隔一定时间取样做放射自显 影观察分析，从而确定细胞周期各时相的长短。 （1）用 3H-TdR 标记 15 分钟后，此时被标记的细胞是 S 期的细胞，占细胞总数的百分比： 6∕（6＋6＋5＋1）＝1/3。 （2）这类细胞的细胞周期刚好是 18 小时，因此培养 18 小时后所有的细胞均被标记。被标 记的 M 期细胞占 1/18。","kp":"ch09_s1_3"},{"id":"ch09_short_12","modI":1,"q":"试述减数分裂的概念、意义和特点。 相关试题：减数分裂前期Ⅰ发生染色体联会的生物学意义何在？","a":"（1）减数分裂的概念 减数分裂是细胞仅进行一次 DNA 复制，随后进行两次分裂、染色体数减半的一种特殊的有 丝分裂。减数分裂是仅发生于有性生殖细胞形成过程中的某个阶段的一种特殊的有丝分裂形 式，整个过程分为减数分裂Ⅰ和减数分裂Ⅱ两个阶段。 （2）减数分裂的意义 ①有效获得双亲的遗传物质，确保世代间遗传的稳定性； ②增加变异机会，确保生物的多样性，增加生物适应环境变化的能力； ③减数分裂是生物有性生殖的基础，是生物遗传、生物进化、生物多样性的重要基础保证。 （3）减数分裂的特点 ①遗传物质只复制一次，细胞连续分裂两次，染色体数目减半； ②S 期持续时间较长； ③同源染色体在减数分裂期Ⅰ配对联会，基因重组； ④同源染色体配对排列在中期赤道极上，第一次分裂时同源染色体分开。","kp":"ch09_s1_7"},{"id":"ch09_short_16","modI":1,"q":"用图文相结合的形式，叙述有丝分裂后期使染色体移向两极的三种马达模型。 相关试题：在动物细胞有丝分裂后期，有哪些分子马达作用于纺锤体的什么部位？各通过何 种运动来决定染色体分离和纺锤体长度？","a":"（1）有丝分裂后期使染色体移向两极的三种马达模型 ①星体微管马达：将有丝分裂器与细胞质膜连在一起。 ②极微管马达：负责将两极间的微管延长。 ③动粒微管马达（染色体微管马达）：负责缩短染色体微管的长度，使染色体向两极运动。 （2）三种马达使染色体移向两极的过程 有丝分裂后期分为后期 A 和后期 B 两个阶段。后期 A，动粒微管变短，牵动染色体向两极 运动；在后期 B，极微管长度增加，两极之间的距离逐渐拉长。 ①后期 A：微管马达蛋白首先结合到动粒上，在 ATP 分解提供能量的情况下，沿动粒微管 向极部运动，并带动动粒和染色体向极部运动。动粒微管的末端随之解聚成微管蛋白二聚体， 动粒微管变短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期 A 结束，转向后期 B。 ②后期 B：极微管游离端（正极）在 ATP 提供能量的情况下与微管蛋白聚合，使极微管加 长，形成较宽的极微管重叠区。KRPs 与极微管重叠区的微管结合并在来自两极的极微管之 间搭桥。KRPs 向微管正极行走，促使来自两极的极微管在重叠区相互滑动，使重叠区逐渐 变得狭窄，两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管和细胞膜之间搭桥， 并向星体微管负极运动，进一步将两极之间的距离拉长。     图 13-1 纺锤体结构模式图 图 13-2 细胞分裂后期 A 和后期 B 产生染色体向极部运动的示意图 六、实验题 已知某信号分子（分泌蛋白）引发的下游事件可抑制细胞分裂，我们推测该信号分子的受体 可能分布在细胞膜上。请你设计一个实验方案证实： （1）该信号分子的受体确实存在于细胞膜上； （2）该信号分子是通过与其受体的结合抑制了细胞分裂。 该实验应特别注意哪些关键环节？ 答：实验方案如下： 实验原理：绿色荧光蛋白（Green Fluorescent Protein，简称 GFP）是一种在美国西北海岸盛 产的水母中发现的一种蛋白质。它之所以能够发光，是因在其包含 238 个氨基酸的序列中， 第 65 至 67 个氨基酸（丝氨酸-酪氨酸-甘氨酸）残基可自发地形成一种荧光发色团。因此能 够直接看到细胞内部的运动情况，轻易地找出 GFP 蛋白所处的位置。 （1）本实验中，可以构建含有可以表达该信号分子基因与 GFP 基因的融合载体，然后将其 转化到细胞中。该载体就会在细胞中表达带有 GFP 蛋白的信号分子。如果该信号分子与细 胞膜上的受体蛋白结合，那么就会在细胞膜上观察到发光的 GFP 蛋白。该实验可以证明已 知信号分子的受体确实存在于细胞膜上。 （2）在（1）的方案基础上设立对照实验。 ①以无信号分子结合的正常细胞作为对照组。 ②构建带有可以与信号分子结合但是没有功能的受体片段，与信号分子竞争性结合，从而阻 止信号分子与受体的结合。 如果①和②情况下细胞正常分裂，则说明该信号分子是通过与其受体结合抑制了细胞分裂。 （3）注意事项： ①GFP 蛋白与已知信号分子融合后可能影响信号分子的构象从而影响信号分子的功能以及 与其受体的结合。 ②表达的受体片段应该与信号分子具有结合性，同时，需要保证该信号片段大量表达，具有 较高浓度，从而可以与信号分子产生竞争性结合。","kp":"ch09_s1_2"},{"id":"ch09_short_17","modI":1,"q":"9％）、偶线期和 粗线期 分裂前后，染色体的分裂后，染色体数目 染色体数目 数目恒定          减半 减数分裂前间期、减 有丝分裂间期和有 数分裂期Ⅰ、减数分 分裂过程 丝分裂期          裂间期、减数分裂期 Ⅱ 联会复合体    无             有 同源染色体非 姐妹染色单体 无              有（果蝇例外） 互换 确保世代遗传的稳 定性；增加变异机 会，确保生物的多样 细胞数目增多，多细性，增强生物适应环 生物学意义    胞生物体的体积增 境变化的能力；是生 大        物有性生殖的基础， 是生物遗传、生物进 化和生物多样性的 重要基础保证","a":"","kp":"ch09_s1_6"},{"id":"ch09_short_19","modI":1,"q":"说明细胞分裂过程中核膜破裂和重装配的调节机制。","a":"（1）细胞分裂过程中核膜破裂的调节机制 在细胞分裂的前期末，活化的 MPF 促使构成核纤层结构的核纤层蛋白磷酸化，导致核纤层 结构瓦解，核膜破裂形成膜泡。 （2）细胞分裂过程中重装配的调节机制 在细胞分裂末期，APC 介导有丝分裂周期蛋白的降解，导致 MPF 失活。染色体开始去凝集， 核纤层蛋白开始去磷酸化并围绕染色质重新形成核纤层结构，膜泡围绕核纤层结构重新形成 新的核膜。","kp":"ch09_s1_12"}],"calc":[{"id":"ch09_calc_1","modI":1,"q":"细胞分裂间期有哪些主要特点？","a":"与分裂期细胞的急剧而明显的形态变化相比，间期细胞的形态变化不明显，但其间进行 着比较复杂的化学变化。 间期细胞最显著的特征就是进行 DNA 的复制，其次就是进行 RNA 和蛋白质的合成。 （1）根据 DNA 的合成情况，又可把间期分为 DNA 合成前期（G1 期）、DNA 合成期（S 期）、 DNA 合成后期（G2 期）。其中 G1 期非常重要，Gl 期的限制点（R 点）是控制细胞 增殖的关键，决定了细胞的 3 种不同命运：①继续增殖细胞，细胞通过 R 点，连续进行增 殖，始终保持旺盛的增殖活性，能量代谢和物质代谢水平高，对外界信号高度敏感，分化程 度低，周期时间较为恒定；②暂不增殖细胞，细胞长时间地停留在 G1 期，合成大量特异性 的 RNA 和蛋白质，在结构和功能上发生分化。随后，代谢活性下降，处于细胞增殖的静止 状态（G0 期），但并没有丧失增殖的能力，在适宜的条件下被激活成增殖状态；③不再增 殖细胞，细胞丧失了增殖能力，始终停留在 G1 期，结构和功能上发生高度分化，直至衰老 死亡。 （2）细胞越过 R 点以后，就加速合成 DNA 复制所必需的各种前体物质和酶，同时，DNA 解旋酶和 DNA 合成启动因子也急剧增加，为进入 S 期 DNA 复制做准备。S 期最主要的特 点是 DNA 复制和组蛋白、非组蛋白等染色体组成蛋白质的合成，通过 DNA 复制精确地将 遗传物质传递给 M 期分裂的子细胞，保证遗传性状的稳定性。因此，S 期是整个细胞周期 中最关键的阶段。G2 期中加速合成 RNA 和蛋白质，其中最主要的是合成有丝分裂因子和微 管蛋白等有丝分裂器的组分。另外，细胞成分如磷脂的合成增加并进行能量 ATP 的积累， 为有丝分裂进行物质和能量的准备。总而言之，有丝分裂间期主要是细胞积累物质的生长过 程，只有缓慢的体积增加，形态上看不到明显的变化，但其间进行着旺盛的细胞代谢反应， 进行 DNA 的复制、RNA 和蛋白质的合成，为有丝分裂作准备。","kp":"ch09_s1_17"},{"id":"ch09_calc_3","modI":1,"q":"在研究促使 G1 期细胞 DNA 复制以及诱导细胞提前进入有丝分裂的调节因子的本质时， 为什么选用蛙和无脊椎动物的卵母细胞及早期的胚进行注射实验？","a":"一些动物的受精卵特别适合作为细胞周期的研究材料，因为这些卵细胞特别大，如蛙的 卵细胞的直径可达 1mm，并且在受精后进行快速胚胎发育，通过细胞周期进行分裂，产生 许多小细腮在每个细胞周期之间，G1 期和 G2 期很短，或没有 G1 期和 G2 期，但是都有 S 期 和 M 期。在受精卵的发育过程中，没有新基因的转录，因为胚胎早期发育阶段所需的 mRNA 和大多数蛋白质都是在卵母细胞形成时就合成好了并被包装在成熟的卵细胞中。另外在早期 的细胞分裂周期中，细胞也不会生长，所有的细胞都是通过对称分裂形成两个小细胞。 在细胞周期的特定阶段分离蛙的卵细胞，并从蛙卵细胞中制备提取物。为了检测蛙卵提取物 的生物活性，将它注射到非洲爪蟾的卵母细胞（未受精卵的不成熟的前体），观察这些提取 物对细胞周期的影响。这种卵母细胞是检测提取物活性的良好系统，因为这种细胞已经完成 了 DNA 复制并正好停留在第一次有丝分裂的 M 期之前，如果注射物具促分裂活性，即可 使注射的卵母细胞进入 M 期。因此卵母细胞所处的细胞周期阶段等于周期细胞的 G2 期。","kp":"ch09_s1_4"},{"id":"ch09_calc_5","modI":1,"q":"细胞增殖有哪几种方式?各有什么特点？","a":"细胞增殖的方式有三种。 （1）无丝分裂又称直接分裂，它是指处于间期的细胞核不经任何有丝分裂时期而分裂为大 致相等的两部分的细胞分裂。该分裂过程简单、快速，在分裂中既没有染色体、纺锤体的形 成，也无核膜、核仁的解体，而是直接进行细胞核与细胞质的分裂。 （2）有丝分裂主要指细胞分裂过程中细胞核有明显的形态学化，特别是染色质的凝集和有 丝分裂器的形成。有丝分裂器在维持染色体的平衡、运动、分配中起着重要的作用。通过有 丝分裂，细胞将已复制加倍的 DNA 精确地平均分配到 2 个子细胞中，使分裂后的子细胞保 持遗传上的一致性。 （3）减数分裂。是有性生殖个体形成生殖细胞过程中发生的一种特殊的分裂方式。整个细 胞周期经过 2 次细胞分裂，而 DNA 只复制一次，这样就由染色体数目为 2n 的体细胞产生 出染色体数目减半（n）的精子或卵细胞。这样产生的精卵细胞再经受精后,形成的受精卵的 染色体数又恢复原来的二倍体数目，维持物种遗传的稳定性。","kp":"ch09_s1_4"},{"id":"ch09_calc_8","modI":1,"q":"细胞周期时间是如何测定的？","a":"常用的细胞周期时间测定方法有三种： （1）脉冲标记 DNA 复制和细胞分裂指数观察测定法 这是一种测定细胞周期时间的常用方法，适用于细胞种类构成相对简单、细胞周期时间相对 较短、周期运转均匀的细胞群体。该方法的测定过程如下： ①用 3H-TdR 对测定细胞进行脉冲标记，定时取材并利用放射自显影技术显示标记细胞，统 计标记的有丝分裂细胞的比例（PLM），以标记后的时间为横坐标，以标记的有丝分裂细 胞的比例为纵坐标，通过读图测定细胞周期，一般常采用半高度读数法。 ②一个细胞群体中细胞周期时间（Tc）和各时相不尽相同，第一个峰常达不到 100％，以后 的峰会发生衰减，PLM 不一定会下降到零。所以实际测量时，常以 （ ＋1/2TM） —     的方式求出 TM。 （2）流式细胞仪测定法 当细胞分别处于 G1、S、G2、M 期时，其细胞内的 DNA 含量不同。利用流式细胞仪可以测 定单个细胞内的 DNA 含量。该方法的测定过程如下： ①应用某些药物对细胞进行处理，将细胞抑制在细胞周期的某个特定时期； ②将细胞从抑制状态中释放出来，所有细胞将会同步运转，在不同时段应用流式细胞仪分别 测定这些细胞内的 DNA 含量，以释放后的时间为横坐标，单个细胞内 DNA 含量为纵坐标 作图，通过读图可以求出 G1、S、G2、M 期时间的长短。 （3）其他方法 ①通过显微缩时摄像技术可以求出分裂间期和分裂期的准确时间； ②通过在不同的时间对细胞群体进行计数，可以推算出细胞群体的倍增时间，即细胞周期的 总时间。","kp":"ch09_s1_3"},{"id":"ch09_calc_10","modI":1,"q":"试比较有丝分裂与减数分裂的异同点。","a":"（1）有丝分裂与减数分裂的相同点 有丝分裂与减数分裂都是通过纺锤体与染色体的相互作用进行的细胞分裂，分裂过程中都形 成有丝分裂器，并且都有明显的的细胞核变化，尤其是染色质的变化。 （2）有丝分裂与减数分裂的不同点 二者的不同点如表表 13-1 所示： 表 13-1 有丝分裂与减数分裂的不同点 区别     有丝分裂            减数分裂 形成的细胞类 形成体细胞          形成生殖细胞 型 DNA 复制 1 次，细 胞连续分裂 2 次，细 DNA 复制 1 次，细胞 胞核 DNA 的合成发 分裂 1 次，细胞核 DNA 复制                 生在减数分裂前间 DNA 的合成发生在 S 期 S 期（99.7％～ 期","kp":"ch09_s1_4"},{"id":"ch09_calc_12","modI":1,"q":"说明细胞分裂后期染色单体分离和向两极移动的运动机制。","a":"细胞分裂后期分为后期 A 和后期 B 两个阶段。后期 A，动粒微管变短，牵动染色体向 两极运动；在后期 B，极微管长度增加，两极之间的距离逐渐拉长。具体运动机制如下： （1）后期 A 的运动机制 微管马达蛋白首先结合到动粒上，在 ATP 分解提供能量的情况下，沿动粒微管向极部运动， 并带动动粒和染色体向极部运动。动粒微管的末端随之解聚成微管蛋白二聚体，动粒微管变 短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期 A 结束，转 向后期 B。 （2）后期 B 的运动机制 极微管游离端（正极）在 ATP 提供能量的情况下与微管蛋白聚合，使极微管加长，形成较 宽的极微管重叠区。KRPs 与极微管重叠区的微管结合并在来自两极的极微管之间搭桥。 KRPs 向微管正极行走，促使来自两极的极微管在重叠区相互滑动，使重叠区逐渐变得狭窄， 两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管和细胞膜之间搭桥，并向星体微 管负极运动，进一步将两极之间的距离拉长。","kp":"ch09_s1_17"}],"term":[{"id":"ch09_term_1","modI":1,"term":"有丝分裂（mitosis）。","def":"有丝分裂（mitosis）是真核细胞分化与增殖的基本方式，分为核分裂和胞质分裂，DNA 及其他物质如蛋白等复制了的细胞平均分配到两个子细胞的过程。真核生物细胞在形成染色 体和纺锤体等丝状结构的同时发生复杂的核内变化。","kps":"","kp":"ch09_s1_5"},{"id":"ch09_term_7","modI":1,"term":"细胞分裂（splinter Cell）。","def":"细胞分裂是指一个细胞（母细胞）分裂成两个以上细胞（子细胞）的现象。由于细胞分 裂，核及细胞器分配给两个子细胞。细胞分裂分为有丝分裂和减数分裂两种主要的分裂方式","kps":"","kp":"ch09_s1_4"},{"id":"ch09_term_8","modI":1,"term":"胞质分裂（cytokine－sis）。","def":"胞质分裂是指在细胞分裂末期时，通常于核分裂之后接着发生的胞质体的分裂。根据生 物种类的不同，胞质分裂可分为两个基本类型：一是在高等植物细胞中，于细胞分裂的后期， 姐妹染色单体群移到两极之后，纺锤体的中间区域分化为膜体。在末期，从纺锤体中部形成 细胞板；二是在动物细胞中，于细胞分裂的末期，赤道板位置上的表层细胞质部位向中间凹 陷缢缩。另外，在一部分植物细胞中，以及在酵母出芽和粘菌的孢子形成时等，可以看到有 介于这两种类型之间的中间型。","kps":"","kp":"ch09_s1_2"},{"id":"ch09_term_9","modI":1,"term":"DNA 合成期。","def":"DNA 合成期指细胞周期中合成 DNA 的时期，也称 S 期。核内的 DNA 几乎都在这一时 期合成，使核内 DNA 的量倍增。在 S 期中，由各条染色体（或染色体的不同部分）所进行 的 DNA 合成是有快有慢的。另外新的组蛋白也在 S 期合成。","kps":"","kp":"ch09_s1_5"},{"id":"ch09_term_10","modI":1,"term":"G0 期。","def":"G0 期指具有分裂能力的组织中的细胞在反复分裂数次之后离开细胞周期，执行某种生 物学功能或进行细胞分化，当受到某种适当的外界刺激后，会重返细胞周期，进行分裂增殖， 细胞所处的停止分裂状态的时期就叫做 G0 期。G0 期只不过是细胞周期中 G1 期或 G2 期的无 限延长，而不是细胞周期中 G0 期或 G2 期的中断和脱离。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_14","modI":1,"term":"中心粒周期。","def":"从中心粒的新生、生长、成熟，以及中心体的分离、移动、组装纺锤体至分配到 2 个子 细胞的过程称为中心粒周期","kps":"","kp":"ch09_s1_1"},{"id":"ch09_term_22","modI":1,"term":"G0 期细胞","def":"G0 期细胞又称休眠细胞，是指一类可长期停留在 G1 早期而不越过 R 点，处于增殖静止 状态的细胞。它们可合成具有特殊功能的 RNA 和蛋白质，使细胞的结构和功能发生分化， 这类细胞并未丧失增殖能力，在一定条件下可以恢复其增殖状态，但需要经过较长的恢复时 间。如：肝、肾的实质细胞、血液中的淋巴细胞都属于 G0 期这类细胞。","kps":"","kp":"ch09_s1_13"},{"id":"ch09_term_23","modI":1,"term":"联会复合体","def":"联会复合体是指同源染色体之间在减数分裂前期联会时所形成的一种临时性结构，是一 种减数分裂特异性超分子蛋白质结构，与减数分裂 I 中同源染色体的凝缩、配对、重组和分 离密切相关。联会复合体从细线期开始组装，经过偶线期至粗线期形成典型的联会复合体结 构，同时在粗线期重组节开始组装。双线期联会复合体开始去装配，终变期时完全消失。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_24","modI":1,"term":"FtsZ 蛋白","def":"FtsZ 蛋白是一种广泛存在于细菌和古菌中的结构保守的蛋白质，在细胞胞质分裂的过 程中，在母细胞中间形成收缩环结构，起着将母细胞缢裂成两个子细胞的关键作用。FtsZ 蛋白具有 GTPase 活性，并能受 GTP 诱导发生聚合，是原核生物细胞分裂的关键蛋白之一。","kps":"","kp":"ch09_s1_2"},{"id":"ch09_term_25","modI":1,"term":"减数分裂","def":"减数分裂是指细胞仅进行一次 DNA 复制，随后进行两次分裂，染色体数目减半的一种 特殊的有丝分裂。减数分裂是仅发生于有性生殖细胞形成过程中的某个阶段的一种特殊的有 丝分裂形式，整个过程分为减数分裂Ⅰ和减数分裂Ⅱ两个阶段。","kps":"","kp":"ch09_s1_4"},{"id":"ch09_term_27","modI":1,"term":"synapsis","def":"synapsis 的中文名称是联会。联会是指减数分裂前期的偶线期，同源染色体发生配对， 来自父母双方的同源染色体逐渐靠近，沿其长轴相互紧密结合在一起的过程。联会形成四分 体，由两条染色体共四条染色单体组成。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_29","modI":1,"term":"细胞周期同步化","def":"细胞周期同步化是指在自然过程中发生的或经人为处理造成的所有细胞处于同一细胞周 期阶段的过程。前者称为天然同步化，后者称为人工同步化。人工同步化包括人工选择同步 化和人工诱导同步化（DNA 合成阻断法和分裂中期阻断法）。","kps":"","kp":"ch09_s1_1"},{"id":"ch09_term_30","modI":1,"term":"有丝分裂器","def":"有丝分裂器是一个动态的结构，在中期细胞中包括两部分：①纺锤体，是由对称的微管 束组成的形似橄榄球的结构，在细胞的赤道板被染色体一分为二；②星体，在纺锤体的两端 各有一个，为一簇呈放射状的微管。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_31","modI":1,"term":"细胞周期","def":"细胞周期是指从第一次细胞有丝分裂结束到第二次分裂完成所经历的过程，包括分裂间 期和分裂期（M 期）。其中分裂间期是指第一次分裂结束到第二次分裂开始的时间，是细 胞增殖的物质准备和积累阶段，包括 G1 期、S 期（DNA 合成）和 G2 期。M 期是指一次分 裂开始到结束的时间，包括前期、中期、后期和末期。","kps":"","kp":"ch09_s1_4"}]},{"i":2,"name":"二 周期调控之brake","slides":[{"i":19,"sec":"","title":"二 周期调控之brake","notes":"细胞内存在一系列监控机制, 用来鉴别细胞周期进\n程中的错误, 并诱导产生特异的抑制因子, 阻止细胞周\n期在错误中继续运行。\n锤体装配检验点。\nof the cell cycle to the next stage until each cell cycle\nevent occurs accurately and in the proper order.\nhave no role in normal cell cycle events and are only\ncalled into action when an abnormality appears.\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ·同源染色体间遗传物质重组,产生新的基因组合一、细胞周期调控系统的主要作用◆在适当时候激活细胞周期各个时相的相关酶和蛋白,然后自身失活(正调控)\n\n【本页英文讲解】\n本页主题是周期调控的“刹车”——检验点（checkpoint）。原文指出：细胞内存在一系列监控机制，用于鉴别细胞周期进程中的错误并诱导特异抑制因子，阻止细胞周期在错误中继续运行；其广泛分布于G1期检验点、G2期检验点、纺锤体装配检验点（spindle assembly checkpoint）。检验点蛋白多数不参与正常周期事件，仅在异常出现时被动用，是高频考点。","page":20,"level":"掌握","img":"assets/img/ch09/p020.jpg","anim":null,"fig":null,"points":["检验点(checkpoint)","广泛用于各个时期: G1期检验点、G2期检验点、 纺","Checkpoints are mechanisms that halt the progress","Many of the proteins of the checkpoint machinery"],"check":{"q":"关于细胞周期检验点(checkpoint)的叙述，正确的是？","o":["A. 检验点是细胞周期的引擎，驱动周期运行","B. 检验点蛋白多不参与正常周期事件，异常时才被动员","C. 检验点在DNA损伤时促进细胞继续分裂","D. 检验点只存在于G1期"],"a":"B","e":"检验点是监控机制，可鉴别周期进程中的错误并诱导抑制因子，阻止周期在错误中继续；广泛分布于G1、G2及纺锤体装配检验点，异常时才被动用。","oe":["错误，引擎是CDK-cyclin复合物，非检验点。","正确，检验点蛋白多在异常出现时才起作用。","错误，检验点会阻止周期在错误中继续运行。","错误，G1、G2及纺锤体装配等均有检验点。"]},"cards":null,"mem":"检验点：G1、G2、纺锤体装配，拦错误","big":"assets/img/ch09/big/p020.jpg","summary":"细胞内存在一系列监控机制, 用来鉴别细胞周期进","goal":"学完应能掌握并运用「二 周期调控之brake」的核心内容，能解释其机制、比较相关概念。","intuition":"检验点是周期的“刹车系统”：出错时及时停下，避免带伤进入下一步。"},{"i":20,"sec":"","title":"检验点是细胞周期的调控信号通路","notes":"保证细胞周期高度有序、正确完成→基因和基因组\n的稳定性；但不是细胞分裂的基本条件。\n【结合课本/笔记】◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系","page":21,"level":"掌握","img":"assets/img/ch09/p021.jpg","anim":null,"fig":null,"points":["从分子水平看，检验点是细胞周期的调控信号通路","保证细胞周期高度有序、正确完成，维持基因和基因组的稳定性","检验点不是细胞分裂的基本条件"],"check":{"q":"关于细胞周期检验点的作用，下列叙述正确的是？","o":["A. 检验点是细胞分裂能否进行的基本条件","B. 检验点确保各时相事件有序、全部完成并与外界环境因素相联系","C. 检验点与基因和基因组的稳定性无关","D. 检验点只存在于G1期，其他时相没有"],"a":"B","e":"检验点是细胞周期调控的一种机制，确保周期每一时相事件有序、全部完成并与外界环境因素相联系，保证基因组稳定性，但不是细胞分裂的基本条件。","oe":["错误，检验点并非细胞分裂的基本条件。","正确，检验点确保各时相有序完成并联系外界因素。","错误，检验点正是保证基因和基因组稳定性的机制。","错误，G1、G2、M等时相均存在检验点。"]},"cards":null,"mem":"检验点是调控通路，保有序但非分裂必需","big":"assets/img/ch09/big/p021.jpg","summary":"保证细胞周期高度有序、正确完成→基因和基因组","goal":"学完应能掌握并运用「检验点是细胞周期的调控信号通路」的核心内容，能解释其机制、比较相关概念。","intuition":"检验点是信号通路，保证各时相有序完成、维持基因组稳定；但它不是分裂的基本条件。"},{"i":21,"sec":"","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Resting state (G0) —— 静息状态(G0)\n• G1 Checkpoint: cell size, nutrients, growth factors, DNA damage —— G1检查点：细胞大小、营养、生长因子、DNA损伤\n• G2 Checkpoint: cell size, DNA replication —— G2检查点：细胞大小、DNA复制\n• Spindle Assembly Checkpoint: chromosome attachment to spindle —— 纺锤体组装检查点：染色体与纺锤体连接\n• G1/S/G2/M —— G1/S(G1 DNA合成)/G2/M 各期\n【读图讲解】\n英文细胞周期图：环形箭头示G1、S(DNA合成)、G2、M，并有G0静止态；标注三个检查点：G1(大小/营养/生长因子/DNA损伤)、G2(大小/DNA复制)、纺锤体组装检查点(染色体与纺锤体连接)。考点：各期顺序与检查点监控内容。","page":22,"level":"掌握","img":"assets/img/ch09/p022.jpg","anim":null,"fig":null,"points":["Resting","Spindle Assembly Checkpoint","state","Checkfor:","Chromosomeattachment","to spindle","G2Checkpoint","Check for:"],"check":{"q":"下列哪项是G2检验点主要监控的内容？","o":["A. 营养与生长因子是否充足","B. 染色体是否附着于纺锤体","C. 细胞大小与DNA复制是否完成","D. DNA是否发生损伤"],"a":"C","e":"G1检验点监控细胞大小、营养、生长因子与DNA损伤；G2检验点监控细胞大小与DNA复制；纺锤体组装检验点监控染色体与纺锤体连接。","oe":["错误，营养与生长因子属G1检验点监控内容。","错误，染色体附着纺锤体由纺锤体组装检验点监控。","正确，G2检验点监控细胞大小与DNA复制完成情况。","错误，DNA损伤主要由G1检验点监控。"]},"cards":null,"mem":"G1查大小营养DNA损，G2查复制，M查纺锤体","big":"assets/img/ch09/big/p022.jpg","summary":"G1 Checkpoint: cell size, nutrients, growth factors, DNA damage —— G1检查点：细胞大小、营养、生长因子、DNA损","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示各检验点（G1/S、G2/M、纺锤体检验点）的位置。"},{"i":22,"sec":"","title":"检验点","notes":"●G1期检验点\n核细胞, especially, 哺乳动物细胞 : G1晚期阶段的一个特定时\n期, 对控制细胞通过G1期, 顺利进入S期具有关键作用。\n【结合课本/笔记】◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系","page":23,"level":"掌握","img":"assets/img/ch09/p023.jpg","anim":"restriction_point","fig":null,"points":["酵母中称起始点(start) ；限制点(restriction point)高等真"],"check":{"q":"哺乳动物细胞的G1期检验点又称？","o":["A. 起始点(start)","B. 纺锤体装配检验点","C. 限制点(restriction point)","D. 后期检验点"],"a":"C","e":"G1期检验点位于G1晚期，对细胞通过G1进入S期起关键作用，酵母中称起始点(start)，高等真核(尤其哺乳动物)细胞中称限制点(restriction point)。","oe":["错误，起始点是酵母中G1检验点的名称。","错误，那是M期监控纺锤体装配的检验点。","正确，高等真核细胞G1期检验点称限制点。","错误，检验点分类中无此特有名称。"]},"cards":null,"mem":"G1检验点=酵母start点=哺乳动物限制点","big":"assets/img/ch09/big/p023.jpg","terms":[{"t":"起始点 / 限制点","en":"start / restriction point","d":"G1期决定细胞是否进入S期的关键检验点，酵母称start、哺乳动物称restriction point。"}],"summary":"核细胞, especially, 哺乳动物细胞 : G1晚期阶段的一个特定时","goal":"学完应能掌握并运用「检验点」的核心内容，能解释其机制、比较相关概念。","intuition":"G1 检验点像“进门关卡”：决定细胞是否进入 S 期；酵母称 start、哺乳动物称限制点。"},{"i":23,"sec":"","title":"G1期：⎯由于离子辐射、化学物质作用等引起DNA损伤(DNA damage),","notes":"checkpoint会阻止G1 cell进入S期；或G2进入M期；此时细胞启动DNA损伤修\n复调控体系, 直到完全修复(或最终不能完成修复而进入细胞凋亡)。 —p53\n件等。\nG2期:\ncheckpoint也会发现并阻止该细胞进入G2/M.\nM期(分裂期):\n锤体微管)，checkpoint阻止细胞进入分裂后期。","page":24,"level":"掌握","img":"assets/img/ch09/p024.jpg","anim":null,"fig":null,"points":["新生细胞生长大小是否足够大，内部rRNA和蛋白质合成是否合适，营养条","DNA是否复制、复制是否完全 ，是否正确复制","细胞大小/环境因素等","如果纺锤体未正确装配or染色体未附着到纺锤体上 (染色体动粒未捕捉到纺"],"check":{"q":"关于DNA损伤后检验点的反应，下列叙述正确的是？","o":["A. 损伤细胞一定立即进入S期","B. G1期检验点阻止损伤细胞进入S期，并启动DNA修复","C. 检验点只存在于M期","D. 损伤后细胞必然直接坏死，不进行修复"],"a":"B","e":"G1期检验点可阻止带DNA损伤的细胞进入S期（或阻止G2进入M期），并启动DNA损伤修复体系，直到修复完成，否则进入凋亡。","oe":["损伤细胞被检验点阻止，而非立即进入S期。","G1检验点阻止进入S期并启动修复，正确。","检验点存在于G1、G2、M等多个时相。","细胞先启动修复，修复失败才凋亡。"],"basis":"G1检验点阻止损伤细胞进入S期并启动修复"},"cards":null,"mem":"DNA损伤p53拦G1/S或G2/M，修复否则凋亡","big":"assets/img/ch09/big/p024.jpg","summary":"checkpoint会阻止G1 cell进入S期；或G2进入M期；此时细胞启动DNA损伤修","goal":"学完应能掌握并运用「G1期：⎯由于离子辐射、化学物质作用等引起DNA损伤(DNA damage),」的核心内容，能解释其机制、比较相关概念。","intuition":"辐射、化学物会损伤 DNA；细胞在检验点停下、先修复，修不好就凋亡。"},{"i":24,"sec":"","title":"检验点概念的提出（AT与DNA修复）","notes":"Ataxia-telangiectasia），体内缺少DNA损伤\n后的修复系统。\n1988年Leland Hartwell and Ted Weinert 提\n出检验点（checkpoint）的概念。人们总结\n出细胞中有两条途径可以通过检验点阻止\n带有损伤DNA的细胞继续进入细胞周期。","page":25,"level":"掌握","img":"assets/img/ch09/p025.jpg","anim":null,"fig":null,"points":["1960年代发现射线引起的癌变病人(AT，共济失调毛细血管扩张症)缺少DNA损伤后的修复系统","1988年Leland Hartwell与Ted Weinert提出检验点(checkpoint)的概念","细胞中有两条途径可通过检验点阻止带损伤DNA的细胞继续进入细胞周期"],"check":{"q":"细胞周期检验点(checkpoint)的主要作用是？","o":["A. 加速带损伤DNA细胞的增殖","B. 直接降解所有细胞周期蛋白","C. 阻止带有损伤DNA的细胞继续进入细胞周期","D. 只在细胞分裂末期起作用"],"a":"C","e":"细胞中有途径可通过检验点阻止带有损伤DNA的细胞继续进入细胞周期，以保证周期事件的准确与安全。","oe":["检验点是阻止而非加速损伤细胞增殖。","检验点并非直接降解所有周期蛋白。","阻止带损伤DNA细胞继续进入周期，正确。","检验点可在G1、G2、M等多个阶段起作用。"],"basis":"通过检验点阻止带有损伤DNA的细胞继续进入细胞周期"},"cards":null,"mem":"1988 Hartwell&Weinert提出检验点概念","big":"assets/img/ch09/big/p025.jpg","summary":"出细胞中有两条途径可以通过检验点阻止","goal":"学完应能掌握并运用「检验点概念的提出（AT与DNA修复）」的核心内容，能解释其机制、比较相关概念。","intuition":"1988 年 Hartwell 与 Weinert 提出检验点概念；细胞有途径阻止带损伤 DNA 的细胞进入周期。","experiment":"【实验】用射线/化学物造成 DNA 损伤，比较正常细胞与 AT(共济失调毛细血管扩张症)细胞。\n【结果判读】正常细胞在 G1/S 等检验点暂停以修复；AT 细胞缺少 ATM/ATR 介导的检验点、带损伤 DNA 继续分裂——据此提出检验点概念(1988 Hartwell & Weinert)。"},{"i":25,"sec":"","title":"阳光中的紫外线辐射导致DNA损伤","notes":"两个相邻的胸腺嘧啶碱基之间共价结合形成胸腺嘧啶\n二聚体，暴露在阳光下的皮肤细胞对这种损伤非常敏\n感。","page":26,"level":"掌握","img":"assets/img/ch09/p026.jpg","anim":null,"fig":null,"points":["阳光中紫外线使相邻两个胸腺嘧啶碱基共价结合形成胸腺嘧啶二聚体","暴露在阳光下的皮肤细胞对这种损伤非常敏感"],"check":{"q":"阳光中紫外线引起DNA损伤的主要形式是？","o":["A. 相邻胸腺嘧啶间形成胸腺嘧啶二聚体","B. 碱基发生脱氨基","C. 染色体数目发生改变","D. DNA双链断裂"],"a":"A","e":"紫外线照射使两个相邻胸腺嘧啶碱基共价结合形成胸腺嘧啶二聚体，暴露于阳光的皮肤细胞对此类损伤非常敏感。","oe":["正确，紫外线主要导致相邻胸腺嘧啶形成二聚体。","错误，脱氨基并非紫外线损伤的主要形式。","错误，染色体数目改变不是紫外线的直接损伤形式。","错误，双链断裂主要与电离辐射等损伤相关。"]},"cards":null,"mem":"紫外线致相邻胸腺嘧啶形成二聚体","big":"assets/img/ch09/big/p026.jpg","summary":"两个相邻的胸腺嘧啶碱基之间共价结合形成胸腺嘧啶","goal":"学完应能掌握并运用「阳光中的紫外线辐射导致DNA损伤」的核心内容，能解释其机制、比较相关概念。","intuition":"紫外线像“在 DNA 上打结”：形成嘧啶二聚体，皮肤细胞对这种损伤很敏感。"},{"i":26,"sec":"","title":"损伤DNA复制导致染色体异常","notes":"chromosome abnormalities, such as gene amplification\nand gene loss.\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 染色体（chromosome）：当细胞进入有丝分裂时，伸展、弥散的丝状染色质高度折叠、盘曲而凝缩成条状或棒状的特殊形态，称为染色体。\n\n【本页英文讲解】\n本页主题是“受损DNA的复制如何导致染色体异常”。原文指出：受损DNA（damaged DNA）的复制可引发染色体异常（chromosome abnormalities），例如基因扩增（gene amplification）与基因丢失（gene loss）。这强调DNA损伤若未被检验点拦截并修复便进入复制，会造成基因组不稳定，是细胞癌变的机制之一，与G1/S检验点功能联系密切。","page":27,"level":"掌握","img":"assets/img/ch09/p027.jpg","anim":null,"fig":null,"points":["损伤DNA的复制可导致染色体异常","如基因扩增(gene amplification)和基因丢失(gene loss)"],"check":{"q":"受损DNA若未被检验点拦截而进入复制，最可能导致？","o":["A. 细胞周期加速顺利完成","B. 基因扩增与基因丢失等染色体异常","C. 染色体数目精确加倍","D. DNA损伤被自动修复"],"a":"B","e":"受损DNA的复制可引发染色体异常，如基因扩增与基因丢失，造成基因组不稳定，是细胞癌变的机制之一。","oe":["错误，受损DNA复制不会使周期顺利完成。","正确，受损DNA复制可致基因扩增与基因丢失。","错误，其结果是不稳定而非精确加倍。","错误，损伤若已进入复制通常无法自动修复。"]},"cards":null,"mem":"损伤DNA复制致基因扩增或丢失","big":"assets/img/ch09/big/p027.jpg","summary":"考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「损伤DNA复制导致染色体异常」的核心内容，能解释其机制、比较相关概念。","intuition":"损伤 DNA 若强行复制，像“照错版复印”：导致染色体异常、基因扩增或丢失。"},{"i":27,"sec":"","title":"共济失调毛细血管扩张综合症","notes":"ATM:\nataxia-telangiectasia mutated\n丝氨酸/苏氨酸蛋白激酶\nATR:\nATM and RAD3-related\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ·同源染色体间遗传物质重组,产生新的基因组合一、细胞周期调控系统的主要作用◆在适当时候激活细胞周期各个时相的相关酶和蛋白,然后自身失活(正调控)\n\n【本页英文讲解】\n本页主题是共济失调毛细血管扩张综合症（ataxia-telangiectasia）相关蛋白ATM。原文说明：ATM全称ataxia-telangiectasia mutated，是一种丝氨酸/苏氨酸蛋白激酶（serine/threonine protein kinase）；ATR即ATM and RAD3-related。二者是DNA损伤应答中的关键感受与传导激酶，ATM主要响应DNA双链断裂。教材第十四章涉及ATM/ATR在DNA损伤检验点中的作用。","page":28,"level":"掌握","img":"assets/img/ch09/p028.jpg","anim":null,"fig":null,"points":["ATM(ataxia-telangiectasia mutated)是丝氨酸/苏氨酸蛋白激酶","ATR为ATM and RAD3-related"],"check":{"q":"关于ATM蛋白，下列叙述正确的是？","o":["A. 主要响应紫外线形成的嘧啶二聚体","B. 是一种酪氨酸蛋白激酶","C. 全称共济失调毛细血管扩张突变蛋白，是丝氨酸/苏氨酸蛋白激酶","D. ATR与ATM毫无关系，属不同家族"],"a":"C","e":"ATM全称ataxia-telangiectasia mutated，是丝氨酸/苏氨酸蛋白激酶，为DNA损伤应答关键激酶，主要响应DNA双链断裂；ATR即ATM and RAD3-related。","oe":["错误，ATM主要响应双链断裂而非嘧啶二聚体。","错误，ATM为丝氨酸/苏氨酸蛋白激酶而非酪氨酸激酶。","正确，ATM是响应DNA损伤的丝/苏氨酸蛋白激酶。","错误，ATR全称即ATM and RAD3-related，关系密切。"]},"cards":null,"mem":"AT症缺ATM/ATR激酶，DNA损伤修复缺陷","big":"assets/img/ch09/big/p028.jpg","summary":"丝氨酸/苏氨酸蛋白激酶","goal":"学完应能掌握并运用「共济失调毛细血管扩张综合症」的核心内容，能解释其机制、比较相关概念。","intuition":"ATM/ATR 像“DNA 损伤的探测雷达”：识别损伤后启动检验点，让周期暂停。"},{"i":28,"sec":"","title":"p53：与人类肿瘤相关性最高的抑癌基因","notes":"p53\n(tumor-suppressor gene associated with human cancer)\n编码一个分子量为53kDa的蛋白；(p53蛋白本身是一转\n录因子，主要集中在细胞核，与DNA特异结合，其活\n性受磷酸化控制), 在细胞增殖起负性调节作用。\n(p53 protein functions in the checkpoint control that arrest human cells with\ndamaged DNA in G1.)\nligase，E3泛素连接酶)蛋白与之结合后输出到胞质，经泛素\nubiquitin途径降解。\n但DNA损伤后p53被磷酸化，则不再被输出到胞质中降解，使\n细胞核中浓度升高。\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ·同源染色体间遗传物质重组,产生新的基因组合一、细胞周期调控系统的主要作用◆在适当时候激活细胞周期各个时相的相关酶和蛋白,然后自身失活(正调控)","page":29,"level":"掌握","img":"assets/img/ch09/p029.jpg","anim":null,"fig":null,"points":["人类细胞DNA损伤修复过程中有重要作用。","健康的G1期细胞中，p53蛋白浓度很低。Mdm2 (ubiquitin"],"check":{"q":"关于p53蛋白的叙述，正确的是？","o":["A. p53是癌基因，促进细胞增殖","B. p53是转录因子，但只在细胞质中起作用","C. DNA损伤后p53被磷酸化并加速输出胞质降解","D. 健康G1期细胞中p53浓度低，经Mdm2介导泛素化降解"],"a":"D","e":"p53是与人类肿瘤相关性最高的抑癌基因，编码53kDa转录因子，在核内负性调节增殖；健康G1期细胞p53浓度低，经Mdm2泛素化降解，DNA损伤时磷酸化而稳定升高。","oe":["错误，p53是抑癌基因，负性调节增殖。","错误，p53主要集中在细胞核内发挥作用。","错误，损伤后p53磷酸化后不再被输出降解。","正确，Mdm2使p53出核并经泛素途径降解。"]},"cards":null,"mem":"p53抑癌负调控，Mdm2降之，DNA损伤则磷酸化","big":"assets/img/ch09/big/p029.jpg","summary":"编码一个分子量为53kDa的蛋白；(p53蛋白本身是一转","goal":"学完应能掌握并运用「p53：与人类肿瘤相关性最高的抑癌基因」的核心内容，能解释其机制、比较相关概念。","intuition":"p53 像“基因组卫士”：DNA 一坏，它马上启动 p21 让周期停下、争取修理时间；修不好就启动凋亡。它是最常突变的抑癌基因。"},{"i":29,"sec":"","title":"Damaged DNA&ATM/ATR(一种蛋白激酶)识别并结合","notes":"p53(a transcription factor)磷酸化后 stabilizes and activates\n→stimulate\nExpression of p21 gene\n(p21蛋白，细胞周期的抑制物：CDK-cyclin inhibitor, CKI)\n✓ p21结合哺乳动物G1期CDK-细胞周期蛋白复合物并抑制其活\n性(p21 binds to and inhibits CDK-cyclin complexes) ；\n✓ 与DNA聚合酶●辅助因子PCNA结合，直接抑制DNA复制。\nrepaired, and p53 and subsequently p21CIP levels fall.\ninduce apoptosis.\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 转录（transcription）：在细胞核中以 DNA 为模板合成 mRNA 的过程，成为转录。\n• 转录子（transcription）：DNA 链上从启动子到终止子为止的长度称为一个转录单位，即转录子。\n\n【本页英文讲解】\n本页主题为DNA损伤经ATM/ATR与p53引发G1/G2阻滞。原文路径：损伤DNA被ATM/ATR（一种蛋白激酶）识别并结合，p53（transcription factor，转录因子）磷酸化后被稳定并激活，刺激p21基因表达；p21是CDK-cyclin抑制物（CKI），结合并抑制CDK-cyclin复合物活性，又可与DNA聚合酶辅助因子PCNA结合直接抑制DNA复制。细胞阻滞于G1、G2待修复；损伤严重时p53激活凋亡基因。此为重要考点。","page":30,"level":"掌握","img":"assets/img/ch09/p030.jpg","anim":null,"fig":null,"points":["Cells are arrested in G1 and G2 until the DNA damage is","In response to extensive DNA damage, p53 activates genes that"],"check":{"q":"关于DNA损伤后p53-p21通路的叙述，正确的是？","o":["A. p53磷酸化后促进p21表达，p21抑制CDK-cyclin并抑制复制","B. p21促进CDK-cyclin活性，加速DNA复制","C. ATM/ATR直接降解p53蛋白","D. p53激活后促使细胞立即进入S期"],"a":"A","e":"损伤DNA被ATM/ATR识别，p53磷酸化后稳定激活，促进p21表达；p21结合并抑制CDK-cyclin复合物，又与PCNA结合直接抑制DNA复制，使细胞阻滞于G1、G2。","oe":["正确，p21抑制CDK-cyclin并抑制DNA复制。","错误，p21是CKI，抑制CDK-cyclin活性。","错误，ATM/ATR识别损伤并磷酸化激活p53。","错误，p53使细胞阻滞于G1、G2等待修复。"]},"cards":null,"mem":"损伤→ATM/ATR→p53→p21→抑CDK与PCNA","big":"assets/img/ch09/big/p030.jpg","summary":"(p21蛋白，细胞周期的抑制物：CDK-cyclin inhibitor, CKI)","goal":"学完应能掌握并运用「Damaged DNA&ATM/ATR(一种蛋白激酶)识别并结合」的核心内容，能解释其机制、比较相关概念。","intuition":"ATM/ATR 是蛋白激酶，像“报警器”：感知 DNA 损伤后激活下游，让周期暂停。"},{"i":30,"sec":"","title":"p53诱导的细胞周期阻滞","notes":"response to DNA damage\np53 is normally very\nshort-lived, but\nphosphorylation by\nchk2 stabilizes the\nprotein, enhancing its\nability to activate p21\ntranscription.\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 转录（transcription）：在细胞核中以 DNA 为模板合成 mRNA 的过程，成为转录。\n• 转录子（transcription）：DNA 链上从启动子到终止子为止的长度称为一个转录单位，即转录子。\n\n【本页英文讲解】\n本页主题是p53诱导的细胞周期阻滞（p53-induced cell cycle arrest）——响应DNA损伤。原文指出：p53通常极不稳定、寿命很短（short-lived），但被chk2磷酸化后蛋白被稳定，从而增强其激活p21转录的能力。即chk2→p53→p21是DNA损伤检验点的重要信号轴，导致细胞周期阻滞以便DNA修复，是分子机制的常考点。","page":31,"level":"掌握","img":"assets/img/ch09/p031.jpg","anim":"p53_checkpoint","fig":null,"points":["p53响应DNA损伤引起细胞周期阻滞","p53通常寿命很短，被chk2磷酸化后稳定","稳定后增强p53激活p21转录的能力"],"check":{"q":"DNA损伤后chk2使p53磷酸化，其直接后果是？","o":["A. p53迅速降解，细胞周期加速进行","B. p21被降解，周期阻滞被解除","C. chk2被抑制，DNA损伤被忽略","D. p53被稳定，增强其激活p21转录的能力"],"a":"D","e":"p53通常寿命很短，被chk2磷酸化后蛋白被稳定，从而增强其激活p21转录的能力，导致细胞周期阻滞以便修复DNA。","oe":["错误，chk2磷酸化使p53稳定而非降解。","错误，p21被激活而非降解，周期被阻滞。","错误，该通路激活而非抑制chk2对损伤的应答。","正确，p53被稳定并增强激活p21转录的能力。"]},"cards":null,"mem":"chk2磷酸化稳p53→促p21转录，周期阻滞","big":"assets/img/ch09/big/p031.jpg","summary":"考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「p53诱导的细胞周期阻滞」的核心内容，能解释其机制、比较相关概念。","intuition":"p53 像“紧急刹车”：被稳定后启动 p21，抑制 CDK，使周期停在 G1。"},{"i":31,"sec":"","title":"Role of the p53 Protein in Responding to DNA Damage","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页主题是“p53蛋白在响应DNA损伤中的作用”（Role of the p53 Protein in Responding to DNA Damage）。原文仅给出标题，未展开文字。可理解为该页图示p53作为“基因组卫士”在DNA受损后被激活，进而引起细胞周期阻滞或凋亡的过程。结合上一页，p53经chk2磷酸化而稳定、激活p21转录，是G1/S检验点的核心枢纽。","page":32,"level":"掌握","img":"assets/img/ch09/p032.jpg","anim":null,"fig":null,"points":["p53被称为“基因组卫士”，DNA受损后被激活","作为基因组卫士引起细胞周期阻滞以便修复，损伤严重时则诱导细胞凋亡"],"check":{"q":"p53被称为“基因组卫士”，其被激活后可引起？","o":["A. 细胞必然发生癌变","B. DNA损伤被p53直接修复","C. 细胞周期阻滞或凋亡","D. 细胞周期加速运行"],"a":"C","e":"p53在DNA受损后被激活，作为基因组卫士引起细胞周期阻滞以便修复，损伤严重时则诱导细胞凋亡。","oe":["错误，p53激活通常抑制癌变而非导致癌变。","错误，p53不直接修复DNA，而是阻滞周期或诱导凋亡。","正确，p53激活可致细胞周期阻滞或凋亡。","错误，p53激活阻滞而非加速细胞周期。"]},"cards":null,"mem":"p53应答DNA损伤：阻G1待修复或凋亡","big":"assets/img/ch09/big/p032.jpg","summary":"考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「Role of the p53 Protein in Responding to」的核心内容，能解释其机制、比较相关概念。","intuition":"p53 被称为“基因组卫士”：损伤时引起周期阻滞或凋亡，防止坏细胞增殖。"},{"i":32,"sec":"","title":"（本页为图片/无文字层）","notes":"细胞周期检验点与APC调控：Mad2结合Cdc20抑制APC，待染色体全部附着后APC才活化，启动向后期转换。\n【图中英文对照】\n• Mad2 —— Mad2(纺锤体组装检查点蛋白)\n• APC-Cdc20 / APC-Cdh1 —— APC-Cdc20 / APC-Cdh1(后期促进复合物)\n• cyclin B —— 周期蛋白 B\n• Cdc14 / Sic1 —— Cdc14 磷酸酶 / Sic1(CDK 抑制因子)\n• ATM/R-p53-p21CIP —— ATM/ATR→p53→p21 通路(DNA 损伤)\n• Cyclin D-CDK4/6 —— 周期蛋白D-CDK4/6\n• Cyclin A/B-CDK1 —— 周期蛋白A/B-CDK1\n• Cdc25C / Cdc25A —— Cdc25C / Cdc25A 磷酸酶\n• Chk1/2 / ATR —— Chk1/2、ATR 检查点激酶\n• Cyclin A-CDK2 —— 周期蛋白A-CDK2\n【读图讲解】\n细胞周期检查点机制图：①未复制DNA(ATR-Chk1-Cdc25℃-CyclinA/B-CDK1)；②纺锤体组装(Mad2-APC-Cdc20-securin→后期)；③染色体分离(Cdc14-APC-Cdh1/Sic1)；④DNA损伤(ATM/R-p53-p21、Chk1/2-Cdc25A)。考点：检查点信号通路与CDK调控。","page":33,"level":"掌握","img":"assets/img/ch09/p033.jpg","anim":null,"fig":null,"points":["染色体分离检测点","纺锤体组装检测点","APC-Cdh1","Mad2","-Cdc14-→Sic1","cyclinB的多聚泛素化","4aDNA损伤检测点","APC-Cdc20"],"check":{"q":"在纺锤体组装检验点中，Mad2蛋白的作用是？","o":["A. 直接促进APC活性，加速进入后期","B. 水解cyclin B","C. 修复DNA损伤","D. 与Cdc20结合抑制APC，确保染色体全部附着后才进入后期"],"a":"D","e":"Mad2与Cdc20结合而抑制APC活性；只有所有染色体都与纺锤体结合后，APC才有活性，从而启动细胞向后期转换。","oe":["Mad2抑制而非直接促进APC。","水解cyclin B由APC等介导，非Mad2。","Mad2属纺锤体检验点蛋白，不修复DNA。","Mad2结合Cdc20抑制APC，保证附着完成后进入后期。"],"basis":"Mad2与Cdc20结合而抑制APC活性"},"cards":null,"mem":"检查点框图：未复制/纺锤体/分离/DNA损伤","big":"assets/img/ch09/big/p033.jpg","terms":[{"t":"Mad2","en":"Mad2","d":"纺锤体组装检验点蛋白，在动粒未附着时抑制APC，阻止进入后期。"},{"t":"APC","en":"anaphase-promoting complex","d":"后期促进复合物，泛素连接酶，触发cyclin B和securin降解。"},{"t":"Cdc20 / Cdh1","en":"Cdc20 / Cdh1","d":"APC的正调激活亚基。"}],"summary":"细胞周期检验点与APC调控：Mad2结合Cdc20抑制APC，待染色体全部附着后APC才活化，启动向后期转换","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"纺锤体检验点是“发车前检查”：只要还有染色体没挂上纺锤体，Mad2 就抱住 Cdc20、摁住 APC（刹车）；全部挂好后才松开，APC 启动，降解 securin 和 cyclin，放行进入后期。宁可多等，也不让染色体分错。"},{"i":33,"sec":"","title":"2001年诺贝尔生理学或医学奖","notes":"芽殖酵母                                               裂殖酵母\nCdc28                                              Cdc2/CDK\n海胆                   1\ncyclin\nfor their discoveries of “key regulators of the cell cycle”.\n“细胞周期的关键调控因子”\n【中文讲解·对照课本/考点】\n考点：二 周期调控之brake ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页讲解】\n本页以2001年诺贝尔生理学或医学奖为线索，介绍细胞周期关键调控因子的发现史。图示列举了不同模式生物的对应因子：芽殖酵母（budding yeast）的Cdc28、裂殖酵母（fission yeast）的Cdc2/CDK，以及海胆（sea urchin）中周期性的cyclin（细胞周期蛋白）。获奖理由是“细胞周期的关键调控因子”的发现。考点联系翟中和《细胞生物学》第十三章细胞周期与细胞分裂第一节，需记忆CDK与cyclin的发现历程及模式生物对应关系。","page":34,"level":"掌握","img":"assets/img/ch09/p034.jpg","anim":null,"fig":null,"points":["2001年诺贝尔生理学或医学奖授予“细胞周期的关键调控因子”的发现","涉及芽殖酵母Cdc28、裂殖酵母Cdc2/CDK与海胆cyclin"],"check":{"q":"关于细胞周期蛋白(cyclin)，下列叙述正确的是？","o":["A. 随细胞周期呈周期性出现或消失，时相性地激活CDK","B. 含量恒定不变","C. 是一种DNA聚合酶","D. 只在M期合成且永不降解"],"a":"A","e":"细胞周期蛋白是一类随细胞周期变化呈周期性出现或消失的蛋白质，可时相性地激活CDK，从而调控细胞周期。","oe":["cyclin周期性出现消失并时相激活CDK，正确。","cyclin含量呈周期性变化，并不恒定。","cyclin是调控蛋白，不是DNA聚合酶。","cyclin会被受控蛋白酶解降解，并非永不降解。"],"basis":"随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活CDK"},"cards":null,"mem":"2001诺奖：细胞周期关键调控因子","big":"assets/img/ch09/big/p034.jpg","summary":"芽殖酵母                                               裂殖酵母","goal":"学完应能掌握并运用「2001年诺贝尔生理学或医学奖」的核心内容，能解释其机制、比较相关概念。","intuition":"2001 年诺奖授予细胞周期关键调控因子（CDK、cyclin）的发现。"},{"i":34,"sec":"","title":"分别使用的模式生物","notes":"芽殖酵母              裂殖酵母               海胆\n① Leland Hartwell：酿酒酵母/芽殖酵母( S. cerevisiae)，发现了\n控制酵母细胞周期的 “START” 基因-Cdc28对控制细胞周期\n的最初G1→S阶段具有决定性的作用。\n②Paul Nurse：裂殖酵母（S. pombe），发现了激酶CDK1(细胞\n周期蛋白依赖性激酶)\n③ Tim Hunt：海胆（Arbacia），发现了CDK的调节蛋白(调节\n亚基)－cyclin(细胞周期蛋白)。","page":35,"level":"掌握","img":"assets/img/ch09/p035.jpg","anim":null,"fig":null,"points":["Hartwell用酿酒酵母(芽殖酵母)发现控制细胞周期的“START”基因Cdc28，对G1→S阶段有决定作用","Nurse用裂殖酵母发现激酶CDK1(细胞周期蛋白依赖性激酶)","Hunt用海胆发现CDK的调节亚基cyclin"],"check":{"q":"三位科学家发现细胞周期调控因子所用的模式生物配对正确的是？","o":["A. Hartwell—海胆，Nurse—芽殖酵母，Hunt—裂殖酵母","B. Hartwell—裂殖酵母，Nurse—海胆，Hunt—芽殖酵母","C. Hartwell—芽殖酵母，Nurse—裂殖酵母，Hunt—海胆","D. 三人均以海胆为研究材料"],"a":"C","e":"Hartwell用芽殖酵母(酿酒酵母)发现START基因Cdc28，Nurse用裂殖酵母发现CDK1(Cdc2)，Hunt用海胆发现CDK的调节亚基cyclin。","oe":["错误，Hartwell与Hunt的材料被互换。","错误，三人的模式生物配对均不正确。","正确，Hartwell-芽殖酵母、Nurse-裂殖酵母、Hunt-海胆。","错误，三人分别使用不同的模式生物。"]},"cards":null,"mem":"三发现：芽殖Cdc28、裂殖CDK1、海胆cyclin","big":"assets/img/ch09/big/p035.jpg","summary":"芽殖酵母              裂殖酵母               海胆","goal":"学完应能掌握并运用「分别使用的模式生物」的核心内容，能解释其机制、比较相关概念。","intuition":"三位科学家用三种材料：Hartwell 用芽殖酵母、Nurse 用裂殖酵母、Hunt 用海胆。"}],"mcq":[{"id":"ch09_mcq_2","mod":"二 周期调控之brake","modI":2,"q":"与 PCNA 结合，直接抑制 DNA 复制的 CDK 激酶抑制物是（       ）。","o":["A．p27","B．P16","C．p18","D．p21"],"a":"D","e":"p21 为 CIP／KIP 类 CDK 激酶抑制物，PCNA 为 DNA 复制聚合酶δ的辅助因子， 为 DNA 复制所必需，p21 同 PCNA 结合后直接抑制 DNA 复制。","kp":"ch09_s2_29","oe":["p27属CIP/KIP家族，抑制CDK活性，但不与PCNA结合。","p16属INK4家族，特异性抑制CDK4/6，不与PCNA结合。","p18属INK4家族，抑制CDK4/6，不与PCNA结合。","正确。p21与PCNA结合，直接抑制DNA复制。"]}],"judge":[],"fill":[{"id":"ch09_fill_15","modI":2,"q":"多细胞生物体内的细胞，根据增殖情况可以分为______、______和______3 种类型。","a":"周期中细胞；暂不增殖的细胞（G0 期细胞）；终末分化细胞","kp":"ch09_s2_20","oe":["连续分裂的细胞，不断循环于细胞周期。","即G0期细胞，暂时退出周期，可被激活重返。","失去分裂能力，不再进入细胞周期。"]},{"id":"ch09_fill_23","modI":2,"q":"中期阻断法是获得细胞同步化培养的一种方法，其原理是______。","a":"通过某些药物，如秋水仙素等，抑制微管聚合，从而有效抑制细胞分裂器的形成，将细胞阻 断在细胞分裂中期","kp":"ch09_s2_20","oe":["中期阻断法用秋水仙素等抑制微管聚合，破坏纺锤体，使细胞停滞于中期。"]}],"short":[{"id":"ch09_short_6","modI":2,"q":"如何利用胸腺嘧啶和秋水仙素获得同步培养的细胞？","a":"（1）高浓度的胸腺嘧啶能够阻断 DNA 合成所需的核苷酸的合成，因此将细胞群体培 养在具有高浓度的胸腺嘧啶的培养液中时，非同步化的细胞能够正常地通过细胞周期，但到 达 S 期时，因 DNA 的合成被阻断，这些细胞不能顺利通过 S 期进入 G2 期。经过对 S 期的 短暂阻断，再改变胸腺嘧啶的浓度，解除抑制，所有的细胞都开始 DNA 的合成，即获得处 于同步生长的细胞。 （2）秋水仙素可抑制微管的聚合，因而抑制有丝分裂器的形成，将细胞阻断在有丝分裂的 中期，适当时间后解除秋水仙素的作用，即获得处于中期的同步化的细胞。这一方法称为中 期阻断法。","kp":"ch09_s2_25"}],"calc":[],"term":[{"id":"ch09_term_6","modI":2,"term":"中间体（midbody）。","def":"中间体（midbody）是指在分裂沟下方，除肌动蛋白之外，还有微管、小膜泡等物质聚 集，共同构成的一个环形致密层。","kps":"","kp":"ch09_s2_22"},{"id":"ch09_term_13","modI":2,"term":"限制点（restriction point）。","def":"在 Gl 期的晚期阶段，细胞对一些环境因素敏感，如果细胞继续分裂，则可以通过这个 特定时期，进入 S 期，这一特定时期即限制点，在酵母中称为起始点。","kps":"","kp":"ch09_s2_22"},{"id":"ch09_term_19","modI":2,"term":"染色体整列（chromosome alignment）。","def":"在细胞分裂的前中期染色体向赤道板的位置移动的过程称为染色体整列。","kps":"","kp":"ch09_s2_26"}]},{"i":3,"name":"三 细胞周期的调控之—engine","slides":[{"i":35,"sec":"","title":"三 细胞周期的调控之—engine","notes":"MPF\n（maturation promoting factor）\n（mitosis promoting factor）\n（M-phase promoting factor）\n【中文讲解·对照课本/考点】\n考点：三 细胞周期的调控之—engine ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ●核仁结构的动态变化依赖于rDNA转录活性和细胞周期的运行第五节 染色质结构和基因转录●活性染色质及其主要特征\n\n【本页英文讲解】\n本页主题是细胞周期调控的“引擎”——MPF。原文列出MPF的三种名称：卵细胞成熟促进因子（maturation promoting factor）、细胞有丝分裂促进因子（mitosis promoting factor）、M期促进因子（M-phase promoting factor）。三者指同一物质，即由周期蛋白B（cyclin B）与CDK1组成的复合物，能促使细胞进入M期，是细胞周期研究史上的里程碑发现。","page":36,"level":"掌握","img":"assets/img/ch09/p036.jpg","anim":"cyclin_cdk","fig":null,"points":["卵细胞成熟促进因子","细胞有丝分裂促进因子","M 期促进因子"],"check":{"q":"MPF是指由下列哪两者组成的复合物？","o":["A. cyclin D与CDK4","B. DNA聚合酶与PCNA","C. cyclin B与CDK1","D. p53与p21"],"a":"C","e":"MPF又称卵细胞成熟促进因子、有丝分裂促进因子、M期促进因子，由周期蛋白B(cyclin B)与CDK1组成，促使细胞进入M期。","oe":["错误，cyclin D-CDK4调节G1期进程。","错误，二者参与DNA复制，不是MPF。","正确，MPF由周期蛋白B与CDK1组成。","错误，p53、p21参与DNA损伤后的阻滞。"]},"cards":null,"mem":"MPF三名一体：成熟/有丝分裂/M期促进因子","big":"assets/img/ch09/big/p036.jpg","terms":[{"t":"MPF","en":"maturation/M-phase promoting factor","d":"M期促进因子，由cyclin B + CDK1组成，推动G2→M。"}],"summary":"考点：三 细胞周期的调控之—engine ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「三 细胞周期的调控之—engine」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞周期调控像“开车”：CDK 是发动机，cyclin 是随周期更换的油门/挡位，检验点是刹车和路检。发动机与对应 cyclin 组合，按时点依次启动 DNA 复制、分裂等工序。"},{"i":36,"sec":"","title":"引言：MPF (maturation promoting factor)","notes":"促成熟因子的发现\n实验现象：人Hella细胞的M期细胞和鼠Ptk间期细胞融合诱导间\n期细胞染色体超前凝集 (premature chromosome condensation,\nPCC) /也称早熟染色体凝缩。\n合，M期的细胞质总能诱导非有丝分裂的细胞中的染色\n质提前凝集，将这种现象称为PCC。\n● 提示M期细胞存在一种使染色质由松散状态凝集成染\n色体的物质，诱导PCC因子-MPF","page":37,"level":"掌握","img":"assets/img/ch09/p037.jpg","anim":null,"fig":null,"points":["处于分裂期（M）细胞与处于间期细胞融(G1/S/G2)"],"check":{"q":"M期细胞与间期细胞融合诱导PCC现象说明？","o":["A. 间期细胞质中含有促凝集因子","B. 染色质凝集与细胞质因子无关","C. PCC是DNA复制异常的结果","D. M期细胞质中存在使染色质提前凝集的因子(MPF)"],"a":"D","e":"M期HeLa细胞与间期Ptk细胞融合后，M期细胞质能诱导间期染色质提前凝集，称早熟染色体凝集(PCC)，提示M期细胞存在诱导PCC的因子即MPF。","oe":["错误，促凝集因子来自M期细胞质。","错误，PCC正说明与M期细胞质因子有关。","错误，PCC是M期因子诱导的提前凝集。","正确，PCC提示M期细胞质含MPF。"]},"cards":null,"mem":"M期间期融合→染色体早凝PCC→提示MPF","big":"assets/img/ch09/big/p037.jpg","summary":"促成熟因子的发现","goal":"学完应能掌握并运用「引言：MPF (maturation promoting factor)」的核心内容，能解释其机制、比较相关概念。","intuition":"MPF 像“M 期启动钥匙”：把 M 期细胞质注入卵母细胞能催它进入 M 期，说明其中含促分裂因子。"},{"i":37,"sec":"","title":"G1:细单线状","notes":"S:粉末状\nG2:双线染色体\n\n【读图讲解】\n本页展示G1、S、G2期染色质形态差异。设计为将不同周期的人细胞与M期细胞融合，诱导早熟染色体凝集，再观察其形态。三列分别对应G1、S、G2期细胞与M期细胞融合，下排为相应光镜照片：G1期呈细单线状(A)，S期呈粉末状或颗粒状(B)，G2期呈双线染色体(C)；各图右侧另标有M期人染色体作对照。要点：随DNA复制进程，染色质凝集形态由细单线、粉末到双线变化，可借此判断细胞所处周期阶段。","page":38,"level":"掌握","img":"assets/img/ch09/p038.jpg","anim":null,"fig":null,"points":["G1期染色体呈细单线状","S期呈粉末状","G2期呈双线染色体"],"check":{"q":"将各期人细胞与M期细胞融合诱导早熟染色体凝集，S期细胞的染色质表现为？","o":["A. 细单线状","B. 粉末状或颗粒状","C. 双线染色体","D. 环状"],"a":"B","e":"早熟染色体凝集中，G1期呈细单线状，S期呈粉末状或颗粒状，G2期呈双线染色体，可借此判断细胞所处周期阶段。","oe":["细单线状是G1期早熟染色体的形态。","S期染色质呈粉末状或颗粒状，正确。","双线染色体是G2期早熟染色体的表现。","该实验未描述环状染色质，S期表现为粉末状。"],"basis":"S:粉末状 ... S期呈粉末状或颗粒状"},"cards":null,"mem":"PCC形态辨周期：G1细单线、S粉末、G2双线","big":"assets/img/ch09/big/p038.jpg","summary":"本页展示G1、S、G2期染色质形态差异","goal":"学完应能掌握并运用「G1:细单线状」的核心内容，能解释其机制、比较相关概念。","intuition":"周期中染色体形态像“换装”：G1 细线、S 粉末状、G2 双线，M 期凝缩成染色体。"},{"i":38,"sec":"","title":"PCC(premature chromosome condensation)","notes":"MPF (maturation/mitosis/M phase-promoting factor)\nthe chromosomes are not condensed, so individual chromosomes\ncannot be distinguished.\nnuclear envelope of the G1 cell to retract into the ER, so that it\nis not visible; ●it also caused the G1 cell chromosomes to\npartially condense.\n【中文讲解·对照课本/考点】\n考点：三 细胞周期的调控之—engine ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 染色体（chromosome）：当细胞进入有丝分裂时，伸展、弥散的丝状染色质高度折叠、盘曲而凝缩成条状或棒状的特殊形态，称为染色体。\n\n【本页英文讲解】\n本页主题是早熟染色体凝集（premature chromosome condensation，PCC）。原文说明：未融合的间期细胞（interphase cells）核膜完整、染色体未凝集，故无法分辨单条染色体；而来自M期细胞质（Mitotic cell cytoplasm）的因子（即MPF）可使G1细胞核膜回缩进入内质网（ER）而消失，并使G1细胞染色体部分凝集。该实验证明MPF能诱导间期核提前进入M期状态。","page":39,"level":"掌握","img":"assets/img/ch09/p039.jpg","anim":null,"fig":null,"points":["In unfused interphase cells, the nuclear envelope is intact and","A factor from the Mitotic cell cytoplasm has caused● the"],"check":{"q":"早熟染色体凝集(PCC)中，M期细胞质使G1期细胞发生的变化是？","o":["A. 核膜增厚，染色体完全解凝","B. 核膜回缩进入内质网而消失，染色体部分凝集","C. 细胞立即完成DNA复制","D. 细胞质分裂提前完成"],"a":"B","e":"未融合的间期细胞核膜完整、染色体不能分辨；来自M期细胞质的因子使G1细胞核膜回缩进入内质网而消失，并使染色体部分凝集，证明MPF可诱导间期核提前进入M期状态。","oe":["错误，核膜消失而非增厚，染色体部分凝集。","正确，M因子使G1核膜回缩入ER并部分凝集。","错误，PCC是染色体凝集，与DNA复制无关。","错误，PCC不涉及胞质分裂提前。"]},"cards":null,"mem":"MPF致核膜退入ER、染色体部分凝集=PCC","big":"assets/img/ch09/big/p039.jpg","terms":[{"t":"PCC","en":"premature chromosome condensation","d":"将M期细胞与间期细胞融合后，间期染色体被诱导提前凝缩的现象。"}],"summary":"考点：三 细胞周期的调控之—engine ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「PCC(premature chromosome condensation)」的核心内容，能解释其机制、比较相关概念。","intuition":"PCC 像“提前凝缩实验”：把 M 期细胞与间期细胞融合，间期染色体会被 M 期因子催着提前凝缩。","experiment":"【经典实验·PCC】把 M 期细胞与间期细胞融合，间期核被 M 期因子诱导提前凝缩成染色体(PCC)，证明 M 期细胞质含有促分裂/凝缩的活性因子(MPF)。"},{"i":39,"sec":"","title":"非洲爪蟾卵细胞也证实:MPF活性","notes":"A 取自M期爪蟾卵细胞的细胞质注射到卵母细胞中, 促\n进后者进入第一次减数分裂的M期,引起核破裂并形成\n纺锤体.\nB 当细胞质取自间期的卵时，不引起卵母细胞进入M期。\n因此A的提取物必定含有某些活性成分-M期促进因子\nMPF -以推动细胞进入M期.","page":40,"level":"掌握","img":"assets/img/ch09/p040.jpg","anim":"mpf_xenopus","fig":null,"points":["将M期爪蟾卵细胞质注射到卵母细胞，可促进其进入第一次减数分裂M期，引起核破裂并形成纺锤体","取自间期的卵细胞质则无此作用","说明M期提取物含M期促进因子(MPF)"],"check":{"q":"将M期爪蟾卵细胞的细胞质注射到卵母细胞中，可观察到？","o":["A. 促进其进入M期，引起核破裂并形成纺锤体","B. 促进其进入S期并复制DNA","C. 抑制其成熟而停留于间期","D. 引起卵母细胞迅速凋亡"],"a":"A","e":"M期爪蟾卵细胞质含MPF，注射后可推动卵母细胞进入第一次减数分裂M期，引起核破裂并形成纺锤体；间期卵细胞质则无此作用。","oe":["正确，M期细胞质含MPF，可推动卵母细胞进入M期。","错误，M期细胞质推动进入M期而非S期。","错误，其作用是促进而非抑制卵母细胞成熟。","错误，该实验表现为进入M期而非凋亡。"]},"cards":null,"mem":"爪蟾M期胞质注射→卵母进M期，证MPF活性","big":"assets/img/ch09/big/p040.jpg","summary":"A 取自M期爪蟾卵细胞的细胞质注射到卵母细胞中, 促","goal":"学完应能掌握并运用「非洲爪蟾卵细胞也证实:MPF活性」的核心内容，能解释其机制、比较相关概念。","intuition":"爪蟾卵实验像“验证 MPF 存在”：M 期细胞质能催卵母细胞进 M 期，间期细胞质则不能。"},{"i":40,"sec":"","title":"M期促进因子(M phase-promoting factor)","notes":"MPF\n细胞促分裂因子(Mitosis-promoting factor)\n促成熟因子(Maturation-promoting factor)\n45kD两种蛋白(2个不同亚基)组成的异二聚体, 结合\n后表现丝氨酸/苏氨酸蛋白激酶活性\n芽殖酵母cdc28)+cyclin B\nCDK1在G2晚期-M期中段活性最大\n【中文讲解·对照课本/考点】\n考点：三 细胞周期的调控之—engine ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页讲解】\n本页讲解M期促进因子（MPF，maturation-promoting factor），又称促成熟因子或细胞促分裂因子。1988年从非洲爪蟾中纯化MPF，鉴定为由32kD与45kD两种蛋白（两个亚基）组成的异二聚体，结合后表现出丝氨酸/苏氨酸蛋白激酶活性。研究发现MPF=CDK1（相当于裂殖酵母cdc2/芽殖酵母cdc28）+cyclin B，在G2向M期转化中起重要作用，CDK1在G2晚期至M期中段活性最大。考点联系翟中和《细胞生物学》第十三章细胞周期调控。","page":41,"level":"掌握","img":"assets/img/ch09/p041.jpg","anim":null,"fig":null,"points":["1988年, 将非洲爪蟾的MPF纯化，经鉴定由32kD和","进一步研究发现MPF=CDK1 (相当于34kD裂殖酵母cdc2/","G2→M 的转化中起重要作用"],"check":{"q":"关于MPF分子组成的叙述，正确的是？","o":["A. 由两个相同亚基组成的同二聚体","B. 由32kD与45kD两个亚基组成的异二聚体，具丝/苏氨酸激酶活性","C. 由DNA与蛋白质组成的复合物","D. MPF=CDK1+cyclin D"],"a":"B","e":"1988年从非洲爪蟾纯化MPF，由32kD和45kD两种蛋白(两个不同亚基)组成异二聚体，表现丝氨酸/苏氨酸蛋白激酶活性；MPF=CDK1(cdc2/cdc28)+cyclin B。","oe":["错误，MPF由两个不同亚基组成异二聚体。","正确，MPF为32kD与45kD两亚基异二聚体。","错误，MPF是蛋白质复合物，不含DNA。","错误，MPF=CDK1+cyclin B，非cyclin D。"]},"cards":null,"mem":"MPF=CDK1+cyclinB，异二聚体丝/苏激酶","big":"assets/img/ch09/big/p041.jpg","summary":"kD两种蛋白(2个不同亚基)组成的异二聚体, 结合","goal":"学完应能掌握并运用「M期促进因子(M phase-promoting factor)」的核心内容，能解释其机制、比较相关概念。","intuition":"MPF 有三个名字：促成熟因子、M 期促进因子、细胞促分裂因子——都指同一复合物。"},{"i":41,"sec":"","title":"M期促进因子      MPF（G2→M期中心调节作用）","notes":"催化亚基              调节亚基\n(蛋白激酶)            (周期蛋白cyclin)\n非洲爪蟾   p32               p45=Cyclin B\n裂殖酵母   p34 (Cdc2基因编码)\n【p34cdc2】\nCdc2激酶第一个被发现， p56Cdc13\n被命名为Cdk1(CDK1)\n人体中也已发现。\n芽殖酵母   p34 (Cdc28基因编码)\n【p34cdc28】","page":42,"level":"掌握","img":"assets/img/ch09/p042.jpg","anim":null,"fig":null,"points":["MPF由催化亚基(蛋白激酶)和调节亚基(周期蛋白cyclin)组成","爪蟾为p32、p45(=Cyclin B)，裂殖酵母为p34(Cdc2基因编码)"],"check":{"q":"关于MPF的组成，下列叙述正确的是？","o":["A. 由两个相同的催化亚基组成","B. 由催化亚基p34(Cdk1)和调节亚基cyclin B组成","C. 其调节亚基是Cdc25磷酸酶","D. 其催化亚基是cyclin B"],"a":"B","e":"MPF即CDK1，由催化亚基p34(Cdc2/Cdk1，蛋白激酶)与调节亚基cyclin B组成，其活性随cyclin浓度变化而变化。","oe":["错误，MPF由催化亚基与调节亚基两种不同亚基组成。","正确，MPF由催化亚基Cdk1和调节亚基cyclin B组成。","错误，Cdc25是磷酸酶而非MPF的调节亚基。","错误，cyclin B是调节亚基，催化亚基是Cdk1。"]},"cards":null,"mem":"MPF双亚基：催化(激酶)+调节(cyclin)","big":"assets/img/ch09/big/p042.jpg","summary":"催化亚基              调节亚基","goal":"学完应能掌握并运用「M期促进因子      MPF（G2→M期中心调节作用）」的核心内容，能解释其机制、比较相关概念。","intuition":"MPF 像“双人组合”：一个催化亚基（激酶）+ 一个调节亚基（cyclin B），缺一不可。"},{"i":42,"sec":"","title":"MPF的结构：催化亚基CDK + 调节亚基cyclin","notes":"MPF由两个不同亚基组成的异二聚体：①催化亚基是丝氨酸/苏氨酸型蛋白激酶，将磷酸基团从ATP转移到特定底物的丝氨酸、苏氨酸残基上；②调节亚基为周期蛋白(cyclin)。其活性有赖于调节亚基，故又称周期蛋白依赖性激酶(CDKs)。不同物种：裂殖酵母为cdc2(34kDa激酶)+p56cdc13(周期蛋白)；芽殖酵母为cdc28(34kDa激酶)；非洲爪蟾为CDK1(32kDa激酶)+cyclin B。","page":43,"level":"掌握","img":"assets/img/ch09/p043.jpg","anim":"mpf_structure","fig":null,"points":["催化亚基","调节亚基 周期蛋白(cyclin)"],"check":{"q":"MPF中催化亚基与调节亚基分别是？","o":["A. 催化亚基为cyclin，调节亚基为CDK","B. 两个亚基均为周期蛋白","C. 两个亚基均为CDK","D. 催化亚基为CDK，调节亚基为周期蛋白(cyclin)"],"a":"D","e":"MPF是丝氨酸/苏氨酸型蛋白激酶，其催化亚基为CDK，调节亚基为周期蛋白(cyclin)，故又称周期蛋白依赖性激酶；如裂殖酵母cdc2+p56cdc13、爪蟾CDK1+cyclin B。","oe":["错误，二者角色互换，cyclin是调节亚基。","错误，MPF含催化亚基CDK和调节亚基cyclin。","错误，MPF由CDK与周期蛋白两个亚基组成。","正确，CDK为催化亚基，cyclin为调节亚基。"]},"cards":null,"mem":"催化亚基p34/cdk1，调节亚基cyclin，异二聚体","big":"assets/img/ch09/big/p043.jpg","summary":"MPF由两个不同亚基组成的异二聚体：①催化亚基是丝氨酸/苏氨酸型蛋白激酶，将磷酸基团从ATP转移到特定底物的丝氨酸、苏氨酸残基上；②调节亚基为周期蛋白(cyclin)","goal":"学完应能掌握并运用「MPF的结构：催化亚基CDK + 调节亚基cyclin」的核心内容，能解释其机制、比较相关概念。","intuition":"MPF 由催化亚基 CDK + 调节亚基 cyclin 组成的异二聚体；不同物种名字不同但本质一样。"},{"i":43,"sec":"","title":"功能：MPF 参与多种有丝分裂早期事件控制","notes":"●组蛋白H1磷酸化，染色质凝缩，变粗变短形成光镜下可\n辨的早期染色体结构(cohesin/condensin)-遗传物质准确分离\n的先决条件。\n● 核纤层蛋白(lamin)磷酸化，引起核纤层解体，进\n而导致核被膜破裂形成小囊泡。\n● 使微管结合蛋白(MAPs)磷酸化，调节微管的动力\n学行为，利于纺锤体的形成。\n● 核仁蛋白磷酸化，核仁解体。","page":44,"level":"掌握","img":"assets/img/ch09/p044.jpg","anim":null,"fig":null,"points":["为细胞进入有丝分裂作准备"],"check":{"q":"下列哪项是MPF参与的有丝分裂早期事件？","o":["A. 使核纤层蛋白磷酸化，导致核纤层解体、核被膜破裂","B. 使组蛋白去磷酸化并使染色体解凝","C. 抑制微管结合蛋白磷酸化，阻止纺锤体形成","D. 促进核仁蛋白去磷酸化使核仁增大"],"a":"A","e":"MPF参与多种有丝分裂早期事件：组蛋白H1磷酸化促染色质凝缩；lamin磷酸化致核纤层解体、核被膜破裂；MAPs磷酸化调节微管动力学以形成纺锤体；核仁蛋白磷酸化使核仁解体。","oe":["正确，lamin磷酸化致核纤层解体核膜破裂。","错误，MPF使组蛋白H1磷酸化，促染色质凝缩。","错误，MPF使MAPs磷酸化，利于纺锤体形成。","错误，MPF使核仁蛋白磷酸化，核仁解体。"]},"cards":null,"mem":"MPF磷酸化：H1缩染色质，lamin裂核膜，核仁解体","big":"assets/img/ch09/big/p044.jpg","summary":"组蛋白H1磷酸化，染色质凝缩，变粗变短形成光镜下可","goal":"学完应能掌握并运用「功能：MPF 参与多种有丝分裂早期事件控制」的核心内容，能解释其机制、比较相关概念。","intuition":"MPF 像“M 期总开关”：触发染色体凝缩、核膜解体、纺锤体装配等一系列早期事件。"}],"mcq":[{"id":"ch09_mcq_1","mod":"三 细胞周期的调控之—engine","modI":3,"q":"裂殖酵母中的 cdc2 基因在芽殖酵母中的同源物是（      ）。","o":["A．cdc2","B．cdc25","C．cdc28","D．cdc20"],"a":"C","e":"在芽殖酵母中的 cdc28 基因和裂殖酵母的 cdc2 基因产物为同源物，等同于 CDK1。","kp":"ch09_s3_41","oe":["cdc2是裂殖酵母的基因名，不是芽殖酵母中的同源物名称。","cdc25编码磷酸酶，去磷酸化激活CDK，并非cdc2的同源物。","正确。芽殖酵母cdc28与裂殖酵母cdc2同源，即CDK1。","cdc20是APC的正调控因子，非cdc2的同源物。"]},{"id":"ch09_mcq_5","mod":"三 细胞周期的调控之—engine","modI":3,"q":"如果将双线期灯刷染色体在放射性标记的尿嘧啶中培养，然后通过放射自显影进行检测， 大部分的放射性将出现在（          ）。","o":["A．灯刷环上","B．沿着灯刷骨架","C．在灯刷环上与灯刷骨架上均有","D．与染色体无关"],"a":"A","e":"在很多动物尤其是鱼类、两栖类、爬行类和鸟类的雌性动物，染色体去凝集成一种 特殊的巨大的染色体结构，形似灯刷，称为灯刷染色体，在灯刷上有很多侧环结构，是进行 活跃转录 RNA 的部位。","kp":"ch09_s3_37","oe":["正确。灯刷环是活跃转录RNA的部位，放射性集中于侧环上。","灯刷骨架为染色体轴，非活跃转录区，放射性很少。","转录主要发生在侧环，骨架几乎无RNA合成，故不选。","灯刷环转录产生RNA，放射性在染色体上，故该说法错误。"]},{"id":"ch09_mcq_9","mod":"三 细胞周期的调控之—engine","modI":3,"q":"下列关于纺锤体的叙述正确的是（                ）。","o":["A．由微管和微管结合蛋白组成","B．有动力微管和极性微管两种类型","C．是细胞分裂中染色体分离相关细胞器","D．以上全对"],"a":"D","e":"","kp":"ch09_s3_43","oe":["该说法本身正确，但仅涉及纺锤体的组成，不全面。","该说法本身正确，但仅涉及纺锤体微管的类型，不全面。","该说法本身正确，但仅涉及纺锤体的功能，不全面。","正确。纺锤体由微管及结合蛋白构成，分动粒/极性微管，介导染色体分离。"]},{"id":"ch09_mcq_10","mod":"三 细胞周期的调控之—engine","modI":3,"q":"在有丝分裂的哪个时期染色体最分散？（                 ）","o":["A．前期","B．前中期","C．中期","D．后期"],"a":"A","e":"B 项，前中期的一个特征性现象是染色体整列，染色体彼此靠近慢慢排列在赤道板 上。C 项，中期染色体已完成整列，规则的排列在赤道板上。D 项，后期染色体在纺锤丝的 牵引下移向细胞两极，排列较规则。","kp":"ch09_s3_43","oe":["正确。前期染色体凝缩程度最低、最为分散，故答案选前期。","前中期染色体逐渐整列、彼此靠近，比前期更集中。","中期染色体已规则排列在赤道板上，高度聚集。","后期染色体在纺锤丝牵引下移向两极，排列较规则。"]}],"judge":[{"id":"ch09_judge_5","modI":3,"q":"有丝分裂中核膜变为碎片，因此能像内质网和高尔基体等膜被细胞器一样在两个子细胞 间分配。（     ）","a":"对","e":"事实上，核膜与内质网膜之间是连续的，因此某些区段含有具两个来源的膜。","kp":"ch09_s3_35","oe":["核膜与内质网膜连续，分裂中解体成片段，可随ER在两子细胞间分配。","若判错，则忽略核膜与ER膜连续、随膜系统重建而分配的事实。"]},{"id":"ch09_judge_8","modI":3,"q":"在减数分裂交换期间，两条染色体上编码同样基因的区域必须彼此配对。（                      ）","a":"对","e":"如果染色体的非对应区域也能发生重组，将产生大范围的基因重排，这对于生物而 言几乎是灾难性的。然而，少数罕见的“不等交换”对生物体可能有利，基因组中已发现这些 罕见的例子。","kp":"ch09_s3_37","oe":["交换发生在同源染色体对应区域之间，只有同源区配对才能保证基因不发生重排。","误以为任意区域均可配对交换，若不对应区重组会造成大范围基因重排，对生物有害。"]},{"id":"ch09_judge_10","modI":3,"q":"分开的染色体分别向细胞两极运动主要是通过着丝点微管的负端的不断解聚而实现的。 （   ）","a":"错","e":"染色体分离机制： （1）后期 A：动粒微管逐渐变短，将染色体移向两极。动粒微管的缩短，是由于动粒端微 管蛋白解聚造成的，蛋白解聚又是由于 dynein 蛋白拖着动粒盘向着极部运动引起的。 （2）后期 B：极性微管不断增长，使两极间距离逐渐拉长。在后期 B，Kinesin 蛋白与来自 一端的极性微管结合，同时与来自另一端的极性微管搭桥，当 Kinesin 蛋白带着连接的微管 沿着另一根微管向着正极运动时，可使两根微管之间产生相互滑动，由此使两极间的距离逐 渐变长。","kp":"ch09_s3_37","oe":["误认为仅靠动粒微管负端解聚即可驱动染色体移向两极。","后期A动粒微管在动粒端正端解聚，由dynein拖动粒向极移动，并有马达蛋白参与。"]},{"id":"ch09_judge_14","modI":3,"q":"中心体的复制独立于染色体的复制。（           ）","a":"对","e":"中心体的复制和染色体的复制是不相关的两个过程。例如在减数第二次分裂，染色 体不复制而中心体复制。","kp":"ch09_s3_37","oe":["中心体与染色体复制互不相关，减数第二次分裂染色体不复制而中心体仍复制。","误以为二者复制同步偶联，其实中心体复制可独立于染色体复制进行。"]}],"fill":[{"id":"ch09_fill_1","modI":3,"q":"细胞减数分裂中，根据细胞形态的变化可以将前期 I 分为______、______、______、______、 ______。","a":"细线期；偶线期；粗线期；双线期；终变期","kp":"ch09_s3_39","oe":["染色质凝集成细线，可见染色粒，尚未配对。","同源染色体配对（联会），形成联会复合体。","同源染色体变粗，非姐妹染色单体间发生交换重组。","联会复合体解体，同源染色体分开并可见交叉。","染色体高度凝集，交叉端化，核仁核膜消失。"]},{"id":"ch09_fill_6","modI":3,"q":"卵母细胞在减数分裂的前期Ⅰ中的______，染色体去凝集形成巨大的灯刷染色体。","a":"双线期","kp":"ch09_s3_39","oe":["卵母细胞在双线期染色体去凝集成灯刷染色体，进行转录。"]},{"id":"ch09_fill_7","modI":3,"q":"间期细胞与 M 期细胞融合后将产生染色体超前凝集现象，其中 S 期超前凝集染色体呈 ______状。","a":"粉末","kp":"ch09_s3_36","oe":["S期染色质尚未凝集，故超前凝集时呈粉末状。"]},{"id":"ch09_fill_10","modI":3,"q":"在间期的细胞核中，染色质以______的形式存在，而再分裂期则以______的形式存在。","a":"分散；凝聚","kp":"ch09_s3_36","oe":["间期染色质松散分散，利于转录和复制。","分裂期染色质高度螺旋凝聚成染色体，便于分配。"]},{"id":"ch09_fill_18","modI":3,"q":"细胞减数分裂 I 的前期可以分为______、______、______、______、______5 个亚期。","a":"细线期；偶线期；粗线期；双线期；终变期","kp":"ch09_s3_39","oe":["染色质凝集成细线，可见染色粒，尚未配对。","同源染色体配对（联会），形成联会复合体。","同源染色体变粗，非姐妹染色单体间发生交换重组。","联会复合体解体，同源染色体分开并可见交叉。","染色体高度凝集，交叉端化，核仁核膜消失。"]},{"id":"ch09_fill_20","modI":3,"q":"选择细胞同步化方法，主要是收集单层培养细胞中的______。期细胞，再加入新鲜培养 基继续培养。","a":"G1／s","kp":"ch09_s3_36","oe":["选择同步化收集中层培养的G1/S期细胞，换新鲜培养基继续培养。"]},{"id":"ch09_fill_21","modI":3,"q":"细胞有丝分裂时，______对染色体平衡运动和分配起着重要作用。","a":"有丝分裂器","kp":"ch09_s3_35","oe":["有丝分裂器包括纺锤体、中心体等，牵引染色体保证均等分配。"]},{"id":"ch09_fill_22","modI":3,"q":"卫星 DNA（高度重复序列 DNA），主要出现在染色体的______区。","a":"主缢痕","kp":"ch09_s3_37","oe":["主缢痕是着丝粒所在区域，富含高度重复的卫星DNA。"]},{"id":"ch09_fill_24","modI":3,"q":"动粒和着丝粒由于它们在染色体中的位置相同，而导致认识上的混淆，其实它们是两个 不同的概念，最本质的差别是：前者是_________，后者则是_________。","a":"蛋白质；DNA","kp":"ch09_s3_37","oe":["动粒是着丝粒两侧由蛋白质构成的盘状结构，供纺锤体附着。","着丝粒是染色体上含特定DNA序列的区域，是动粒的座位。"]}],"short":[{"id":"ch09_short_5","modI":3,"q":"简述细胞有丝分裂的过程。","a":"有丝分裂过程分为前期、前中期、中期、后期、末期和胞质分裂。 前期：染色体凝集，核膜解体及核仁消失。 前中期：核膜破裂，纺锤体开始组装。 中期：染色体排列到赤道面上。 后期：中期染色体的两条染色单体相互分离，形成子代染色体，并分别向两极运动。 末期：子核形成。 胞质分裂：开始于细胞分裂后期，完成于细胞分裂末期","kp":"ch09_s3_35"},{"id":"ch09_short_14","modI":3,"q":"试比较染色体着丝粒与着丝点的区别与联系。","a":"（1）着丝粒与着丝点的区别 ①着丝粒是指位于染色体主缢痕部位的染色质。 ②着丝点即动粒，在主缢痕处两个染色单体的外侧表面部位的特殊结构，它与染色体微管接 触，是微管蛋白的组织中心。在电镜下，动粒为一个圆盘状结构，分内、中、外三层。 （2）着丝粒与着丝点的联系 着丝点（动粒）是附着于着丝粒上的一种特殊结构，动粒的外侧主要用于纺锤体微管附着， 内侧与着丝粒相互交织。由于动粒和着丝粒联系紧密，结构成分相互穿插，在功能方面联系 密切，因而两者常被称为着丝粒-动粒复合体。","kp":"ch09_s3_37"},{"id":"ch09_short_18","modI":3,"q":"试述动粒的结构及功能。","a":"（1）动粒的结构 动粒又称着丝点，是附着于着丝粒上的一种细胞结构。动粒的外侧主要用于纺锤体微管附着， 内侧与着丝粒相互交织。在电镜下，动粒为一个圆盘状结构，分为内板、中间间隙、外板和 纤维冠 4 个部分。 （2）动粒的功能 动粒是有丝分裂和减数分裂中染色体分离必不可少的要素。在细胞分裂（包括有丝分裂和减 数分裂）的前、中、后期等几个阶段，纺锤体的纺锤丝（或星射线）需附着在染色体的动粒 上（而非着丝粒上）。在细胞分裂过程中，微管与动粒相连，牵引染色体在分裂中期进行染 色体整列，在分裂后期，牵引分开的染色体分别向细胞的两极运动，形成两个新的子细胞。","kp":"ch09_s3_42"}],"calc":[{"id":"ch09_calc_6","modI":3,"q":"细胞通过什么机制将染色体排列到赤道板上？","a":"解释这一问题，目前流行两种学说，即牵拉假说和外推假说。牵拉假说认为，染色体向 赤道板方向运动，是由于动粒微管牵拉的结果。动粒微管越长，拉力越大。当来自两极的动 粒微管的拉力相等时，染色体即被稳定在赤道板上；外推假说认为，染色体向赤道方向移动， 是由于星体的排斥力将染色体外推的结果。染色体距离中心体越近，星体对染色体的外推力 越强，当来自两极的推力达到平衡时，染色体即被稳定在赤道板上。这两种假说并不排斥， 有时可能同时作用，或有其他机制共同参与，最终将染色体排列在赤道板上。由于某些染色 体不能被微管及时捕捉而滞后，Mad2 和 Bubl 不能从这些染色体的动粒上消失，后期则不能 启动，染色单体不能相互分离。只有等到这些染色体也被微管捕捉并排列到赤道板上，Mad 和 Bubl 从动粒上消失，后期才能开始启动。故只有染色体排列到赤道板，后期才能开始启 动，细胞周期才能顺利进行。","kp":"ch09_s3_37"},{"id":"ch09_calc_11","modI":3,"q":"细胞通过什么机制将染色体排列到赤道板上？有何生物学意义？","a":"（1）染色体排列到赤道板的机制 Mad2 和 Bub1 位于前期和前中期的染色体的动粒上，二者可以促使动粒敏化，促使微管与 动粒接触。只有当这些染色体也被微管捕捉并排列到赤道板上，Mad2 和 Bub1 从动粒上消 失，后期才能开始启动。 ①牵拉假说认为，染色体向赤道板方向运动是动粒微管牵拉的结果。动粒微管越长，拉力越 大，当来自两极的动粒微管拉力相等时，染色体即被稳定在赤道板上。 ②外推假说认为，染色体向赤道方向移动是星体的排斥力将染色体外推的结果。染色体距离 中心体越近，星体对染色体的外推力越强，当来自两极的推力达到平衡时，染色体即被稳定 在赤道板上。 这两种假说并不相互排斥，有时可能同时作用，或有其他机制共同参与，最终将染色体排列 在赤道板上。 （2）染色体排列的生物学意义 ①微管与动粒接触后促使一些蛋白质分子从动粒上释放出来，促使 APC 活化，使细胞从中 期进入到后期； ②保证每条染色体的两条染色单体分离后分别移向细胞的两极，确保细胞经过有丝分裂后染 色体的数目保持恒定，保证生物体的遗传稳定性。","kp":"ch09_s3_37"}],"term":[{"id":"ch09_term_16","modI":3,"term":"着丝点微管。","def":"着丝点微管又称动粒微管或染色体微管，是从着丝点与一个极相连的微管。","kps":"","kp":"ch09_s3_37"},{"id":"ch09_term_18","modI":3,"term":"核内有丝分裂（intranuclear mitosis）。","def":"核内有丝分裂是指在核分裂过程中核膜始终保持完整的一种有丝分裂方式。纺锤丝可以 完全局限在核内，如酵母菌；也可伸出核膜以外，但仍保持核膜的完整性。","kps":"","kp":"ch09_s3_35"},{"id":"ch09_term_26","modI":3,"term":"诱导同步（Induction Synchrony）","def":"诱导同步是指用物理、化学方法处理培养细胞，使所有细胞群停留在细胞周期的某一时 相，从而使它们的分裂周期同步化的方法。目前应用较广泛的诱导同步方法主要有两种，即 DNA 合成阻断法和分裂中期阻断法。","kps":"","kp":"ch09_s3_35"},{"id":"ch09_term_28","modI":3,"term":"amitosis","def":"amitosis 的中文名称是无丝分裂。无丝分裂是最早发现的一种细胞分裂方式，在无丝分 裂中，核膜和核仁都不消失，没有纺锤体和染色体的出现，这是无丝分裂与有丝分裂的最大 区别。无丝分裂的过程比较简单，一般是细胞核先延长，从核的中部向内凹进，缢裂成为两 个细胞核；然后整个细胞从中部缢裂成两部分，形成两个子细胞。","kps":"","kp":"ch09_s3_35"}]},{"i":4,"name":"3.1 细胞周期蛋白(Cyclin)","slides":[{"i":44,"sec":"3.1 细胞周期蛋白(Cyclin)","title":"3.1 细胞周期蛋白(Cyclin)","notes":"细胞周期蛋白(cyclin):含量随细胞周期进程呈周期性增\n长或消失的蛋白质, 称~。\n芽殖酵母: Cln1, Cln2, Cln3, Clb1~Clb6/cdc28\n裂殖酵母只有一种：Cdc13/cdc2\n哺乳动物: 周期蛋白A, B, D1~D3, E\n乳动物：\n节亚基，(蛋白激酶本身为催化亚基)，两者必须结合后\n才能表现蛋白激酶的活性。","page":45,"level":"掌握","img":"assets/img/ch09/p045.jpg","anim":null,"fig":null,"points":["cyclin广泛存在于从酵母到人等各种真核生物中","cyclin周期中表达的时期不同，执行功能不同。如哺","G1期周期蛋白 eg. Cyclin D.E","S、 G2、有丝分裂早期 eg. Cyclin A, cyclin B","cyclin作为CDK激酶(周期蛋白依赖性蛋白激酶)的调"],"check":{"q":"关于细胞周期蛋白(cyclin)的叙述，正确的是？","o":["A. 含量恒定不变，自身直接具有激酶活性","B. 哺乳动物细胞中只有一种周期蛋白","C. 含量随细胞周期呈周期性变化，作为CDK的调节亚基","D. cyclin是催化亚基，CDK是调节亚基"],"a":"C","e":"cyclin是含量随细胞周期呈周期性出现或消失的蛋白质，作为CDK的调节亚基，二者结合后才表现蛋白激酶活性；如哺乳动物有cyclin A、B、D1到D3、E等。","oe":["错误，cyclin含量周期性变化，本身非催化亚基。","错误，哺乳动物有周期蛋白A、B、D、E等。","正确，cyclin周期变化并作为CDK调节亚基。","错误，CDK是催化亚基，cyclin是调节亚基。"]},"cards":null,"mem":"Cyclin随周期周期消长，为CDK调节亚基","big":"assets/img/ch09/big/p045.jpg","summary":"细胞周期蛋白(cyclin):含量随细胞周期进程呈周期性增","goal":"学完应能掌握并运用「3.1 细胞周期蛋白(Cyclin)」的核心内容，能解释其机制、比较相关概念。","intuition":"cyclin 像“随周期涨落的油门”：含量周期性积累与降解，决定 CDK 何时活跃。","experiment":"【经典实验】Tim Hunt 用海胆卵观察，发现一种蛋白随细胞周期周期性合成与降解，命名为 cyclin（周期蛋白）——它是 CDK 的调节亚基，Hunt 因此获 2001 年诺贝尔生理学或医学奖。"},{"i":45,"sec":"3.1 细胞周期蛋白(Cyclin)","title":"There are ~29 cyclins","notes":"【结合课本/笔记】A protein kinaseis an enzyme that modifies other proteins by chemically adding phosphategroups to them (phosphorylation). This usually results in a functionalchange of the target protein (substrate) by changing enzyme activity,cellular location, or association with other proteins.第二信使：是在细胞内的多由胞外信号分子转导的产物，同时又可以介导下一步的信号转\n【中文讲解·对照课本/考点】\n考点：3.1 细胞周期蛋白(Cyclin) ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页讲解】\n本页为表17-1，主题是脊椎动物（vertebrates）与芽殖酵母（budding yeast）中主要周期蛋白与CDK的配对。表格按复合物归类：G1-Cdk为cyclin D*＋Cdk4、Cdk6（酵母Cln3＋Cdk1**）；G1/S-Cdk为cyclin E＋Cdk2（Cln1、2＋Cdk1）；S-Cdk为cyclin A＋Cdk2及Cdk1**（Clb5、6＋Cdk1）；M-Cdk为cyclin B＋Cdk1（Clb1、2、3、4＋Cdk1）。脚注*指出哺乳动物有D1、D2、D3三种D型周期蛋白；**指出Cdk1原名在脊椎动物和裂殖酵母为Cdc2、在芽殖酵母为Cdc28。右下系统树展示含cyclin box的蛋白，底部标“There are ~29 cyclins”。考点：各类cyclin-Cdk复合物的时相配对。","page":46,"level":"掌握","img":"assets/img/ch09/p046.jpg","anim":null,"fig":null,"points":["脊椎动物与酵母的周期蛋白(cyclin)家族约有29种","哺乳动物M-Cdk为cyclin B + Cdk1；G1-Cdk为cyclin D+Cdk4/6，S-Cdk为cyclin A+Cdk2"],"check":{"q":"在哺乳动物细胞中，驱动M期的M-Cdk复合物是？","o":["A. cyclin D + Cdk4/6","B. cyclin E + Cdk2","C. cyclin B + Cdk1","D. cyclin A + Cdk2"],"a":"C","e":"哺乳动物中G1-Cdk为cyclinD+Cdk4/6，G1/S-Cdk为cyclinE+Cdk2，S-Cdk为cyclinA+Cdk2，M-Cdk为cyclinB+Cdk1。","oe":["错误，cyclinD+Cdk4/6属G1-Cdk复合物。","错误，cyclinE+Cdk2属G1/S-Cdk复合物。","正确，M-Cdk由cyclin B与Cdk1组成。","错误，cyclinA+Cdk2属S-Cdk复合物。"]},"cards":null,"mem":"脊椎动物与酵母周期蛋白家族约29种","big":"assets/img/ch09/big/p046.jpg","summary":"A protein kinaseis an enzyme that modifies other proteins by chemically adding phosphategr","goal":"学完应能掌握并运用「There are ~29 cyclins」的核心内容，能解释其机制、比较相关概念。","intuition":"脊椎动物与酵母的 cyclin 家族约 29 种，各自在不同时相起作用。"}],"mcq":[],"judge":[{"id":"ch09_ajudge_2","modI":4,"q":"cyclin广泛存在于从酵母到人等各种真核生物中","a":"对","e":"本页要点：cyclin广泛存在于从酵母到人等各种真核生物中","kp":"ch09_s4_44","oe":["细胞周期蛋白cyclin在真核生物中高度保守，从酵母到人普遍存在。","误以为cyclin只存在于高等动物，其实低等真核生物如酵母也含有。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":5,"name":"3.2 周期蛋白依赖性蛋白激酶","slides":[{"i":46,"sec":"3.2    周期蛋白依赖性蛋白激酶","title":"3.2    周期蛋白依赖性蛋白激酶","notes":"CDK(cyclin-dependent kinase)\nCDK激酶:\n与周期蛋白(cyclin)结合, 以cyclin为其调\n节亚基, 进而表现蛋白激酶的活性, 称“依赖\n周期蛋白的蛋白激酶(CDK激酶)”.\neg.哺乳动物CDK1~CDK6\n芽殖酵母只有一种CDK: Cdc28+周期蛋白Cln1, Cln2,\nCln3, Clb1~Clb6\n裂殖酵母只有一种CDK: Cdc2+周期蛋白Cdc13\n【中文讲解·对照课本/考点】\n考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页讲解】\n本页讲解周期蛋白依赖性蛋白激酶（CDK，cyclin-dependent kinase），即CDK激酶：它与周期蛋白（cyclin）结合，以cyclin为调节亚基，进而表现蛋白激酶活性。哺乳动物有CDK1~CDK6等多种；芽殖酵母只有一种CDK即Cdc28，搭配周期蛋白Cln1、Cln2、Cln3及Clb1~Clb6；裂殖酵母也只有一种CDK即Cdc2，搭配周期蛋白Cdc13。考点联系翟中和《细胞生物学》第十三章，需掌握CDK与cyclin的配对关系及种属差异。","page":47,"level":"掌握","img":"assets/img/ch09/p047.jpg","anim":null,"fig":null,"points":["CDK激酶与周期蛋白(cyclin)结合，以cyclin为调节亚基而表现蛋白激酶活性","哺乳动物有CDK1~CDK6","芽殖酵母只有一种CDK(Cdc28)，裂殖酵母只有一种CDK(Cdc2)"],"check":{"q":"关于CDK激酶，下列叙述正确的是？","o":["A. 与cyclin结合并以cyclin为调节亚基才表现蛋白激酶活性","B. cyclin是CDK的催化亚基","C. 芽殖酵母中存在多种功能各异的CDK","D. 裂殖酵母中不含任何CDK"],"a":"A","e":"CDK与周期蛋白结合，以cyclin为调节亚基，进而表现蛋白激酶活性；哺乳动物有CDK1~CDK6，而芽殖酵母只有Cdc28，裂殖酵母只有Cdc2。","oe":["正确，CDK结合cyclin作为调节亚基后才具激酶活性。","错误，cyclin是调节亚基而不是催化亚基。","错误，芽殖酵母只有一种CDK即Cdc28。","错误，裂殖酵母含有一种CDK即Cdc2。"]},"cards":null,"mem":"CDK=cyclin依赖激酶，cyclin为调节亚基","big":"assets/img/ch09/big/p047.jpg","summary":"与周期蛋白(cyclin)结合, 以cyclin为其调","goal":"学完应能掌握并运用「3.2    周期蛋白依赖性蛋白激酶」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 像“发动机”：本身不转，必须与 cyclin 结合、被调节后才表现激酶活性。"},{"i":47,"sec":"3.2    周期蛋白依赖性蛋白激酶","title":"20 CDK","notes":"【中文讲解·对照课本/考点】\n考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系\n\n【本页讲解】\n本页取自Trends in Biochemical Sciences 2005年综述，主题是哺乳动物细胞周期蛋白依赖性激酶（cyclin-dependent kinases, CDKs）家族，标注“20 CDK”。图中系统树列出各成员及氨基酸数：Cdk1（297 aa）、Cdk2（298）、Cdk3（305）、Cdk5（292）、Cdk4（303）、Cdk6（326）、Cdk7（346）、Cdk8（464）、Cdk9（372）、Cdk10（360）、Cdk11（502），以及PCTAIRE、PFTAIRE、PITSLRE、CHED、CRK7、CCRK等。右侧条形标注结构域：粉色为Ser/Thr蛋白激酶结构域（Ser/Thr protein kinase），蓝色为核定位信号（nuclear localization signal），青色为卷曲螺旋结构域（coiled-coil domains）。考点：CDK家族成员众多，直接驱动细胞周期的主要是Cdk1、Cdk2、Cdk4、Cdk6。","page":48,"level":"掌握","img":"assets/img/ch09/p048.jpg","anim":null,"fig":null,"points":["CDK家族有20余种，均具Ser/Thr激酶结构域","直接驱动哺乳动物细胞周期进程的主要是Cdk1、Cdk2、Cdk4、Cdk6"],"check":{"q":"直接驱动哺乳动物细胞周期进程的主要CDK是？","o":["A. Cdk7、Cdk8、Cdk9、Cdk10","B. Cdk3、Cdk5、Cdk11、Cdk8","C. PCTAIRE、PFTAIRE、PITSLRE、CHED","D. Cdk1、Cdk2、Cdk4、Cdk6"],"a":"D","e":"哺乳动物CDK家族成员众多，但直接驱动细胞周期的主要是Cdk1、Cdk2、Cdk4和Cdk6。","oe":["错误，Cdk7~Cdk10多参与转录等过程。","错误，Cdk3、Cdk5、Cdk11等并非周期主要驱动者。","错误，PCTAIRE等属相关激酶而非周期驱动CDK。","正确，Cdk1、Cdk2、Cdk4、Cdk6直接驱动细胞周期。"]},"cards":null,"mem":"CDK家族20余种，均有Ser/Thr激酶结构域","big":"assets/img/ch09/big/p048.jpg","terms":[{"t":"核定位信号","en":"nuclear localization signal, NLS","d":"引导蛋白进入细胞核的短序列。"},{"t":"卷曲螺旋结构域","en":"coiled-coil domain","d":"参与蛋白-蛋白相互作用的结构域。"}],"summary":"考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「20 CDK」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 家族有 20 多种，但直接驱动周期的主要是 Cdk1/2/4/6。"},{"i":48,"sec":"3.2    周期蛋白依赖性蛋白激酶","title":"细胞周期控制系统的核心：CDK家族","notes":"as CDKs, 这些激酶的活性在细胞周期进程中rise and fall.\n它蛋白磷酸化；\n不同的。\n\n【读图讲解】\n本页讲细胞周期控制系统的核心——CDK。文字指出：核心是一类蛋白激酶CDKs，其活性在细胞周期中升高与下降；细胞周期进程依赖该酶的激活，其唯一活性是使底物蛋白磷酸化；其活性受cyclin控制，而cyclin浓度在各阶段不同。下方图(Figure 19-10)以多条曲线表示G1/S期CDK、S期CDK、有丝分裂期CDK及APC/C活性的消长，横轴为G1、S、G2、M期。要点：不同CDK-cyclin组合依次被激活，启动相应事件；APC/C经泛素化降解蛋白，驱动后期与退出分裂。","page":49,"level":"掌握","img":"assets/img/ch09/p049.jpg","anim":null,"fig":null,"points":["细胞周期的进程依赖于该酶的激活，这种酶的唯一活性是使其","此酶的活性受cyclin控制， cyclin浓度在细胞周期不同阶段是"],"check":{"q":"关于细胞周期控制系统核心CDK的叙述，正确的是？","o":["A. CDK是一种磷酸酶，去除底物磷酸基团","B. CDK活性在细胞周期中恒定不变","C. CDK通过水解ATP直接降解周期蛋白","D. CDK唯一活性是使底物蛋白磷酸化，其活性受cyclin控制"],"a":"D","e":"细胞周期控制系统的核心是一类蛋白激酶CDK，其活性在周期中升高与下降；唯一活性是使底物蛋白磷酸化，活性受cyclin控制，而cyclin浓度在各阶段不同。","oe":["错误，CDK是蛋白激酶，使底物磷酸化。","错误，CDK活性在周期中升高与下降。","错误，降解周期蛋白的是泛素-蛋白酶体途径。","正确，CDK使底物磷酸化且活性受cyclin控制。"]},"cards":null,"mem":"CDK活性升落控周期，唯一作用是磷酸化底物","big":"assets/img/ch09/big/p049.jpg","summary":"as CDKs, 这些激酶的活性在细胞周期进程中rise and fall.","goal":"学完应能掌握并运用「细胞周期控制系统的核心：CDK家族」的核心内容，能解释其机制、比较相关概念。","intuition":"周期控制核心是 CDK 家族：与不同 cyclin 组合，驱动不同时相。"},{"i":49,"sec":"3.2    周期蛋白依赖性蛋白激酶","title":"CDK激酶/cyclin复合物对细胞周期的核心调控","notes":"CDK激酶/cyclin复合物对细胞周期起核心性调控作用：不同种类的cyclin与不同种类的CDK结合，形成不同的CDK激酶；这些复合物在细胞周期的不同时期表现活性，对细胞周期的不同时期进行调节。","page":50,"level":"掌握","img":"assets/img/ch09/p050.jpg","anim":null,"fig":null,"points":["CDK激酶/cyclin复合物对细胞周期起核心性调控作用","不同种类的cyclin与不同种类CDK结合成不同的CDK激酶","在细胞周期不同时期表现活性，调节相应时期"],"check":{"q":"关于CDK对细胞周期的调控，下列叙述正确的是？","o":["A. 所有cyclin-CDK复合物在整个周期持续保持高活性","B. 不同cyclin与不同CDK结合，在不同时期表现活性","C. 一种CDK只能结合一种cyclin且活性恒定","D. CDK活性高低与细胞周期时相无关"],"a":"B","e":"不同种类cyclin与不同种类CDK结合形成不同CDK激酶，在细胞周期不同时期表现活性，从而对各时相进行调节。","oe":["错误，cyclin-CDK复合物活性随周期时相变化。","正确，不同cyclin-CDK组合在周期不同时期表现活性。","错误，一种CDK可与不同cyclin结合，活性也非恒定。","错误，CDK活性与细胞周期时相密切相关。"]},"cards":null,"mem":"不同cyclin×CDK组合，异时相调控细胞周期","big":"assets/img/ch09/big/p050.jpg","summary":"CDK激酶/cyclin复合物对细胞周期起核心性调控作用：不同种类的cyclin与不同种类的CDK结合，形成不同的CDK激酶；这些复合物在细胞周期的不同时期表现活性，对细胞周期的不","goal":"学完应能掌握并运用「CDK激酶/cyclin复合物对细胞周期的核心调控」的核心内容，能解释其机制、比较相关概念。","intuition":"不同 cyclin×CDK 组合像“不同挡位”：在周期不同时期表现活性、调控相应阶段。"},{"i":50,"sec":"3.2    周期蛋白依赖性蛋白激酶","title":"芽殖酵母与裂殖酵母的CDK","notes":"Activity of S. cerevisiae cyclin-CDK\ncomplexes through the course of the\ncell cycle\n裂殖酵母(Cdc2)都\n只有一种CDK激\n酶。\nS. cerevisiae(芽殖酵母) produces a single cyclin-dependent\nkinase (CDK-Cdc28) whose activity is controlled by the\nvarious cyclins, which are expressed during different portions\nof the cell cycle.\n【中文讲解·对照课本/考点】\n考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是芽殖酵母（S. cerevisiae）细胞周期中cyclin-CDK复合物的活性变化。原文指出：芽殖酵母只有一种CDK——Cdc28，其活性由在不同周期阶段表达的各种周期蛋白（cyclins）所控制；裂殖酵母（S. pombe）同样只有一种CDK即Cdc2。单CDK—多周期蛋白模式是理解真核周期调控的重要模型，属教材第十四章内容。","page":51,"level":"掌握","img":"assets/img/ch09/p051.jpg","anim":null,"fig":null,"points":["芽殖酵母(Cdc28)与裂殖酵母(Cdc2)都只有一种CDK激酶","芽殖酵母只有一个CDK(Cdc28)，其活性由多种cyclin控制"],"check":{"q":"芽殖酵母和裂殖酵母细胞周期调控的共同特点是？","o":["A. 都有多种CDK且各自对应一种cyclin","B. 都不需要cyclin即可发挥激酶活性","C. 都只有一种CDK，其活性由不同cyclin控制","D. 都以cyclin B为细胞周期中唯一的周期蛋白"],"a":"C","e":"芽殖酵母只有一种CDK即Cdc28，裂殖酵母也只有一种CDK即Cdc2，其活性均由在不同周期阶段表达的各种周期蛋白控制。","oe":["错误，两种酵母都只有一种CDK。","错误，二者均需cyclin作为调节亚基。","正确，二者均只有一种CDK而由多种cyclin控制。","错误，二者均有多种周期蛋白而非只有cyclin B。"]},"cards":null,"mem":"芽殖酵母仅一种CDK(Cdc28)，配多种cyclin","big":"assets/img/ch09/big/p051.jpg","summary":"考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「芽殖酵母与裂殖酵母的CDK」的核心内容，能解释其机制、比较相关概念。","intuition":"芽殖酵母只用 Cdc28、裂殖酵母只用 Cdc2 一种 CDK，靠换 cyclin 切换任务。"},{"i":51,"sec":"3.2    周期蛋白依赖性蛋白激酶","title":"Mammalian Cdk-cyclin complexes through the cell cycle","notes":"Combinations\nbetween various\ncyclins and cyclin-\ndependent kinases\nat different stages\n【中文讲解·对照课本/考点】\n考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是“哺乳动物细胞周期中的Cdk-cyclin复合物”。原文说明：不同阶段由不同周期蛋白（cyclins）与周期蛋白依赖性激酶（CDKs，cyclin-dependent kinases）组合，形成多种Cdk-cyclin复合物来驱动周期推进。与酵母只有单一CDK不同，哺乳动物拥有多种CDK和多种cyclin，通过组合的时空特异性实现对各时相的精细调控。","page":52,"level":"掌握","img":"assets/img/ch09/p052.jpg","anim":null,"fig":null,"points":["哺乳动物细胞在不同时期由各种cyclin与CDK的不同组合形成复合物"],"check":{"q":"与酵母只有单一CDK不同，哺乳动物细胞周期调控的特点是？","o":["A. 只有一种CDK但拥有很多种cyclin","B. 多种CDK与多种cyclin组合实现精细调控","C. 只有一种cyclin而完全没有CDK","D. CDK不依赖cyclin即可发挥活性"],"a":"B","e":"哺乳动物拥有多种CDK和多种cyclin，通过不同组合的时空特异性，在细胞周期不同阶段形成多种Cdk-cyclin复合物，实现精细调控。","oe":["错误，哺乳动物拥有多种CDK而不止一种。","正确，多种CDK与多种cyclin组合实现精细调控。","错误，哺乳动物既有多种cyclin也有多种CDK。","错误，哺乳动物CDK同样依赖cyclin。"]},"cards":null,"mem":"哺乳动物多CDK多cyclin，组合时空特异","big":"assets/img/ch09/big/p052.jpg","summary":"考点：3.2 周期蛋白依赖性蛋白激酶 ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「Mammalian Cdk-cyclin complexes through t」的核心内容，能解释其机制、比较相关概念。","intuition":"哺乳动物有多个 CDK-cyclin 组合，不同时相用不同搭配。"}],"mcq":[{"id":"ch09_mcq_3","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"细胞合成新的组蛋白是在细胞周期的哪个阶段？（             ）","o":["A．G1","B．S","C．G2","D．M"],"a":"B","e":"在 DNA 复制的同时，组蛋白也被复制。","kp":"ch09_s5_49","oe":["G1期合成RNA、蛋白质及生长所需物质，不合成组蛋白。","正确。DNA复制的同时组蛋白也被合成，以包装新DNA。","G2期为M期作准备，主要合成微管蛋白等，非组蛋白。","M期染色体凝缩并分配，无新组蛋白合成。"]},{"id":"ch09_mcq_4","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"在细胞周期的哪个时期，周期蛋白的浓缩程度最高？（               ）","o":["A．晚 G1 期和早 S 期","B．晚 G0 期和早 M 期","C．晚 G1 期和晚 G2 期","D．晚 M 期和晚 S 期"],"a":"C","e":"细胞中主要的周期蛋白分为周期蛋白 A 和周期蛋白 B 两种，周期蛋白 A 在 G1 期 的的早期开始表达并积累，到达 G1 /S 交界处含量达到最大值，并维持到 G2/ M 期。周期蛋 白 B 则是从 G1 期 晚期开始表达并逐渐积累到 G2 期后期阶段达到最大值，并一直维持到 M 期的中期阶段然后迅速降解。","kp":"ch09_s5_49","oe":["此时cyclin刚开始积累，尚未达到最高浓度。","G0期细胞静止，cyclin含量低，不符合题意。","正确。周期蛋白在晚G1期和晚G2期前后积累至峰值，浓度最高。","晚M期cyclin被降解，含量最低，不符合题意。"]},{"id":"ch09_mcq_6","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"细胞中 RNA 大量合成是在细胞周期中的（         ）。","o":["A．G1 期","B．S 期","C．G2 期","D．M 期"],"a":"A","e":"G1 期开始合成细胞生长所需要的各种蛋白质、糖类、脂质、RNA 等。","kp":"ch09_s5_49","oe":["正确。G1期合成生长所需蛋白质、糖类、脂质及大量RNA。","S期主要进行DNA复制，RNA合成不如G1期旺盛。","G2期主要合成微管蛋白等，RNA合成量不及G1期。","M期染色体凝缩，转录基本停止，RNA合成很少。"]},{"id":"ch09_mcq_12","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"动物克隆（如多莉羊）研究中，你认为供体细胞核最好处于细胞周期的哪一个时相？ （     ）","o":["A．G0∕G1 期","B．S 期","C．G2 期","D．M 期"],"a":"A","e":"休眠细胞可长期停留在 G1 早期而不越过 R 点，处于增殖静止状态。它们合成具有 特殊功能的 RNA 和蛋白质，使细胞的结构和功能发生分化，但这类细胞并未丧失增殖能力， 在一定条件下可以恢复其增殖状态，但需要经过较长的恢复时间。通常把这类细胞称为 G0 期细胞。G1 期是 DNA 合成前的准备时期，也是细胞生长的主要阶段。G1 早期由于细胞大 量合成 RNA 和进行核糖体组装，导致结构蛋白和酶的形成，这些酶控制着用于形成新细胞 成分的代谢活动。所以，供体细胞核最好处于细胞周期的 G0∕G1 期。","kp":"ch09_s5_49","oe":["正确。G0/G1期核DNA未复制、染色体为单倍，利于核重编程。","S期DNA正在复制，染色体状态不稳定，不适合做供体核。","G2期DNA已复制为四倍体，移植后染色体易异常。","M期染色体凝缩且核膜解体，不适合做供体核。"]}],"judge":[{"id":"ch09_judge_7","modI":5,"q":"温度敏感突变体是研究细胞周期控制蛋白的有用突变体。（               ）","a":"对","e":"该实验利用了所谓的条件突变体。条件突变体所产生的蛋白质在某一温度下是稳定 的、有功能的，但在其他温度条件下，则变得不稳定且失去功能。细胞可以先在突变蛋白正 常工作的温度下培养，然后转换到蛋白质功能丧失的温度下培养。","kp":"ch09_s5_48","oe":["温度敏感突变体属条件突变体，控温可使其蛋白可逆失活，便于研究周期控制蛋白。","误以为该突变体不能用于周期研究，其实它正是研究周期调控蛋白的经典工具。"]}],"fill":[{"id":"ch09_fill_5","modI":5,"q":"联会复合物在______期形成，在______期解体，重组结在______期最明显。","a":"偶线期；双线期；粗线期","kp":"ch09_s5_49","oe":["同源染色体配对，联会复合体在偶线期形成。","联会复合体解体，同源染色体开始分离。","重组结在粗线期最明显，进行同源重组交换。"]},{"id":"ch09_fill_11","modI":5,"q":"在细胞同步化的培养中，秋水仙碱可将细胞阻止在 M 期，其机制是______。","a":"秋水仙碱抑制了纺锤体的形成","kp":"ch09_s5_49","oe":["秋水仙碱抑制微管聚合，破坏纺锤体形成，使细胞停滞于M期。"]},{"id":"ch09_fill_28","modI":5,"q":"用 3H 嘧啶核苷标记已证明，mtDNA 复制时间主要在细胞周期的_______期、_______期， DNA_______，随后_______。","a":"S；G2；先复制；线粒体分裂","kp":"ch09_s5_49","oe":["线粒体DNA复制主要发生在细胞周期的S期","mtDNA复制持续到G2期，故G2期也能检测到合成","mtDNA先于线粒体分裂完成复制，保证DNA均分","DNA复制完成后线粒体才进行分裂增殖"]}],"short":[{"id":"ch09_short_2","modI":5,"q":"简述细胞周期中不同时相及其主要事件。","a":"细胞周期分为间期（G1 期、S 期、G2 期）和分裂期（M 期），各个时相发生的主要事 件如下所述： （1）G1 期，与 DNA 合成启动相关，开始合成细胞生长所需要的多种蛋白质、RNA、 碳水化合物、脂质等，同时染色质去凝集。 （2）S 期，合成 DNA 和染色体蛋白（组蛋白和非组蛋白）。新合成的 DNA 立即与组蛋白 结合，组成核小体串珠结构。 （3）G2 期，合成其他结构物质和相关的亚细胞结构，如微管蛋白、染色体凝集因子等。 （4）M 期，即细胞分裂期，包括胞核分裂和胞质分裂，细胞将其遗传物质载体平均分配到 两个子代细胞中。","kp":"ch09_s5_49"},{"id":"ch09_short_13","modI":5,"q":"用秋水仙素处理培养的细胞以使细胞同步化。这种处理会使细胞停留在细胞周期的什么 位置？什么机制阻止了细胞周期的进行？","a":"（1）用秋水仙素处理培养的细胞后，会使细胞停留在有丝分裂中期。 （2）阻止细胞周期进行的机制为： 秋水仙素可以与微管蛋白亚基结合，而当结合有秋水仙素的微管蛋白亚基组装到微管末端后， 其他的微管蛋白亚基就很难再在该处进行组装，因而秋水仙素可以抑制微管的形成，不能形 成纺锤体。用低浓度的秋水仙素处理细胞，可立即破坏细胞内的微管或纺锤体结构，使细胞 周期停留在有丝分裂中期。","kp":"ch09_s5_49"},{"id":"ch09_short_15","modI":5,"q":"简要说明细胞周期的间期各时相的特点。","a":"细胞周期的间期各时相的特点如下： （1）G1 期 ①时间：在周期时间中所占的比例最大，时间变化也最大，不同细胞类型的周期时间的差别 以及细胞的失同步等都是由 G1 期的差异造成的。 ②生化特征：主要合成大量的 RNA 和蛋白质，为细胞进入 S 期准备必要的物质基础。 ③重要性：G1 期细胞能对多种环境信号进行综合、协调并作出反应，以确定细胞是否进入 S 期。 （2）S 期 细胞内主要进行 DNA 的复制、组蛋白和非组蛋白等染色体蛋白的合成。 （3）G2 期 ①形态特征：染色质凝聚或螺旋化。 ②生化特征：合成一定的蛋白质和 RNA，为 M 期的细胞结构变化做准备。 （4）M 期 ①时间：细胞周期中 M 期占用的时间最短，可分为前、中、后、末期 4 个阶段。 ②形态特征：细胞的形态结构变化最大。 ③生化特征：RNA 合成停止、蛋白质合成减少以及染色体高度螺旋化。 ④关键因子：由 G2 期进入 M 期是细胞周期中的另一个关键时刻，M 期细胞质中存在一种使 染色质浓缩的物质，即 M 期促进因子（MPF）。","kp":"ch09_s5_49"}],"calc":[{"id":"ch09_calc_2","modI":5,"q":"科学家们已获得在细胞周期控制中有缺陷的许多酵母突变株。这些突变株在低温（30℃） 能正常增殖，而在较高温度（37℃）则不能正常生长和分裂。两个突变株（分别称为 Gee 和 Wee）在同一基因的不同部位有缺陷，对升高温度有明显不同的反应。在 37℃时，Gee 株细胞只生长得很大而不分裂，Wee 株细胞有很短的细胞周期，并且当体积远小于正常大 小时仍进行分裂。提出一个可能的模型，解释这些观察结果，并指出由这个基因编码的正常 蛋白会起什么作用？","a":"通常细胞必须长到一定大小才开始分裂。这两种突变株的细胞大小控制系统显然有缺陷。 在 Gee 细胞中，细胞只增大而不分裂，说明此突变的细胞周期控制蛋白已无法检测细胞的 大小，可能永远抑制 MPF。而另一方面在 Wee 细胞中，细胞在长到一定大小之前，突变的 控制蛋白过早地引发细胞分裂，包括 MPF 过早被激活等。实际上，Weel 就是一种酵母的细 胞周期调控蛋白，能够使 MPF 特定部位发生磷酸化以使之失活的一种激酶。Weel 突变的酵 母细胞有短的细胞周期，其细胞个体也较小。","kp":"ch09_s5_49"}],"term":[{"id":"ch09_term_20","modI":5,"term":"花束期（bouquet stage）。","def":"在减数分裂的细线期时，有些物种表现为染色体细线一端在核膜的一侧集中，另一端呈 放射状伸出，形似花束，称为花束期。","kps":"","kp":"ch09_s5_51"}]},{"i":6,"name":"3.3 The role of CDK","slides":[{"i":52,"sec":"3.3    The role of C","title":"3.3    The role of CDK","notes":"Four stages for engines that drive the cell cycle\n(1)cyclin binding\n(2)Cdk phosphorylation state\n(3) Cdk inhibitors\n(4) Controlled proteolysis\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是“CDK的作用”（The role of CDK）。原文指出驱动细胞周期的“引擎”受四方面调控：(1) cyclin结合（cyclin binding）；(2) Cdk磷酸化状态（Cdk phosphorylation state）；(3) Cdk抑制物（Cdk inhibitors，CKI）；(4) 受控的蛋白酶解（controlled proteolysis）。这四点构成CDK活性调控的完整框架，是本章总结与常考要点。","page":53,"level":"掌握","img":"assets/img/ch09/p053.jpg","anim":null,"fig":null,"points":["CDK驱动细胞周期的调控涉及四个方面","(1)cyclin结合 (2)Cdk磷酸化状态 (3)Cdk抑制剂 (4)受控的蛋白水解"],"check":{"q":"驱动细胞周期的“引擎”CDK活性受多方面调控，不包括下列哪项？","o":["A. cyclin结合","B. Cdk磷酸化状态","C. Cdk抑制物(CKI)","D. 核糖体的组装"],"a":"D","e":"CDK活性调控包括cyclin结合、Cdk磷酸化状态、Cdk抑制物(CKI)和受控的蛋白酶解四方面，不包括核糖体组装。","oe":["cyclin结合是CDK活性调控因素之一。","Cdk磷酸化状态是重要调控方式。","Cdk抑制物(CKI)可阻止CDK装配或抑制其活性。","核糖体组装与CDK活性调控无直接关系。"],"basis":"(1)cyclin结合(2)磷酸化状态(3)CKI(4)蛋白酶解"},"cards":null,"mem":"CDK引擎四调：cyclin/磷酸化/CKI/蛋白酶解","big":"assets/img/ch09/big/p053.jpg","summary":"考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「3.3    The role of CDK」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 的活性受四方面调控：cyclin 结合、磷酸化、CKI 抑制、受控降解。"},{"i":53,"sec":"3.3    The role of C","title":"与cyclin结合","notes":"(1) cyclin binding\n【结合课本/笔记】· Cdc20 和Mad2蛋白位于动粒上，在染色体结合有丝分裂纺锤体前将不能从动粒上释放，由于Mad2与Cdc20结合而抑制APC的活性。所以只有所有染色体都与纺锤体结合后，APC才有活性，才启动细胞向后期转换。五、细胞周期运转的阻遏(细胞周期运转的负调控)◆细胞至少可通过两种不同机制阻遏细胞周期的运转：Cdk抑制蛋白(CDI)阻止Cyclin-Cdk复合物的装配或活性；周期调控系统组分停止合成。","page":54,"level":"掌握","img":"assets/img/ch09/p054.jpg","anim":null,"fig":null,"points":["CDK活性调控方式之一：与cyclin结合"],"check":{"q":"只有当所有染色体都连接纺锤体后APC才有活性，其机制是？","o":["A. Mad2激活APC，促进后期提前启动","B. Mad2与Cdc20结合抑制APC，染色体连接后Mad2解离解除抑制","C. Cdc20降解Mad2后APC被激活","D. Cdk1抑制securin从而激活APC"],"a":"B","e":"Mad2与Cdc20结合而抑制APC活性，只有所有染色体都与纺锤体结合后Mad2从动粒解离，解除对Cdc20的抑制，APC才被激活。","oe":["错误，Mad2抑制而非激活APC。","正确，Mad2结合Cdc20抑制APC，解离后APC活化。","错误，是Mad2解离而非Cdc20降解Mad2。","错误，APC活化与Cdk1抑制securin无关。"]},"cards":null,"mem":"cyclin结合激活CDK；Mad2抑Cdc20阻APC","big":"assets/img/ch09/big/p054.jpg","summary":"· Cdc20 和Mad2蛋白位于动粒上，在染色体结合有丝分裂纺锤体前将不能从动粒上释放，由于Mad2与Cdc20结合而抑制APC的活性","goal":"学完应能掌握并运用「与cyclin结合」的核心内容，能解释其机制、比较相关概念。","intuition":"调控方式之一就是“与 cyclin 结合”：有 cyclin 才有活性。"},{"i":54,"sec":"3.3    The role of C","title":"CDK1 = MPF ，该激酶活性依赖于，但不仅限于 M期cyclin (哺乳动","notes":"物cyclin B)。\nCDK1 活性和cyclin B 含量的关系\ncyclin B 在CDK1 活性调节过程中的作用\nCDK1 活性首先依赖于cyclin B 含量的积累。cyclin B 的含量达\n到一定值并与CDK 1结合，同时在其他一些因素的调节下，逐渐\n表现出最高激酶活性","page":55,"level":"掌握","img":"assets/img/ch09/p055.jpg","anim":null,"fig":null,"points":["CDK1=MPF，其活性依赖但不限于M期cyclin(哺乳动物cyclin B)","CDK1活性首先依赖于cyclin B含量的积累","cyclin B达到一定值并与CDK1结合，在其他因素调节下逐渐表现最高激酶活性"],"check":{"q":"关于CDK1活性的调节，下列叙述正确的是？","o":["A. CDK1活性与cyclin B含量无关","B. cyclin B始终大量存在且不被降解","C. CDK1活性首先依赖于cyclin B含量的积累并与其结合","D. CDK1只在G1期具有活性"],"a":"C","e":"CDK1活性首先依赖于cyclin B含量的积累；当cyclin B达到一定值并与CDK1结合，在其他因素调节下逐渐表现出最高激酶活性。","oe":["CDK1活性首先依赖cyclin B含量积累。","cyclin B呈周期性变化，会被降解。","cyclin B积累并与之结合是CDK1激活的基础，正确。","CDK1(MPF)主要在M期发挥活性。"],"basis":"CDK1活性首先依赖于cyclin B含量的积累...并与CDK1结合"},"cards":null,"mem":"CDK1活性靠cyclin B积累结合后渐达高峰","big":"assets/img/ch09/big/p055.jpg","summary":"CDK1 活性和cyclin B 含量的关系","goal":"学完应能掌握并运用「CDK1 = MPF ，该激酶活性依赖于，但不仅限于 M期cyclin (哺乳动」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK1 是“发动机”，cyclin B 是“油门”：发动机一直在，但没油门不转。cyclin B 随周期积累到一定量、与 CDK1 结合并调好状态，激酶活性才冲上来，把细胞推入 M 期；之后 cyclin 被降解，发动机熄火。所以周期性变化的是 cyclin 的量，而不是发动机本身。"},{"i":55,"sec":"3.3    The role of C","title":"CDK1 活性受多种因素综合调节","notes":"白与CDK 结合是激活CDK\n活性的先决条件。\nkinase, CAK）的激活\n去磷酸化作用\n化\n\n【读图讲解】\n本页主题为CDK1活性的综合调节。文字列出五方面：cyclin的合成与降解(与CDK结合是激活的先决条件)；CDK活化激酶(CAK)使Thr160/161磷酸化；weel/mik1与Cdc25C对Thr14/Tyr15的磷酸化与去磷酸化；CKI的结合与否；以及蛋白泛素降解。图为中心循环示意：CDK1与cyclin B/A结合后，需CAK磷酸化Thr161并由Cdc25C去除Thr14/Tyr15上的抑制性磷酸，才呈有激酶活性；反之weel/mik1磷酸化这两个位点使其失活，APC介导cyclin降解。要点：活性由磷酸化与cyclin结合双重把控。","page":56,"level":"掌握","img":"assets/img/ch09/p056.jpg","anim":null,"fig":null,"points":["Cyclin 的合成与降解：周期蛋","CDK活化激酶（CDK-activating","Thr 160/161的磷酸化","wee1/mik1和Cdc25C的磷酸化与","Thr14 / Tyr15的磷酸化与去磷酸","CKIs的结合与否","蛋白泛素降解                    CDK1 激酶活性综合调控示意图"],"check":{"q":"激活CDK1活性所必需的是？","o":["A. Wee1对Tyr15的磷酸化","B. cyclin结合与CAK对Thr161的磷酸化","C. CKI与CDK1结合","D. APC介导cyclin B降解"],"a":"B","e":"CDK1活性受多重调节：cyclin结合是先决条件，CAK磷酸化Thr160/161激活，Wee1/mik1磷酸化Thr14/Tyr15抑制、Cdc25C去磷酸化激活，CKI结合抑制，泛素降解cyclin。","oe":["错误，Wee1磷酸化Tyr15是抑制性修饰。","正确，cyclin结合加CAK磷酸化Thr161激活CDK1。","错误，CKI结合会抑制CDK1的活性。","错误，APC降解cyclin B使CDK1失活。"]},"cards":null,"mem":"CDK1五调：cyclin、CAK、Cdc25、CKI","big":"assets/img/ch09/big/p056.jpg","terms":[{"t":"CAK","en":"CDK-activating kinase","d":"磷酸化CDK的激活位点、使其活化的激酶。"}],"summary":"本页主题为CDK1活性的综合调节","goal":"学完应能掌握并运用「CDK1 活性受多种因素综合调节」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK1(=MPF)的活性依赖 cyclin B 的积累，但还需其他因素共同调节。"},{"i":56,"sec":"3.3    The role of C","title":"（2）Cdk的磷酸化状态              裂殖酵母MPF为例","notes":"cyclin-CDK复合物刚形成时并无活性，随后在其\n●激活型磷酸化位点⎯CAK (Cdc2-activating kinase) 【Thr161】\n●抑制型磷酸化位点⎯Wee1 kinase\n→CDK两处位点发生磷酸化。【Thr14/Tyr15】\n→此时MPF仍不具活性。只有当磷酸酶cdc25除去抑制性\n磷酸基团时，MPF才最终被活化.","page":57,"level":"掌握","img":"assets/img/ch09/p057.jpg","anim":"cdk_phospho_switch","fig":null,"points":["cyclin-CDK复合物刚形成时并无活性","随后在激活型磷酸化位点由CAK(Cdc2-activating kinase)磷酸化而激活"],"check":{"q":"在裂殖酵母MPF活化中，Wee1激酶和Cdc25磷酸酶的作用分别是？","o":["A. Wee1加抑制性磷酸，Cdc25去除该磷酸","B. Wee1去除抑制性磷酸，Cdc25加上磷酸","C. 两者都通过磷酸化激活MPF","D. 两者都通过去磷酸化抑制MPF"],"a":"A","e":"cyclin-CDK复合物形成后，CAK磷酸化激活位点，Wee1激酶磷酸化抑制位点使MPF仍无活性；只有Cdc25磷酸酶除去抑制性磷酸后MPF才最终活化。","oe":["正确，Wee1加抑制性磷酸，Cdc25去除该磷酸。","错误，Wee1与Cdc25的作用被相互颠倒。","错误，Wee1加的是抑制性磷酸而非激活MPF。","错误，Cdc25去除抑制性磷酸从而激活MPF。"]},"cards":null,"mem":"CAK激活位点、Wee1抑制位点，Cdc25去磷酸才活化","big":"assets/img/ch09/big/p057.jpg","summary":"cyclin-CDK复合物刚形成时并无活性，随后在其","goal":"学完应能掌握并运用「（2）Cdk的磷酸化状态              裂殖酵母MPF为例」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 刚与 cyclin 结合时还没活性，需在激活位点被 CAK 磷酸化才被打开。"},{"i":57,"sec":"3.3    The role of C","title":"（2）Cdk的磷酸化状态","notes":"weel/mik1激酶和cdc25\neg. 裂殖酵母中的MPF-\nCdc2活性调节\nP522-23\n●Wee1 kinase (Wee1激酶)：磷酸化CDK N-端附近的\nTyr15(抑制型磷酸化位点), 抑制MPF的活性。\n●Cdc25蛋白具蛋白磷酸酶活性，Remove CDK N-端被磷酸\n化的Tyr15 -去磷酸化，从而将MPF激活，诱导细胞从G2\n进入M期。\n长得不够大，Wee1活性强，抑制MPF活性。反之，…","page":58,"level":"掌握","img":"assets/img/ch09/p058.jpg","anim":null,"fig":null,"points":["Wee1蛋白和Cdc25蛋白的活性是相互竞争的。如细胞"],"check":{"q":"关于Wee1与Cdc25对MPF调节的叙述，正确的是？","o":["A. Wee1磷酸化Tyr15抑制MPF，Cdc25去磷酸化Tyr15激活MPF","B. Wee1去磷酸化Tyr15从而激活MPF","C. Cdc25是激酶，磷酸化Tyr15抑制MPF","D. 两者均抑制MPF的活性"],"a":"A","e":"Wee1激酶磷酸化CDK N端Tyr15抑制MPF活性；Cdc25具磷酸酶活性，去除Tyr15磷酸而激活MPF，诱导细胞由G2进入M期；二者活性相互竞争。","oe":["正确，Wee1抑制、Cdc25去磷酸化激活MPF。","错误，Wee1是激酶，磷酸化Tyr15抑制MPF。","错误，Cdc25是磷酸酶，去除Tyr15磷酸激活MPF。","错误，Cdc25激活MPF，并非抑制。"]},"cards":null,"mem":"Wee1磷酸Tyr15抑制，Cdc25去磷酸激活MPF","big":"assets/img/ch09/big/p058.jpg","terms":[{"t":"抑制型磷酸化位点","en":"Tyr15","d":"CDK上被Wee1磷酸化而抑制、被Cdc25去磷酸而激活的位点。"}],"summary":"Wee1 kinase (Wee1激酶)：磷酸化CDK N-端附近的","goal":"学完应能掌握并运用「（2）Cdk的磷酸化状态」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 上还有抑制位点(Tyr15)：被 Wee1 磷酸化就关、被 Cdc25 去磷酸就开。"},{"i":58,"sec":"3.3    The role of C","title":"Phenotypes of Cell cycle mutants in fission yeast","notes":"CDK inactive\nCDK active\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是裂殖酵母细胞周期突变体的表型（Phenotypes of Cell cycle mutants in fission yeast）。原文仅以“CDK inactive”（CDK失活）与“CDK active”（CDK活性）两图对比。可理解为：CDK活性有无决定细胞能否进入M期，CDK失活则周期停滞于G2而不能分裂。该页借助裂殖酵母cdc突变体（如cdc2）说明CDK是周期推进的关键，属经典实验证据。","page":59,"level":"掌握","img":"assets/img/ch09/p059.jpg","anim":null,"fig":null,"points":["裂殖酵母细胞周期突变体可表现为CDK失活与CDK持续激活两种表型"],"check":{"q":"裂殖酵母cdc突变体中CDK失活时的典型表型是？","o":["A. 细胞周期加速，细胞体积变小","B. 细胞周期停滞于G2而不能进入M期","C. 细胞进入M期但不能完成分裂","D. DNA复制无法进行而停滞于G1"],"a":"B","e":"裂殖酵母cdc突变体显示CDK失活时细胞周期停滞、不能进入M期，说明CDK活性有无决定细胞能否进入M期。","oe":["错误，CDK失活使周期停滞而非加速。","正确，CDK失活导致细胞停滞于G2不能进入M期。","错误，CDK失活时细胞不能进入M期。","错误，该突变主要阻滞于G2而非G1。"]},"cards":null,"mem":"CDK失活周期停G2；CDK活性方可进M期","big":"assets/img/ch09/big/p059.jpg","summary":"考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「Phenotypes of Cell cycle mutants in fiss」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 突变的表型两极：要么失活（周期停）、要么持续激活（失控）。"},{"i":59,"sec":"3.3    The role of C","title":"(3) Cdk inhibitors CDK抑制蛋白 (CKI)","notes":"质，称~。阻止CDK装配或抑制CDK活性\n目前有两大类：\nCip/Kip家族⎯如p21(主要对G1-CDK起抑制作用)、p27、\np57；\nINK4家族⎯如p16、p15、p18、p19\n【结合课本/笔记】· Cdc20 和Mad2蛋白位于动粒上，在染色体结合有丝分裂纺锤体前将不能从动粒上释放，由于Mad2与Cdc20结合而抑制APC的活性。所以只有所有染色体都与纺锤体结合后，APC才有活性，才启动细胞向后期转换。五、细胞周期运转的阻遏(细胞周期运转的负调控)◆细胞至少可通过两种不同机制阻遏细胞周期的运转：Cdk抑制蛋白(CDI)阻止Cyclin-Cdk复合物的装配或活性；周期调控系统组分停止合成。","page":60,"level":"掌握","img":"assets/img/ch09/p060.jpg","anim":null,"fig":null,"points":["细胞内存在一些对CDK激酶活性起负性调控的蛋白"],"check":{"q":"下列属于INK4家族CDK抑制蛋白(CKI)的是？","o":["A. p16","B. p21","C. p27","D. p57"],"a":"A","e":"CDK抑制蛋白分两大类：Cip/Kip家族如p21、p27、p57；INK4家族如p16、p15、p18、p19。故p16属INK4家族。","oe":["p16属于INK4家族，是本题的正确答案。","p21属Cip/Kip家族，主要抑制G1-CDK。","p27属于Cip/Kip家族，不属INK4家族。","p57属于Cip/Kip家族，不属INK4家族。"],"basis":"INK4家族⎯如p16、p15、p18、p19"},"cards":null,"mem":"CKI两类：Cip/Kip与INK4，阻CDK装配/活性","big":"assets/img/ch09/big/p060.jpg","terms":[{"t":"CKI","en":"CDK inhibitor","d":"结合并抑制CDK活性的蛋白，如p21、p27。"}],"summary":"阻止CDK装配或抑制CDK活性","goal":"学完应能掌握并运用「(3) Cdk inhibitors CDK抑制蛋白 (CKI)」的核心内容，能解释其机制、比较相关概念。","intuition":"CKI 像“CDK 的刹车片”：直接结合并压住 CDK，让周期在合适时点暂停（如 p21、p27）。"},{"i":60,"sec":"3.3    The role of C","title":"CDK 活性受多种因素综合调节","notes":"【结合课本/笔记】●生物膜结构结构模型●E.Gorter和F．Grendel（1925）:“蛋白质-脂类-蛋白质”三夹板质膜结构模型●J.D.Robertson（1959年）：单位膜模型(unit membrane model)●S.J.Singer和G.Nicolson（1972）：生物膜的流动镶嵌模型(fluid mosaic model)●K.Simons et al(1997): 脂筏模型（lipid rafts model）Functional rafts in Cell membranes. Nature 387:569-572生物膜结构●磷脂双分子层是组成生物膜的基本结构成分,尚未发现膜结构中起组织作用的蛋白；●蛋白分子以不同方式镶嵌在\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 单位膜（unit membrane）：生物膜在电镜下呈现出较为一致的3层结构，即电子致密度高的内、外两层之间夹着电子密度较低的中间层。","page":61,"level":"掌握","img":"assets/img/ch09/p061.jpg","anim":null,"fig":null,"points":["CDK活性受多种因素综合调节：cyclin结合、Cdk磷酸化状态、Cdk抑制物(CKI)及受控的蛋白酶解"],"check":{"q":"关于CDK活性的调节，下列叙述正确的是？","o":["A. CDK活性仅由cyclin浓度决定","B. CDK活性受cyclin结合、磷酸化状态、CKI及蛋白酶解等多因素综合调节","C. CDK一旦合成即持续具有活性","D. CDK活性不受磷酸化状态影响"],"a":"B","e":"CDK活性受多种因素综合调节，包括cyclin结合、Cdk磷酸化状态、Cdk抑制物(CKI)以及受控的蛋白酶解等。","oe":["cyclin浓度只是影响因素之一，非唯一。","CDK活性受多因素综合调节，正确。","CDK需被激活，并非合成即持续有活性。","Cdk磷酸化状态是重要调控因素。"],"basis":"CDK 活性受多种因素综合调节"},"cards":null,"mem":"CDK活性综合调节：多种因素协同(磷酸化/结合/降解)","big":"assets/img/ch09/big/p061.jpg","summary":"生物膜结构结构模型●E.Gorter和F．Grendel（1925）:“蛋白质-脂类-蛋白质”三夹板质膜结构模型●J.D.Robertson（1959年）：单位膜模型(unit m","goal":"学完应能掌握并运用「CDK 活性受多种因素综合调节」的核心内容，能解释其机制、比较相关概念。","intuition":"CDK 活性受多种因素综合调节：cyclin、磷酸化、CKI 和蛋白酶解共同决定。"},{"i":61,"sec":"3.3    The role of C","title":"细胞周期各时相转换的激酶调控","notes":"活性。\n(control CDK-cyclin complex activity before\nundergoing cell cycle transitions.)\n●当DNA损伤或在其它信号通讯指导下暂时停滞\n细胞周期。\n(arrest the cell cycle temporarily in response to DNA\ndamage or to other signaling pathways)\n活(premature)。\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是CKI等因子对细胞周期的调控。原文要点：①在细胞周期各时相转化之前，控制相关激酶（CDK-cyclin复合物）的活性；②在DNA损伤或其它信号通讯指导下暂时停滞细胞周期。人类细胞中，p21是DNA损伤控制途径中的重要因子；p27则在G1晚期抑制S期CDK激酶活性的过早激活（premature activation）。","page":62,"level":"掌握","img":"assets/img/ch09/p062.jpg","anim":null,"fig":null,"points":["人类细胞中，","p21, 细胞DNA损伤控制途径中一重要因子。","p27, 在G1晚期抑制S期的CDK激酶活性过早激"],"check":{"q":"关于CKI(CDK抑制蛋白)作用的叙述，正确的是？","o":["A. CKI激活CDK，加速细胞周期运转","B. 在时相转换前控制CDK-cyclin活性，DNA损伤时暂时阻滞周期","C. p27促进S期CDK的过早激活","D. CKI只在M期发挥作用"],"a":"B","e":"CKI在细胞周期各时相转化前控制CDK-cyclin复合物活性，并可在DNA损伤或其它信号指导下暂时阻滞周期；p21是DNA损伤控制途径的重要因子，p27抑制S期CDK过早激活。","oe":["错误，CKI对CDK起负性调控作用。","正确，CKI控制CDK活性并应激暂时阻滞周期。","错误，p27在G1晚期抑制S期CDK过早激活。","错误，CKI在各时相转换及损伤应答中均起作用。"]},"cards":null,"mem":"CKI控CDK：p21应损伤，p27阻G1晚激活","big":"assets/img/ch09/big/p062.jpg","summary":"当DNA损伤或在其它信号通讯指导下暂时停滞","goal":"学完应能掌握并运用「细胞周期各时相转换的激酶调控」的核心内容，能解释其机制、比较相关概念。","intuition":"周期各时相切换前，相关激酶被适时激活，保证事件按序进行、防止过早启动。"},{"i":62,"sec":"3.3    The role of C","title":"Figure 8.13a The Biology of Cancer (© Garland Science 2007)","notes":"【结合课本/笔记】Alberts B et al. Molecuar Biology of the Cell, 3rd ed. New York and London ： GarlandPublishing，Inc. 1994\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系\n\n【本页英文讲解】\n本页主题为教材图示（Figure 8.13a，The Biology of Cancer，Garland Science 2007）。原文仅给出图注来源，无正文内容。结合本页在课件中的位置，该图应展示细胞周期检验点与CDK-cyclin调控的整体示意，属癌症生物学中周期失调的内容。复习时可将其与CKI、DNA损伤检验点等知识对照理解。","page":63,"level":"掌握","img":"assets/img/ch09/p063.jpg","anim":null,"fig":null,"points":["细胞周期检验点是细胞周期调控的一种机制","确保周期每一时相事件有序、全部完成并与外界环境因素相联系"],"check":{"q":"细胞周期检验点(checkpoint)的主要作用是？","o":["A. 确保每一时相事件有序、全部完成并与外界环境因素相联系","B. 缩短细胞周期所需时间","C. 直接催化DNA的复制","D. 专一性地降解所有cyclin"],"a":"A","e":"细胞周期检验点是细胞周期调控的一种机制，主要是确保周期每一时相事件有序、全部完成并与外界环境因素相联系。","oe":["检验点保证各时相事件有序完成并联系环境，正确。","检验点起监控作用，并非缩短细胞周期时间。","检验点不直接催化DNA复制，复制由复制酶完成。","专一降解cyclin不是检验点的功能。"],"basis":"确保周期每一时相事件的有序、全部完成并与外界环境因素相联系"},"cards":null,"mem":"癌症中周期检验点失调示意","big":"assets/img/ch09/big/p063.jpg","summary":"考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「Figure 8.13a The Biology of Cancer (© Ga」的核心内容，能解释其机制、比较相关概念。","intuition":"本页为教材图，展示检验点/周期调控，配合文字理解。"},{"i":63,"sec":"3.3    The role of C","title":"CKI (CDK激酶抑制物—调节激酶活性方式之一):","notes":"CDK inhibitor\nactivity late in G1.\nthen degraded before progression into S phase.\nP27必须被水解后细胞才能进入S期。\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系\n\n【本页英文讲解】\n本页主题是CDK激酶抑制物（CDK inhibitor，CKI），是调节激酶活性的方式之一。原文指出：p27在G1晚期抑制S期CDK活性的过早激活；在许多细胞中，p27必须被磷酸化然后降解，细胞才能进入S期，即“p27必须被水解后细胞才能进入S期”。这体现CKI通过降解解除抑制来推动G1/S转换，是重要考点。","page":64,"level":"掌握","img":"assets/img/ch09/p064.jpg","anim":null,"fig":null,"points":["p27 inhibit premature activation of S-phase CDK","In many cells, p27 must be phosphorylated and"],"check":{"q":"关于p27的叙述，正确的是？","o":["A. p27促进G1向S期的转换","B. p27在S期大量积累并抑制DNA复制","C. p27属于INK4家族CKI","D. p27须被磷酸化后降解，细胞才能由G1进入S期"],"a":"D","e":"p27在G1晚期抑制S期CDK活性的过早激活；在许多细胞中p27必须被磷酸化然后降解，细胞才能进入S期，体现CKI通过降解解除抑制来推动G1/S转换。","oe":["错误，p27抑制S期CDK，阻碍G1/S转换。","错误，p27主要在G1晚期起作用，并非S期积累。","错误，p27属于Cip/Kip家族CKI。","正确，p27磷酸化降解后细胞才能进入S期。"]},"cards":null,"mem":"p27抑G1晚S-CDK；需磷酸化降解方进S期","big":"assets/img/ch09/big/p064.jpg","summary":"P27必须被水解后细胞才能进入S期","goal":"学完应能掌握并运用「CKI (CDK激酶抑制物—调节激酶活性方式之一):」的核心内容，能解释其机制、比较相关概念。","intuition":"CKI 像“CDK 的刹车”：结合并抑制 CDK，是调控激酶活性的重要方式之一。"},{"i":64,"sec":"3.3    The role of C","title":"p27-cyclin-       12周的转基因 正常胸腺和p27基因","notes":"p27: a Cdk inhibitor that arrests cell cycle progress\np27 knockout\nCK\nCdk 复合体           鼠. 黑毛的是 敲除鼠的胸腺的比\n的三维结构             突变的缺少   较。The gland from\n图.                p27的转基因 the p27 knockout\n鼠，相对较大。 mouse is much larger\nowing to an increased\nnumber cells.\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是p27作为Cdk抑制物阻滞细胞周期进程。原文及图注指出：p27敲除（p27 knockout）小鼠在12周时胸腺（thymus）显著增大，原因是细胞数量增多（increased number cells）；相比正常小鼠，p27基因突变缺失的转基因鼠胸腺更大。这说明p27缺失导致细胞过度增殖，证明CKI对细胞分裂的抑制及其抑癌作用。","page":65,"level":"掌握","img":"assets/img/ch09/p065.jpg","anim":null,"fig":null,"points":["p27是使细胞周期进程阻滞的Cdk抑制剂","p27敲除鼠的胸腺明显大于正常，说明缺失p27使细胞增殖增加"],"check":{"q":"p27敲除小鼠12周时胸腺显著增大，说明p27是？","o":["A. 一种Cdk抑制物，可阻滞细胞周期并抑制增殖","B. 一种促进细胞增殖的周期蛋白","C. 一种参与DNA损伤修复的酶","D. 一种纺锤体组装相关蛋白"],"a":"A","e":"p27是一种Cdk抑制物(CKI)，能阻滞细胞周期进程；p27敲除小鼠胸腺因细胞数量增多而显著增大，说明p27缺失导致细胞过度增殖。","oe":["正确，p27是Cdk抑制物，可阻滞周期并抑制增殖。","错误，p27抑制而非促进细胞增殖。","错误，p27并非DNA损伤修复酶。","错误，p27不属于纺锤体组装蛋白。"]},"cards":null,"mem":"p27敲除鼠胸腺增大：CKI失则细胞增多","big":"assets/img/ch09/big/p065.jpg","summary":"Cdk 复合体           鼠. 黑毛的是 敲除鼠的胸腺的比","goal":"学完应能掌握并运用「p27-cyclin-       12周的转基因 正常胸腺和p27基因」的核心内容，能解释其机制、比较相关概念。","intuition":"p27 像“刹车片”：它抑制 CDK、阻滞周期；敲除 p27 的小鼠胸腺会异常增大。"},{"i":65,"sec":"3.3    The role of C","title":"（4）受控的蛋白水解","notes":"The cyclin concentrations oscillate during each cell cycle, which leads to changes\nin the activity of Cdks.\nDegradation is accomplished by means of the ubiquintin-proeasome pathway.\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是调控方式之四——受控的蛋白酶解（Controlled proteolysis）。原文指出：周期蛋白（cyclin）浓度在每个细胞周期中发生振荡（oscillate），从而引起Cdk活性的变化；周期蛋白的降解通过泛素-蛋白酶体途径（ubiquitin-proteasome pathway）完成。这是“引擎”四大调控方式之一，也是M期退出（cyclin B降解）的关键。","page":66,"level":"掌握","img":"assets/img/ch09/p066.jpg","anim":null,"fig":null,"points":["cyclin浓度在每个细胞周期中振荡，导致Cdk活性变化","cyclin降解通过泛素-蛋白酶体途径完成"],"check":{"q":"周期蛋白浓度周期性振荡并引起Cdk活性变化，其降解途径是？","o":["A. 溶酶体自噬途径","B. 泛素-蛋白酶体途径","C. 直接由Caspase切割","D. 随细胞分裂被稀释清除"],"a":"B","e":"周期蛋白浓度在每个细胞周期中发生振荡，从而引起Cdk活性变化；其降解通过泛素-蛋白酶体途径完成。","oe":["错误，周期蛋白降解不通过溶酶体自噬途径。","正确，周期蛋白经泛素-蛋白酶体途径降解。","错误，Caspase切割不是周期蛋白降解的主要途径。","错误，周期蛋白靠主动降解而非分裂稀释。"]},"cards":null,"mem":"受控蛋白酶解：cyclin振荡，经泛素-蛋白酶体降","big":"assets/img/ch09/big/p066.jpg","summary":"考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「（4）受控的蛋白水解」的核心内容，能解释其机制、比较相关概念。","intuition":"cyclin 靠泛素-蛋白酶体“定时销毁”，浓度像潮水涨落，所以周期只能向前。"},{"i":66,"sec":"3.3    The role of C","title":"M期的周期蛋白N端含一段9个","notes":"M-cyclin and polyubiquitin-degradation pathway\n氨基酸组成的特殊序列, 称降解\n盒/破坏框(destruction box), 参与\n泛素介导的cyclinA, cyclinB降解。\n【如将该破坏框突变，则突变分子不能\n被泛素化降解。】\nG1周期蛋白也通过类似的途径降解，但其N端没有降\n解盒，C端有一段PEST序列与其降解有关。","page":67,"level":"掌握","img":"assets/img/ch09/p067.jpg","anim":null,"fig":null,"points":["M期周期蛋白N端含一段9个氨基酸的特殊序列，称降解盒/破坏框(destruction box)","参与泛素介导的cyclin A、cyclin B降解"],"check":{"q":"关于周期蛋白降解的信号序列，下列叙述正确的是？","o":["A. G1周期蛋白N端也含有相同的降解盒","B. 降解盒位于周期蛋白的C端","C. M期周期蛋白N端含9个氨基酸的降解盒，参与泛素化降解","D. 周期蛋白的降解完全不依赖泛素"],"a":"C","e":"M期周期蛋白N端含一段9个氨基酸的降解盒(破坏框)，参与泛素介导的cyclin A、cyclin B降解；G1周期蛋白N端无降解盒，C端PEST序列与其降解有关。","oe":["错误，G1周期蛋白N端不含降解盒，其C端有PEST。","错误，M期周期蛋白的降解盒位于N端。","正确，M期cyclin N端9氨基酸降解盒介导泛素化降解。","错误，周期蛋白降解通过泛素化途径完成。"]},"cards":null,"mem":"M周期蛋白N端降解盒；G1型靠C端PEST","big":"assets/img/ch09/big/p067.jpg","terms":[{"t":"破坏框","en":"destruction box","d":"M期周期蛋白N端的一段9个氨基酸序列，介导其泛素化降解。"}],"summary":"氨基酸组成的特殊序列, 称降解","goal":"学完应能掌握并运用「M期的周期蛋白N端含一段9个」的核心内容，能解释其机制、比较相关概念。","intuition":"破坏框像“cyclin 的保质期标签”：M 期 cyclin N 端的一段序列，触发泛素化降解。"},{"i":67,"sec":"3.3    The role of C","title":"（本页为图片/无文字层）","notes":"泛素-蛋白酶体途径：E1激活泛素，E2结合泛素，E3识别靶蛋白并转移泛素(决定底物特异性)，26S蛋白酶体降解之。\n【图中英文对照】\n• Ub / ATP —— 泛素 / ATP\n• E1 ubiquitin-activating enzyme —— E1 泛素活化酶\n• E2 ubiquitin-conjugating enzyme —— E2 泛素结合酶\n• E3 ubiquitin ligase —— E3 泛素连接酶\n• Cytosolic target protein —— 胞质靶蛋白\n• Recognition/Unfolding/Cleavage/Discharge —— 识别→去折叠→切割→排出肽段\n• 19S cap / 20S core —— 19S 调节帽 / 20S 核心颗粒(26S 蛋白酶体)\n• Figure 3-29 —— 图3-29《分子细胞生物学》\n【读图讲解】\n泛素-蛋白酶体降解途径图：E1激活酶→E2结合酶→E3连接酶→多聚泛素链→26S蛋白酶体识别、去折叠、降解并释放肽段；附19S帽与20S核心冷冻电镜结构。考点：E1/E2/E3 与 ATP 依赖降解。","page":68,"level":"掌握","img":"assets/img/ch09/p068.jpg","anim":"ubiquitin_pathway","fig":null,"points":["(q)","NH2","E2","Cytosolic","Ub","AMP","targetprotein","+PP"],"check":{"q":"在泛素-蛋白酶体途径中，决定底物特异性的是？","o":["A. E1泛素活化酶","B. E2泛素结合酶","C. E3泛素连接酶","D. 19S调节帽"],"a":"C","e":"泛素-蛋白酶体途径中，E1激活泛素，E2结合泛素，E3泛素连接酶识别特定靶蛋白并转移泛素，决定底物特异性；26S蛋白酶体随后降解之。","oe":["错误，E1负责活化泛素而非识别底物。","错误，E2负责结合泛素，不决定底物特异性。","正确，E3泛素连接酶识别底物并决定特异性。","错误，19S调节帽参与识别与去折叠而非决定特异性。"]},"cards":null,"mem":"泛素降解：E1→E2→E3→26S，ATP依赖","big":"assets/img/ch09/big/p068.jpg","summary":"泛素-蛋白酶体途径：E1激活泛素，E2结合泛素，E3识别靶蛋白并转移泛素(决定底物特异性)，26S蛋白酶体降解之","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"泛素-蛋白酶体像“贴标+碎纸”：E1/E2/E3 依次把泛素挂到靶蛋白上，再由蛋白酶体降解。"},{"i":68,"sec":"3.3    The role of C","title":"参与细胞周期调控的两类E3泛素连接酶：SCF与APC","notes":"参与细胞周期调控的E3泛素连接酶通常为多亚基复合体，至少有两类：①SCF(skp1-cullin-F-box protein复合体)负责将泛素连接到G1/S-cyclins和某些CKI(p21、p27等)上，降解间期的相关蛋白；②APC(anaphase promoting complex)称为“促后期复合物”，负责将泛素连接到M期的相关蛋白上，促进细胞进入有丝分裂后期。","page":69,"level":"掌握","img":"assets/img/ch09/p069.jpg","anim":"scf_apc","fig":null,"points":["SCF (skp1-cullin-F-box","APC (anaphase promoting"],"check":{"q":"关于两类E3泛素连接酶SCF与APC的叙述，正确的是？","o":["A. 二者都直接水解底物蛋白","B. SCF促进细胞进入后期，APC降解G1/S-cyclin","C. SCF降解G1/S-cyclins和某些CKI，APC促进细胞进入有丝分裂后期","D. 二者都只在M期起作用"],"a":"C","e":"SCF(skp1-cullin-F-box)将泛素连接到G1/S-cyclins和某些CKI(p21、p27等)，降解间期相关蛋白；APC是促后期复合物，介导M期相关蛋白泛素化，促进进入后期。","oe":["E3连接酶介导泛素化，不直接水解底物。","二者功能颠倒，促进后期的是APC。","SCF与APC分工的叙述符合本页内容，正确。","SCF主要在间期、APC在M期发挥作用。"],"basis":"SCF降解G1/S-cyclins和CKI；APC促进入后期"},"cards":null,"mem":"E3两类：SCF降G1/S与CKI，APC降M期","big":"assets/img/ch09/big/p069.jpg","summary":"参与细胞周期调控的E3泛素连接酶通常为多亚基复合体，至少有两类：①SCF(skp1-cullin-F-box protein复合体)负责将泛素连接到G1/S-cyclins和某些C","goal":"学完应能掌握并运用「参与细胞周期调控的两类E3泛素连接酶：SCF与APC」的核心内容，能解释其机制、比较相关概念。","intuition":"两类 E3 像“两个时段的值班员”：SCF 管间期，降解 G1/S-cyclin 和 CKI；APC 管 M 期，启动染色体分离。一个守日常，一个管大动作。"},{"i":69,"sec":"3.3    The role of C","title":"APC对分裂中期→后期的精密调控","notes":"APC(anaphase-promoting complex，促后期复合物)对细胞由分裂中期向后期进行精密调控。它本身是一个E3泛素连接酶，从酵母到人类都是保守的。其靶蛋白为M期一系列蛋白(cyclin A、cyclin B、securin等)，通过泛素化途径降解。APC活性受M期CDK激酶、Cdc20(正调)、Mad2(负调)等多种调节：MPF活性在有丝分裂中期最高，此时将APC磷酸化激活。G1后期APC失活，cyclin B浓度升高，以便进入下一个分裂周期。","page":70,"level":"掌握","img":"assets/img/ch09/p070.jpg","anim":"checkpoint_apc","fig":null,"points":["后期促进因子: 细胞分裂中期(metaphase)→后期","作用及特点","靶蛋白：M期一系列蛋白(cyclinA和B, securin等)泛素化途","APC活性受M期CDK激酶、Cdc20(正调)*Mad2(负调)等多","G1后期，失活，cyclin B浓度升高，以便进入下一个分裂"],"check":{"q":"关于APC(促后期复合物)的叙述，正确的是？","o":["A. 是一种蛋白激酶，通过磷酸化底物起作用","B. 作用于G1/S转换，主要降解p21","C. 是E3泛素连接酶，靶蛋白为cyclin A/B、securin等M期蛋白","D. APC活性不受Cdc20和Mad2调节"],"a":"C","e":"APC(促后期复合物)是保守的E3泛素连接酶，对分裂中期到后期进行精密调控，靶蛋白为M期一系列蛋白(cyclin A、B、securin等)；其活性受M期CDK、Cdc20(正调)和Mad2(负调)等调节。","oe":["错误，APC是E3泛素连接酶而非蛋白激酶。","错误，降解p21的是SCF，APC作用于M期。","正确，APC为E3酶，靶向cyclin A/B、securin等。","错误，Cdc20正调控、Mad2负调控APC。"]},"cards":null,"mem":"APC后期促进物：E3连接酶，保守，调中期→后期","big":"assets/img/ch09/big/p070.jpg","terms":[{"t":"APC","en":"anaphase-promoting complex","d":"后期促进复合物，泛素连接酶；Mad2负调、Cdc20正调。"}],"summary":"APC(anaphase-promoting complex，促后期复合物)对细胞由分裂中期向后期进行精密调控","goal":"学完应能掌握并运用「APC对分裂中期→后期的精密调控」的核心内容，能解释其机制、比较相关概念。","intuition":"APC 是 E3 泛素连接酶，像“后期开关”：受 CDK、Cdc20(正调)、Mad2(负调)调控。"},{"i":70,"sec":"3.3    The role of C","title":"APC活性受多种因素综合调节","notes":"（Cdc20 in mid-mitosis; Cdh from late\nmitosis through early G1）\ndeficient 2)，与Cdc20结合，抑制\n其活性。两者均定位在染色体动\n粒上。\nMad2定位在早中期和错误排列的\n中期染色体动粒上，直到纺锤体\n正确组装完成，染色体被动粒微\n管捕捉后→\nMad2从动粒上消失，解除对Cdc20\n的抑制;\nCdc20与APC结合，活化APC。\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系","page":71,"level":"掌握","img":"assets/img/ch09/p071.jpg","anim":null,"fig":null,"points":["正调控因子：Cdc20/Cdh1等","负调控：Mad2 (mitosis arrest"],"check":{"q":"关于Mad2对APC调节的叙述，正确的是？","o":["A. Mad2促进Cdc20与APC结合而激活APC","B. Mad2是APC的正调控因子","C. Mad2位于细胞质膜上，与动粒无关","D. Mad2结合Cdc20抑制APC，直至染色体被纺锤体正确捕捉"],"a":"D","e":"Mad2是APC的负调控因子，与Cdc20结合抑制其活性，二者均定位在动粒上；直到纺锤体正确组装、染色体被微管捕捉后Mad2从动粒消失，解除抑制，Cdc20与APC结合并激活APC。","oe":["错误，Mad2结合Cdc20后抑制APC激活。","错误，Mad2对APC起负调控作用。","错误，Mad2定位在染色体动粒上。","正确，Mad2结合Cdc20抑制APC，直到纺锤体正确连接。"]},"cards":null,"mem":"APC正调Cdc20/Cdh1，负调Mad2","big":"assets/img/ch09/big/p071.jpg","summary":"两者均定位在染色体动","goal":"学完应能掌握并运用「APC活性受多种因素综合调节」的核心内容，能解释其机制、比较相关概念。","intuition":"APC 的活性被正调(Cdc20)与负调(Mad2)精细控制，确保时机正确。"},{"i":71,"sec":"3.3    The role of C","title":"APC的功能及调节","notes":"●纺锤体装配检验点的检控→纺锤体装配完全，染色体附着于纺\n锤体动粒微管上，【位于染色体动粒上的Mad2(负调)/Cdc20(正调)】\nMad2从动粒解离，解除对Cdc20的抑制，促使APC活化。\n●M期CDK1激酶(MPF)的高活性→磷酸化APC的多个成分\nAPC激活被多种因素综合调节 (磷酸化APC+Cdc20结合)\n●APC在M后期表现出活性\n● M期周期蛋白A和B的泛素化途径降解\n(CyclinA, Cyclin B–分子中的“破坏框”重要作用)\n●降解securin，最终使姐妹染色单体的分离，mark the\nonset of anaphase.\n细胞周期从M期中期向后期转化","page":72,"level":"掌握","img":"assets/img/ch09/p072.jpg","anim":null,"fig":null,"points":["APC的功能受纺锤体装配检验点检控","检验点确认纺锤体装配完全、染色体附着于动粒微管"],"check":{"q":"关于APC（后期促进复合物）的功能及调节，下列叙述正确的是？","o":["A. APC在M期始终没有活性","B. APC活性不受M期CDK1磷酸化的影响","C. 纺锤体装配完全后Mad2解离解除对Cdc20的抑制，促使APC活化","D. APC直接降解securin而不经泛素化"],"a":"C","e":"纺锤体装配完全、染色体附着于动粒微管后，Mad2从动粒解离，解除对Cdc20的抑制，促使APC活化；M期CDK1高活性还磷酸化APC多个成分。","oe":["错误，APC在M后期表现活性而非始终无活性。","错误，M期CDK1磷酸化APC多个成分参与其调节。","正确，Mad2解离解除抑制后APC被活化。","错误，APC通过泛素化途径降解securin。"]},"cards":null,"mem":"APC活化：Mad2解离+MPF磷酸化+Cdc20结合","big":"assets/img/ch09/big/p072.jpg","summary":"纺锤体装配检验点的检控→纺锤体装配完全，染色体附着于纺","goal":"学完应能掌握并运用「APC的功能及调节」的核心内容，能解释其机制、比较相关概念。","intuition":"APC 像“后期的清场工”：降解 securin 等、释放分离酶，也降解 cyclin 让 CDK 失活。"},{"i":72,"sec":"3.3    The role of C","title":"● 降解M期周期蛋白，cyclin B1, 使Cdk1失活。","notes":"●APC/C activates separase through securin ubiquitinylation\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页主题是M期周期蛋白的降解。原文指出：降解M期周期蛋白cyclin B1，使Cdk1失活；APC/C（后期促进复合物/周期体）通过使securin（分离酶抑制蛋白）泛素化，从而激活separase（分离酶）。这两点分别对应M期退出机制与姐妹染色单体分离机制，是细胞分裂调控的重要考点。","page":73,"level":"掌握","img":"assets/img/ch09/p073.jpg","anim":null,"fig":null,"points":["APC/C降解M期周期蛋白cyclin B1，使Cdk1失活","APC/C通过泛素化securin激活分离酶separase"],"check":{"q":"APC/C通过使securin泛素化而激活的是？","o":["A. 凝缩蛋白","B. 分离酶(separase)","C. Cdc25磷酸酶","D. CDK1"],"a":"B","e":"APC/C使securin泛素化而被降解，从而释放并激活分离酶(separase)；同时APC/C降解M期周期蛋白cyclin B1使Cdk1失活。","oe":["错误，凝缩蛋白并非securin降解所激活。","正确，securin降解释放出分离酶并将其激活。","错误，Cdc25是磷酸酶，不由securin释放。","错误，cyclin B1降解反而使Cdk1失活。"]},"cards":null,"mem":"APC降cyclinB1→Cdk1失活释separase","big":"assets/img/ch09/big/p073.jpg","terms":[{"t":"保全蛋白","en":"securin","d":"结合并抑制分离酶的蛋白；被APC泛素化降解后释放separase。"},{"t":"分离酶","en":"separase","d":"切割黏连蛋白、促使姐妹染色单体分离的蛋白酶。"}],"summary":"考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「● 降解M期周期蛋白，cyclin B1, 使Cdk1失活。」的核心内容，能解释其机制、比较相关概念。","intuition":"APC 降解 cyclin B1 使 Cdk1 失活，细胞才能退出 M 期。"},{"i":73,"sec":"3.3    The role of C","title":"泛素降解保全蛋白securin, 释放出分离酶separase,","notes":"●The initiation of sister-chromatid separation by the APC/C\nseparase再消除染色单体之间的粘连复合体，促进姐妹染色\n单体的分离：\nMdm2\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• ◆对外界环境因子起反应(如多细胞生物对增殖信号的反应)二、细胞周期检验点(checkpoint)◆细胞周期检验点是细胞周期调控的一种机制,主要是确保周期每一时相事件的有序、全部完成并与外界环境因素相联系\n\n【本页讲解】\n本页讲解姐妹染色单体分离的启动机制，核心是APC/C（后期促进复合物）介导的泛素化降解。APC/C通过泛素化降解保全蛋白（securin），释放出分离酶（separase），separase再去消除染色单体之间的黏连复合体，从而促进姐妹染色单体的分离；图中还标注了Mdm2。考点联系翟中和《细胞生物学》第十三章细胞周期与细胞分裂，需掌握“APC/C→securin降解→separase释放→黏连复合体被消除→姐妹染色单体分离”这条链条，理解泛素-蛋白酶体途径在M期退出中的作用。","page":74,"level":"掌握","img":"assets/img/ch09/p074.jpg","anim":"securin_separase","fig":null,"points":["泛素降解保全蛋白securin，释放出分离酶separase","separase消除姐妹染色单体之间的粘连复合体，促进姐妹染色单体分离"],"check":{"q":"姐妹染色单体分离启动的正确顺序是？","o":["A. APC/C→泛素化降解securin→释放separase→消除黏连复合体","B. separase→降解securin→APC/C→增强黏连","C. securin→激活APC/C→降解separase","D. Cdk1→降解separase→增强黏连"],"a":"A","e":"APC/C介导securin泛素化降解，释放分离酶separase，separase再消除姐妹染色单体之间的黏连复合体，促进姐妹染色单体分离。","oe":["正确，APC/C降解securin→释放separase→消除黏连。","错误，该顺序颠倒且结果是黏连被消除而非增强。","错误，securin被降解而非激活APC/C。","错误，Cdk1失活后才退出M期，不直接降解separase。"]},"cards":null,"mem":"降securin放separase，解黏连促姐妹单体分离","big":"assets/img/ch09/big/p074.jpg","summary":"separase再消除染色单体之间的粘连复合体，促进姐妹染色","goal":"学完应能掌握并运用「泛素降解保全蛋白securin, 释放出分离酶separase,」的核心内容，能解释其机制、比较相关概念。","intuition":"securin 像“刀鞘”：平时套住分离酶；被 APC 降解后，separase 出鞘、切开 cohesin，让姐妹染色单体分开。"},{"i":74,"sec":"3.3    The role of C","title":"（本页为图片/无文字层）","notes":"细胞周期中的泛素连接酶：SCF参与G1/S期降解，APC/C^Cdc20在后期降解securin启动染色体分离，APC/C^Cdh1在末期降解有丝分裂cyclin。\n【图中英文对照】\n• START —— START(G1/S 限制点)\n• G1/S phase CDKs —— G1/S 期 CDK\n• S phase CDKs —— S 期 CDK\n• SCF —— SCF 泛素连接酶\n• APC/C^Cdc20 —— APC/C^Cdc20(后期降解 securin)\n• APC/C^Cdh1 —— APC/C^Cdh1(末期降解有丝分裂 cyclin)\n• Cdc25 phosphatase —— Cdc25 磷酸酶(激活有丝分裂 CDK)\n• DNA prereplication complexes —— DNA 前复制复合物(在复制起点组装)\n• Figure 19-28 —— 图19-28 真核细胞周期基本过程\n【读图讲解】\n真核细胞周期图：中央环示 M、早G1、中晚G1、START、S、G2，由 Mitotic CDK、G1/S-CDK、S-CDK 驱动，Cdc25、APC/C、SCF 调控，周围示中期/后期/末期胞质分裂与DNA复制。考点：CDK 周期调控与泛素连接酶对 cyclin/抑制剂的降解。","page":75,"level":"掌握","img":"assets/img/ch09/p075.jpg","anim":null,"fig":null,"points":["Phosphatasesactivate","Cdh1andAPC/Ccdh1","proteasomedegrades","mitoticcyclins","APC/CCdh1","APC/CCdc20","Telophase andcytokinesis","proteasome"],"check":{"q":"在真核细胞周期中，分别降解securin和M期cyclin的泛素连接酶是？","o":["A. SCF与Cdc25","B. APC/C^Cdh1与SCF","C. Cdc25与Wee1","D. APC/C^Cdc20与APC/C^Cdh1"],"a":"D","e":"后期APC/C^Cdc20降解securin启动染色体分离，末期APC/C^Cdh1降解有丝分裂cyclin；SCF则参与G1/S等时期的降解。","oe":["错误，SCF与Cdc25并非分别降解securin与cyclin。","错误，该配对与实际降解对象不符。","错误，Cdc25是磷酸酶，Wee1是激酶，均非泛素连接酶。","正确，APC/C^Cdc20降解securin，APC/C^Cdh1降解cyclin。"]},"cards":null,"mem":"真核周期：CDK驱动，Cdc25/SCF/APC/C调控","big":"assets/img/ch09/big/p075.jpg","summary":"细胞周期中的泛素连接酶：SCF参与G1/S期降解，APC/C^Cdc20在后期降解securin启动染色体分离，APC/C^Cdh1在末期降解有丝分裂cyclin","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示 SCF/APC 在不同时期的降解任务。"},{"i":75,"sec":"3.3    The role of C","title":"本章小结","notes":"The engine of the cell cycle: CDK-cyclin complexes\n(1) cyclin binding\n(2) Cdk phosphorylation state\n(3) Cdk inhibitors (CKI)\n(4) Controlled proteolysis\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页为本章小结（Summary）。原文总结：细胞周期的“引擎”是CDK-cyclin复合物，包括CDKs、cyclins，以及CDK-cyclin的四种调控方式：(1) cyclin结合；(2) Cdk磷酸化状态；(3) Cdk抑制物（CKI）；(4) 受控的蛋白酶解。该框架串联全章核心概念，是复习与答题的总纲。","page":76,"level":"掌握","img":"assets/img/ch09/p076.jpg","anim":null,"fig":null,"points":["CDKs","Cylins","CDK-cyclin regulation:"],"check":{"q":"细胞周期引擎(CDK-cyclin复合物)的调控方式中，通过SCF/APC清除调节蛋白的是？","o":["A. cyclin与CDK结合","B. 受控的蛋白酶解","C. Cdk的磷酸化状态","D. Cdk抑制物(CKI)的结合"],"a":"B","e":"本章小结指出，细胞周期引擎为CDK-cyclin复合物，其调控方式有四种：cyclin结合、Cdk磷酸化状态、Cdk抑制物(CKI)以及受控的蛋白酶解(主要经SCF/APC泛素化)。","oe":["错误，cyclin结合是激活的先决条件之一。","正确，SCF/APC介导的受控蛋白酶解。","错误，磷酸化状态调节CDK活性。","错误，CKI结合可抑制CDK活性。"]},"cards":null,"mem":"CDK-cyclin引擎四调：结合/磷酸化/CKI/酶解","big":"assets/img/ch09/big/p076.jpg","summary":"考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）","goal":"学完应能掌握并运用「本章小结」的核心内容，能解释其机制、比较相关概念。","intuition":"小结：周期由 CDK-cyclin 引擎 + 检验点刹车 + 泛素降解定时共同控制。"},{"i":76,"sec":"3.3    The role of C","title":"Cdc2/cdc28/CDK1；cdc25; cdc20","notes":"【结合课本/笔记】◆MPF的发现◆MPF是一种使多种底物蛋白磷酸化的蛋白激酶；由M期Cyclin-Cdk(Cyclin-dependent protein kinase)形成的复合物。MPF=CDK1=p34cdc2+cyclinBMitotic Cyclin-Cdk复合物的活化与功能◆活化·随Cyclin浓度变化而变化·激酶与磷酸酶的调节，活化的MPF可使更多的MPF活化\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页讲解】\n本页为表17-2，汇总主要细胞周期调控蛋白，底部点出“Cdc2/cdc28/CDK1；cdc25；cdc20”。表分三组：①修饰CDK的激酶与磷酸酶——Cdk活化激酶（CAK）磷酸化CDK活化位点；Wee1激酶磷酸化抑制位点，在M期前抑制Cdk1；Cdc25磷酸酶去除抑制性磷酸，哺乳动物有Cdc25A、B、C三个成员，控制M期启动时Cdk1活化。②CDK抑制蛋白（CKI）——Sic1（芽殖酵母）、p27、p21、p16。③泛素连接酶及其激活因子——APC/C、Cdc20、Cdh1、SCF，其中Cdc20在中期到后期转换时触发APC/C初始活化。考点：Cdk1（即Cdc2/cdc28）受Wee1与Cdc25的磷酸化开关双向调控。","page":77,"level":"掌握","img":"assets/img/ch09/p077.jpg","anim":null,"fig":null,"points":["MPF=CDK1=p34cdc2 + cyclin B","Wee1激酶磷酸化并抑制Cdk1，Cdc25磷酸酶去除抑制性磷酸","Cdc25控制M期启动时Cdk1的活化"],"check":{"q":"控制M期启动时Cdk1活化的磷酸酶是？","o":["A. Cdc25磷酸酶","B. Wee1激酶","C. CAK","D. Sic1"],"a":"A","e":"Wee1激酶在M期前磷酸化抑制Cdk1，而Cdc25磷酸酶去除抑制性磷酸，控制M期启动时Cdk1的活化；哺乳动物有Cdc25A、B、C三个成员。","oe":["正确，Cdc25磷酸酶去除抑制性磷酸，激活Cdk1。","错误，Wee1是激酶，磷酸化并抑制Cdk1。","错误，CAK磷酸化CDK的活化位点，非去除抑制磷酸。","错误，Sic1是CDK抑制蛋白而非磷酸酶。"]},"cards":null,"mem":"Cdc2/28=CDK1，cdc25、cdc20关键","big":"assets/img/ch09/big/p077.jpg","summary":"◆MPF的发现◆MPF是一种使多种底物蛋白磷酸化的蛋白激酶；由M期Cyclin-Cdk(Cyclin-dependent protein kinase)形成的复合物","goal":"学完应能掌握并运用「Cdc2/cdc28/CDK1；cdc25; cdc20」的核心内容，能解释其机制、比较相关概念。","intuition":"Cdc25 像“启动钥匙”：去除 CDK 上的抑制磷酸，激活 Cdk1、启动 M 期。"},{"i":77,"sec":"3.3    The role of C","title":"An overview of the cell-cycle control system","notes":"【结合课本/笔记】美国国立卫生研究院（NIH）在1988年底发表的一份题为《什麽是当今科研领域的热门话题？》（“What is popular in research today？”）的调查报告中指出，目前全球研究最热门的是●三种疾病：●癌症（cancer）●心血管病（cardiovascular diseases）●爱滋病和肝炎等传染病（infectious diseases：AIDS，hepatitis）●五大研究方向：●细胞周期调控（cell cycle control）；●细胞凋亡（ cell apoptosis）；●细胞衰老（cellular senescence）；●信号转导（signal transduction）；●DNA的损伤与修复\n【中文讲解·对照课本/考点】\n考点：3.3 The role of CDK ｜ 教材：第十三章 细胞周期与细胞分裂 · 第一节 细胞周期（p273–280）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页主题是“细胞周期控制系统概览”（An overview of the cell-cycle control system）。原文仅给出标题，无正文，应为一幅总览示意图。可据此把前述“引擎”（CDK-cyclin）与“刹车”（检验点）整合：控制系统在G1、G2、M等关键节点整合内外信号，决定细胞继续周期、暂停或退出，是翟中和教材第十四章的核心图示。","page":78,"level":"掌握","img":"assets/img/ch09/p078.jpg","anim":null,"fig":null,"points":["细胞周期控制系统在G1、G2、M等关键节点整合内外信号","决定细胞继续周期、暂时暂停或退出周期","将引擎(CDK-cyclin)与刹车(检验点)整合在一起"],"check":{"q":"细胞周期控制系统在关键节点整合内外信号后，可决定细胞？","o":["A. 必然进入细胞凋亡","B. 必然发生癌变","C. 继续周期、暂时暂停或退出周期","D. 直接改变DNA的碱基序列"],"a":"C","e":"细胞周期控制系统在G1、G2、M等关键节点整合内外信号，决定细胞继续周期、暂停或退出周期，将引擎(CDK-cyclin)与刹车(检验点)整合在一起。","oe":["错误，控制系统并不必然导致细胞凋亡。","错误，正常调控不会必然引起癌变。","正确，控制系统决定继续、暂停或退出周期。","错误，控制系统不直接改变DNA碱基序列。"]},"cards":null,"mem":"热门五方向：周期/凋亡/衰老/信号转导/DNA修复","big":"assets/img/ch09/big/p078.jpg","summary":"美国国立卫生研究院（NIH）在1988年底发表的一份题为《什麽是当今科研领域的热门话题","goal":"学完应能掌握并运用「An overview of the cell-cycle control sy」的核心内容，能解释其机制、比较相关概念。","intuition":"周期控制像“引擎+刹车”：CDK-cyclin 推进周期，检验点在关键节点决定继续、暂停或退出。"}],"mcq":[],"judge":[],"fill":[{"id":"ch09_fill_26","modI":6,"q":"中期染色体具有比较稳定的形态，它由两条相同的姐妹染色单体构成，彼此以________ 相连。","a":"着丝粒","kp":"ch09_s6_73","oe":["两条姐妹染色单体在着丝粒处相连，着丝粒也是纺锤丝附着位点"]}],"short":[],"calc":[],"term":[{"id":"ch09_term_2","modI":6,"term":"动粒（kinetochore）。","def":"动粒（kinetochore）是指在主缢痕处 2 个染色单体的外侧表层部位的特殊结构，它与染 色体微管接触，是微管蛋白的组织中心，又称着丝点。","kps":"","kp":"ch09_s6_52"},{"id":"ch09_term_3","modI":6,"term":"纺锤体（spindle）。","def":"纺锤体（spindle）是指减数和有丝分裂中期，细胞质中出现的纺锤形结构，由能收缩的 微管和微丝纵向成束排列而成。","kps":"","kp":"ch09_s6_53"},{"id":"ch09_term_4","modI":6,"term":"姐妹染色单体（sister chromatid）。","def":"姐妹染色单体（sister chromatid）是指染色体分裂间期进行自我复制，所形成的由一个 着丝点连接着的两条完全相同的染色单体。","kps":"","kp":"ch09_s6_73"},{"id":"ch09_term_5","modI":6,"term":"分裂中期阻断法（metaphase blocking）。","def":"分裂中期阻断法（metaphase blocking）是指应用可以抑制微管聚合的某些药物，如秋水 仙素、秋水酰胺和 noeodazole 等，从而有效抑制细胞分裂器的形成，将细胞阻断在分裂中期 的细胞周期同步方法。","kps":"","kp":"ch09_s6_69"},{"id":"ch09_term_11","modI":6,"term":"细线期（leptotene stage）。","def":"细线期是指第一次减数分裂前期的最初时期。在这个时期，染色质凝集成单条细线，细 线与核膜相连，染色质线上有染色粒。","kps":"","kp":"ch09_s6_52"},{"id":"ch09_term_12","modI":6,"term":"双线期（diplotene stage）。","def":"双线期是指在第一减数分裂前期，继粗线期的时期。在这一时期，重组阶段结束，同源 染色体相互分离，仅留几处相互联系，四分体结构变得清晰可见。在双线期可见染色体交叉。","kps":"","kp":"ch09_s6_52"},{"id":"ch09_term_15","modI":6,"term":"着丝点。","def":"着丝点是在主缢痕处 2 个染色单体的外侧表层部位的特殊结构，它与染色体微管相接触， 是微管蛋白的组织中心，着丝点又称动粒或动原粒","kps":"","kp":"ch09_s6_73"},{"id":"ch09_term_21","modI":6,"term":"中心体列队（centrosome alignment）。","def":"在细胞分裂过程中一对中心体分别移向细胞的两极的过程称为中心体列队。","kps":"","kp":"ch09_s6_65"}]}],"mcq":[{"id":"ch09_mcq_1","mod":"三 细胞周期的调控之—engine","modI":3,"q":"裂殖酵母中的 cdc2 基因在芽殖酵母中的同源物是（      ）。","o":["A．cdc2","B．cdc25","C．cdc28","D．cdc20"],"a":"C","e":"在芽殖酵母中的 cdc28 基因和裂殖酵母的 cdc2 基因产物为同源物，等同于 CDK1。","kp":"ch09_s5_4","oe":["cdc2是裂殖酵母的基因名，不是芽殖酵母中的同源物名称。","cdc25编码磷酸酶，去磷酸化激活CDK，并非cdc2的同源物。","正确。芽殖酵母cdc28与裂殖酵母cdc2同源，即CDK1。","cdc20是APC的正调控因子，非cdc2的同源物。"]},{"id":"ch09_mcq_2","mod":"二 周期调控之brake","modI":2,"q":"与 PCNA 结合，直接抑制 DNA 复制的 CDK 激酶抑制物是（       ）。","o":["A．p27","B．P16","C．p18","D．p21"],"a":"D","e":"p21 为 CIP／KIP 类 CDK 激酶抑制物，PCNA 为 DNA 复制聚合酶δ的辅助因子， 为 DNA 复制所必需，p21 同 PCNA 结合后直接抑制 DNA 复制。","kp":"ch09_s6_11","oe":["p27属CIP/KIP家族，抑制CDK活性，但不与PCNA结合。","p16属INK4家族，特异性抑制CDK4/6，不与PCNA结合。","p18属INK4家族，抑制CDK4/6，不与PCNA结合。","正确。p21与PCNA结合，直接抑制DNA复制。"]},{"id":"ch09_mcq_3","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"细胞合成新的组蛋白是在细胞周期的哪个阶段？（             ）","o":["A．G1","B．S","C．G2","D．M"],"a":"B","e":"在 DNA 复制的同时，组蛋白也被复制。","kp":"ch09_s1_4","oe":["G1期合成RNA、蛋白质及生长所需物质，不合成组蛋白。","正确。DNA复制的同时组蛋白也被合成，以包装新DNA。","G2期为M期作准备，主要合成微管蛋白等，非组蛋白。","M期染色体凝缩并分配，无新组蛋白合成。"]},{"id":"ch09_mcq_4","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"在细胞周期的哪个时期，周期蛋白的浓缩程度最高？（               ）","o":["A．晚 G1 期和早 S 期","B．晚 G0 期和早 M 期","C．晚 G1 期和晚 G2 期","D．晚 M 期和晚 S 期"],"a":"C","e":"细胞中主要的周期蛋白分为周期蛋白 A 和周期蛋白 B 两种，周期蛋白 A 在 G1 期 的的早期开始表达并积累，到达 G1 /S 交界处含量达到最大值，并维持到 G2/ M 期。周期蛋 白 B 则是从 G1 期 晚期开始表达并逐渐积累到 G2 期后期阶段达到最大值，并一直维持到 M 期的中期阶段然后迅速降解。","kp":"ch09_s4_0","oe":["此时cyclin刚开始积累，尚未达到最高浓度。","G0期细胞静止，cyclin含量低，不符合题意。","正确。周期蛋白在晚G1期和晚G2期前后积累至峰值，浓度最高。","晚M期cyclin被降解，含量最低，不符合题意。"]},{"id":"ch09_mcq_5","mod":"三 细胞周期的调控之—engine","modI":3,"q":"如果将双线期灯刷染色体在放射性标记的尿嘧啶中培养，然后通过放射自显影进行检测， 大部分的放射性将出现在（          ）。","o":["A．灯刷环上","B．沿着灯刷骨架","C．在灯刷环上与灯刷骨架上均有","D．与染色体无关"],"a":"A","e":"在很多动物尤其是鱼类、两栖类、爬行类和鸟类的雌性动物，染色体去凝集成一种 特殊的巨大的染色体结构，形似灯刷，称为灯刷染色体，在灯刷上有很多侧环结构，是进行 活跃转录 RNA 的部位。","kp":"ch09_s1_4","oe":["正确。灯刷环是活跃转录RNA的部位，放射性集中于侧环上。","灯刷骨架为染色体轴，非活跃转录区，放射性很少。","转录主要发生在侧环，骨架几乎无RNA合成，故不选。","灯刷环转录产生RNA，放射性在染色体上，故该说法错误。"]},{"id":"ch09_mcq_6","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"细胞中 RNA 大量合成是在细胞周期中的（         ）。","o":["A．G1 期","B．S 期","C．G2 期","D．M 期"],"a":"A","e":"G1 期开始合成细胞生长所需要的各种蛋白质、糖类、脂质、RNA 等。","kp":"ch09_s1_4","oe":["正确。G1期合成生长所需蛋白质、糖类、脂质及大量RNA。","S期主要进行DNA复制，RNA合成不如G1期旺盛。","G2期主要合成微管蛋白等，RNA合成量不及G1期。","M期染色体凝缩，转录基本停止，RNA合成很少。"]},{"id":"ch09_mcq_7","mod":"一 细胞周期的概念","modI":1,"q":"在减数分裂 S 期 DNA 并不完全复制，大约还有（             ）DNA 是在偶线期合成的。[浙江 师范大学 2011 研]","o":["A．100%","B．50%","C．10%","D．0.3%"],"a":"D","e":"偶线期发生的重要事件：（1）同源染色体配对；（2）合成在 S 期未合成的约 0.3% 的 DNA（偶线期 DNA）。","kp":"ch09_s1_4","oe":["若全部未复制则与事实不符，偶线期仅合成极少量DNA。","数值明显过大，S期已复制绝大部分DNA。","数值偏大，偶线期合成的DNA仅占约0.3%。","正确。偶线期合成S期未合成的约0.3%DNA，即偶线期DNA。"]},{"id":"ch09_mcq_8","mod":"绪论 · 概览","modI":0,"q":"细胞周期中不经历解聚和重建的是（                 ）。[南开大学 2011 研]","o":["A．收缩环","B．纺锤体","C．核纤层","D．中心体"],"a":"D","e":"A 项，胞质分裂开始时，大量的肌动蛋白和肌球蛋白在中间体处组装成微丝，并相 互组成微丝束，环绕细胞，称为收缩环。B 项，当细胞从间期进入有丝分裂期，间期细胞微 管网络解聚为游离的α∕β-微管蛋白二聚体，再重组成纺锤体，介导染色体的运动；分裂末期 纺锤体微管解聚，又重组形成细胞质微管网络。C 项，当细胞进行有丝分裂时，核纤层蛋白 被磷酸化，引起核纤层的可逆解聚。D 项，中心体在细胞周期过程中也要进行复制，并经历 一系列的发育过程，称为中心体周期。包括：G1 期末到 S 期复制；晚 G2 期到 M 期，子中 心粒长大并逐渐分离；有丝分裂前期分离成为一个生长辐射状微管的核心。","kp":"ch09_s1_6","oe":["胞质分裂时肌动蛋白与肌球蛋白组装成收缩环，经历重建。","间期微管解聚，M期重组成纺锤体，经历解聚与重建。","核纤层蛋白磷酸化引起核纤层可逆解聚，经历重建。","正确。中心体只进行复制与发育，不发生解聚和重建。"]},{"id":"ch09_mcq_9","mod":"三 细胞周期的调控之—engine","modI":3,"q":"下列关于纺锤体的叙述正确的是（                ）。[南京师范大学 2008 研]","o":["A．由微管和微管结合蛋白组成","B．有动力微管和极性微管两种类型","C．是细胞分裂中染色体分离相关细胞器","D．以上全对"],"a":"D","e":"","kp":"ch09_s1_6","oe":["该说法本身正确，但仅涉及纺锤体的组成，不全面。","该说法本身正确，但仅涉及纺锤体微管的类型，不全面。","该说法本身正确，但仅涉及纺锤体的功能，不全面。","正确。纺锤体由微管及结合蛋白构成，分动粒/极性微管，介导染色体分离。"]},{"id":"ch09_mcq_10","mod":"三 细胞周期的调控之—engine","modI":3,"q":"在有丝分裂的哪个时期染色体最分散？（                 ）[中科院-中科大 2007 研]","o":["A．前期","B．前中期","C．中期","D．后期"],"a":"A","e":"B 项，前中期的一个特征性现象是染色体整列，染色体彼此靠近慢慢排列在赤道板 上。C 项，中期染色体已完成整列，规则的排列在赤道板上。D 项，后期染色体在纺锤丝的 牵引下移向细胞两极，排列较规则。","kp":"ch09_s1_6","oe":["正确。前期染色体凝缩程度最低、最为分散，故答案选前期。","前中期染色体逐渐整列、彼此靠近，比前期更集中。","中期染色体已规则排列在赤道板上，高度聚集。","后期染色体在纺锤丝牵引下移向两极，排列较规则。"]},{"id":"ch09_mcq_11","mod":"绪论 · 概览","modI":0,"q":"染色体出现成倍状态发生于细胞周期中的（                ）[湖南大学 2007 研]","o":["A．G2 期和早 M 期","B．G1 期和 S 期","C．晚 M 期和 Gl 期","D．G0 期和 G1 期"],"a":"A","e":"S 期开始 DNA 的复制，同时染色体也在这个阶段完成复制。而 G2 与早 M 期是紧 接在 S 期之后的两个时期，其染色体同样保持成倍状态。","kp":"ch09_s1_4","oe":["正确。S期完成复制后，G2期与早M期染色体保持成倍状态。","G1期DNA未复制，S期正在复制，染色体不成倍。","晚M期细胞分裂后染色体减半，G1期未复制，不成倍。","G0期和G1期DNA均未复制，染色体不成倍。"]},{"id":"ch09_mcq_12","mod":"3.2    周期蛋白依赖性蛋白激酶","modI":5,"q":"动物克隆（如多莉羊）研究中，你认为供体细胞核最好处于细胞周期的哪一个时相？ （     ）[华中师范大学 2003 研]","o":["A．G0∕G1 期","B．S 期","C．G2 期","D．M 期"],"a":"A","e":"休眠细胞可长期停留在 G1 早期而不越过 R 点，处于增殖静止状态。它们合成具有 特殊功能的 RNA 和蛋白质，使细胞的结构和功能发生分化，但这类细胞并未丧失增殖能力， 在一定条件下可以恢复其增殖状态，但需要经过较长的恢复时间。通常把这类细胞称为 G0 期细胞。G1 期是 DNA 合成前的准备时期，也是细胞生长的主要阶段。G1 早期由于细胞大 量合成 RNA 和进行核糖体组装，导致结构蛋白和酶的形成，这些酶控制着用于形成新细胞 成分的代谢活动。所以，供体细胞核最好处于细胞周期的 G0∕G1 期。","kp":"ch09_s1_4","oe":["正确。G0/G1期核DNA未复制、染色体为单倍，利于核重编程。","S期DNA正在复制，染色体状态不稳定，不适合做供体核。","G2期DNA已复制为四倍体，移植后染色体易异常。","M期染色体凝缩且核膜解体，不适合做供体核。"]}],"judge":[{"id":"ch09_judge_1","modI":1,"q":"细胞分裂时内质网要经历解体与重建的过程。（           ）","a":"对","e":"","kp":"ch09_s1_6","oe":["有丝分裂时内质网解体、分散，分裂后重新聚合重建，表述正确。","若判错，则忽视内质网在分裂期解体、分裂后重建的事实。"]},{"id":"ch09_judge_2","modI":1,"q":"早期胚胎细胞细胞周期短，随着卵裂球数量增加，其总体积也随着增加。（                      ）","a":"错","e":"卵细胞在成熟过程中已积累了大量的物质基础，基本满足早期胚胎发育的物质需要， 子细胞在 G1、G2 期并不生长，越分裂体积越小，但总体积并不增加。","kp":"ch09_s1_10","oe":["若判对则忽略卵裂期子细胞不生长，分裂后体积减小，总体积不增。","早期卵裂球只分裂不生长，子细胞越小，胚胎总体积并不增加。"]},{"id":"ch09_judge_3","modI":1,"q":"正常细胞在有丝分裂中期时，每条染色体的动粒均已分别结合来自纺锤体两极的微管。 （     ）","a":"对","e":"","kp":"ch09_s1_6","oe":["中期每条染色体的两个动粒分别连接来自两极的动粒微管。","若判错，则中期染色体确已实现双极动粒微管连接，否定无据。"]},{"id":"ch09_judge_4","modI":0,"q":"极微管头对头连接，因此从一个纺锤极到另一个纺锤极是连续存在的。（                     ）","a":"错","e":"极微管末端相互重叠并通过将微管之间跨接起来的蛋白质而相互连接。","kp":"ch09_s1_6","oe":["若判对则误认为极微管连续贯穿两极，实则两端重叠并借蛋白相连。","极微管并非连续，而是在赤道区末端重叠，通过交联蛋白相互连接。"]},{"id":"ch09_judge_5","modI":3,"q":"有丝分裂中核膜变为碎片，因此能像内质网和高尔基体等膜被细胞器一样在两个子细胞 间分配。（     ）","a":"对","e":"事实上，核膜与内质网膜之间是连续的，因此某些区段含有具两个来源的膜。","kp":"ch09_s1_6","oe":["核膜与内质网膜连续，分裂中解体成片段，可随ER在两子细胞间分配。","若判错，则忽略核膜与ER膜连续、随膜系统重建而分配的事实。"]},{"id":"ch09_judge_6","modI":1,"q":"G0 细胞是永远失去了分裂能力的细胞。（      ）","a":"错","e":"G0 细胞是暂时处于休眠状态的细胞，在受到适当的刺激后会回重返细胞周期进行 分裂繁殖。","kp":"ch09_s1_12","oe":["认为G0期细胞已永久脱离细胞周期，不再具有分裂能力。","G0只是暂时休眠，受适当刺激后可重返周期、恢复分裂繁殖。"]},{"id":"ch09_judge_7","modI":5,"q":"温度敏感突变体是研究细胞周期控制蛋白的有用突变体。（               ）","a":"对","e":"该实验利用了所谓的条件突变体。条件突变体所产生的蛋白质在某一温度下是稳定 的、有功能的，但在其他温度条件下，则变得不稳定且失去功能。细胞可以先在突变蛋白正 常工作的温度下培养，然后转换到蛋白质功能丧失的温度下培养。","kp":"ch09_s6_6","oe":["温度敏感突变体属条件突变体，控温可使其蛋白可逆失活，便于研究周期控制蛋白。","误以为该突变体不能用于周期研究，其实它正是研究周期调控蛋白的经典工具。"]},{"id":"ch09_judge_8","modI":3,"q":"在减数分裂交换期间，两条染色体上编码同样基因的区域必须彼此配对。（                      ）","a":"对","e":"如果染色体的非对应区域也能发生重组，将产生大范围的基因重排，这对于生物而 言几乎是灾难性的。然而，少数罕见的“不等交换”对生物体可能有利，基因组中已发现这些 罕见的例子。","kp":"ch09_s1_7","oe":["交换发生在同源染色体对应区域之间，只有同源区配对才能保证基因不发生重排。","误以为任意区域均可配对交换，若不对应区重组会造成大范围基因重排，对生物有害。"]},{"id":"ch09_judge_9","modI":0,"q":"微管在着丝粒处成核然后连接至动粒。（            ）","a":"错","e":"微管在中心体处成核组装，然后连接到动粒。","kp":"ch09_s1_6","oe":["误认为微管由着丝粒成核再连动粒，混淆了成核部位与连接部位。","微管实际在中心体处成核组装，随后其正端连接到动粒上。"]},{"id":"ch09_judge_10","modI":3,"q":"分开的染色体分别向细胞两极运动主要是通过着丝点微管的负端的不断解聚而实现的。 （   ）","a":"错","e":"染色体分离机制： （1）后期 A：动粒微管逐渐变短，将染色体移向两极。动粒微管的缩短，是由于动粒端微 管蛋白解聚造成的，蛋白解聚又是由于 dynein 蛋白拖着动粒盘向着极部运动引起的。 （2）后期 B：极性微管不断增长，使两极间距离逐渐拉长。在后期 B，Kinesin 蛋白与来自 一端的极性微管结合，同时与来自另一端的极性微管搭桥，当 Kinesin 蛋白带着连接的微管 沿着另一根微管向着正极运动时，可使两根微管之间产生相互滑动，由此使两极间的距离逐 渐变长。","kp":"ch09_s1_6","oe":["误认为仅靠动粒微管负端解聚即可驱动染色体移向两极。","后期A动粒微管在动粒端正端解聚，由dynein拖动粒向极移动，并有马达蛋白参与。"]},{"id":"ch09_judge_11","modI":0,"q":"一般细胞周期中，细胞经历生长和分裂两个过程，但有些细胞基本上只经历 DNA 复制 （S 相）和分裂（M 相），而无生长现象，例如干细胞。（           ）","a":"错","e":"干细胞具有完整的细胞周期。","kp":"ch09_s1_10","oe":["误以为干细胞只有DNA复制与分裂而无生长，故判对。","干细胞具有完整细胞周期，G1、S、G2、M齐全，同样经历生长过程。"]},{"id":"ch09_judge_12","modI":1,"q":"在细胞周期中，如果纺锤体装配不正常，则被阻止于 G2 期。（           ）","a":"错","e":"纺锤体组装检验点存在于细胞分裂中期，监控纺锤体微管与染色单体动粒的连接、 染色体在赤道面的队列和向纺锤体两极的分离等。上述事件未正确完成前，该检验点阻止细 胞从分裂中期进入后期。","kp":"ch09_s2_3","oe":["误认为纺锤体装配检验点位于G2期，故判对。","纺锤体组装检验点位于分裂中期，异常时阻止细胞由中期进入后期。"]},{"id":"ch09_judge_13","modI":1,"q":"体细胞只能进行有丝分裂，生殖细胞只能进行减数分裂。（              ）","a":"错","e":"生殖细胞还可进行有丝分裂。","kp":"ch09_s1_4","oe":["误以为生殖细胞只进行减数分裂，故判对。","生殖细胞（如精原、卵原细胞）也能进行有丝分裂增殖，并非只能减数分裂。"]},{"id":"ch09_judge_14","modI":3,"q":"中心体的复制独立于染色体的复制。（           ）","a":"对","e":"中心体的复制和染色体的复制是不相关的两个过程。例如在减数第二次分裂，染色 体不复制而中心体复制。","kp":"ch09_s1_6","oe":["中心体与染色体复制互不相关，减数第二次分裂染色体不复制而中心体仍复制。","误以为二者复制同步偶联，其实中心体复制可独立于染色体复制进行。"]},{"id":"ch09_judge_15","modI":1,"q":"不同生物及同一生物的不同细胞的细胞周期时间是不同的，其中 G1 期持续时间的差异最 大。（      ）","a":"对","e":"细胞周期时间长短主要差别在 G1 期，而 S、G2、M 总时间是相对恒定的。","kp":"ch09_s1_2","oe":["周期长短差异主要在G1期，S、G2、M总时间相对恒定。","误以为各期时长可变性相同，其实G1期持续时间的差异最大。"]},{"id":"ch09_judge_16","modI":1,"q":"所渭 Hayflick 界限是指细胞分化的极限。（      ）","a":"错","e":"Hayflick 界限是指细胞分裂次数的极限。","kp":"ch09_s1_12","oe":["误以为Hayflick界限指细胞分化的极限，故判对。","Hayflick界限指正常细胞体外分裂次数的极限，与分化程度无关。"]},{"id":"ch09_ajudge_2","modI":4,"q":"cyclin广泛存在于从酵母到人等各种真核生物中","a":"对","e":"本页要点：cyclin广泛存在于从酵母到人等各种真核生物中","kp":"ch09_s4_0","oe":["细胞周期蛋白cyclin在真核生物中高度保守，从酵母到人普遍存在。","误以为cyclin只存在于高等动物，其实低等真核生物如酵母也含有。"]}],"fill":[{"id":"ch09_fill_1","modI":3,"q":"细胞减数分裂中，根据细胞形态的变化可以将前期 I 分为______、______、______、______、 ______。","a":"细线期；偶线期；粗线期；双线期；终变期","kp":"ch09_s1_7","oe":["染色质凝集成细线，可见染色粒，尚未配对。","同源染色体配对（联会），形成联会复合体。","同源染色体变粗，非姐妹染色单体间发生交换重组。","联会复合体解体，同源染色体分开并可见交叉。","染色体高度凝集，交叉端化，核仁核膜消失。"]},{"id":"ch09_fill_2","modI":1,"q":"根据增殖状况，可将细胞分类三类，分别为______、______、______。","a":"周期中细胞；静止期细胞（G0 细胞）；终末分化细胞","kp":"ch09_s1_12","oe":["持续分裂的细胞，不断循环于细胞周期。","暂时退出周期进入G0期，受刺激可重返分裂。","高度分化失去分裂能力，不再进入细胞周期。"]},{"id":"ch09_fill_3","modI":1,"q":"和动物细胞的细胞周期相比较，植物细胞的细胞周期两个突出特点是______和______。","a":"不含中心体；以中间板形式进行胞质分裂","kp":"ch09_s1_1","oe":["植物细胞无中心体，纺锤体由无中心体机制形成。","靠细胞板扩展形成新壁来完成胞质分裂。"]},{"id":"ch09_fill_4","modI":1,"q":"中心体在______期末开始复制。到达______期，细胞已经含有一对中心体，但两者不分 开。到达______期，一对中心体开始分离，移向两极。","a":"G1 期；S 期；G2 期","kp":"ch09_s1_6","oe":["中心体在G1期开始复制，为S期提供拷贝基础。","到达S期细胞已含一对中心体，但两者不分开。","到达G2期一对中心体开始分离，并移向两极。"]},{"id":"ch09_fill_5","modI":5,"q":"联会复合物在______期形成，在______期解体，重组结在______期最明显。","a":"偶线期；双线期；粗线期","kp":"ch09_s1_7","oe":["同源染色体配对，联会复合体在偶线期形成。","联会复合体解体，同源染色体开始分离。","重组结在粗线期最明显，进行同源重组交换。"]},{"id":"ch09_fill_6","modI":3,"q":"卵母细胞在减数分裂的前期Ⅰ中的______，染色体去凝集形成巨大的灯刷染色体。","a":"双线期","kp":"ch09_s1_7","oe":["卵母细胞在双线期染色体去凝集成灯刷染色体，进行转录。"]},{"id":"ch09_fill_7","modI":3,"q":"间期细胞与 M 期细胞融合后将产生染色体超前凝集现象，其中 S 期超前凝集染色体呈 ______状。","a":"粉末","kp":"ch09_s3_3","oe":["S期染色质尚未凝集，故超前凝集时呈粉末状。"]},{"id":"ch09_fill_8","modI":1,"q":"原核生物的细胞周期分为：______、______、______。","a":"启动期；DNA 合成期；细胞分裂期","kp":"ch09_s1_0","oe":["细胞生长并启动复制，为DNA合成做准备。","进行DNA复制，使遗传物质加倍。","完成分裂，将DNA均等分配给子细胞。"]},{"id":"ch09_fill_9","modI":1,"q":"细胞分裂的方式有：______、______、______。","a":"无丝分裂；有丝分裂；减数分裂","kp":"ch09_s1_0","oe":["核直接缢裂，无纺锤体和染色体变化，如蛙红细胞。","体细胞分裂方式，染色体均等分配，维持数目恒定。","生殖细胞分裂方式，染色体减半，形成配子。"]},{"id":"ch09_fill_10","modI":3,"q":"在间期的细胞核中，染色质以______的形式存在，而再分裂期则以______的形式存在。","a":"分散；凝聚","kp":"ch09_s1_6","oe":["间期染色质松散分散，利于转录和复制。","分裂期染色质高度螺旋凝聚成染色体，便于分配。"]},{"id":"ch09_fill_11","modI":5,"q":"在细胞同步化的培养中，秋水仙碱可将细胞阻止在 M 期，其机制是______。","a":"秋水仙碱抑制了纺锤体的形成","kp":"ch09_s1_12","oe":["秋水仙碱抑制微管聚合，破坏纺锤体形成，使细胞停滞于M期。"]},{"id":"ch09_fill_12","modI":0,"q":"细线期的主要特征有：______、______、______。","a":"染色质凝集成单条细线；细线与核膜相连；染色质线上有染色粒","kp":"ch09_s1_7","oe":["细线期染色体呈细线状凝集，尚未配对。","细线期染色体通过端粒与核膜相连，起固定作用。","细线上可见染色粒，呈串珠状结构。"]},{"id":"ch09_fill_13","modI":1,"q":"细菌的细胞周期最短的时间为______min，最长可达______min，这与环境有关。","a":"20；100","kp":"ch09_s1_0","oe":["细菌周期最短约20分钟，如快速生长的大肠杆菌。","最长可达100分钟，取决于营养等环境条件。"]},{"id":"ch09_fill_14","modI":1,"q":"细胞周期中各个时期的长短各有不同，但一般说来，______期长，______期短。","a":"S；M","kp":"ch09_s1_2","oe":["S期即DNA合成期，时间较长，以完成DNA复制。","M期即分裂期，时间较短，相对快速完成。"]},{"id":"ch09_fill_15","modI":2,"q":"多细胞生物体内的细胞，根据增殖情况可以分为______、______和______3 种类型。","a":"周期中细胞；暂不增殖的细胞（G0 期细胞）；终末分化细胞","kp":"ch09_s1_12","oe":["连续分裂的细胞，不断循环于细胞周期。","即G0期细胞，暂时退出周期，可被激活重返。","失去分裂能力，不再进入细胞周期。"]},{"id":"ch09_fill_16","modI":1,"q":"常用的细胞同步化方法有______和______等。","a":"选择同步化；诱导同步化","kp":"ch09_s1_12","oe":["利用细胞物理性质差异，分离出同一时相的细胞。","用药物或营养抑制使细胞积累于某时相而同步。"]},{"id":"ch09_fill_17","modI":1,"q":"减数分裂过程中变化最为复杂的时相为______。","a":"减数分裂Ⅰ的前期","kp":"ch09_s1_7","oe":["减数分裂Ⅰ前期经历细线、偶线、粗线、双线、终变期，变化最复杂。"]},{"id":"ch09_fill_18","modI":3,"q":"细胞减数分裂中，根据细胞形态的变化可以将前期 I 分为______、______、______、______、 ______。","a":"细线期；偶线期；粗线期；双线期；终变期","kp":"ch09_s1_7","oe":["染色质凝集成细线，可见染色粒，尚未配对。","同源染色体配对（联会），形成联会复合体。","同源染色体变粗，非姐妹染色单体间发生交换重组。","联会复合体解体，同源染色体分开并可见交叉。","染色体高度凝集，交叉端化，核仁核膜消失。"]},{"id":"ch09_fill_19","modI":1,"q":"各种细胞的细胞周期时间（Tc）长短不一，有的细胞只有数十分钟，如______细胞，有 的可长达数月之久，如______细胞和______细胞。","a":"胚胎；休眠；卵母","kp":"ch09_s1_2","oe":["胚胎细胞周期很短，仅数十分钟，分裂迅速。","休眠细胞可长期停留，细胞周期长达数月之久。","卵母细胞停留于减数分裂，周期可长达数月。"]},{"id":"ch09_fill_20","modI":3,"q":"选择细胞同步化方法，主要是收集单层培养细胞中的______。期细胞，再加入新鲜培养 基继续培养。","a":"G1／s","kp":"ch09_s1_12","oe":["选择同步化收集中层培养的G1/S期细胞，换新鲜培养基继续培养。"]},{"id":"ch09_fill_21","modI":3,"q":"细胞有丝分裂时，______对染色体平衡运动和分配起着重要作用。","a":"有丝分裂器","kp":"ch09_s1_6","oe":["有丝分裂器包括纺锤体、中心体等，牵引染色体保证均等分配。"]},{"id":"ch09_fill_22","modI":3,"q":"卫星 DNA（高度重复序列 DNA），主要出现在染色体的______区。","a":"主缢痕","kp":"ch09_s1_6","oe":["主缢痕是着丝粒所在区域，富含高度重复的卫星DNA。"]},{"id":"ch09_fill_23","modI":2,"q":"中期阻断法是获得细胞同步化培养的一种方法，其原理是______。","a":"通过某些药物，如秋水仙素等，抑制微管聚合，从而有效抑制细胞分裂器的形成，将细胞阻 断在细胞分裂中期","kp":"ch09_s1_12","oe":["中期阻断法用秋水仙素等抑制微管聚合，破坏纺锤体，使细胞停滞于中期。"]},{"id":"ch09_fill_24","modI":3,"q":"动粒和着丝粒由于它们在染色体中的位置相同，而导致认识上的混淆，其实它们是两个 不同的概念，最本质的差别是：前者是_________，后者则是_________。[中山大学 2007 研]","a":"蛋白质；DNA","kp":"ch09_s1_6","oe":["动粒是着丝粒两侧由蛋白质构成的盘状结构，供纺锤体附着。","着丝粒是染色体上含特定DNA序列的区域，是动粒的座位。"]},{"id":"ch09_fill_25","modI":0,"q":"根据是否增殖可将细胞划分为：______、________、和_______。[湖南大学 2007 研]","a":"G0 期细胞；周期中细胞；终末分化细胞","kp":"ch09_s1_12","oe":["暂时脱离细胞周期、停止分裂，受刺激可重返周期的细胞","持续进行分裂增殖，不断循环于G1-S-G2-M各时相的细胞","已丧失分裂能力、高度分化而不再增殖的细胞"]},{"id":"ch09_fill_26","modI":6,"q":"中期染色体具有比较稳定的形态，它由两条相同的姐妹染色单体构成，彼此以________ 相连。[郑州大学 2007 研]","a":"着丝粒","kp":"ch09_s1_6","oe":["两条姐妹染色单体在着丝粒处相连，着丝粒也是纺锤丝附着位点"]},{"id":"ch09_fill_27","modI":1,"q":"G1 期细胞同 S 期细胞融合，则 S 期细胞__________，G1 期细胞_________。G2 期细胞同 S 期细胞融合，则 S 期细胞__________，G2 期细胞_________。G1、S 和 G2 期细胞分别同 M 期细胞融合，则 Gl、S 及 G2 细胞均产生________。","a":"染色体凝聚；发生染色体复制；DNA 复制加快；保持不变；染色体超前凝聚","kp":"ch09_s3_2","oe":["S期细胞受G1期细胞影响，染色质发生凝聚","G1期细胞被S期细胞诱导，提前启动DNA复制","S期细胞受G2期细胞作用，DNA复制速度加快","G2期细胞已完成DNA复制，故保持不变","M期成熟促进因子使G1、S、G2染色质均超前凝聚"]},{"id":"ch09_fill_28","modI":5,"q":"用 3H 嘧啶核苷标记已证明，mtDNA 复制时间主要在细胞周期的_______期、_______期， DNA_______，随后_______。[中科院-中科大 2004 研]","a":"S；G2；先复制；线粒体分裂","kp":"ch09_s1_4","oe":["线粒体DNA复制主要发生在细胞周期的S期","mtDNA复制持续到G2期，故G2期也能检测到合成","mtDNA先于线粒体分裂完成复制，保证DNA均分","DNA复制完成后线粒体才进行分裂增殖"]}],"term":[{"id":"ch09_term_1","modI":1,"term":"有丝分裂（mitosis）。","def":"有丝分裂（mitosis）是真核细胞分化与增殖的基本方式，分为核分裂和胞质分裂，DNA 及其他物质如蛋白等复制了的细胞平均分配到两个子细胞的过程。真核生物细胞在形成染色 体和纺锤体等丝状结构的同时发生复杂的核内变化。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_2","modI":6,"term":"动粒（kinetochore）。","def":"动粒（kinetochore）是指在主缢痕处 2 个染色单体的外侧表层部位的特殊结构，它与染 色体微管接触，是微管蛋白的组织中心，又称着丝点。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_3","modI":6,"term":"纺锤体（spindle）。","def":"纺锤体（spindle）是指减数和有丝分裂中期，细胞质中出现的纺锤形结构，由能收缩的 微管和微丝纵向成束排列而成。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_4","modI":6,"term":"姐妹染色单体（sister chromatid）。","def":"姐妹染色单体（sister chromatid）是指染色体分裂间期进行自我复制，所形成的由一个 着丝点连接着的两条完全相同的染色单体。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_5","modI":6,"term":"分裂中期阻断法（metaphase blocking）。","def":"分裂中期阻断法（metaphase blocking）是指应用可以抑制微管聚合的某些药物，如秋水 仙素、秋水酰胺和 noeodazole 等，从而有效抑制细胞分裂器的形成，将细胞阻断在分裂中期 的细胞周期同步方法。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_6","modI":2,"term":"中间体（midbody）。","def":"中间体（midbody）是指在分裂沟下方，除肌动蛋白之外，还有微管、小膜泡等物质聚 集，共同构成的一个环形致密层。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_7","modI":1,"term":"细胞分裂（splinter Cell）。","def":"细胞分裂是指一个细胞（母细胞）分裂成两个以上细胞（子细胞）的现象。由于细胞分 裂，核及细胞器分配给两个子细胞。细胞分裂分为有丝分裂和减数分裂两种主要的分裂方式","kps":"","kp":"ch09_s1_0"},{"id":"ch09_term_8","modI":1,"term":"胞质分裂（cytokine－sis）。","def":"胞质分裂是指在细胞分裂末期时，通常于核分裂之后接着发生的胞质体的分裂。根据生 物种类的不同，胞质分裂可分为两个基本类型：一是在高等植物细胞中，于细胞分裂的后期， 姐妹染色单体群移到两极之后，纺锤体的中间区域分化为膜体。在末期，从纺锤体中部形成 细胞板；二是在动物细胞中，于细胞分裂的末期，赤道板位置上的表层细胞质部位向中间凹 陷缢缩。另外，在一部分植物细胞中，以及在酵母出芽和粘菌的孢子形成时等，可以看到有 介于这两种类型之间的中间型。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_9","modI":1,"term":"DNA 合成期。（S phase (DNA synthesis phase)）","def":"DNA 合成期指细胞周期中合成 DNA 的时期，也称 S 期。核内的 DNA 几乎都在这一时 期合成，使核内 DNA 的量倍增。在 S 期中，由各条染色体（或染色体的不同部分）所进行 的 DNA 合成是有快有慢的。另外新的组蛋白也在 S 期合成。","kps":"","kp":"ch09_s1_3"},{"id":"ch09_term_10","modI":1,"term":"G0 期。（G0 phase）","def":"G0 期指具有分裂能力的组织中的细胞在反复分裂数次之后离开细胞周期，执行某种生 物学功能或进行细胞分化，当受到某种适当的外界刺激后，会重返细胞周期，进行分裂增殖， 细胞所处的停止分裂状态的时期就叫做 G0 期。G0 期只不过是细胞周期中 G1 期或 G2 期的无 限延长，而不是细胞周期中 G0 期或 G2 期的中断和脱离。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_11","modI":6,"term":"细线期（leptotene stage）。","def":"细线期是指第一次减数分裂前期的最初时期。在这个时期，染色质凝集成单条细线，细 线与核膜相连，染色质线上有染色粒。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_12","modI":6,"term":"双线期（diplotene stage）。","def":"双线期是指在第一减数分裂前期，继粗线期的时期。在这一时期，重组阶段结束，同源 染色体相互分离，仅留几处相互联系，四分体结构变得清晰可见。在双线期可见染色体交叉。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_13","modI":2,"term":"限制点（restriction point）。","def":"在 Gl 期的晚期阶段，细胞对一些环境因素敏感，如果细胞继续分裂，则可以通过这个 特定时期，进入 S 期，这一特定时期即限制点，在酵母中称为起始点。","kps":"","kp":"ch09_s1_3"},{"id":"ch09_term_14","modI":1,"term":"中心粒周期。（Centriole cycle）","def":"从中心粒的新生、生长、成熟，以及中心体的分离、移动、组装纺锤体至分配到 2 个子 细胞的过程称为中心粒周期","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_15","modI":6,"term":"着丝点。（Kinetochore）","def":"着丝点是在主缢痕处 2 个染色单体的外侧表层部位的特殊结构，它与染色体微管相接触， 是微管蛋白的组织中心，着丝点又称动粒或动原粒","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_16","modI":3,"term":"着丝点微管。（Kinetochore microtubule）","def":"着丝点微管又称动粒微管或染色体微管，是从着丝点与一个极相连的微管。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_17","modI":0,"term":"静止期细胞（quiescent cell）。","def":"由于 R 点（又称 checkpoint）作用，周期中细胞暂时脱离细胞周期不进行增殖（大多处 于 G1 期），但给予适当刺激后可重新进入细胞周期进行细胞分裂，这些细胞称为静止期细 胞，或 G0 期细胞。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_18","modI":3,"term":"核内有丝分裂（intranuclear mitosis）。","def":"核内有丝分裂是指在核分裂过程中核膜始终保持完整的一种有丝分裂方式。纺锤丝可以 完全局限在核内，如酵母菌；也可伸出核膜以外，但仍保持核膜的完整性。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_19","modI":2,"term":"染色体整列（chromosome alignment）。","def":"在细胞分裂的前中期染色体向赤道板的位置移动的过程称为染色体整列。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_20","modI":5,"term":"花束期（bouquet stage）。","def":"在减数分裂的细线期时，有些物种表现为染色体细线一端在核膜的一侧集中，另一端呈 放射状伸出，形似花束，称为花束期。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_21","modI":6,"term":"中心体列队（centrosome alignment）。","def":"在细胞分裂过程中一对中心体分别移向细胞的两极的过程称为中心体列队。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_22","modI":1,"term":"G0 期细胞（G0 phase cell）","def":"G0 期细胞又称休眠细胞，是指一类可长期停留在 G1 早期而不越过 R 点，处于增殖静止 状态的细胞。它们可合成具有特殊功能的 RNA 和蛋白质，使细胞的结构和功能发生分化， 这类细胞并未丧失增殖能力，在一定条件下可以恢复其增殖状态，但需要经过较长的恢复时 间。如：肝、肾的实质细胞、血液中的淋巴细胞都属于 G0 期这类细胞。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_23","modI":1,"term":"联会复合体（Synaptonemal complex）","def":"联会复合体是指同源染色体之间在减数分裂前期联会时所形成的一种临时性结构，是一 种减数分裂特异性超分子蛋白质结构，与减数分裂 I 中同源染色体的凝缩、配对、重组和分 离密切相关。联会复合体从细线期开始组装，经过偶线期至粗线期形成典型的联会复合体结 构，同时在粗线期重组节开始组装。双线期联会复合体开始去装配，终变期时完全消失。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_24","modI":1,"term":"FtsZ 蛋白（FtsZ protein）","def":"FtsZ 蛋白是一种广泛存在于细菌和古菌中的结构保守的蛋白质，在细胞胞质分裂的过 程中，在母细胞中间形成收缩环结构，起着将母细胞缢裂成两个子细胞的关键作用。FtsZ 蛋白具有 GTPase 活性，并能受 GTP 诱导发生聚合，是原核生物细胞分裂的关键蛋白之一。","kps":"","kp":"ch09_s1_0"},{"id":"ch09_term_25","modI":1,"term":"减数分裂（Meiosis）","def":"减数分裂是指细胞仅进行一次 DNA 复制，随后进行两次分裂，染色体数目减半的一种 特殊的有丝分裂。减数分裂是仅发生于有性生殖细胞形成过程中的某个阶段的一种特殊的有 丝分裂形式，整个过程分为减数分裂Ⅰ和减数分裂Ⅱ两个阶段。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_26","modI":3,"term":"诱导同步（Induction Synchrony）","def":"诱导同步是指用物理、化学方法处理培养细胞，使所有细胞群停留在细胞周期的某一时 相，从而使它们的分裂周期同步化的方法。目前应用较广泛的诱导同步方法主要有两种，即 DNA 合成阻断法和分裂中期阻断法。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_27","modI":1,"term":"synapsis（Synapsis）","def":"synapsis 的中文名称是联会。联会是指减数分裂前期的偶线期，同源染色体发生配对， 来自父母双方的同源染色体逐渐靠近，沿其长轴相互紧密结合在一起的过程。联会形成四分 体，由两条染色体共四条染色单体组成。","kps":"","kp":"ch09_s1_7"},{"id":"ch09_term_28","modI":3,"term":"amitosis（Amitosis）","def":"amitosis 的中文名称是无丝分裂。无丝分裂是最早发现的一种细胞分裂方式，在无丝分 裂中，核膜和核仁都不消失，没有纺锤体和染色体的出现，这是无丝分裂与有丝分裂的最大 区别。无丝分裂的过程比较简单，一般是细胞核先延长，从核的中部向内凹进，缢裂成为两 个细胞核；然后整个细胞从中部缢裂成两部分，形成两个子细胞。","kps":"","kp":"ch09_s1_0"},{"id":"ch09_term_29","modI":1,"term":"细胞周期同步化（Cell cycle synchronization）","def":"细胞周期同步化是指在自然过程中发生的或经人为处理造成的所有细胞处于同一细胞周 期阶段的过程。前者称为天然同步化，后者称为人工同步化。人工同步化包括人工选择同步 化和人工诱导同步化（DNA 合成阻断法和分裂中期阻断法）。","kps":"","kp":"ch09_s1_12"},{"id":"ch09_term_30","modI":1,"term":"有丝分裂器（Mitotic apparatus）","def":"有丝分裂器是一个动态的结构，在中期细胞中包括两部分：①纺锤体，是由对称的微管 束组成的形似橄榄球的结构，在细胞的赤道板被染色体一分为二；②星体，在纺锤体的两端 各有一个，为一簇呈放射状的微管。","kps":"","kp":"ch09_s1_6"},{"id":"ch09_term_31","modI":1,"term":"细胞周期（Cell cycle）","def":"细胞周期是指从第一次细胞有丝分裂结束到第二次分裂完成所经历的过程，包括分裂间 期和分裂期（M 期）。其中分裂间期是指第一次分裂结束到第二次分裂开始的时间，是细 胞增殖的物质准备和积累阶段，包括 G1 期、S 期（DNA 合成）和 G2 期。M 期是指一次分 裂开始到结束的时间，包括前期、中期、后期和末期。","kps":"","kp":"ch09_s1_0"}],"short":[{"id":"ch09_short_1","modI":1,"q":"细胞增殖有何意义？","a":"细胞增殖的意义是： （1）细胞增殖是细胞生命活动的重要特征之一，是生物繁育的基础。 （2）单细胞生物细胞增殖导致生物个体数量的增加。 （3）多细胞生物由一个单细胞（受精卵）分裂发育而来，细胞增殖是多细胞生物繁殖的基 础。 （4）成体生物仍然需要细胞增殖，主要取代衰老死亡的细胞，维持个体细胞数量的相对平 衡和机体的正常功能。 （5）创伤愈合、组织再生、病理组织修复等，都要依赖细胞增殖。","kp":"ch09_s1_0","kps":"意义：生命活动重要特征与繁育基础；多细胞生物由受精卵分裂而来；成体替换衰老死亡细胞、维持数量功能；创伤愈合、组织再生"},{"id":"ch09_short_2","modI":5,"q":"简述细胞周期中不同时相及其主要事件。","a":"细胞周期分为间期（G1 期、S 期、G2 期）和分裂期（M 期），各个时相发生的主要事 件如下所述： （1）G1 期，与 DNA 合成启动相关，开始合成细胞生长所需要的多种蛋白质、RNA、 碳水化合物、脂质等，同时染色质去凝集。 （2）S 期，合成 DNA 和染色体蛋白（组蛋白和非组蛋白）。新合成的 DNA 立即与组蛋白 结合，组成核小体串珠结构。 （3）G2 期，合成其他结构物质和相关的亚细胞结构，如微管蛋白、染色体凝集因子等。 （4）M 期，即细胞分裂期，包括胞核分裂和胞质分裂，细胞将其遗传物质载体平均分配到 两个子代细胞中。","kp":"ch09_s1_0","kps":"周期=间期(G1、S、G2)+M期；G1合成RNA；S复制DNA及组蛋白；G2合成微管蛋白、凝集因子；M核分裂与胞质分裂"},{"id":"ch09_short_3","modI":0,"q":"比较自然同步化、人工选择同步化、密度梯度离心法。","a":"（1）自然同步化，如有一种黏菌的变形体 plasmodia，某些受精卵早期卵裂。条件依赖 性突变株在细胞周期同步化中的应用：将与细胞周期调控有关的条件依赖性突变株转移到限 定条件下培养，所有细胞便被同步化在细胞周期中某一特定时期。 （2）人工选择同步化，如有丝分裂选择法，可用于单层贴壁生长细胞。优点是细胞未经任 何药物处理，细胞同步化效率高。缺点是分离的细胞数量少。 （3）密度梯度离心法，根据不同时期的细胞在体积和重量上存在差别进行分离。优点是方 法简单省时，效率高，成本低。缺点是对大多数种类的细胞并不适用。","kp":"ch09_s1_12","kps":"自然同步化：黏菌变形体、条件突变株；人工选择同步化：有丝分裂选择法，效率高但数量少；密度梯度离心法：按体积重量分离"},{"id":"ch09_short_4","modI":1,"q":"植物细胞的细胞周期有何特点？","a":"（1）植物细胞的细胞周期与动物细胞的标准细胞周期非常相似，含有 G1 期、S 期、C2 期和 M 期四个时期；（2）植物细胞不含中心体，但在细胞分裂时可以正常组装纺锤体；（3） 植物细胞以形成中板的形式进行胞质分裂。","kp":"ch09_s1_1","kps":"与动物细胞周期相似，含G1、S、G2、M；无中心体但能正常组装纺锤体；以形成中板方式行胞质分裂"},{"id":"ch09_short_5","modI":3,"q":"简述细胞有丝分裂的过程。","a":"有丝分裂过程分为前期、前中期、中期、后期、末期和胞质分裂。 前期：染色体凝集，核膜解体及核仁消失。 前中期：核膜破裂，纺锤体开始组装。 中期：染色体排列到赤道面上。 后期：中期染色体的两条染色单体相互分离，形成子代染色体，并分别向两极运动。 末期：子核形成。 胞质分裂：开始于细胞分裂后期，完成于细胞分裂末期","kp":"ch09_s1_6","kps":"前期染色体凝集、核膜核仁消失；前中期核膜破裂、纺锤体组装；中期染色体排列赤道面；后期染色单体分离；末期子核形成；胞质分裂"},{"id":"ch09_short_6","modI":2,"q":"如何利用胸腺嘧啶和秋水仙素获得同步培养的细胞？","a":"（1）高浓度的胸腺嘧啶能够阻断 DNA 合成所需的核苷酸的合成，因此将细胞群体培 养在具有高浓度的胸腺嘧啶的培养液中时，非同步化的细胞能够正常地通过细胞周期，但到 达 S 期时，因 DNA 的合成被阻断，这些细胞不能顺利通过 S 期进入 G2 期。经过对 S 期的 短暂阻断，再改变胸腺嘧啶的浓度，解除抑制，所有的细胞都开始 DNA 的合成，即获得处 于同步生长的细胞。 （2）秋水仙素可抑制微管的聚合，因而抑制有丝分裂器的形成，将细胞阻断在有丝分裂的 中期，适当时间后解除秋水仙素的作用，即获得处于中期的同步化的细胞。这一方法称为中 期阻断法。","kp":"ch09_s1_12","kps":"①高浓度胸腺嘧啶阻断核苷酸，解除后同步进入S期；②秋水仙素抑制微管聚合、不能形成纺锤体，阻断于中期，解除后获中期同步细胞"},{"id":"ch09_short_7","modI":1,"q":"下面的叙述有错误吗？请指出并解释。“生殖细胞和体细胞 DNA 的稳定对于一种物种的 生存都是至关重要的。”","a":"这种说法是正确的。如果体细胞中的 DNA 不够稳定（即如果积累突变过程过快）则导 致个体死亡（如死于肿瘤），因为这些突变常发生在生物繁殖之前，因此导致该物种的灭绝。 如果生殖细胞中的 DNA 不够稳定，就会积累许多突变并传递给后代，所以该物种将难以维 持下去。","kp":"ch09_s1_2","kps":"说法正确；体细胞DNA不稳定积累突变致个体死亡（如肿瘤），多在繁殖前可致物种灭绝；生殖细胞DNA不稳定则突变传后代"},{"id":"ch09_short_8","modI":1,"q":"细胞内的突变使编码参与 DNA 复制的蛋白质的基因失活。在没有这种蛋白质的情况下， 细胞内的 DNA 复制仍然尽可能地进行。如果下列蛋白质消失，将会产生什么样的 DNA 产 物？ （1）DNA 聚合酶； （2）DNA 连接酶； （3）DNA 聚合酶的滑动夹钳； （4）清除 RNA 引物的切除酶； （5）DNA 解旋酶: （6）引物酶。","a":"（1）无 DNA 聚合酶，复制根本不可能进行，RNA 引物将在复制起始位点积累。 （2）DNA 连接酶负责连接后随链上合成的 DNA 片段。没有连接酶，则新复制的 DNA 链 将保持片段状态，但核苷酸不会丢失。 （3）无滑动夹钳，DNA 聚合酶常会脱离 DNA 模板，虽然原则上能够再结合上来并继续反 应，但不断地脱离与再结合将会耗费很多时间，从而大大降低 DNA 复制的速度。 （4）没有 RNA 切除酶，则 RNA 片段将保持与新复制的 DNA 片段共价连接。由于连接酶 不能将 DNA 连接于 RNA,连接反应不能进行。因此，后随链将由 RNA 和 DNA 片段两者组 成。 （5）没有 DNA 解旋酶，则 DNA 聚合酶将不会前进，因为它不能分开其前方模板 DNA 双 链，不合成或极少合成新的 DNA （6）无引物酶，则 RNA 引物在前导链或后随链上均不能合成。DNA 复制不能起始","kp":"ch09_s1_0","kps":"无聚合酶：复制不能；无连接酶：后随链片段不连接；无夹钳：聚合酶易脱落；无切除酶：引物残留；无解旋酶、无引物酶：复制受阻"},{"id":"ch09_short_9","modI":1,"q":"在减数分裂Ⅰ中，姐妹染色单体为什么必须保持配对？","a":"减数分裂开始于 DNA 的复制，产生一个含有各条染色体 4 个拷贝的四倍体细胞，在随 后的两次减数分裂中这 4 个拷贝必须被均等分配至 4 个单倍体细胞。姐妹染色单体保持配对， 这样： （1）第一次减数分裂产生的细胞接受完整的两套染色体。 （2）在第二次减数分裂中染色体将会再次均等分配。如果姐妹染色单体不保持配对，在第 二次分裂中将不可能鉴别哪些染色单体应被组合在一起，因而很难保证每一染色单体的一个 拷贝被精确分配到每一个子细胞中。因而在第一次减数分裂中保持姐妹染色单体配对是一种 简易的方法，用于始终监视哪些染色单体应被分配在一起","kp":"ch09_s1_7","kps":"减数分裂前DNA复制，染色体4拷贝须均分至4个单倍体细胞；配对保证①第一次分裂得两套完整染色体②第二次分裂均等分配"},{"id":"ch09_short_10","modI":1,"q":"比较有丝分裂与减数分裂的异同。","a":"见表 13-1。 表 13-1 有丝分裂与减数分裂的比较 有丝分裂           减数分裂 确保遗传的稳定性和生 体细胞以此方式进行分化与增 物变异，主要是生殖细胞 殖，维持机体发育和细胞更新 的分裂方式 DNA 复制一次，细胞分 DNA 复制一次，细胞分裂一次 裂两次 S 期时间相对较长       S 期时间相对较短 一个细胞产生四个子细 一个细胞产生两个子细胞 胞 常发生染色体的交叉互 不发生染色体互换 换，产生变异分裂时间 分裂时间短，1～2 小时 长，24 小时至几年","kp":"ch09_s1_4","kps":"同：DNA复制一次；异：有丝分裂为体细胞、2子细胞、S期长；减数分裂为生殖细胞、4子细胞、同源染色体联会互换、S期短"},{"id":"ch09_short_11","modI":1,"q":"简述用放射性同位素 3H-TdR（氚胸腺嘧啶）标记法来测定细胞周期长短的原理。假如一 种体外培养的非同步生长细胞，它的细胞周期 G1 期是 6 小时，S 期是 6 小时，G2 期是 5 小 时，M 期是 1 小时，如果用 3H-TdR 标记细胞 15 分钟后，立即洗去 3H-TdR，然后放置在新 鲜培养基中继续培养。请问： （1）用 3H-TdR 标记 15 分钟后，这时被标记的细胞占细胞总数的百分比是多少？ （2）用 3H-TdR 标记 15 分钟后，洗净后放置在新鲜培养基中培养 18 小时，这时被标记的 M 期细胞又占多少比例？","a":"用 3H-TdR 标记法测定细胞周期长短的原理：用放射性同位素 3H-TdR（氚胸腺嘧啶） 标记细胞，3H-TdR（氚胸腺嘧啶）在 DNA 复制过程中被整合入新合成的 DNA 从而对细胞 做上标记。短暂标记后将细胞转移到新鲜普通培养基中培养，每隔一定时间取样做放射自显 影观察分析，从而确定细胞周期各时相的长短。 （1）用 3H-TdR 标记 15 分钟后，此时被标记的细胞是 S 期的细胞，占细胞总数的百分比： 6∕（6＋6＋5＋1）＝1/3。 （2）这类细胞的细胞周期刚好是 18 小时，因此培养 18 小时后所有的细胞均被标记。被标 记的 M 期细胞占 1/18。","kp":"ch09_s1_2","kps":"原理：3H-TdR掺入新DNA标记；(1)S期细胞被标记，占1/3；(2)周期18h，18h后全标记，标记M期占1/18"},{"id":"ch09_short_12","modI":1,"q":"试述减数分裂的概念、意义和特点。 相关试题：减数分裂前期Ⅰ发生染色体联会的生物学意义何在？","a":"（1）减数分裂的概念 减数分裂是细胞仅进行一次 DNA 复制，随后进行两次分裂、染色体数减半的一种特殊的有 丝分裂。减数分裂是仅发生于有性生殖细胞形成过程中的某个阶段的一种特殊的有丝分裂形 式，整个过程分为减数分裂Ⅰ和减数分裂Ⅱ两个阶段。 （2）减数分裂的意义 ①有效获得双亲的遗传物质，确保世代间遗传的稳定性； ②增加变异机会，确保生物的多样性，增加生物适应环境变化的能力； ③减数分裂是生物有性生殖的基础，是生物遗传、生物进化、生物多样性的重要基础保证。 （3）减数分裂的特点 ①遗传物质只复制一次，细胞连续分裂两次，染色体数目减半； ②S 期持续时间较长； ③同源染色体在减数分裂期Ⅰ配对联会，基因重组； ④同源染色体配对排列在中期赤道极上，第一次分裂时同源染色体分开。","kp":"ch09_s1_7","kps":"概念：一次DNA复制、两次分裂、染色体减半；意义：得双亲遗传物质、有性生殖基础；特点：复制一次分裂两次、同源染色体联会"},{"id":"ch09_short_13","modI":5,"q":"用秋水仙素处理培养的细胞以使细胞同步化。这种处理会使细胞停留在细胞周期的什么 位置？什么机制阻止了细胞周期的进行？","a":"（1）用秋水仙素处理培养的细胞后，会使细胞停留在有丝分裂中期。 （2）阻止细胞周期进行的机制为： 秋水仙素可以与微管蛋白亚基结合，而当结合有秋水仙素的微管蛋白亚基组装到微管末端后， 其他的微管蛋白亚基就很难再在该处进行组装，因而秋水仙素可以抑制微管的形成，不能形 成纺锤体。用低浓度的秋水仙素处理细胞，可立即破坏细胞内的微管或纺锤体结构，使细胞 周期停留在有丝分裂中期。","kp":"ch09_s1_12","kps":"停留于有丝分裂中期；机制：秋水仙素结合微管蛋白亚基，阻碍亚基在微管末端组装，抑制微管与纺锤体形成，使细胞停滞于中期"},{"id":"ch09_short_14","modI":3,"q":"试比较染色体着丝粒与着丝点的区别与联系。","a":"（1）着丝粒与着丝点的区别 ①着丝粒是指位于染色体主缢痕部位的染色质。 ②着丝点即动粒，在主缢痕处两个染色单体的外侧表面部位的特殊结构，它与染色体微管接 触，是微管蛋白的组织中心。在电镜下，动粒为一个圆盘状结构，分内、中、外三层。 （2）着丝粒与着丝点的联系 着丝点（动粒）是附着于着丝粒上的一种特殊结构，动粒的外侧主要用于纺锤体微管附着， 内侧与着丝粒相互交织。由于动粒和着丝粒联系紧密，结构成分相互穿插，在功能方面联系 密切，因而两者常被称为着丝粒-动粒复合体。","kp":"ch09_s1_6","kps":"区别：着丝粒为主缢痕处染色质；着丝点即动粒，位于两染色单体外侧；联系：动粒附着于着丝粒，合称着丝粒-动粒复合体"},{"id":"ch09_short_15","modI":5,"q":"简要说明细胞周期的间期各时相的特点。","a":"细胞周期的间期各时相的特点如下： （1）G1 期 ①时间：在周期时间中所占的比例最大，时间变化也最大，不同细胞类型的周期时间的差别 以及细胞的失同步等都是由 G1 期的差异造成的。 ②生化特征：主要合成大量的 RNA 和蛋白质，为细胞进入 S 期准备必要的物质基础。 ③重要性：G1 期细胞能对多种环境信号进行综合、协调并作出反应，以确定细胞是否进入 S 期。 （2）S 期 细胞内主要进行 DNA 的复制、组蛋白和非组蛋白等染色体蛋白的合成。 （3）G2 期 ①形态特征：染色质凝聚或螺旋化。 ②生化特征：合成一定的蛋白质和 RNA，为 M 期的细胞结构变化做准备。 （4）M 期 ①时间：细胞周期中 M 期占用的时间最短，可分为前、中、后、末期 4 个阶段。 ②形态特征：细胞的形态结构变化最大。 ③生化特征：RNA 合成停止、蛋白质合成减少以及染色体高度螺旋化。 ④关键因子：由 G2 期进入 M 期是细胞周期中的另一个关键时刻，M 期细胞质中存在一种使 染色质浓缩的物质，即 M 期促进因子（MPF）。","kp":"ch09_s1_0","kps":"G1期合成RNA和蛋白质、决定进S期；S期复制DNA及组蛋白；G2期染色质凝聚、合成微管蛋白等为M期准备；M期核质分裂"},{"id":"ch09_short_16","modI":1,"q":"用图文相结合的形式，叙述有丝分裂后期使染色体移向两极的三种马达模型。 相关试题：在动物细胞有丝分裂后期，有哪些分子马达作用于纺锤体的什么部位？各通过何 种运动来决定染色体分离和纺锤体长度？","a":"（1）有丝分裂后期使染色体移向两极的三种马达模型 ①星体微管马达：将有丝分裂器与细胞质膜连在一起。 ②极微管马达：负责将两极间的微管延长。 ③动粒微管马达（染色体微管马达）：负责缩短染色体微管的长度，使染色体向两极运动。 （2）三种马达使染色体移向两极的过程 有丝分裂后期分为后期 A 和后期 B 两个阶段。后期 A，动粒微管变短，牵动染色体向两极 运动；在后期 B，极微管长度增加，两极之间的距离逐渐拉长。 ①后期 A：微管马达蛋白首先结合到动粒上，在 ATP 分解提供能量的情况下，沿动粒微管 向极部运动，并带动动粒和染色体向极部运动。动粒微管的末端随之解聚成微管蛋白二聚体， 动粒微管变短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期 A 结束，转向后期 B。 ②后期 B：极微管游离端（正极）在 ATP 提供能量的情况下与微管蛋白聚合，使极微管加 长，形成较宽的极微管重叠区。KRPs 与极微管重叠区的微管结合并在来自两极的极微管之 间搭桥。KRPs 向微管正极行走，促使来自两极的极微管在重叠区相互滑动，使重叠区逐渐 变得狭窄，两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管和细胞膜之间搭桥， 并向星体微管负极运动，进一步将两极之间的距离拉长。     图 13-1 纺锤体结构模式图 图 13-2 细胞分裂后期 A 和后期 B 产生染色体向极部运动的示意图 六、实验题 已知某信号分子（分泌蛋白）引发的下游事件可抑制细胞分裂，我们推测该信号分子的受体 可能分布在细胞膜上。请你设计一个实验方案证实： （1）该信号分子的受体确实存在于细胞膜上； （2）该信号分子是通过与其受体的结合抑制了细胞分裂。 该实验应特别注意哪些关键环节？ 答：实验方案如下： 实验原理：绿色荧光蛋白（Green Fluorescent Protein，简称 GFP）是一种在美国西北海岸盛 产的水母中发现的一种蛋白质。它之所以能够发光，是因在其包含 238 个氨基酸的序列中， 第 65 至 67 个氨基酸（丝氨酸-酪氨酸-甘氨酸）残基可自发地形成一种荧光发色团。因此能 够直接看到细胞内部的运动情况，轻易地找出 GFP 蛋白所处的位置。 （1）本实验中，可以构建含有可以表达该信号分子基因与 GFP 基因的融合载体，然后将其 转化到细胞中。该载体就会在细胞中表达带有 GFP 蛋白的信号分子。如果该信号分子与细 胞膜上的受体蛋白结合，那么就会在细胞膜上观察到发光的 GFP 蛋白。该实验可以证明已 知信号分子的受体确实存在于细胞膜上。 （2）在（1）的方案基础上设立对照实验。 ①以无信号分子结合的正常细胞作为对照组。 ②构建带有可以与信号分子结合但是没有功能的受体片段，与信号分子竞争性结合，从而阻 止信号分子与受体的结合。 如果①和②情况下细胞正常分裂，则说明该信号分子是通过与其受体结合抑制了细胞分裂。 （3）注意事项： ①GFP 蛋白与已知信号分子融合后可能影响信号分子的构象从而影响信号分子的功能以及 与其受体的结合。 ②表达的受体片段应该与信号分子具有结合性，同时，需要保证该信号片段大量表达，具有 较高浓度，从而可以与信号分子产生竞争性结合。","kp":"ch09_s1_6","kps":"①星体微管马达连分裂器与质膜；②极微管马达延长极间微管；③动粒微管马达缩短动粒微管；后期A动粒微管变短、后期B极微管延长"},{"id":"ch09_short_17","modI":1,"q":"9％）、偶线期和 粗线期 分裂前后，染色体的分裂后，染色体数目 染色体数目 数目恒定          减半 减数分裂前间期、减 有丝分裂间期和有 数分裂期Ⅰ、减数分 分裂过程 丝分裂期          裂间期、减数分裂期 Ⅱ 联会复合体    无             有 同源染色体非 姐妹染色单体 无              有（果蝇例外） 互换 确保世代遗传的稳 定性；增加变异机 会，确保生物的多样 细胞数目增多，多细性，增强生物适应环 生物学意义    胞生物体的体积增 境变化的能力；是生 大        物有性生殖的基础， 是生物遗传、生物进 化和生物多样性的 重要基础保证","a":"","kp":"ch09_s1_6","kps":"有丝分裂：复制一次分裂一次、2子细胞、无联会互换、细胞数目增多；减数分裂：染色体减半、有联会互换、增加变异、有性生殖基础"},{"id":"ch09_short_18","modI":3,"q":"试述动粒的结构及功能。","a":"（1）动粒的结构 动粒又称着丝点，是附着于着丝粒上的一种细胞结构。动粒的外侧主要用于纺锤体微管附着， 内侧与着丝粒相互交织。在电镜下，动粒为一个圆盘状结构，分为内板、中间间隙、外板和 纤维冠 4 个部分。 （2）动粒的功能 动粒是有丝分裂和减数分裂中染色体分离必不可少的要素。在细胞分裂（包括有丝分裂和减 数分裂）的前、中、后期等几个阶段，纺锤体的纺锤丝（或星射线）需附着在染色体的动粒 上（而非着丝粒上）。在细胞分裂过程中，微管与动粒相连，牵引染色体在分裂中期进行染 色体整列，在分裂后期，牵引分开的染色体分别向细胞的两极运动，形成两个新的子细胞。","kp":"ch09_s1_6","kps":"结构：动粒附着于着丝粒，外侧附纺锤体微管，电镜下分内板、外板；功能：染色体分离，纺锤丝附于动粒，后期牵引染色体移极"},{"id":"ch09_short_19","modI":1,"q":"说明细胞分裂过程中核膜破裂和重装配的调节机制。","a":"（1）细胞分裂过程中核膜破裂的调节机制 在细胞分裂的前期末，活化的 MPF 促使构成核纤层结构的核纤层蛋白磷酸化，导致核纤层 结构瓦解，核膜破裂形成膜泡。 （2）细胞分裂过程中重装配的调节机制 在细胞分裂末期，APC 介导有丝分裂周期蛋白的降解，导致 MPF 失活。染色体开始去凝集， 核纤层蛋白开始去磷酸化并围绕染色质重新形成核纤层结构，膜泡围绕核纤层结构重新形成 新的核膜。","kp":"ch09_s1_6","kps":"破裂：前期末MPF使核纤层蛋白磷酸化，核膜破裂；重装配：末期APC介导周期蛋白降解，核纤层蛋白去磷酸化重建核膜"},{"id":"ch09_short_y1","modI":0,"q":"比较有丝分裂与减数分裂在复制/分裂次数、联会重组、同源染色体行为和子细胞数目上的差异。","a":"①复制/分裂次数：有丝分裂DNA复制1次、分裂1次；减数分裂DNA复制1次、连续分裂2次。②联会与重组：有丝分裂无同源染色体联会与交换重组；减数分裂前期I发生联会、形成二价体/四分体并发生交换重组。③同源染色体行为：有丝分裂中同源染色体不配对，后期姐妹染色单体分离；减数分裂后期I同源染色体分离、后期II姐妹染色单体分离。④子细胞数目与染色体数：有丝分裂产生2个子细胞，2n→2n；减数分裂产生4个子细胞，2n→n。⑤相同点：都通过纺锤体与染色体相互作用进行，都有明显的核与染色质变化。","kps":"复制/分裂:1次1次 vs 1次2次;联会重组:无 vs 前期I;同源行为:不配对/姐妹分离 vs 同源分离/姐妹分离;子细胞:2个2n vs 4个n;共同:纺锤体/核变化","type":"比较型","kp":"ch09_s1_4"}],"calc":[{"id":"ch09_calc_1","modI":1,"q":"细胞分裂间期有哪些主要特点？","a":"与分裂期细胞的急剧而明显的形态变化相比，间期细胞的形态变化不明显，但其间进行 着比较复杂的化学变化。 间期细胞最显著的特征就是进行 DNA 的复制，其次就是进行 RNA 和蛋白质的合成。 （1）根据 DNA 的合成情况，又可把间期分为 DNA 合成前期（G1 期）、DNA 合成期（S 期）、 DNA 合成后期（G2 期）。其中 G1 期非常重要，Gl 期的限制点（R 点）是控制细胞 增殖的关键，决定了细胞的 3 种不同命运：①继续增殖细胞，细胞通过 R 点，连续进行增 殖，始终保持旺盛的增殖活性，能量代谢和物质代谢水平高，对外界信号高度敏感，分化程 度低，周期时间较为恒定；②暂不增殖细胞，细胞长时间地停留在 G1 期，合成大量特异性 的 RNA 和蛋白质，在结构和功能上发生分化。随后，代谢活性下降，处于细胞增殖的静止 状态（G0 期），但并没有丧失增殖的能力，在适宜的条件下被激活成增殖状态；③不再增 殖细胞，细胞丧失了增殖能力，始终停留在 G1 期，结构和功能上发生高度分化，直至衰老 死亡。 （2）细胞越过 R 点以后，就加速合成 DNA 复制所必需的各种前体物质和酶，同时，DNA 解旋酶和 DNA 合成启动因子也急剧增加，为进入 S 期 DNA 复制做准备。S 期最主要的特 点是 DNA 复制和组蛋白、非组蛋白等染色体组成蛋白质的合成，通过 DNA 复制精确地将 遗传物质传递给 M 期分裂的子细胞，保证遗传性状的稳定性。因此，S 期是整个细胞周期 中最关键的阶段。G2 期中加速合成 RNA 和蛋白质，其中最主要的是合成有丝分裂因子和微 管蛋白等有丝分裂器的组分。另外，细胞成分如磷脂的合成增加并进行能量 ATP 的积累， 为有丝分裂进行物质和能量的准备。总而言之，有丝分裂间期主要是细胞积累物质的生长过 程，只有缓慢的体积增加，形态上看不到明显的变化，但其间进行着旺盛的细胞代谢反应， 进行 DNA 的复制、RNA 和蛋白质的合成，为有丝分裂作准备。","kp":"ch09_s1_0","kps":"间期特点:DNA复制、RNA与蛋白合成;分G1/S/G2;G1限制点(R)决定三种命运(继续增殖/暂不增殖G0/终末分化)"},{"id":"ch09_calc_2","modI":5,"q":"科学家们已获得在细胞周期控制中有缺陷的许多酵母突变株。这些突变株在低温（30℃） 能正常增殖，而在较高温度（37℃）则不能正常生长和分裂。两个突变株（分别称为 Gee 和 Wee）在同一基因的不同部位有缺陷，对升高温度有明显不同的反应。在 37℃时，Gee 株细胞只生长得很大而不分裂，Wee 株细胞有很短的细胞周期，并且当体积远小于正常大 小时仍进行分裂。提出一个可能的模型，解释这些观察结果，并指出由这个基因编码的正常 蛋白会起什么作用？","a":"通常细胞必须长到一定大小才开始分裂。这两种突变株的细胞大小控制系统显然有缺陷。 在 Gee 细胞中，细胞只增大而不分裂，说明此突变的细胞周期控制蛋白已无法检测细胞的 大小，可能永远抑制 MPF。而另一方面在 Wee 细胞中，细胞在长到一定大小之前，突变的 控制蛋白过早地引发细胞分裂，包括 MPF 过早被激活等。实际上，Weel 就是一种酵母的细 胞周期调控蛋白，能够使 MPF 特定部位发生磷酸化以使之失活的一种激酶。Weel 突变的酵 母细胞有短的细胞周期，其细胞个体也较小。","kp":"ch09_s6_6","kps":"Gee/Wee模型:细胞大小控制缺陷;Gee不能检测大小→永久抑制MPF→只长不分裂;Wee过早激活MPF→小细胞分裂;Weel=使MPF磷酸化失活的激酶"},{"id":"ch09_calc_3","modI":1,"q":"在研究促使 G1 期细胞 DNA 复制以及诱导细胞提前进入有丝分裂的调节因子的本质时， 为什么选用蛙和无脊椎动物的卵母细胞及早期的胚进行注射实验？","a":"一些动物的受精卵特别适合作为细胞周期的研究材料，因为这些卵细胞特别大，如蛙的 卵细胞的直径可达 1mm，并且在受精后进行快速胚胎发育，通过细胞周期进行分裂，产生 许多小细腮在每个细胞周期之间，G1 期和 G2 期很短，或没有 G1 期和 G2 期，但是都有 S 期 和 M 期。在受精卵的发育过程中，没有新基因的转录，因为胚胎早期发育阶段所需的 mRNA 和大多数蛋白质都是在卵母细胞形成时就合成好了并被包装在成熟的卵细胞中。另外在早期 的细胞分裂周期中，细胞也不会生长，所有的细胞都是通过对称分裂形成两个小细胞。 在细胞周期的特定阶段分离蛙的卵细胞，并从蛙卵细胞中制备提取物。为了检测蛙卵提取物 的生物活性，将它注射到非洲爪蟾的卵母细胞（未受精卵的不成熟的前体），观察这些提取 物对细胞周期的影响。这种卵母细胞是检测提取物活性的良好系统，因为这种细胞已经完成 了 DNA 复制并正好停留在第一次有丝分裂的 M 期之前，如果注射物具促分裂活性，即可 使注射的卵母细胞进入 M 期。因此卵母细胞所处的细胞周期阶段等于周期细胞的 G2 期。","kp":"ch09_s3_4","kps":"蛙/无脊椎卵母细胞:卵大约1mm、早期胚胎快、G1/G2短、无新转录(母源mRNA)、对称分裂;卵母细胞停于减数分裂,适合注射检测MPF"},{"id":"ch09_calc_4","modI":0,"q":"试述 UPPS。","a":"UPPS 即泛素蛋白酶水解系统，是一种依赖能量（ATP）的蛋白质降解系统，在这个系 统中，起介导蛋白质水解的是泛素，它是一个由 76 个氨基酸组成的高度保守的蛋白，其中 E1（泛素激活酶）、E2（泛素结合酶）和 E3（泛素蛋白连接酶）三种酶起重要的催化作用， 具体过程是： （1）泛素与泛素激活酶 E1 结合，形成 E1-泛素复合体。 （2）E1-泛素复合体将泛素转移给另一泛素结合酶 E2。 （3）在泛素蛋白连接酶 E3 的催化下，泛素与靶蛋白连接，并形成一条多聚泛素链。 （4）泛素化的靶蛋白转运到蛋白酶体，从而被降解。 这种泛素调节的蛋白质降锯过程在生物体中的作用非常重要。比如，与细胞周期相关的许多 蛋白质就是利用这个途径降解，使得蛋白质的浓度周期性的变化，保证在正确的时间和空间 上执行功能，使得细胞周期正常的运转。以色列科学家阿龙·切哈诺沃、阿夫拉姆·赫什科和 美国科学家欧文·罗斯三位科学家正是因为发现了泛素调节的蛋白质降解而获得 2004 年诺 贝尔奖。","kp":"ch09_s6_13","kps":"UPPS=泛素-蛋白酶体系统;泛素76aa;E1激活、E2结合、E3连接、多聚泛素链、26S蛋白酶体降解;周期蛋白周期降解;2004诺奖"},{"id":"ch09_calc_5","modI":1,"q":"细胞增殖有哪几种方式?各有什么特点？","a":"细胞增殖的方式有三种。 （1）无丝分裂又称直接分裂，它是指处于间期的细胞核不经任何有丝分裂时期而分裂为大 致相等的两部分的细胞分裂。该分裂过程简单、快速，在分裂中既没有染色体、纺锤体的形 成，也无核膜、核仁的解体，而是直接进行细胞核与细胞质的分裂。 （2）有丝分裂主要指细胞分裂过程中细胞核有明显的形态学化，特别是染色质的凝集和有 丝分裂器的形成。有丝分裂器在维持染色体的平衡、运动、分配中起着重要的作用。通过有 丝分裂，细胞将已复制加倍的 DNA 精确地平均分配到 2 个子细胞中，使分裂后的子细胞保 持遗传上的一致性。 （3）减数分裂。是有性生殖个体形成生殖细胞过程中发生的一种特殊的分裂方式。整个细 胞周期经过 2 次细胞分裂，而 DNA 只复制一次，这样就由染色体数目为 2n 的体细胞产生 出染色体数目减半（n）的精子或卵细胞。这样产生的精卵细胞再经受精后,形成的受精卵的 染色体数又恢复原来的二倍体数目，维持物种遗传的稳定性。","kp":"ch09_s1_0","kps":"三种方式:无丝分裂(简单快速、无染色体纺锤体)、有丝分裂(有丝分裂器、DNA均分)、减数分裂(2次分裂1次复制、染色体减半)"},{"id":"ch09_calc_6","modI":3,"q":"细胞通过什么机制将染色体排列到赤道板上？","a":"解释这一问题，目前流行两种学说，即牵拉假说和外推假说。牵拉假说认为，染色体向 赤道板方向运动，是由于动粒微管牵拉的结果。动粒微管越长，拉力越大。当来自两极的动 粒微管的拉力相等时，染色体即被稳定在赤道板上；外推假说认为，染色体向赤道方向移动， 是由于星体的排斥力将染色体外推的结果。染色体距离中心体越近，星体对染色体的外推力 越强，当来自两极的推力达到平衡时，染色体即被稳定在赤道板上。这两种假说并不排斥， 有时可能同时作用，或有其他机制共同参与，最终将染色体排列在赤道板上。由于某些染色 体不能被微管及时捕捉而滞后，Mad2 和 Bubl 不能从这些染色体的动粒上消失，后期则不能 启动，染色单体不能相互分离。只有等到这些染色体也被微管捕捉并排列到赤道板上，Mad 和 Bubl 从动粒上消失，后期才能开始启动。故只有染色体排列到赤道板，后期才能开始启 动，细胞周期才能顺利进行。","kp":"ch09_s1_6","kps":"牵拉假说+外推假说;Mad2/Bub1;排列赤道板后Mad2/Bub1消失→APC活化→后期启动"},{"id":"ch09_calc_7","modI":0,"q":"什么是细胞周期？细胞周期各时相的主要变化是什么？","a":"（1）细胞周期 细胞周期是指细胞从一次有丝分裂结束到下一次有丝分裂完成所经历的一个有序过程。它包 括细胞生长、DNA 复制和细胞分裂，最终将细胞遗传物质和其他内含物分配给两个子代细 胞等阶段。 （2）细胞周期各时相及其主要变化 细胞周期可划分为 G1、S、G2 和 M 四个时相，其主要变化如下： ①G1 期：G1 期细胞的物质代谢活跃，进行 RNA 和蛋白质的合成，细胞体积增大，dNTP 积 累，为细胞进入 S 期做准备。在 G1 晚期有检验点，可检验前次有丝分裂是否完成、外界环 境条件（如营养条件等）是否合适、细胞是否充分长大、DNA 是否有损伤等。多数细胞的 细胞周期时间长短主要由 G1 期决定。 ②S 期：主要进行 DNA 复制，常染色质与异染色质的复制不同步进行，DNA 量加倍。 ③G2 期：合成大量的蛋白质，但此期合成的蛋白质与前两期的不同，主要为细胞进入 M 期 做好充分准备。 ④M 期：核膜破裂，核仁消失，染色质聚集形成染色体，子染色体移向两极，在两极形成 子核，胞质分裂，形成两个子细胞。","kp":"ch09_s1_0","kps":"周期定义;G1(物质准备+限制点)、S(DNA复制)、G2(备M)、M(分裂)"},{"id":"ch09_calc_8","modI":1,"q":"细胞周期时间是如何测定的？","a":"常用的细胞周期时间测定方法有三种： （1）脉冲标记 DNA 复制和细胞分裂指数观察测定法 这是一种测定细胞周期时间的常用方法，适用于细胞种类构成相对简单、细胞周期时间相对 较短、周期运转均匀的细胞群体。该方法的测定过程如下： ①用 3H-TdR 对测定细胞进行脉冲标记，定时取材并利用放射自显影技术显示标记细胞，统 计标记的有丝分裂细胞的比例（PLM），以标记后的时间为横坐标，以标记的有丝分裂细 胞的比例为纵坐标，通过读图测定细胞周期，一般常采用半高度读数法。 ②一个细胞群体中细胞周期时间（Tc）和各时相不尽相同，第一个峰常达不到 100％，以后 的峰会发生衰减，PLM 不一定会下降到零。所以实际测量时，常以 （ ＋1/2TM） —     的方式求出 TM。 （2）流式细胞仪测定法 当细胞分别处于 G1、S、G2、M 期时，其细胞内的 DNA 含量不同。利用流式细胞仪可以测 定单个细胞内的 DNA 含量。该方法的测定过程如下： ①应用某些药物对细胞进行处理，将细胞抑制在细胞周期的某个特定时期； ②将细胞从抑制状态中释放出来，所有细胞将会同步运转，在不同时段应用流式细胞仪分别 测定这些细胞内的 DNA 含量，以释放后的时间为横坐标，单个细胞内 DNA 含量为纵坐标 作图，通过读图可以求出 G1、S、G2、M 期时间的长短。 （3）其他方法 ①通过显微缩时摄像技术可以求出分裂间期和分裂期的准确时间； ②通过在不同的时间对细胞群体进行计数，可以推算出细胞群体的倍增时间，即细胞周期的 总时间。","kp":"ch09_s1_2","kps":"方法:PLM脉冲标记+放射自显影;流式细胞仪;3H-TdR掺入"},{"id":"ch09_calc_9","modI":0,"q":"细胞周期同步化有哪些方法？比较其优缺点。","a":"细胞周期同步化是指在自然或者实验条件下，使一个细胞群体中所有细胞都处于细胞周 期的同一时相的过程。 （1）细胞周期同步化的方法 ①天然同步化 黏菌变形体进行多次核分裂后，再进行同步细胞分裂；大多数无脊椎动物和个别脊椎动物的 早期胚胎细胞，可同步化卵裂形成同步化细胞群体等，这种自然界存在的细胞周期同步化过 程，称为天然同步化。 ②人工同步化 a．人工选择同步化 人工选择同步化是指人为地将处于周期不同时相的细胞分离开来，从而获得不同时相的细胞 群体。在体外进行细胞培养时，处于 M 期的细胞体积较大，会变成球形，附着力减弱，经 振荡后可从培养液中收集。 b．人工诱导同步化 第一，DNA 合成阻断法：采用低毒或无毒的 DNA 合成抑制剂特异地抑制 DNA 合成，而不 影响处于其他时相的细胞进行细胞周期运转，经过两次 DNA 合成抑制剂处理，细胞最终抑 制在 G1／S 期交界处狭窄的时间区段，抑制剂去除后，细胞即可以进行同步细胞周期运转。 常用的 DNA 合成抑制剂有 TdR、羟基脲（HU）。 第二，分裂中期阻断法：某些药物可以抑制微管聚合，因而能有效地抑制细胞纺锤体的形成， 将细胞阻断在细胞分裂中期。常用药物有秋水仙素、秋水酰胺和诺考达唑。 （2）天然同步化与人工同步化的优、缺点 ①天然同步化 优点：不受人为条件的干扰，因而有可能在接近自然的条件下进行观察。 缺点：天然同步化的细胞群体受到诸多条件的限制，对结果有很大的影响。一般难以获得大 量的同步化细胞，难以满足实验的需要。 ②人工选择同步化 优点：细胞未经任何药物处理和伤害，能够真实反映细胞周期状况，且细胞同步化效率高。 缺点：分离的细胞数量少，需要多次收集方可得到较多的细胞，成本远大于其他方法。 ③人工诱导同步化 优点：在较短时间内可以获得较多的同步化细胞，并且比较节省时间和成本。 缺点：化学药物可能影响细胞的正常生理，从而影响细胞周期的状况。如果药物浓度过高， 一些细胞将不能回到细胞周期中，甚至死亡。","kp":"ch09_s1_12","kps":"天然同步化;人工选择(M期振荡收集);人工诱导(DNA合成阻断、中期阻断);优缺点"},{"id":"ch09_calc_10","modI":1,"q":"试比较有丝分裂与减数分裂的异同点。","a":"（1）有丝分裂与减数分裂的相同点 有丝分裂与减数分裂都是通过纺锤体与染色体的相互作用进行的细胞分裂，分裂过程中都形 成有丝分裂器，并且都有明显的的细胞核变化，尤其是染色质的变化。 （2）有丝分裂与减数分裂的不同点 二者的不同点如表表 13-1 所示： 表 13-1 有丝分裂与减数分裂的不同点 区别     有丝分裂            减数分裂 形成的细胞类 形成体细胞          形成生殖细胞 型 DNA 复制 1 次，细 胞连续分裂 2 次，细 DNA 复制 1 次，细胞 胞核 DNA 的合成发 分裂 1 次，细胞核 DNA 复制                 生在减数分裂前间 DNA 的合成发生在 S 期 S 期（99.7％～ 期","kp":"ch09_s1_4","kps":"相同:纺锤体/有丝分裂器/核变化;不同:细胞类型、复制分裂次数、联会重组、同源分离、子细胞数"},{"id":"ch09_calc_11","modI":3,"q":"细胞通过什么机制将染色体排列到赤道板上？有何生物学意义？","a":"（1）染色体排列到赤道板的机制 Mad2 和 Bub1 位于前期和前中期的染色体的动粒上，二者可以促使动粒敏化，促使微管与 动粒接触。只有当这些染色体也被微管捕捉并排列到赤道板上，Mad2 和 Bub1 从动粒上消 失，后期才能开始启动。 ①牵拉假说认为，染色体向赤道板方向运动是动粒微管牵拉的结果。动粒微管越长，拉力越 大，当来自两极的动粒微管拉力相等时，染色体即被稳定在赤道板上。 ②外推假说认为，染色体向赤道方向移动是星体的排斥力将染色体外推的结果。染色体距离 中心体越近，星体对染色体的外推力越强，当来自两极的推力达到平衡时，染色体即被稳定 在赤道板上。 这两种假说并不相互排斥，有时可能同时作用，或有其他机制共同参与，最终将染色体排列 在赤道板上。 （2）染色体排列的生物学意义 ①微管与动粒接触后促使一些蛋白质分子从动粒上释放出来，促使 APC 活化，使细胞从中 期进入到后期； ②保证每条染色体的两条染色单体分离后分别移向细胞的两极，确保细胞经过有丝分裂后染 色体的数目保持恒定，保证生物体的遗传稳定性。","kp":"ch09_s1_6","kps":"机制:牵拉/外推;意义:APC活化、保证均分、检查点"},{"id":"ch09_calc_12","modI":1,"q":"说明细胞分裂后期染色单体分离和向两极移动的运动机制。","a":"细胞分裂后期分为后期 A 和后期 B 两个阶段。后期 A，动粒微管变短，牵动染色体向 两极运动；在后期 B，极微管长度增加，两极之间的距离逐渐拉长。具体运动机制如下： （1）后期 A 的运动机制 微管马达蛋白首先结合到动粒上，在 ATP 分解提供能量的情况下，沿动粒微管向极部运动， 并带动动粒和染色体向极部运动。动粒微管的末端随之解聚成微管蛋白二聚体，动粒微管变 短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期 A 结束，转 向后期 B。 （2）后期 B 的运动机制 极微管游离端（正极）在 ATP 提供能量的情况下与微管蛋白聚合，使极微管加长，形成较 宽的极微管重叠区。KRPs 与极微管重叠区的微管结合并在来自两极的极微管之间搭桥。 KRPs 向微管正极行走，促使来自两极的极微管在重叠区相互滑动，使重叠区逐渐变得狭窄， 两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管和细胞膜之间搭桥，并向星体微 管负极运动，进一步将两极之间的距离拉长。","kp":"ch09_s1_6","kps":"后期A:动粒微管缩短+马达蛋白;后期B:极微管加长+KRPs滑动+动力蛋白"},{"id":"ch09_calc_y2","modI":3,"q":"说明MPF（CDK1-cyclinB）激活与失活的分子机制及其对G2/M转换的调控。","a":"①MPF由催化亚基CDK1（p34cdc2）和调节亚基cyclinB组成。②cyclinB在G1晚期开始合成，经S期、G2期逐渐积累，G2晚期达高峰；CDK1含量相对稳定。③CDK1的活化需：cyclinB结合、CAK使Thr161磷酸化（激活所需），同时wee1/mik1使Thr14、Tyr15磷酸化（抑制）。④当Cdc25去除Thr14/Tyr15的磷酸后，CDK1被激活，MPF活性达高峰，磷酸化组蛋白H1、核纤层蛋白、微管蛋白等，促使染色体凝集、核纤层解聚、纺锤体形成，驱动G2→M转换。⑤M期后期，cyclinB经泛素-蛋白酶体途径降解，MPF失活，细胞退出M期。","kps":"CDK1+cyclinB;cyclinB周期积累;CAK磷酸化Thr161激活;wee1/mik1磷酸化Thr14/Tyr15抑制;Cdc25去磷酸化→激活;底物(H1/核纤层/微管);cyclinB降解失活","type":"机制型","kp":"ch09_s6_3"},{"id":"ch09_calc_y3","modI":0,"q":"设计实验测定某细胞群体的细胞周期时间及各时相。","a":"思路一（PLM法，脉冲标记）：用3H-TdR短时脉冲标记处于S期的细胞，定时取材做放射自显影，统计标记的有丝分裂细胞比例（PLM），以时间为横坐标作图，由曲线求出各时相和总周期时间Tc。思路二（流式细胞术）：用DNA染料（如PI）染色，流式检测G1、S、G2/M期细胞的DNA含量分布；结合BrdU/EdU标记可区分S期。思路三（同步化+定时取样）：用同步化方法（如血清饥饿、诺考达唑）使细胞同步，释放后定时取样，用流式或显微计数追踪各时相。对照：未处理细胞作基准。","kps":"PLM(3H-TdR脉冲+自显影)求Tc;流式(PI/BrdU)测DNA含量;同步化定时取样;对照;计算各时相","type":"实验设计型","kp":"ch09_s1_2"}],"appcards":[{"front":"细胞增殖有何意义？","back":"细胞增殖的意义是： （1）细胞增殖是细胞生命活动的重要特征之一，是生物繁育的基础。 （2）单细胞生物细胞增殖导致生物个体数量的增加。 （3）多细胞生物由一个单细胞（受精卵）分裂发育而来，细胞增殖是多细胞生物繁殖的基 础。 （4）成体生物仍然需要细胞增殖，主要取代衰老死亡的细胞，维持个体细胞数量的相对平 衡和机体的正常功能。 （5）创伤愈合、组织再生、病理组织修复等，都要依赖细胞增殖。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"简述细胞周期中不同时相及其主要事件。","back":"细胞周期分为间期（G1 期、S 期、G2 期）和分裂期（M 期），各个时相发生的主要事 件如下所述： （1）G1 期，与 DNA 合成启动相关，开始合成细胞生长所需要的多种蛋白质、RNA、 碳水化合物、脂质等，同时染色质去凝集。 （2）S 期，合成 DNA 和染色体蛋白（组蛋白和非组蛋白）。新合成的 DNA 立即与组蛋白 结合，组成核小体串珠结构。 （3）G2 期，合成其他结构物质和相关的亚细胞结构，如微管蛋白、染色体凝集因子等。 （4）M 期，即细胞分裂期，包括胞核分裂和胞质分裂，细胞将其遗传物质载体平均分配到 两个子代细胞中。","mod":5,"modName":"3.2 周期蛋白依赖性蛋白激酶","points":""},{"front":"比较自然同步化、人工选择同步化、密度梯度离心法。","back":"（1）自然同步化，如有一种黏菌的变形体 plasmodia，某些受精卵早期卵裂。条件依赖 性突变株在细胞周期同步化中的应用：将与细胞周期调控有关的条件依赖性突变株转移到限 定条件下培养，所有细胞便被同步化在细胞周期中某一特定时期。 （2）人工选择同步化，如有丝分裂选择法，可用于单层贴壁生长细胞。优点是细胞未经任 何药物处理，细胞同步化效率高。缺点是分离的细胞数量少。 （3）密度梯度离心法，根据不同时期的细胞在体积和重量上存在差别进行分离。优点是方 法简单省时，效率高，成本低。缺点是对大多数种类的细胞并不适用。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"植物细胞的细胞周期有何特点？","back":"（1）植物细胞的细胞周期与动物细胞的标准细胞周期非常相似，含有 G1 期、S 期、C2 期和 M 期四个时期；（2）植物细胞不含中心体，但在细胞分裂时可以正常组装纺锤体；（3） 植物细胞以形成中板的形式进行胞质分裂。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"简述细胞有丝分裂的过程。","back":"有丝分裂过程分为前期、前中期、中期、后期、末期和胞质分裂。 前期：染色体凝集，核膜解体及核仁消失。 前中期：核膜破裂，纺锤体开始组装。 中期：染色体排列到赤道面上。 后期：中期染色体的两条染色单体相互分离，形成子代染色体，并分别向两极运动。 末期：子核形成。 胞质分裂：开始于细胞分裂后期，完成于细胞分裂末期","mod":3,"modName":"三 细胞周期的调控之—engine","points":""},{"front":"如何利用胸腺嘧啶和秋水仙素获得同步培养的细胞？","back":"（1）高浓度的胸腺嘧啶能够阻断 DNA 合成所需的核苷酸的合成，因此将细胞群体培 养在具有高浓度的胸腺嘧啶的培养液中时，非同步化的细胞能够正常地通过细胞周期，但到 达 S 期时，因 DNA 的合成被阻断，这些细胞不能顺利通过 S 期进入 G2 期。经过对 S 期的 短暂阻断，再改变胸腺嘧啶的浓度，解除抑制，所有的细胞都开始 DNA 的合成，即获得处 于同步生长的细胞。 （2）秋水仙素可抑制微管的聚合，因而抑制有丝分裂器的形成，将细胞阻断在有丝分裂的 中期，适当时间后解除秋水仙素的作用，即获得处于中期的同步化的细胞。这一方法称为中 期阻断法。","mod":2,"modName":"二 周期调控之brake","points":""},{"front":"下面的叙述有错误吗？请指出并解释。“生殖细胞和体细胞 DNA 的稳定对于一种物种的 生存都是至关重要的。”","back":"这种说法是正确的。如果体细胞中的 DNA 不够稳定（即如果积累突变过程过快）则导 致个体死亡（如死于肿瘤），因为这些突变常发生在生物繁殖之前，因此导致该物种的灭绝。 如果生殖细胞中的 DNA 不够稳定，就会积累许多突变并传递给后代，所以该物种将难以维 持下去。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"细胞内的突变使编码参与 DNA 复制的蛋白质的基因失活。在没有这种蛋白质的情况下， 细胞内的 DNA 复制仍然尽可能地进行。如果下列蛋白质消失，将会产生什么样的 DNA 产 物？ （1）DNA 聚合酶； （2）DNA 连接酶； （3）DNA 聚合酶的滑动夹钳； （4）清除 RNA 引物的切除酶； （5）DNA 解旋酶: （6）引物酶。","back":"（1）无 DNA 聚合酶，复制根本不可能进行，RNA 引物将在复制起始位点积累。 （2）DNA 连接酶负责连接后随链上合成的 DNA 片段。没有连接酶，则新复制的 DNA 链 将保持片段状态，但核苷酸不会丢失。 （3）无滑动夹钳，DNA 聚合酶常会脱离 DNA 模板，虽然原则上能够再结合上来并继续反 应，但不断地脱离与再结合将会耗费很多时间，从而大大降低 DNA 复制的速度。 （4）没有 RNA 切除酶，则 RNA 片段将保持与新复制的 DNA 片段共价连接。由于连接酶 不能将 DNA 连接于 RNA,连接反应不能进行。因此，后随链将由 RNA 和 DNA 片段两者组 成。 （5）没有 DNA 解旋酶，则 DNA 聚合酶将不会前进，因为它不能分开其前方模板 DNA 双 链，不合成或极少合成新的 DNA （6）无引物酶，则 RNA 引物在前导链或后随链上均不能合成。DNA 复制不能起始","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"在减数分裂Ⅰ中，姐妹染色单体为什么必须保持配对？","back":"减数分裂开始于 DNA 的复制，产生一个含有各条染色体 4 个拷贝的四倍体细胞，在随 后的两次减数分裂中这 4 个拷贝必须被均等分配至 4 个单倍体细胞。姐妹染色单体保持配对， 这样： （1）第一次减数分裂产生的细胞接受完整的两套染色体。 （2）在第二次减数分裂中染色体将会再次均等分配。如果姐妹染色单体不保持配对，在第 二次分裂中将不可能鉴别哪些染色单体应被组合在一起，因而很难保证每一染色单体的一个 拷贝被精确分配到每一个子细胞中。因而在第一次减数分裂中保持姐妹染色单体配对是一种 简易的方法，用于始终监视哪些染色单体应被分配在一起","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"比较有丝分裂与减数分裂的异同。","back":"见表 13-1。 表 13-1 有丝分裂与减数分裂的比较 有丝分裂           减数分裂 确保遗传的稳定性和生 体细胞以此方式进行分化与增 物变异，主要是生殖细胞 殖，维持机体发育和细胞更新 的分裂方式 DNA 复制一次，细胞分 DNA 复制一次，细胞分裂一次 裂两次 S 期时间相对较长       S 期时间相对较短 一个细胞产生四个子细 一个细胞产生两个子细胞 胞 常发生染色体的交叉互 不发生染色体互换 换，产生变异分裂时间 分裂时间短，1～2 小时 长，24 小时至几年","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"简述用放射性同位素 3H-TdR（氚胸腺嘧啶）标记法来测定细胞周期长短的原理。假如一 种体外培养的非同步生长细胞，它的细胞周期 G1 期是 6 小时，S 期是 6 小时，G2 期是 5 小 时，M 期是 1 小时，如果用 3H-TdR 标记细胞 15 分钟后，立即洗去 3H-TdR，然后放置在新 鲜培养基中继续培养。请问： （1）用 3H-TdR 标记 15 分钟后，这时被标记的细胞占细胞总数的百分比是多少？ （2）用 3H-TdR 标记 15 分钟后，洗净后放置在新鲜培养基中培养 18 小时，这时被标记的 M 期细胞又占多少比例？","back":"用 3H-TdR 标记法测定细胞周期长短的原理：用放射性同位素 3H-TdR（氚胸腺嘧啶） 标记细胞，3H-TdR（氚胸腺嘧啶）在 DNA 复制过程中被整合入新合成的 DNA 从而对细胞 做上标记。短暂标记后将细胞转移到新鲜普通培养基中培养，每隔一定时间取样做放射自显 影观察分析，从而确定细胞周期各时相的长短。 （1）用 3H-TdR 标记 15 分钟后，此时被标记的细胞是 S 期的细胞，占细胞总数的百分比： 6∕（6＋6＋5＋1）＝1/3。 （2）这类细胞的细胞周期刚好是 18 小时，因此培养 18 小时后所有的细胞均被标记。被标 记的 M 期细胞占 1/18。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"试述减数分裂的概念、意义和特点。 相关试题：减数分裂前期Ⅰ发生染色体联会的生物学意义何在？","back":"（1）减数分裂的概念 减数分裂是细胞仅进行一次 DNA 复制，随后进行两次分裂、染色体数减半的一种特殊的有 丝分裂。减数分裂是仅发生于有性生殖细胞形成过程中的某个阶段的一种特殊的有丝分裂形 式，整个过程分为减数分裂Ⅰ和减数分裂Ⅱ两个阶段。 （2）减数分裂的意义 ①有效获得双亲的遗传物质，确保世代间遗传的稳定性； ②增加变异机会，确保生物的多样性，增加生物适应环境变化的能力； ③减数分裂是生物有性生殖的基础，是生物遗传、生物进化、生物多样性的重要基础保证。 （3）减数分裂的特点 ①遗传物质只复制一次，细胞连续分裂两次，染色体数目减半； ②S 期持续时间较长； ③同源染色体在减数分裂期Ⅰ配对联会，基因重组； ④同源染色体配对排列在中期赤道极上，第一次分裂时同源染色体分开。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"用秋水仙素处理培养的细胞以使细胞同步化。这种处理会使细胞停留在细胞周期的什么 位置？什么机制阻止了细胞周期的进行？","back":"（1）用秋水仙素处理培养的细胞后，会使细胞停留在有丝分裂中期。 （2）阻止细胞周期进行的机制为： 秋水仙素可以与微管蛋白亚基结合，而当结合有秋水仙素的微管蛋白亚基组装到微管末端后， 其他的微管蛋白亚基就很难再在该处进行组装，因而秋水仙素可以抑制微管的形成，不能形 成纺锤体。用低浓度的秋水仙素处理细胞，可立即破坏细胞内的微管或纺锤体结构，使细胞 周期停留在有丝分裂中期。","mod":5,"modName":"3.2 周期蛋白依赖性蛋白激酶","points":""},{"front":"试比较染色体着丝粒与着丝点的区别与联系。","back":"（1）着丝粒与着丝点的区别 ①着丝粒是指位于染色体主缢痕部位的染色质。 ②着丝点即动粒，在主缢痕处两个染色单体的外侧表面部位的特殊结构，它与染色体微管接 触，是微管蛋白的组织中心。在电镜下，动粒为一个圆盘状结构，分内、中、外三层。 （2）着丝粒与着丝点的联系 着丝点（动粒）是附着于着丝粒上的一种特殊结构，动粒的外侧主要用于纺锤体微管附着， 内侧与着丝粒相互交织。由于动粒和着丝粒联系紧密，结构成分相互穿插，在功能方面联系 密切，因而两者常被称为着丝粒-动粒复合体。","mod":3,"modName":"三 细胞周期的调控之—engine","points":""},{"front":"简要说明细胞周期的间期各时相的特点。","back":"细胞周期的间期各时相的特点如下： （1）G1 期 ①时间：在周期时间中所占的比例最大，时间变化也最大，不同细胞类型的周期时间的差别 以及细胞的失同步等都是由 G1 期的差异造成的。 ②生化特征：主要合成大量的 RNA 和蛋白质，为细胞进入 S 期准备必要的物质基础。 ③重要性：G1 期细胞能对多种环境信号进行综合、协调并作出反应，以确定细胞是否进入 S 期。 （2）S 期 细胞内主要进行 DNA 的复制、组蛋白和非组蛋白等染色体蛋白的合成。 （3）G2 期 ①形态特征：染色质凝聚或螺旋化。 ②生化特征：合成一定的蛋白质和 RNA，为 M 期的细胞结构变化做准备。 （4）M 期 ①时间：细胞周期中 M 期占用的时间最短，可分为前、中、后、末期 4 个阶段。 ②形态特征：细胞的形态结构变化最大。 ③生化特征：RNA 合成停止、蛋白质合成减少以及染色体高度螺旋化。 ④关键因子：由 G2 期进入 M 期是细胞周期中的另一个关键时刻，M 期细胞质中存在一种使 染色质浓缩的物质，即 M 期促进因子（MPF）。","mod":5,"modName":"3.2 周期蛋白依赖性蛋白激酶","points":""},{"front":"用图文相结合的形式，叙述有丝分裂后期使染色体移向两极的三种马达模型。 相关试题：在动物细胞有丝分裂后期，有哪些分子马达作用于纺锤体的什么部位？各通过何 种运动来决定染色体分离和纺锤体长度？","back":"（1）有丝分裂后期使染色体移向两极的三种马达模型 ①星体微管马达：将有丝分裂器与细胞质膜连在一起。 ②极微管马达：负责将两极间的微管延长。 ③动粒微管马达（染色体微管马达）：负责缩短染色体微管的长度，使染色体向两极运动。 （2）三种马达使染色体移向两极的过程 有丝分裂后期分为后期 A 和后期 B 两个阶段。后期 A，动粒微管变短，牵动染色体向两极 运动；在后期 B，极微管长度增加，两极之间的距离逐渐拉长。 ①后期 A：微管马达蛋白首先结合到动粒上，在 ATP 分解提供能量的情况下，沿动粒微管 向极部运动，并带动动粒和染色体向极部运动。动粒微管的末端随之解聚成微管蛋白二聚体， 动粒微管变短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期 A 结束，转向后期 B。 ②后期 B：极微管游离端（正极）在 ATP 提供能量的情况下与微管蛋白聚合，使极微管加 长，形成较宽的极微管重叠区。KRPs 与极微管重叠区的微管结合并在来自两极的极微管之 间搭桥。KRPs 向微管正极行走，促使来自两极的极微管在重叠区相互滑动，使重叠区逐渐 变得狭窄，两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管和细胞膜之间搭桥， 并向星体微管负极运动，进一步将两极之间的距离拉长。     图 13-1 纺锤体结构模式图 图 13-2 细胞分裂后期 A 和后期 B 产生染色体向极部运动的示意图 六、实验题 已知某信号分子（分泌蛋白）引发的下游事件可抑制细胞分裂，我们推测该信号分子的受体 可能分布在细胞膜上。请你设计一个实验方案证实： （1）该信号分子的受体确实存在于细胞膜上； （2）该信号分子是通过与其受体的结合抑制了细胞分裂。 该实验应特别注意哪些关键环节？ 答：实验方案如下： 实验原理：绿色荧光蛋白（Green Fluorescent Protein，简称 GFP）是一种在美国西北海岸盛 产的水母中发现的一种蛋白质。它之所以能够发光，是因在其包含 238 个氨基酸的序列中， 第 65 至 67 个氨基酸（丝氨酸-酪氨酸-甘氨酸）残基可自发地形成一种荧光发色团。因此能 够直接看到细胞内部的运动情况，轻易地找出 GFP 蛋白所处的位置。 （1）本实验中，可以构建含有可以表达该信号分子基因与 GFP 基因的融合载体，然后将其 转化到细胞中。该载体就会在细胞中表达带有 GFP 蛋白的信号分子。如果该信号分子与细 胞膜上的受体蛋白结合，那么就会在细胞膜上观察到发光的 GFP 蛋白。该实验可以证明已 知信号分子的受体确实存在于细胞膜上。 （2）在（1）的方案基础上设立对照实验。 ①以无信号分子结合的正常细胞作为对照组。 ②构建带有可以与信号分子结合但是没有功能的受体片段，与信号分子竞争性结合，从而阻 止信号分子与受体的结合。 如果①和②情况下细胞正常分裂，则说明该信号分子是通过与其受体结合抑制了细胞分裂。 （3）注意事项： ①GFP 蛋白与已知信号分子融合后可能影响信号分子的构象从而影响信号分子的功能以及 与其受体的结合。 ②表达的受体片段应该与信号分子具有结合性，同时，需要保证该信号片段大量表达，具有 较高浓度，从而可以与信号分子产生竞争性结合。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"试述动粒的结构及功能。","back":"（1）动粒的结构 动粒又称着丝点，是附着于着丝粒上的一种细胞结构。动粒的外侧主要用于纺锤体微管附着， 内侧与着丝粒相互交织。在电镜下，动粒为一个圆盘状结构，分为内板、中间间隙、外板和 纤维冠 4 个部分。 （2）动粒的功能 动粒是有丝分裂和减数分裂中染色体分离必不可少的要素。在细胞分裂（包括有丝分裂和减 数分裂）的前、中、后期等几个阶段，纺锤体的纺锤丝（或星射线）需附着在染色体的动粒 上（而非着丝粒上）。在细胞分裂过程中，微管与动粒相连，牵引染色体在分裂中期进行染 色体整列，在分裂后期，牵引分开的染色体分别向细胞的两极运动，形成两个新的子细胞。","mod":3,"modName":"三 细胞周期的调控之—engine","points":""},{"front":"说明细胞分裂过程中核膜破裂和重装配的调节机制。","back":"（1）细胞分裂过程中核膜破裂的调节机制 在细胞分裂的前期末，活化的 MPF 促使构成核纤层结构的核纤层蛋白磷酸化，导致核纤层 结构瓦解，核膜破裂形成膜泡。 （2）细胞分裂过程中重装配的调节机制 在细胞分裂末期，APC 介导有丝分裂周期蛋白的降解，导致 MPF 失活。染色体开始去凝集， 核纤层蛋白开始去磷酸化并围绕染色质重新形成核纤层结构，膜泡围绕核纤层结构重新形成 新的核膜。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"细胞分裂间期有哪些主要特点？","back":"与分裂期细胞的急剧而明显的形态变化相比，间期细胞的形态变化不明显，但其间进行 着比较复杂的化学变化。 间期细胞最显著的特征就是进行 DNA 的复制，其次就是进行 RNA 和蛋白质的合成。 （1）根据 DNA 的合成情况，又可把间期分为 DNA 合成前期（G1 期）、DNA 合成期（S 期）、 DNA 合成后期（G2 期）。其中 G1 期非常重要，Gl 期的限制点（R 点）是控制细胞 增殖的关键，决定了细胞的 3 种不同命运：①继续增殖细胞，细胞通过 R 点，连续进行增 殖，始终保持旺盛的增殖活性，能量代谢和物质代谢水平高，对外界信号高度敏感，分化程 度低，周期时间较为恒定；②暂不增殖细胞，细胞长时间地停留在 G1 期，合成大量特异性 的 RNA 和蛋白质，在结构和功能上发生分化。随后，代谢活性下降，处于细胞增殖的静止 状态（G0 期），但并没有丧失增殖的能力，在适宜的条件下被激活成增殖状态；③不再增 殖细胞，细胞丧失了增殖能力，始终停留在 G1 期，结构和功能上发生高度分化，直至衰老 死亡。 （2）细胞越过 R 点以后，就加速合成 DNA 复制所必需的各种前体物质和酶，同时，DNA 解旋酶和 DNA 合成启动因子也急剧增加，为进入 S 期 DNA 复制做准备。S 期最主要的特 点是 DNA 复制和组蛋白、非组蛋白等染色体组成蛋白质的合成，通过 DNA 复制精确地将 遗传物质传递给 M 期分裂的子细胞，保证遗传性状的稳定性。因此，S 期是整个细胞周期 中最关键的阶段。G2 期中加速合成 RNA 和蛋白质，其中最主要的是合成有丝分裂因子和微 管蛋白等有丝分裂器的组分。另外，细胞成分如磷脂的合成增加并进行能量 ATP 的积累， 为有丝分裂进行物质和能量的准备。总而言之，有丝分裂间期主要是细胞积累物质的生长过 程，只有缓慢的体积增加，形态上看不到明显的变化，但其间进行着旺盛的细胞代谢反应， 进行 DNA 的复制、RNA 和蛋白质的合成，为有丝分裂作准备。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"科学家们已获得在细胞周期控制中有缺陷的许多酵母突变株。这些突变株在低温（30℃） 能正常增殖，而在较高温度（37℃）则不能正常生长和分裂。两个突变株（分别称为 Gee 和 Wee）在同一基因的不同部位有缺陷，对升高温度有明显不同的反应。在 37℃时，Gee 株细胞只生长得很大而不分裂，Wee 株细胞有很短的细胞周期，并且当体积远小于正常大 小时仍进行分裂。提出一个可能的模型，解释这些观察结果，并指出由这个基因编码的正常 蛋白会起什么作用？","back":"通常细胞必须长到一定大小才开始分裂。这两种突变株的细胞大小控制系统显然有缺陷。 在 Gee 细胞中，细胞只增大而不分裂，说明此突变的细胞周期控制蛋白已无法检测细胞的 大小，可能永远抑制 MPF。而另一方面在 Wee 细胞中，细胞在长到一定大小之前，突变的 控制蛋白过早地引发细胞分裂，包括 MPF 过早被激活等。实际上，Weel 就是一种酵母的细 胞周期调控蛋白，能够使 MPF 特定部位发生磷酸化以使之失活的一种激酶。Weel 突变的酵 母细胞有短的细胞周期，其细胞个体也较小。","mod":5,"modName":"3.2 周期蛋白依赖性蛋白激酶","points":""},{"front":"在研究促使 G1 期细胞 DNA 复制以及诱导细胞提前进入有丝分裂的调节因子的本质时， 为什么选用蛙和无脊椎动物的卵母细胞及早期的胚进行注射实验？","back":"一些动物的受精卵特别适合作为细胞周期的研究材料，因为这些卵细胞特别大，如蛙的 卵细胞的直径可达 1mm，并且在受精后进行快速胚胎发育，通过细胞周期进行分裂，产生 许多小细腮在每个细胞周期之间，G1 期和 G2 期很短，或没有 G1 期和 G2 期，但是都有 S 期 和 M 期。在受精卵的发育过程中，没有新基因的转录，因为胚胎早期发育阶段所需的 mRNA 和大多数蛋白质都是在卵母细胞形成时就合成好了并被包装在成熟的卵细胞中。另外在早期 的细胞分裂周期中，细胞也不会生长，所有的细胞都是通过对称分裂形成两个小细胞。 在细胞周期的特定阶段分离蛙的卵细胞，并从蛙卵细胞中制备提取物。为了检测蛙卵提取物 的生物活性，将它注射到非洲爪蟾的卵母细胞（未受精卵的不成熟的前体），观察这些提取 物对细胞周期的影响。这种卵母细胞是检测提取物活性的良好系统，因为这种细胞已经完成 了 DNA 复制并正好停留在第一次有丝分裂的 M 期之前，如果注射物具促分裂活性，即可 使注射的卵母细胞进入 M 期。因此卵母细胞所处的细胞周期阶段等于周期细胞的 G2 期。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"试述 UPPS。","back":"UPPS 即泛素蛋白酶水解系统，是一种依赖能量（ATP）的蛋白质降解系统，在这个系 统中，起介导蛋白质水解的是泛素，它是一个由 76 个氨基酸组成的高度保守的蛋白，其中 E1（泛素激活酶）、E2（泛素结合酶）和 E3（泛素蛋白连接酶）三种酶起重要的催化作用， 具体过程是： （1）泛素与泛素激活酶 E1 结合，形成 E1-泛素复合体。 （2）E1-泛素复合体将泛素转移给另一泛素结合酶 E2。 （3）在泛素蛋白连接酶 E3 的催化下，泛素与靶蛋白连接，并形成一条多聚泛素链。 （4）泛素化的靶蛋白转运到蛋白酶体，从而被降解。 这种泛素调节的蛋白质降锯过程在生物体中的作用非常重要。比如，与细胞周期相关的许多 蛋白质就是利用这个途径降解，使得蛋白质的浓度周期性的变化，保证在正确的时间和空间 上执行功能，使得细胞周期正常的运转。以色列科学家阿龙·切哈诺沃、阿夫拉姆·赫什科和 美国科学家欧文·罗斯三位科学家正是因为发现了泛素调节的蛋白质降解而获得 2004 年诺 贝尔奖。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"细胞增殖有哪几种方式?各有什么特点？","back":"细胞增殖的方式有三种。 （1）无丝分裂又称直接分裂，它是指处于间期的细胞核不经任何有丝分裂时期而分裂为大 致相等的两部分的细胞分裂。该分裂过程简单、快速，在分裂中既没有染色体、纺锤体的形 成，也无核膜、核仁的解体，而是直接进行细胞核与细胞质的分裂。 （2）有丝分裂主要指细胞分裂过程中细胞核有明显的形态学化，特别是染色质的凝集和有 丝分裂器的形成。有丝分裂器在维持染色体的平衡、运动、分配中起着重要的作用。通过有 丝分裂，细胞将已复制加倍的 DNA 精确地平均分配到 2 个子细胞中，使分裂后的子细胞保 持遗传上的一致性。 （3）减数分裂。是有性生殖个体形成生殖细胞过程中发生的一种特殊的分裂方式。整个细 胞周期经过 2 次细胞分裂，而 DNA 只复制一次，这样就由染色体数目为 2n 的体细胞产生 出染色体数目减半（n）的精子或卵细胞。这样产生的精卵细胞再经受精后,形成的受精卵的 染色体数又恢复原来的二倍体数目，维持物种遗传的稳定性。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"细胞通过什么机制将染色体排列到赤道板上？","back":"解释这一问题，目前流行两种学说，即牵拉假说和外推假说。牵拉假说认为，染色体向 赤道板方向运动，是由于动粒微管牵拉的结果。动粒微管越长，拉力越大。当来自两极的动 粒微管的拉力相等时，染色体即被稳定在赤道板上；外推假说认为，染色体向赤道方向移动， 是由于星体的排斥力将染色体外推的结果。染色体距离中心体越近，星体对染色体的外推力 越强，当来自两极的推力达到平衡时，染色体即被稳定在赤道板上。这两种假说并不排斥， 有时可能同时作用，或有其他机制共同参与，最终将染色体排列在赤道板上。由于某些染色 体不能被微管及时捕捉而滞后，Mad2 和 Bubl 不能从这些染色体的动粒上消失，后期则不能 启动，染色单体不能相互分离。只有等到这些染色体也被微管捕捉并排列到赤道板上，Mad 和 Bubl 从动粒上消失，后期才能开始启动。故只有染色体排列到赤道板，后期才能开始启 动，细胞周期才能顺利进行。","mod":3,"modName":"三 细胞周期的调控之—engine","points":""},{"front":"什么是细胞周期？细胞周期各时相的主要变化是什么？","back":"（1）细胞周期 细胞周期是指细胞从一次有丝分裂结束到下一次有丝分裂完成所经历的一个有序过程。它包 括细胞生长、DNA 复制和细胞分裂，最终将细胞遗传物质和其他内含物分配给两个子代细 胞等阶段。 （2）细胞周期各时相及其主要变化 细胞周期可划分为 G1、S、G2 和 M 四个时相，其主要变化如下： ①G1 期：G1 期细胞的物质代谢活跃，进行 RNA 和蛋白质的合成，细胞体积增大，dNTP 积 累，为细胞进入 S 期做准备。在 G1 晚期有检验点，可检验前次有丝分裂是否完成、外界环 境条件（如营养条件等）是否合适、细胞是否充分长大、DNA 是否有损伤等。多数细胞的 细胞周期时间长短主要由 G1 期决定。 ②S 期：主要进行 DNA 复制，常染色质与异染色质的复制不同步进行，DNA 量加倍。 ③G2 期：合成大量的蛋白质，但此期合成的蛋白质与前两期的不同，主要为细胞进入 M 期 做好充分准备。 ④M 期：核膜破裂，核仁消失，染色质聚集形成染色体，子染色体移向两极，在两极形成 子核，胞质分裂，形成两个子细胞。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"细胞周期时间是如何测定的？","back":"常用的细胞周期时间测定方法有三种： （1）脉冲标记 DNA 复制和细胞分裂指数观察测定法 这是一种测定细胞周期时间的常用方法，适用于细胞种类构成相对简单、细胞周期时间相对 较短、周期运转均匀的细胞群体。该方法的测定过程如下： ①用 3H-TdR 对测定细胞进行脉冲标记，定时取材并利用放射自显影技术显示标记细胞，统 计标记的有丝分裂细胞的比例（PLM），以标记后的时间为横坐标，以标记的有丝分裂细 胞的比例为纵坐标，通过读图测定细胞周期，一般常采用半高度读数法。 ②一个细胞群体中细胞周期时间（Tc）和各时相不尽相同，第一个峰常达不到 100％，以后 的峰会发生衰减，PLM 不一定会下降到零。所以实际测量时，常以 （ ＋1/2TM） —     的方式求出 TM。 （2）流式细胞仪测定法 当细胞分别处于 G1、S、G2、M 期时，其细胞内的 DNA 含量不同。利用流式细胞仪可以测 定单个细胞内的 DNA 含量。该方法的测定过程如下： ①应用某些药物对细胞进行处理，将细胞抑制在细胞周期的某个特定时期； ②将细胞从抑制状态中释放出来，所有细胞将会同步运转，在不同时段应用流式细胞仪分别 测定这些细胞内的 DNA 含量，以释放后的时间为横坐标，单个细胞内 DNA 含量为纵坐标 作图，通过读图可以求出 G1、S、G2、M 期时间的长短。 （3）其他方法 ①通过显微缩时摄像技术可以求出分裂间期和分裂期的准确时间； ②通过在不同的时间对细胞群体进行计数，可以推算出细胞群体的倍增时间，即细胞周期的 总时间。","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"细胞周期同步化有哪些方法？比较其优缺点。","back":"细胞周期同步化是指在自然或者实验条件下，使一个细胞群体中所有细胞都处于细胞周 期的同一时相的过程。 （1）细胞周期同步化的方法 ①天然同步化 黏菌变形体进行多次核分裂后，再进行同步细胞分裂；大多数无脊椎动物和个别脊椎动物的 早期胚胎细胞，可同步化卵裂形成同步化细胞群体等，这种自然界存在的细胞周期同步化过 程，称为天然同步化。 ②人工同步化 a．人工选择同步化 人工选择同步化是指人为地将处于周期不同时相的细胞分离开来，从而获得不同时相的细胞 群体。在体外进行细胞培养时，处于 M 期的细胞体积较大，会变成球形，附着力减弱，经 振荡后可从培养液中收集。 b．人工诱导同步化 第一，DNA 合成阻断法：采用低毒或无毒的 DNA 合成抑制剂特异地抑制 DNA 合成，而不 影响处于其他时相的细胞进行细胞周期运转，经过两次 DNA 合成抑制剂处理，细胞最终抑 制在 G1／S 期交界处狭窄的时间区段，抑制剂去除后，细胞即可以进行同步细胞周期运转。 常用的 DNA 合成抑制剂有 TdR、羟基脲（HU）。 第二，分裂中期阻断法：某些药物可以抑制微管聚合，因而能有效地抑制细胞纺锤体的形成， 将细胞阻断在细胞分裂中期。常用药物有秋水仙素、秋水酰胺和诺考达唑。 （2）天然同步化与人工同步化的优、缺点 ①天然同步化 优点：不受人为条件的干扰，因而有可能在接近自然的条件下进行观察。 缺点：天然同步化的细胞群体受到诸多条件的限制，对结果有很大的影响。一般难以获得大 量的同步化细胞，难以满足实验的需要。 ②人工选择同步化 优点：细胞未经任何药物处理和伤害，能够真实反映细胞周期状况，且细胞同步化效率高。 缺点：分离的细胞数量少，需要多次收集方可得到较多的细胞，成本远大于其他方法。 ③人工诱导同步化 优点：在较短时间内可以获得较多的同步化细胞，并且比较节省时间和成本。 缺点：化学药物可能影响细胞的正常生理，从而影响细胞周期的状况。如果药物浓度过高， 一些细胞将不能回到细胞周期中，甚至死亡。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"试比较有丝分裂与减数分裂的异同点。","back":"（1）有丝分裂与减数分裂的相同点 有丝分裂与减数分裂都是通过纺锤体与染色体的相互作用进行的细胞分裂，分裂过程中都形 成有丝分裂器，并且都有明显的的细胞核变化，尤其是染色质的变化。 （2）有丝分裂与减数分裂的不同点 二者的不同点如表表 13-1 所示： 表 13-1 有丝分裂与减数分裂的不同点 区别     有丝分裂            减数分裂 形成的细胞类 形成体细胞          形成生殖细胞 型 DNA 复制 1 次，细 胞连续分裂 2 次，细 DNA 复制 1 次，细胞 胞核 DNA 的合成发 分裂 1 次，细胞核 DNA 复制                 生在减数分裂前间 DNA 的合成发生在 S 期 S 期（99.7％～ 期","mod":1,"modName":"一 细胞周期的概念","points":""},{"front":"细胞通过什么机制将染色体排列到赤道板上？有何生物学意义？","back":"（1）染色体排列到赤道板的机制 Mad2 和 Bub1 位于前期和前中期的染色体的动粒上，二者可以促使动粒敏化，促使微管与 动粒接触。只有当这些染色体也被微管捕捉并排列到赤道板上，Mad2 和 Bub1 从动粒上消 失，后期才能开始启动。 ①牵拉假说认为，染色体向赤道板方向运动是动粒微管牵拉的结果。动粒微管越长，拉力越 大，当来自两极的动粒微管拉力相等时，染色体即被稳定在赤道板上。 ②外推假说认为，染色体向赤道方向移动是星体的排斥力将染色体外推的结果。染色体距离 中心体越近，星体对染色体的外推力越强，当来自两极的推力达到平衡时，染色体即被稳定 在赤道板上。 这两种假说并不相互排斥，有时可能同时作用，或有其他机制共同参与，最终将染色体排列 在赤道板上。 （2）染色体排列的生物学意义 ①微管与动粒接触后促使一些蛋白质分子从动粒上释放出来，促使 APC 活化，使细胞从中 期进入到后期； ②保证每条染色体的两条染色单体分离后分别移向细胞的两极，确保细胞经过有丝分裂后染 色体的数目保持恒定，保证生物体的遗传稳定性。","mod":3,"modName":"三 细胞周期的调控之—engine","points":""},{"front":"说明细胞分裂后期染色单体分离和向两极移动的运动机制。","back":"细胞分裂后期分为后期 A 和后期 B 两个阶段。后期 A，动粒微管变短，牵动染色体向 两极运动；在后期 B，极微管长度增加，两极之间的距离逐渐拉长。具体运动机制如下： （1）后期 A 的运动机制 微管马达蛋白首先结合到动粒上，在 ATP 分解提供能量的情况下，沿动粒微管向极部运动， 并带动动粒和染色体向极部运动。动粒微管的末端随之解聚成微管蛋白二聚体，动粒微管变 短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期 A 结束，转 向后期 B。 （2）后期 B 的运动机制 极微管游离端（正极）在 ATP 提供能量的情况下与微管蛋白聚合，使极微管加长，形成较 宽的极微管重叠区。KRPs 与极微管重叠区的微管结合并在来自两极的极微管之间搭桥。 KRPs 向微管正极行走，促使来自两极的极微管在重叠区相互滑动，使重叠区逐渐变得狭窄， 两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管和细胞膜之间搭桥，并向星体微 管负极运动，进一步将两极之间的距离拉长。","mod":1,"modName":"一 细胞周期的概念","points":""}],"jyq":[{"id":"jyq_ch09_1","kind":"fill","q":"2001年诺贝尔生理学或医学奖授予了3位科学家，他们是在的研究上作出了杰出贡献。","a":"细胞周期调控。","src":"南开大学，2009年","kp":null,"oe":["2001年诺贝尔生理学或医学奖授予Hartwell、Nurse和Hunt，表彰他们发现细胞周期调控的关键分子机制。"]},{"id":"jyq_ch09_2","kind":"mcq","q":"原核细胞遗传物质集中在细胞的一个或几个区域中，密度较低，与周围的细胞质无明确的分界线，称作_。","o":["A. 核质","B. 核孔","C. 核液","D. 类核"],"a":"D","src":"复旦大学，2003年","kp":null,"e":"原核细胞无核膜，遗传物质集中区域称类核（拟核）。","oe":["A. 核质：错误，核质是真核细胞核内的物质。","B. 核孔：错误，核孔是核膜上的通道结构。","C. 核液：错误，核液指真核细胞核内的基质。","D. 类核：正确，原核细胞DNA集中区称类核或拟核。"]},{"id":"jyq_ch09_3","kind":"mcq","q":"关于病毒的增殖，下列说法中错误的是（））。","o":["A. 必须在细胞内进行","B. 病毒的核酸和病毒蛋白均在宿主细胞内合成","C. 病毒是否侵染细胞，主要取决于病毒表面的识别结构","D. 存在以RNA为模板反转录为DNA的过程"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"病毒能否侵染细胞主要取决于宿主细胞表面受体，而非病毒表面识别结构，故C错误。","oe":["A. 必须在细胞内进行：正确，病毒无独立代谢，必须寄生在活细胞内增殖。","B. 病毒的核酸和病毒蛋白均在宿主细胞内合成：正确，二者均利用宿主系统合成。","C. 病毒是否侵染细胞，主要取决于病毒表面的识别结构：错误，主要由宿主细胞表面受体决定。","D. 存在以RNA为模板反转录为DNA的过程：正确，逆转录病毒即如此。"]},{"id":"jyq_ch09_4","kind":"mcq","q":"正常细胞培养中除培养基外常需加人血清，主要是因为血清中含有（）。","o":["A. 大量氨基酸","B. 核酸","C. 生长因子","D. 维生素"],"a":"C","src":"华中农业大学，2009年","kp":null,"e":"血清含多种生长因子，可促进细胞生长分裂，是体外培养的重要补充。","oe":["A. 大量氨基酸：错误，氨基酸主要由培养基提供，非加血清主因。","B. 核酸：错误，血清并非以提供核酸为主要作用。","C. 生长因子：正确，血清含多种生长因子，促进细胞增殖。","D. 维生素：错误，维生素主要由培养基补充。"]},{"id":"jyq_ch09_5","kind":"mcq","q":"人胚胎细胞去核得到的胞质体（cytoplast）与老年个体完整细胞相融合，所得到的杂种细胞进行培养时（）。","o":["A.只能分裂很少几次","B.迅速发生凋亡","C.其分裂能力与胚胎细胞大致相同"],"a":"A","src":"南京师范大学，2009年","kp":null,"e":"细胞的分裂能力由细胞核决定，老年个体的核使杂种细胞只能分裂少数几次。","oe":["A. 只能分裂很少几次：正确，核决定分裂次数，老年核分裂潜力低。","B. 迅速发生凋亡：错误，实验表现为分裂次数受限，而非迅速凋亡。","C. 其分裂能力与胚胎细胞大致相同：错误，胞质不能改变核决定的分裂限度。"]},{"id":"jyq_ch09_6","kind":"mcq","q":"重组DNA分子引I人受体细胞的过程称为（）。","o":["A. 转移","B. 转化","C. 转染","D. 转录"],"a":"A","src":"南京师范大学，2008年","kp":null,"e":"把重组DNA分子引入受体细胞的过程通称转移，其中细菌摄取游离DNA特称转化。","oe":["A. 转移：正确，将重组DNA分子引入受体细胞的整体过程可通称为转移。","B. 转化：错误，转化特指受体菌摄取游离DNA，范围较窄。","C. 转染：错误，转染多指将DNA导入真核细胞，并非通用名称。","D. 转录：错误，转录指以DNA为模板合成RNA，与导入无关。"]},{"id":"jyq_ch09_7","kind":"short","q":"从生物膜结构模型的演化谈谈人们对生物膜结构的认识过程。","a":"答从1925年至今，关于生物膜结构的模型主要有三明治式模型、单位膜模型、流动镶嵌模型、晶格镶嵌模型和板块镶嵌模型、脂模型。最早对质膜进行研究的是E.Verton，他于1895年研究了质膜的透性。他用植物细胞作为材料，发现凡是溶于脂肪的物质也很容易穿过膜，反之不溶于脂肪的物质则不容易穿过膜。1897年Crjins和Hediu用红细胞做了类似的实验，亦证明分子穿膜有通透性与其在脂中的溶解度有关。于是E.Dverton主张，细胞膜是由一层脂物质所组成，从而初步明确了细胞膜的化学性质。1917年Langmilir设计了脂类单分子膜技术，亦称为膜平衡技术，此技术至今仍然是研究人工膜的重要技术，通过此方法可得到单层脂分子膜。1925年Gtorter和Grendel利用langmulir设计的脂分子膜技术测定了细胞膜中脂分子单层的总面积，所获结果支持Overton的推论。1933年Couandev和Barlurd发现，虽然质膜对某些物质的通透性与该物质的脂溶性有关，但在一些分子如水、甲醇等，其细胞的能力大于根据其脓溶性所应用的能力，因此推想，细胞膜脂双层分子中一定还有一些贯穿脂双层的小孔，便于分子的通过。以上认识虽然是初步的，但却为对质膜的深人研究打下了基础。①三明治模型是Davson和Danielli提出的质膜中含有蛋白质成分，并提出“蛋白质-脂质-蛋白质”的质膜结构模型，这一模型影响长达20年之久。②1959年，J.D.Roberbson发展了三明治模型，提出了单位膜模型，大胆地推断所有的生物膜都由蛋白质-脂质-蛋白质的单位膜构成。③1972年，S.J.Singer和G.Nicolson提出了生物膜的流动镶嵌模型。④1975年，Wallach提出了晶格镶嵌模型。51977年，Jain和White进一步发展了Wallach的晶格镶嵌模型，提出了板块镶嵌模型。6最近有人提出脂模型，即在生物从生物膜结构模型的演化过程可知，人们对事物的认识是在实践中不断深人，认识是逐渐完善的过程。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_8","kind":"judge","q":"细胞周期蛋白降解是通过溶酶体途径进行的。","a":"对","src":"华中师范大学，2008年","kp":null,"e":"细胞周期蛋白在完成调控功能后需被及时降解，细胞周期才能单向有序推进，故题干说法成立。","oe":["按教材，细胞周期蛋白可经溶酶体途径降解，此说法与教材一致，故判对。","若判错，是误以为周期蛋白只能由泛素—蛋白酶体降解，忽视了溶酶体途径。"]},{"id":"jyq_ch09_9","kind":"short","q":"Caspase的活化需要在两个亚基的连接区的位点进行切割，结果产生由两个亚基组成的异二聚体。","a":"天冬氨酸。","src":"南开大学，2009年","kp":null},{"id":"jyq_ch09_10","kind":"short","q":"细胞周期运转到分裂中期时，周期蛋白A和B通过泛素化途径降解。（1）简述蛋白质的泛素化降解途径。(2）在上述泛素化降解途径中，蛋白降解的特异性（即确保只有该降解的蛋白被降解）是如何实现的？该破坏框在周期蛋白A和B的泛素化降解途径中起了重要作用。（4）如何证明周期蛋白A和B的存在对于驱动细胞周期从M期中期向后期转化是必需的？请提出两种不同的实验方案。","a":"（1)蛋白质的泛素化降解途径的主要步骤：①识别被降解的靶蛋白；②多个泛素分子共价结合到蛋白质底物上，形成多泛素链；③通过26s的蛋白酶体复合物降解靶蛋白，同时释放游离的、可重新利用的泛素分子。目前发现参与泛素化反应的酶有E1、E2、E3三类，E1即泛素活化酶（Ubactivatingenzyme），在ATP的参与下，E1以其活性位点半胱氨酸的巯基与泛素的C末端生成高能硫酯键，使泛素活化；E2即泛素结合酶（Ubs），是多个成员组成的蛋白家族，可接受E1传递来的Ub，在E3的参与下将Ub转移到底物上。(3)将周期蛋白A和B的破坏框缺失或突变掉，引I人到细胞中表达，然后显示周期蛋白A和B不能通过泛素化途径降解。（4)siRNA沉默，基因敲除，表达DominantNegative变种三种方案中的选两种。以鉴定蛋白质二聚体形式存在的两种方法。【答案】①对蛋白单体进行不同标记[lag－（orGFP-）tagged]，用其中一种抗体进行免疫沉淀，再用另一种抗体做Western检测；②蔗糖或者CsCl密度梯度离心，再做Western；③变性胶看相对分子质量大小。","src":"中国科学院，2008年","kp":null},{"id":"jyq_ch09_11","kind":"judge","q":"胞质分裂时，形成的收缩环是由微管形成的。","a":"错","src":"华中师范大学，2008年","kp":null,"e":"收缩环由肌动蛋白微丝和肌球蛋白组成，与微管无关，故该说法错误。","oe":["若选对，是误以为收缩环由微管构成；微管主要组成纺锤体，并不形成收缩环。","收缩环由肌动蛋白与肌球蛋白组成的微丝构成，并非微管，故该说法错误。"]},{"id":"jyq_ch09_12","kind":"short","q":"基因座控制区（locuscontrolregion，LCR）","a":"染色体DNA上一种顺式作用元件，具有稳定染色质疏松结构的功能；与多种反式因子的结合序列可保证DINA复制时与启动子结合的因子仍保持在原位。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_13","kind":"short","q":"隔离子（insulator）","a":"防止处于阻遏状态与活化状态的染色质结构域之间的结构特点向两侧扩展的染色质DNA序列，称为隔离子。作用：作为异染色质定向形成的起始位点；提供拓扑隔离区。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_14","kind":"judge","q":"核纤层蛋白磷酸化可导致核纤层结构崩解。","a":"对","src":"华中师范大学，2007年","kp":null,"oe":["核纤层蛋白被周期蛋白依赖激酶磷酸化后解聚，核纤层随之崩解，说法正确。","若选错，是误认为核纤层崩解与磷酸化无关；实际磷酸化正是其解体的原因。"]},{"id":"jyq_ch09_15","kind":"judge","q":"结构异染色质有转录活性。","a":"错","src":"华中师范大学，2008年","kp":null,"oe":["若选对，是混淆了结构异染色质与兼性异染色质；前者高度浓缩、无转录活性。","结构异染色质高度螺旋化，转录活性很低或没有转录活性，故该说法错误。"]},{"id":"jyq_ch09_16","kind":"short","q":"灯刷染色体的染色质环由轴丝和基质组成，构成基质的成分是和","a":"","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_17","kind":"short","q":"不同时期的间期细胞与M期细胞融合产生","a":"超前凝聚染色体。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch09_18","kind":"mcq","q":"核仁的大小与细胞内（）。","o":["A. 合成RNA的水平成正比","B. 合成蛋白质水平成正比","C. 细胞分裂速度成正比","D. DNA复制速度成正比"],"a":"B","src":"南京师范大学，2008年","kp":null,"e":"核仁大小与细胞合成蛋白质的水平成正比，蛋白合成旺盛的细胞核仁大。","oe":["A. 合成RNA的水平成正比：错误，核仁更直接反映蛋白质合成能力，非泛指RNA水平。","B. 合成蛋白质水平成正比：正确，核仁大小随蛋白质合成旺盛程度而增大。","C. 细胞分裂速度成正比：错误，分裂快的细胞核仁不一定大。","D. DNA复制速度成正比：错误，核仁大小与DNA复制速度无直接关系。"]},{"id":"jyq_ch09_19","kind":"mcq","q":"一条灯刷染色体含有一系列侧环，每个侧环在双线期卵母细胞中的拷贝数是（）。","o":["A. 2","B. 4个","C. 8个","D. 1个"],"a":"B","src":"南京师范大学，2008年","kp":null,"e":"灯刷染色体每个侧环由四条染色单体构成，故拷贝数为4。","oe":["A. 2：错误，双线期同源染色体已配对，共含四条染色单体。","B. 4个：正确，每个侧环含四条染色单体，拷贝数为4。","C. 8个：错误，侧环并不含8条染色单体。","D. 1个：错误，侧环不是单拷贝结构。"]},{"id":"jyq_ch09_20","kind":"mcq","q":"在真核细胞内，着丝粒是指（、）。","o":["A. 两个构成染色体DNA分子的连接区域","B. 一段高度重复的序列与组蛋白结合形成异染色质区","C. 染色体DNA上的一段特殊序列，能够促进与纺锤体的相互作用","D. 大约430bp长的一段序列，两端为两段高度保守的序列"],"a":"C","src":"南开大学，2009年","kp":null,"e":"着丝粒是染色体DNA上的特殊序列区域，能与纺锤体微管相互作用。","oe":["A. 两个构成染色体DNA分子的连接区域：错误，这不是着丝粒的定义。","B. 一段高度重复序列与组蛋白结合形成异染色质区：错误，只描述部分结构，未点明与纺锤体作用的功能。","C. 染色体DNA上的一段特殊序列，能够促进与纺锤体的相互作用：正确，着丝粒是纺锤体附着位点。","D. 大约430bp长的一段序列：错误，这是酵母ARS等特定序列的描述。"]},{"id":"jyq_ch09_21","kind":"short","q":"说明细胞分裂过程中膜破裂和重装配的调节机制。","a":"以非洲爪蟾卵提取物为基础的非细胞装配体系提供了核被膜解体与装配模型。在分裂期，双层核膜崩解成单层膜泡，核孔复合体解体，核纤层去装配；到分裂末期，核被膜开始重新形成。一种直径200nm左右的单层小膜泡直接参与了核膜的形成。它们首先附着到染色质表面，在染色质表面排列并相互融合形成双层膜，同时在膜上的某些部位内外膜相互融合并形成核孔复合体结构。核被膜的去装配不是随机的，而是具有区域特异性。此外，核被膜去装配、重装配变化受细胞周期调节因子的调节，调节作用可能与核纤层蛋白、核孔复合体蛋白的磷酸化与去磷酸化修饰有关。","src":"华中师范大学，2007年","kp":null},{"id":"jyq_ch09_22","kind":"short","q":"分析中期染色体的三种功能元件及其作用。","a":"答在细胞世代中要确保染色体的复制和稳定遗传，染色体起码应具备三种功能元件：①自主复制DNA序列：一个DNA复制起点，确保染色体在细胞周期中能够自我复制，维持染色体在细胞世代传递中的③端粒DNA序列：在染色体的两个末端必须有端粒，保持染色体的独立性和稳定性。构成染色体DNA的这三种关键序列称为染色体DNA的功能元件。近年来采用分子克隆技术把真核细胞染色体的复制起点、着丝粒和端粒这三种DNA关键序列分别克隆成功，并把它们互相搭配或改造而构成“人造微小染色体”。","src":"华中科技大学，2006年","kp":null},{"id":"jyq_ch09_23","kind":"judge","q":"细胞周期中，仅在G,/S有检验点（checkpoint）。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["若选对，是漏掉了G2/M检验点和纺锤体组装检验点，检验点并非只有G1/S。","细胞周期还有G2/M检验点及中后期纺锤体检验点等，故“仅有G1/S”说法错误。"]},{"id":"jyq_ch09_24","kind":"short","q":"rRNA基因在间期核中位于，在有丝分裂中期位于。","a":"核仁浅染区；次痕核仁组织区。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch09_25","kind":"mcq","q":"下列哪种细胞周期时相组成是准确的（）。","o":["A. 前期-中期-后期-末期","B. G-G-S-M","C. G-S-G-M","D. M-G-G-S"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"细胞周期由G1、S、G2、M四个时相顺序组成。","oe":["A. 前期-中期-后期-末期：错误，这只是M期的各阶段，不构成完整周期。","B. G-G-S-M：错误，时相名称和顺序均有误。","C. G-S-G-M：正确，即G1到S到G2到M的周期时相。","D. M-G-G-S：错误，顺序完全颠倒。"]},{"id":"jyq_ch09_26","kind":"mcq","q":"细胞周期的长短主要差别在（）。","o":["A. G期","B. G期","C. M期","D. S期"],"a":"A","src":"南京师范大学，2008年","kp":null,"e":"细胞周期的长短主要差别在G1期，G1期长短决定周期总时长。","oe":["A. G1期：正确，G1期可变性最大，是周期长短的主要差别所在。","B. G2期：错误，G2期持续时间相对稳定，变化不大。","C. M期：错误，M期持续时间较短且相对恒定。","D. S期：错误，S期持续时间也相对稳定。"]},{"id":"jyq_ch09_27","kind":"mcq","q":"减数分裂中染色体的联会、交换及交叉现象之间的关系是（）。","o":["A. 三者是独立过程，没有联系","B. 三者同时发生","C. 交叉是交换的条件，交叉还是联会的表现","D. 联会是交换的前提，交换的结果表现为交叉"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"减数分裂中联会是交换的前提，交换的结果表现为交叉。","oe":["A. 三者是独立过程，没有联系：错误，联会、交换和交叉密切相关。","B. 三者同时发生：错误，联会先于交换，交叉是交换的结果。","C. 交叉是交换的条件，交叉还是联会的表现：错误，因果与顺序颠倒。","D. 联会是交换的前提，交换的结果表现为交叉：正确，准确反映三者关系。"]},{"id":"jyq_ch09_28","kind":"mcq","q":"同步生长于M期的Hela细胞与另一同步生长的细胞融合，除看到中期染色体外还见到凝缩成粉末状的染色体，推测这种同步生长的细胞是处于（）。","o":["A. G期","B. S期","C. G2期","D. M期"],"a":"B","src":"中山大学，1999年","kp":null,"e":"S期细胞与M期细胞融合后，S期染色质被诱导早熟凝集，呈粉末状染色体。","oe":["A. G1期：错误，G1期染色质凝集呈细线状而非粉末状。","B. S期：正确，S期正在进行DNA复制，染色质早熟凝集呈粉末状。","C. G2期：错误，G2期染色质凝集呈双线状。","D. M期：错误，M期本身即有中期染色体，不会额外出现粉末状。"]},{"id":"jyq_ch09_29","kind":"short","q":"4nm的圆筒状结构，称为超螺线管，是染色体包装的三级结构，这些螺线管进一步螺旋折叠，形成长2～10um的染色单体。放射环模型认为：螺线管形成DNA复制下，每18个复制环呈放射状平面排列，结合在核基质上形成微带，微带是染色体高级机构的单位，大约106个微带沿纵轴构成子染色体。染色体列队是有丝分裂过程中的重要事件之一，是启动染色体分裂并向两个子细胞中平均分配的先决条件。染色体列队中有很多种蛋白参与，最主要的要数Mad和Bub，这两者可以使动粒敏化，促进动粒与微管接触，只有等染色体被微管捕捉并排列到赤道板上，Mad2和Bubl从动力上消失，后期才能开始启动。牵拉假说认为：染色体向赤道板上运动，是由于动粒微管牵拉的结果。动粒微管越长，拉力越大，当来自两极的动粒微管的拉力相等时，染色体即被稳定在赤道板上。外推假说认为：染色体距中心体越近，星体对染色体的外推越强，当来自两极的推力达到平衡时，染色体即被稳定在赤道板上。这两种假说并不排斥，有时可能同时作用，或有其他机制共同参与，最终染色体排列在赤道板上。在染色体排列在赤道板上之前，Mad2可以与后期促进因子复合体（APC）结合，抑制APC活性，阻止细胞周期向下一个阶段发展。当动粒与微管连接后，CENP-E分子的结构和位置发生变化，这些变化影响到Bubl的活性，进而影响到Mad2的稳定性和与其他有关物质的结合，最终导致Mad2对APC抑制作用的解除。从DNA到染色体要经过四级组装：压缩7倍压缩6倍压缩40倍压缩5倍DNA→核小体→螺线管→超螺线管→染色体经过四级组装成为染色体，DNA共压缩了8400倍。染色体列队与细胞骨架有关，两个假说：牵拉假说和外推假说。状，为什么？","a":"S期细胞PCC呈粉末状，因S期细胞正处于活跃的复制险臻物分PG&r即C是现第十三章细胞周期与细胞分裂出粉末状。","src":"武汉大学，2006年","kp":null},{"id":"jyq_ch09_30","kind":"short","q":"什么是细胞周期？","a":"细胞周期各时期主要变化是什么？谷细胞周期是指细胞从上一次有丝分裂结束到下一次有丝分裂完成所经历的一个有序过程。其间将细胞遗传物质和其他内含物分配给子细胞。间期：Gphase，Sphase，G2phase，Mphase；有丝分裂期：胞质分裂期细胞沿着G→S→G2→M→G，周期性运转，在间期细胞体积增大（生长），在M期细胞先是核分裂，接着胞质分裂，完成一个细胞周期。细胞周期各时期主要变化是：G，期与DNA合成启动相关，开始合成细胞生长所需要的多种蛋白质、RNA、碳水化合物、脂等，同时染色质去凝集。S期：DNA复制与组蛋白合成同步，组成核小体串珠结构。G2期DNA复制完成，在G2期合成一定数量的蛋白质和RNA分子。M期即细胞分裂期，真核细胞的细胞分裂主要包括两种方式，即有丝分裂和减数分裂。遗传物质和细胞内其他物质分配给子细胞。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_31","kind":"short","q":"说明细胞分裂过程中核膜破裂和重组装的调节机制。","a":"核纤层蛋白通过磷酸化和去磷酸化使核纤层解体和重新装配，在细胞分裂过程中对核被膜的破裂和重建起调节作用。在细胞分裂的前期末，活化的MPF促使构成核纤层结构的核纤层蛋白磷酸化，导致核纤层结构瓦解，核膜破裂形成膜泡。在细胞分裂末期，APC已经介导了有丝分裂周期蛋白的降解，导致MPF失活。染色体开始去凝集，核纤层蛋白开始去磷酸化并围绕染色质重新形成核纤层结构，膜泡围绕核纤层结构重新形成新的核膜。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_32","kind":"judge","q":"cdc2与周期蛋白结合后才能活化，具有蛋白激酶活性。","a":"对","src":"南京师范大学，2009年","kp":null,"oe":["cdc2单独无活性，须与周期蛋白结合成MPF后才具蛋白激酶活性，说法正确。","若选错，是误认为cdc2本身即有活性；其活化依赖周期蛋白结合，不能判错。"]},{"id":"jyq_ch09_33","kind":"judge","q":"细胞周期蛋白也是cdc2基因的产物。","a":"错","src":"南京师范大学，2008年","kp":null,"e":"cdc2基因的产物是CDK激酶，而细胞周期蛋白由另一类基因编码，故该说法错误。","oe":["若选对，是误以为周期蛋白与cdc2由同一基因编码；二者由不同基因编码。","周期蛋白由周期蛋白基因编码，cdc2是CDK基因的产物，二者来源不同，说法错误。"]},{"id":"jyq_ch09_34","kind":"mcq","q":"CdK（cyclin-dependentkinase）是否具有酶活性依赖于（）。","o":["A. 从G期进人S期","B. 从S期进入G2期","C. 从G，期进人G期","D. 从M期进入G,期"],"a":"A","src":"中国科学院，2005年","kp":null,"e":"Cdk（周期蛋白依赖性激酶）需与周期蛋白结合才有活性，推动周期时相转换。","oe":["A. 从G1期进入S期：正确，Cdk与周期蛋白结合获得酶活性，驱动G1/S转换。","B. 从S期进入G2期：错误，该转换不是Cdk酶活性依赖的典型事件。","C. 从G1期进入G2期：错误，G1之后为S期，时相顺序有误。","D. 从M期进入G1期：错误，该过程主要由其他调控因子介导。"]},{"id":"jyq_ch09_35","kind":"mcq","q":"成熟促进因子（MPF）不能促进（）。","o":["A. 卵母细胞称为卵细胞","B. 卵巢发育","C. G向M期转化","D. 蛋白质磷酸化"],"a":"B","src":"中国科学院，2004年","kp":null,"e":"MPF促进卵母细胞成熟、G2向M期转化及蛋白质磷酸化，但不促进卵巢发育。","oe":["A. 卵母细胞成熟为卵细胞：正确，促进卵母细胞成熟是MPF的功能之一。","B. 卵巢发育：错误，卵巢发育属个体发育，不由MPF直接促进，为本题答案。","C. G2向M期转化：正确，MPF驱动G2/M转换。","D. 蛋白质磷酸化：正确，MPF为蛋白激酶，能使底物磷酸化。"]},{"id":"jyq_ch09_36","kind":"mcq","q":"促细胞成熟因子（MPF）于以下细胞周期的哪一时期被激活（）。","o":["A. G期","B. M期","C. G期","D. S期"],"a":"B","src":"南京师范大学，2008年","kp":null,"e":"MPF在M期被激活并行使功能，驱动细胞进入并维持M期。","oe":["A. G1期：错误，G1期MPF尚未激活。","B. M期：正确，MPF在G2/M转换时激活，于M期发挥作用。","C. G2期：错误，G2期MPF尚未被激活。","D. S期：错误，S期以DNA复制为主，MPF未激活。"]},{"id":"jyq_ch09_37","kind":"mcq","q":"MPF调控细胞周期中（）。","o":["A. G，向S期转换","B. S期向G期转换","C. 中期向后期转换","D. G2期向M期转换"],"a":"D","src":"南开大学，2009年","kp":null,"e":"MPF调控G2期向M期转换，使细胞进入有丝分裂。","oe":["A. G1向S期转换：错误，该转换主要由G1/S周期蛋白-Cdk控制。","B. S期向G2期转换：错误，MPF不调控此转换。","C. 中期向后期转换：错误，该转换由后期促进复合物APC介导。","D. G2期向M期转换：正确，MPF是G2/M转换的关键调控因子。"]},{"id":"jyq_ch09_38","kind":"mcq","q":"抑癌基因之一是(）。","o":["A. c-fos","B. V-jun","C. v-raf","D. p53"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"p53是重要的抑癌基因，其突变或缺失与多种肿瘤相关。","oe":["A. c-fos：错误，c-fos是原癌基因。","B. V-jun：错误，v-jun是病毒癌基因。","C. v-raf：错误，v-raf是癌基因。","D. p53：正确，p53是经典的抑癌基因。"]},{"id":"jyq_ch09_39","kind":"short","q":"简述细胞周期M期MPF活化的条件以及APC功能。","a":"MPF是由cyclin和CDC基因编码的依赖于cyclin的蛋白激酶（cyclin-dependentkinase，CDK）。在M期活化的条件包括：M期CDK的激活起始于分裂期cyclin的积累；结合cyclinB的CDK1被Wee1将Thr14和Tyr15磷酸化而不具有活性，使CDK/cyclin不断积累；在M期，Wee1的活性下降，CDC25使CDK去磷酸化，去除了CDK活化的障碍；CDK的激活需要Thr161的磷酸化，它是在CDK激酶（CDKactivatingkinaseCAK）的作用下完成的。在中期当MPF活性达到最高时，通过一种未知的途径，激活后期蛋白复合体-APC，将cyclinB被蛋白酶体降解，完成一个细胞周期。","src":"湖北大学，2007年","kp":null},{"id":"jyq_ch09_40","kind":"short","q":"简述MPF的组成和在G2/M期进程中的作用。","a":"MPF即卵母细胞促成熟因子。1988年，Maller实验室以非洲爪蟾卵为材料，分离获得了微克级的纯化MPF，并证实其主要含有p32和p45两种蛋白。p32和p45结合后，表现出蛋白激酶活性，可以使多种蛋白质底物磷酸化。CDKI激酶即MPF，或p34cdc2激酶，由p34cdc2蛋白和周期蛋白B结合而成。p34cdc2蛋白在细胞周期中的含量相对稳定，而周期蛋白B的含量呈现周期性变化。p34cdc2蛋白只有与周期蛋白B结合后才有可能表现出激酶活性。因而，CDKI激酶活性首先依赖于周期蛋白B含量的积累。周期蛋白B一般在G，期的晚期开始合成，通过S期，其含量不断增加，到达G2期，其含量达到最大值。随周期蛋白B含量达到一定程度，CDKI激酶活性开始出现。到G2期晚期阶段，CDKI活性达到最大值并一直维持到M期的中期阶段。","src":"华中科大，2006年","kp":null},{"id":"jyq_ch09_41","kind":"short","q":"细胞中有哪几种方式可让CDK（cyclin-dependentkinase）失活？","a":"CDK的降解和灭活，除了泛素化-蛋白酶体外，CDI也可特异性抑制CDK的活性。CDI相对分子质量较小，其主要包括：Ink4（inhibitorofcdk4）和Cip/Kip（kinaseinhibitorprotein，Kip）等。①Ink4有P16INK4a、P15INK4b、P18INK4和P19INK4d等成员，主要抑制CDK4、CDK6。②Cip/Kip有p21Cipl、P27Kip1、P57Cipl主要抑制CDK2。大多数CDIs是通过直接结合CDK-cyclin复合物的磷酸化活化部位，抑制CDK的激酶活性。只有P16INK4a是通过结合CDK4单体，阻断它与cyclin的结合。","src":"中国科学院，2007年","kp":null},{"id":"jyq_ch09_42","kind":"short","q":"细胞周期调控的研究是从染色体凝集实验获得突破的，导致了MPF的发现、细胞周期蛋白的发现等。请简述这一研究过程，并评述研究思路、研究方法设计等在科学研究中的重要作用。","a":"1970年，Johnson和Rao将HeLa细胞同步化在细胞周期中臻物奢研然盗诵VM期细胞与其第十四章细胞增殖调控与癌细胞他间期细胞在仙台病毒介导下融合，并继续培养一定时间。他们发现，与M期细胞融合的间期细胞发生了形态各异的染色体凝集，称为早熟染色体凝集（PCC）。不同时相的见其细胞与M期细胞融合，产生的PCC形态各异。1971年，Masui和Markert用非洲爪蟾卵做实验，明确提出了MPF这一概念。他们发现，将孕酮诱导成熟的卵细胞的细胞质注射到卵母细胞中，可以诱导后者成熟；再将后者的细胞质少量注射到一些新的卵母细胞中，这些新的卵细胞仍被诱导成熟；再将刚被诱导成熟的卵细胞的细胞质少量注射到另一些新的卵母细胞中，仍然可以诱导卵母细胞成熟。因而他们认为，在成熟的卵细胞的细胞质中，必然有一种物质，可以诱导卵母细胞成熟。他们将这种物质称为促成熟因子，即MPF。1988年，Mailer实验室仍以非洲爪蟾为材料，分离出毫克级的纯化MPF，并证明其主要含p32和p45两种蛋白。它们结合后表现出蛋白激酶活性。与此同时，科学家通过对裂殖酵母和芽殖酵母的突变体分析，发现了一种p34cdc2激酶，并证明p34cdc2跟MPF中的p32是同源物。在上述工作开展的同时，以TimHunt为代表的科学家以海胆卵为材料，对细胞周期调控进行深人研究。当MPF被提纯之后，JamesMailer就和TimHunt实验室合作，并很快证明MPF的另一种成分为周期蛋白B，序列分析证明，周期蛋白B与酵母p56cdc13为同源物。至此，MPF的化学成分便被确定下来，它含有两个亚单位，即Cdc2蛋白和周期蛋白B，当二者结合之后，表现出蛋白激酶活性。综观MPF的发现过程，我们发现科学研究都是走的发现现象、提出问题、做出假想、设计实验、解释结果、给出结论这样一条道路。MPF的发现与生化成分的最终确认经历了漫长的时间和科学家艰辛的努力。还可以看到，研究清楚这个问题用了很多种生物材料。爪蟾和海胆的卵很大，易于观察和提取细胞内含物，而酵母个体小。生殖周期短、突变多、遗传物质少而遗传背景清楚，所以适用于进行突变体研究，可见选择合适的模式生物也是很重要的。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch09_43","kind":"short","q":"假设你所在的实验室正在寻找能编码出在细胞周期中起调控作用的蛋白质。由于细胞周期蛋白具有高度的保守性，人类的基因可以在酵母细胞中正确表达出具有功能的蛋白质。现在你手头的材料包括一个人类细胞株、几个酵母细胞株（包括某些能在非允许温度下阻止细胞周期的温敏突变体）、限制性内切酶，同时你也掌握了将外源DNA转人酵母细胞的技术。请设计一个实验来证明并分离一个编码控制细胞周期蛋白的人类基因。","a":"首先，从人细胞中分离出DNA，用限制性内切酶消化，凝胶电泳分离各个片段。然后将每个片段导人不同的温度敏感型酵母突变体。让这些带有人类基因的酵母突变体在允许温度和禁止温度下生长，能够在禁止温度下生长的酵母细胞被人DNA“挽救”了，该DNA中必然含有编码细胞周期蛋白的基码细胞周期调控蛋白的关键基因。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch09_44","kind":"short","q":"简述p34/cyclinB蛋白激酶的发现过程。","a":"容1970年，R.T.Johnson和P.N.Rao发现将M期细胞与其他间期细胞融合，可诱导间期细胞染色质提前凝集成染色体，提示在M期细胞内可能存在一种诱导染色体凝缩的因子，称为细胞有丝分裂促进因子。1971年，Y.Masui和C.L.Markert用非洲爪蟾卵做实验，明确提出了MPF这一概念。1988年，Lohka等人从非洲爪蟾卵中分离出了微克级纯化的MPF，证明其含p32和p45两种蛋白质，表现出蛋白激酶活性。L.Hartwell等获得了数十个芽殖酵母温度敏感型突变株，发现在限定温度下失去正常分裂繁殖能力的现象是由于基因发生突变而引起的。PaulNurse以裂殖酵母为材料发现，cdc2基因突变导致细胞停留在G2/M期的交界处。cdc2基因的表达产物相对分子质量为34kDa，与其他蛋白质结合后具有激酶活性，能为MPF的p32抗体识别，能增强MPF活性，表明其为p32同源物。1983年，TimothyHunt首次发现海胆卵受精后，在其卵裂过程中两种蛋白质的含量随细胞周期剧烈变化，分别命臻生物者研和瓷询i：BXr底证明酵母的p56c为cyclinB的同源物。至此，酵母的MPF蛋白也被确定了。综上所述，上述发现遵循了从现象到本质，带着问题找答案的科学研究方法。爪蟾卵细胞MPF的发现极大地推动了酵母MPF的研究。目前同源物的鉴定是分子生物学的重要研究内容之一。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch09_45","kind":"short","q":"细胞凋亡受到哪些因素的调控？","a":"达产物的调控。细胞凋亡可以分为caspase依赖性的和非caspase依赖性，在caspase依赖性的细胞凋亡过程中，caspase家族具有非常重要的作用。当DNA受损后，p53被激活，它通过激活凋亡正调节分子的表达和抑制抗凋亡因子的表达而促进细胞的凋亡。细胞内的caspase抑制剂与caspase特异性结合具有抗凋亡的作用。参与细胞凋亡和抗凋亡的基因有很多。","src":"姜益泉《辅导与习题集》","kp":null}],"outline":["细胞周期时相","CDK-cyclin 引擎","检验点","MPF 与周期调控","有丝/减数分裂"],"outlineMap":[1,0,3,1,1],"narrative":"【问题】细胞如何按序、准确地复制并分裂？\n【时相】周期分 G1/S/G2/M；长短差别主要在 G1，M 期最短约 0.5h。\n【发现史】Tim Hunt 在海胆卵中发现随周期涨落的 cyclin；把 M 期爪蟾卵细胞质注入卵母细胞可促其进入 M 期，说明存在 MPF(=CDK1+cyclin B)；PCC 实验把 M 期与间期细胞融合，间期核被诱导提前凝缩。Hartwell（芽殖酵母 cdc 突变体）与 Nurse（裂殖酵母 Cdc2）发现 CDK——三人获 2001 年诺奖。\n【调控】cyclin 随周期涨落决定 CDK 活性，磷酸化（Wee1 关 / CAK 开 / Cdc25 去磷酸）与 CKI 精细调节；检验点监控各时相，DNA 损伤经 ATM/ATR→p53→p21 使周期阻滞以修复，失败则凋亡；SCF 管间期降解、APC 管 M 期（降解 securin/cyclin，促进入后期）。","preview":{"main":"本章讲细胞周期时相、CDK-cyclin 引擎、检验点与 p53，以及泛素降解(SCF/APC)对周期的调控。","questions":["细胞周期分哪些时相？长短差别在哪？","CDK-cyclin 如何驱动周期？","检验点与 p53 起什么作用？","SCF 与 APC 如何分工？"],"answers":["G1/S/G2/M；差别主要在 G1，M 期最短，约 0.5h。","cyclin 随周期涨落、决定 CDK 活性；MPF=CDK1+cyclin B，磷酸化与 CKI 精细调节。","检验点监控各时相；DNA 损伤经 ATM/ATR→p53→p21 使周期阻滞以修复，失败则凋亡。","SCF 管间期，降解 G1/S-cyclin 与 CKI；APC 管 M 期，降解 securin/cyclin，促进入后期。"]}};